      · unfold Elixir.Module.Types.Descr.«map_union/2»
        split
        · rename_i h₁ heq h₂; exact (h₂ _ rfl).elim
        · simp_all
        · rename_i h₁ h₂; exact (h₂ _ rfl).elim
      · simp only [leaf_guard]
        split
        · rw [if_neg]
          · split
            · rcases h with h | h
              · exact (h _ _ _ rfl).elim
              · exact (h _ _ _ rfl).elim
            · rfl
          · intro e
            obtain ⟨a, b, c, rfl, -⟩ := exact_tuple3 e
            rcases h with h | h
            · exact h _ _ _ rfl
            · exact h _ _ _ rfl
        · split
          · rcases h with h | h
            · exact (h _ _ _ rfl).elim
            · exact (h _ _ _ rfl).elim
          · rfl

