        obtain ⟨r, run, rest⟩ := diff_key name x y (bA.field hx) (bB.field hy)
        exact ⟨r, gval _ _ _ _ run, rest⟩).1⟩
      obtain ⟨depth, rfl⟩ : ∃ depth, m = depth + 2 := ⟨m - 2, by omega⟩
      obtain ⟨C', fold', -, eq'⟩ := fold depth
      rw [eqC, ← eq']
