    theorem tuple_top_bool (L : List (Term × Term)) : ∃ b, ∀ d,
        Elixir.Module.Types.Descr.«tuple_empty?/2» d (.tuple #[.integer 61102469, .atom "open", .nil]) (.map L) =
          .ok (boolAtom b) := by
