    /-- Maps whose values are BDDs, with literals of each key satisfying `P`. -/
    def AllBddP (P : Term → Term → Prop) (R : List (Term × Term)) : Prop :=
      ∀ q v, mapLookup R q = some v → Bdd (P q) v

