          obtain ⟨b, hb⟩ := nonempty_args_total ops S args' hargs' "-all_non_empty_arguments?/2-fun-0-" (fun d a => by
            rw [Erlang.program.«Elixir.Module.Types.Descr:-all_non_empty_arguments?/2-fun-0-/1».pure]; rfl)
          refine ⟨b, fun m hm => ?_⟩
