            (fun t mt => by
              rw [List.mem_singleton.mp mt]
              exact ⟨kt, _, _, rfl, by simpa using len, fun a ma => by
                obtain ⟨_, _, rfl⟩ := List.mem_map.mp ma; exact hnone, ops.term⟩) hneg
          refine ⟨b, fun m hm => ?_⟩
          have h := hb m hm
