        ((mapEntries R).map fun e => .tuple #[e.1, e.2]) (fun x mx => by
          obtain ⟨e, me, rfl⟩ := List.mem_map.mp mx
          have wv := bR _ _ (mapLookup_of_mem_mapEntries me)
