          obtain ⟨lb, hlb⟩ := all_uni (K + 4) "Elixir.Module.Types.Descr" "-fun_empty?/2-fun-0-"
            #[.map ((.cons e.1 e.2, .atom "true") :: S)] lines (fun l ml => by
