            BoolAt K (fun m => Elixir.Module.Types.Descr.«empty_key?/3» (D m) e.1 e.2 (.map []))) :
        BoolAt K (fun m => Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map A) (.map B)) := by
      obtain ⟨b, hb⟩ := iterator_sub_uni K B (mapEntries A) both alone
