                    have nsome : mapLookup nfields (.atom b) = some (.tuple #[t₂, boolAtom Bool.false]) := by
                      rw [hpre]; exact lookup_head (lookup_below fun e me => preBelow e me _ mem₂)
                    have h₁ := hw b
                    have h₂ := hn b
