          rw [Elixir.Module.Types.Descr.«fields_merge_with_defaults/5».eq_def]; simp [fieldsTerm, Term.list]
        | [], (k₂, v₂) :: ys =>
          obtain ⟨b, rfl⟩ := (h₂.1 _ List.mem_cons_self).1
          obtain ⟨u₂, p₂, rfl, f₂⟩ := (h₂.1 _ List.mem_cons_self).2
