            have noneR : ∃ res, Elixir.Module.Types.Descr.«opt_map_difference_strategy/5» (D m) (fieldsTerm xs)
                (fieldsTerm ys) (.atom t₁) (.atom t₂) (.atom "none") = .ok res ∧
                DRes E den t₁ t₂ res (P₁ ++ (.atom a, v₁) :: xs) (P₂ ++ (.atom a, v₂) :: ys) :=
