    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-! Differences of map types on value maps. -/

    theorem denMF_botV (v : (MW V)) : denMF E den (.atom "bdd_bot") v = Bool.false := by
      rw [denMF_bdd (Bdd.bot (ok := MLit E))]; rfl

    /-- Plain differences of map types hold the maps of the first and not the second. -/
    theorem map_diff_val {x y : Term} (fx : MField E x) (fy : MField E y) :
        ∃ w, Elixir.Module.Types.Descr.«map_difference/2» x y = .ok w ∧ MField E w ∧
          ∀ v, denMF E den w v = (denMF E den x v && !denMF E den y v) := by
      rcases fy with ⟨k, rfl⟩ | wy
      · exact ⟨.atom "bdd_bot", by unfold Elixir.Module.Types.Descr.«map_difference/2»; rfl, Or.inr Bdd.bot,
          fun v => by rw [denMF_botV, denMF_top]; simp⟩
      have ny := not_top_of_ok wy mlit_not
      rcases fx with ⟨kt, rfl⟩ | wx
      · rcases wy.shape with rfl | rfl | ⟨k', a, b, rfl⟩ | ⟨h, lit, c, u, d, rfl⟩
        · refine ⟨.atom "bdd_bot", ?_, Or.inr Bdd.bot, fun v => ?_⟩
          · unfold Elixir.Module.Types.Descr.«map_difference/2»
            simp [diff_leaf_top]
          · rw [denMF_botV, denMF_bdd wy]; rfl
        · refine ⟨_, ?_, Or.inl ⟨kt, rfl⟩, fun v => ?_⟩
          · unfold Elixir.Module.Types.Descr.«map_difference/2»
            simp [diff_leaf_bot]
          · rw [denMF_bdd wy]; simp [eval]
        all_goals
          obtain ⟨w, run, keep, sem⟩ := neg_ok wy
          have ww := keep _ wy
          refine ⟨w, by rw [map_difference_neg ny _ rfl, run], Or.inr ww, fun v => ?_⟩
          rw [denMF_bdd ww, denMF_bdd wy, denMF_top, sem _ (valM_resp v)]
          simp
      · obtain ⟨w, run, keep, sem⟩ := diff_ok wx wy
        have ww := keep _ wx wy
        refine ⟨w, by rw [map_difference_bdd (not_top_of_ok wx mlit_not) ny, run], Or.inr ww, fun v => ?_⟩
        rw [denMF_bdd ww, denMF_bdd wx, denMF_bdd wy, sem _ (valM_resp v)]

    /-- `orddict:find/2` on sorted fields finds the field of a key. -/
    theorem find_val (a : String) : ∀ {l : List (Term × Term)}, FieldsV E l →
        Erlang.orddict.«find/2» (.atom a) (fieldsTerm l) =
          match mapLookup l (.atom a) with
          | some f => .ok (.tuple #[.atom "ok", f])
          | none => .ok (.atom "error")
      | [], _ => by rw [Erlang.orddict.«find/2».eq_def]; simp [fieldsTerm, Term.list, mapLookup]
      | (k, v) :: t, sl => by
        obtain ⟨b, rfl⟩ := (sl.1 _ List.mem_cons_self).1
        have st := fieldsV_tail sl
        have hd := fieldsV_head sl
        rcases cmp : Term.compare (.atom a) (.atom b)
        · have ne : b ≠ a := by
            rintro rfl; rw [compare_self] at cmp; cases cmp
          have none : mapLookup t (.atom a) = Option.none := lookup_none fun e me eq => by
            have := cmp_lt_trans cmp (hd e me)
            rw [eq, compare_self] at this; cases this
          rw [Erlang.orddict.«find/2».eq_def, lookup_cons_atom, if_neg ne, none]
          simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», cmp]
        · have ab : a = b := Std.compare_eq_iff_eq.mp (by rw [← atoms_cmp]; exact cmp)
          subst ab
          rw [Erlang.orddict.«find/2».eq_def, lookup_cons_atom, if_pos rfl]
          simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», Erlang.erlang.«>/2», cmp]
        · have ne : b ≠ a := by
            rintro rfl; rw [compare_self] at cmp; cases cmp
          have ih := find_val a st
          rw [Erlang.orddict.«find/2».eq_def, lookup_cons_atom, if_neg ne, ← ih]
          simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», Erlang.erlang.«>/2», cmp]

    theorem field_empty1_val (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) {c : Term} (hc : E c) (o : Bool) :
        ∃ e : Bool, Elixir.Module.Types.Descr.«field_empty?/1» (D m) (.tuple #[c, boolAtom o]) = .ok (boolAtom e) ∧
          (e = Bool.true ↔ ∀ x, ¬FieldSem den (.tuple #[c, boolAtom o]) x) := by
      cases o
      · obtain ⟨b, run, sem⟩ := ef.empty1 hm hc
        refine ⟨b, by simpa [Elixir.Module.Types.Descr.«field_empty?/1», boolAtom] using run, ?_⟩
        rw [sem]
        constructor
        · intro h x hx
          rw [fieldSem_mk] at hx
          rcases hx with ⟨-, h'⟩ | ⟨y, -, hy⟩
          · cases h'
          · exact h y hy
        · intro h y hy
          exact h (some y) ((fieldSem_mk (opt := Bool.false)).mpr (Or.inr ⟨y, rfl, hy⟩))
      · refine ⟨Bool.false, by simp [Elixir.Module.Types.Descr.«field_empty?/1», boolAtom], ?_⟩
        simp only [Bool.false_eq_true, false_iff]
        exact fun h => h Option.none ((fieldSem_mk (opt := Bool.true)).mpr (Or.inl ⟨rfl, rfl⟩))

    theorem field_opt_diff_val (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) {t₁ t₂ : Term} {o₁ o₂ : Bool} (h₁ : E t₁) (h₂ : E t₂)
        (S : List (Term × Term)) :
        ∃ c, E c ∧ Elixir.Module.Types.Descr.«field_opt_difference/3» (D m) (.tuple #[t₁, boolAtom o₁])
            (.tuple #[t₂, boolAtom o₂]) (.map S) = .ok (.tuple #[c, boolAtom (o₁ && !o₂)]) ∧
          ∀ x, FieldSem den (.tuple #[c, boolAtom (o₁ && !o₂)]) x ↔
            FieldSem den (.tuple #[t₁, boolAtom o₁]) x ∧ ¬FieldSem den (.tuple #[t₂, boolAtom o₂]) x := by
      obtain ⟨c, hc, run, sem⟩ := ef.opt_diff S h₁ h₂ hm
      refine ⟨c, hc, ?_, fieldSem_diff sem⟩
      simp only [Elixir.Module.Types.Descr.«field_opt_difference/3», run]
      cases o₁ <;> cases o₂ <;> simp [boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1»]

    theorem field_opt_inter_val (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) {t₁ t₂ : Term} {o₁ o₂ : Bool} (h₁ : E t₁) (h₂ : E t₂)
        (S : List (Term × Term)) :
        ∃ c, E c ∧ Elixir.Module.Types.Descr.«field_opt_intersection/3» (D m) (.tuple #[t₁, boolAtom o₁])
            (.tuple #[t₂, boolAtom o₂]) (.map S) = .ok (.tuple #[c, boolAtom (o₁ && o₂)]) ∧
          ∀ x, FieldSem den (.tuple #[c, boolAtom (o₁ && o₂)]) x ↔
            FieldSem den (.tuple #[t₁, boolAtom o₁]) x ∧ FieldSem den (.tuple #[t₂, boolAtom o₂]) x := by
      obtain ⟨c, hc, run, sem⟩ := ef.opt_inter S h₁ h₂ hm
      refine ⟨c, hc, ?_, fieldSem_meet sem⟩
      simp only [Elixir.Module.Types.Descr.«field_opt_intersection/3», run]
      cases o₁ <;> cases o₂ <;> simp [boolAtom, Lynx.Except.andAlso]

    /-- Maps a literal allows at every key but one atom key. -/
    def MSemExcept (den : Term → V → Prop) (tag : Term) (l : List (Term × Term)) (a : String) (w : MW V) : Prop :=
      (∀ s, s ≠ a → FSem den tag l s (w (.atom s))) ∧ ∀ k i, TagSem den tag (domKind k) (w (.dom k i))

    theorem msem_split_at {tag : Term} {l : List (Term × Term)} {a : String} {f : Term}
        (at_a : ∀ o, FSem den tag l a o ↔ FieldSem den f o) (w : (MW V)) :
        MSem den tag l w ↔ MSemExcept den tag l a w ∧ FieldSem den f (w (.atom a)) := by
      constructor
      · intro h; exact ⟨⟨fun s _ => h s, h.doms⟩, (at_a _).mp (h a)⟩
      · rintro ⟨⟨h, hd⟩, ha⟩
        refine ⟨fun s => ?_, hd⟩
        by_cases e : s = a
        · subst e; exact (at_a _).mpr ha
        · exact h s e

    /-- Literals without an atom key allow there the default field of their tag. -/
    theorem msem_split_absent (ef : EF nd E V den tl K) {tag : Term} (g : TagV E tag) {l : List (Term × Term)} {a : String}
        (la : mapLookup l (.atom a) = Option.none) (w : (MW V)) :
        MSem den tag l w ↔ MSemExcept den tag l a w ∧ FieldSem den (tagField tag) (w (.atom a)) :=
      msem_split_at (fun o => by rw [fieldSem_tagV ef.mopsE ef.mdopsE ef.semR g]; simp only [FSem, la]) w

    theorem msem_split {tag : Term} {l : List (Term × Term)} {a : String} {f : Term} (la : mapLookup l (.atom a) = some f)
        (w : (MW V)) : MSem den tag l w ↔ MSemExcept den tag l a w ∧ FieldSem den f (w (.atom a)) := by
      have at_a : FSem den tag l a (w (.atom a)) ↔ FieldSem den f (w (.atom a)) := by unfold FSem; rw [la]
      constructor
      · intro h; exact ⟨⟨fun s _ => h s, h.doms⟩, at_a.mp (h a)⟩
      · rintro ⟨⟨h, hd⟩, ha⟩
        refine ⟨fun s => ?_, hd⟩
        by_cases e : s = a
        · subst e; exact at_a.mpr ha
        · exact h s e

    theorem msem_store {tag : Term} {l l' : List (Term × Term)} {a : String} {d : Term}
        (look : ∀ s, mapLookup l' (.atom s) = if a = s then some d else mapLookup l (.atom s)) (w : (MW V)) :
        MSem den tag l' w ↔ MSemExcept den tag l a w ∧ FieldSem den d (w (.atom a)) := by
      have fs : ∀ s o, FSem den tag l' s o ↔ if a = s then FieldSem den d o else FSem den tag l s o := by
        intro s o
        unfold FSem
        rw [look s]
        by_cases e : a = s <;> simp [e]
      constructor
      · intro h
        refine ⟨⟨fun s ne => ?_, h.doms⟩, ?_⟩
        · have := (fs s (w (.atom s))).mp (h s); rwa [if_neg (Ne.symm ne)] at this
        · have := (fs a (w (.atom a))).mp (h a); rwa [if_pos rfl] at this
      · rintro ⟨⟨h, hd⟩, ha⟩
        refine ⟨fun s => ?_, hd⟩
        rw [fs]
        by_cases e : a = s
        · subst e; rw [if_pos rfl]; exact ha
        · rw [if_neg e]; exact h s (Ne.symm e)

    /-- Map values. -/
    def ValM (E : Term → Prop) (den : Term → V → Prop) (ρ : Term → Bool) : Prop := ∃ w, ρ = valM E den w

    theorem valM_respM : ∀ ρ, ValM E den ρ → Resp ρ := fun _ ⟨w, e⟩ => e ▸ valM_resp w

    theorem valM_leaf (ef : EF nd E V den tl K) {k : Int} {tag : Term} {l : List (Term × Term)} (sl : FieldsV E l)
        (g : TagV E tag) (w : (MW V)) :
        valM E den w (.tuple #[.integer k, tag, fieldsTerm l]) = Bool.true ↔ MSem den tag l w :=
      (valM_iff ef.mopsE ef.mdopsE ef.semR ⟨k, tag, l, rfl, g, sl⟩).trans nsem_lit

    /-- Storing a field into the fields of a literal makes a leaf of the literal's maps with that field. -/
    theorem store_leaf (ef : EF nd E V den tl K) {tag : Term} (g : TagV E tag) {l : List (Term × Term)} (sl : FieldsV E l)
        (a : String) {d : Term} (hd : FieldValue E d) :
        ∃ (k : Int) (l' : List (Term × Term)), Erlang.orddict.«store/3» (.atom a) d (fieldsTerm l) = .ok (fieldsTerm l') ∧
          Elixir.Module.Types.Descr.«bdd_leaf_new/2» tag (fieldsTerm l') =
            .ok (.tuple #[.integer k, tag, fieldsTerm l']) ∧
          MLit E (.tuple #[.integer k, tag, fieldsTerm l']) ∧
          ∀ w, valM E den w (.tuple #[.integer k, tag, fieldsTerm l']) = Bool.true ↔
            MSemExcept den tag l a w ∧ FieldSem den d (w (.atom a)) := by
      obtain ⟨l', runS, sl', -, look⟩ := store_val a hd sl
      obtain ⟨k, leaf, key⟩ := leaf_new_keyM g (l'.map fun e => .tuple #[e.1, e.2])
      have ne : ¬(tag = .atom "open" ∧ l' = []) := by
        rintro ⟨-, rfl⟩
        have := look a
        simp [mapLookup] at this
      refine ⟨k, l', runS, leaf, ⟨⟨k, tag, l', rfl, g, sl'⟩, fun ⟨_, e⟩ => leaf_not_top ne e, key⟩, fun w => ?_⟩
      rw [valM_leaf ef sl' g, msem_store look]

    /-- The one-key difference of a literal and another that agrees with it but at one key. -/
    theorem one_key_val (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) {k₁ : Int} {tag : Term} (g : TagV E tag)
        {l : List (Term × Term)} (sl : FieldsV E l) (ntop : ¬(tag = .atom "open" ∧ l = []))
        (key₁ : KeyOk (.tuple #[.integer k₁, tag, fieldsTerm l])) (a₂ : Term) {a : String}
        {t₁ t₂ : Term} {o₁ o₂ : Bool} (ht₁ : E t₁) (ht₂ : E t₂)
        (split : ∀ w, MSem den tag l w ↔ MSemExcept den tag l a w ∧ FieldSem den (.tuple #[t₁, boolAtom o₁]) (w (.atom a)))
        (type : Term) (S : List (Term × Term))
        (htype : type = .atom "none" ∨ type = .atom "intersection" ∨ type = .atom "union")
        (rel : ∀ w, MSem den tag l w → (valM E den w a₂ = Bool.true ↔ FieldSem den (.tuple #[t₂, boolAtom o₂]) (w (.atom a))))
        (full : type = .atom "union" → ∀ w, valM E den w a₂ = Bool.true ↔
          MSemExcept den tag l a w ∧ FieldSem den (.tuple #[t₂, boolAtom o₂]) (w (.atom a))) :
        ∃ res, Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7» (D m) tag (fieldsTerm l) (.atom a)
            (.tuple #[t₁, boolAtom o₁]) (.tuple #[t₂, boolAtom o₂]) type (.map S) = .ok res ∧
          CmpOk (ValM E den) (MLit E) (.tuple #[.integer k₁, tag, fieldsTerm l]) a₂ type res := by
      have v₁ : ∀ w, valM E den w (.tuple #[.integer k₁, tag, fieldsTerm l]) = Bool.true ↔ MSem den tag l w :=
        valM_leaf ef sl g
      obtain ⟨c, hc, runc, semc⟩ := field_opt_diff_val ef (m := m) (o₁ := o₁) (o₂ := o₂) (by omega) ht₁ ht₂ S
      obtain ⟨e, rune, seme⟩ := field_empty1_val ef (m := m) (by omega) hc (o₁ && !o₂)
      cases e
      rotate_left
      · refine ⟨.atom "subtype", ?_, Or.inr (Or.inl ⟨rfl, fun ρ ⟨w, ew⟩ h => ?_⟩)⟩
        · rw [Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7».eq_def]
          simp only [runc, rune, Lynx.Except.ok_bind]
          simp [boolAtom, Lynx.Except.guard, isMember]
        · subst ew
          have hm₁ := (v₁ w).mp h
          have f₁ := ((split w).mp hm₁).2
          refine (rel w hm₁).mpr (Classical.byContradiction fun nf => ?_)
          exact (seme.mp rfl) (w (.atom a)) ((semc (w (.atom a))).mpr ⟨f₁, nf⟩)
      obtain ⟨kd, ld, runS, leafd, okd, semd⟩ := store_leaf ef g sl a (d := .tuple #[c, boolAtom (o₁ && !o₂)]) ⟨c, _, rfl, hc⟩
      have sad : ∀ ρ, ValM E den ρ → eval ρ (.tuple #[.integer kd, tag, fieldsTerm ld]) =
          (ρ (.tuple #[.integer k₁, tag, fieldsTerm l]) && !ρ a₂) := by
        rintro ρ ⟨w, rfl⟩
        rw [eval_leaf]
        apply Bool.eq_iff_iff.mpr
        rw [semd, Bool.and_eq_true, v₁, Bool.not_eq_true', ← Bool.not_eq_true, split, semc]
        constructor
        · rintro ⟨h, f₁, nf₂⟩
          exact ⟨⟨h, f₁⟩, fun r => nf₂ ((rel w ((split w).mpr ⟨h, f₁⟩)).mp r)⟩
        · rintro ⟨⟨h, f₁⟩, nr⟩
          exact ⟨h, f₁, fun f₂ => nr ((rel w ((split w).mpr ⟨h, f₁⟩)).mpr f₂)⟩
      have ad : LeafOrBot (MLit E) (.tuple #[.integer kd, tag, fieldsTerm ld]) := Or.inr ⟨kd, _, _, rfl, okd⟩
      rcases htype with rfl | rfl | rfl
      · refine ⟨_, ?_, Or.inr (Or.inr (Or.inl ⟨_, .atom "bdd_bot", rfl, ad, Or.inl rfl, sad, fun h => by simp at h,
          fun h => by simp at h, fun _ => rfl⟩))⟩
        rw [Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7».eq_def]
        simp only [runc, rune, runS, leafd, Lynx.Except.ok_bind]
        simp [boolAtom, Lynx.Except.guard, isMember]
      · obtain ⟨ci, hci, runi, semi⟩ := field_opt_inter_val ef (m := m) (o₁ := o₁) (o₂ := o₂) (by omega) ht₁ ht₂ S
        obtain ⟨ei, runei, semei⟩ := field_empty1_val ef (m := m) (by omega) hci (o₁ && o₂)
        cases ei
        · obtain ⟨ki, li, runSi, leafi, oki, semli⟩ := store_leaf ef g sl a (d := .tuple #[ci, boolAtom (o₁ && o₂)])
            ⟨ci, _, rfl, hci⟩
          refine ⟨_, ?_, Or.inr (Or.inr (Or.inl ⟨_, _, rfl, ad, Or.inr ⟨ki, _, _, rfl, oki⟩, sad, fun _ ρ hρ => ?_,
            fun h => by simp at h, fun h => by simp at h⟩))⟩
          · rw [Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7».eq_def]
            simp only [runc, rune, runS, leafd, runi, runei, runSi, leafi, Lynx.Except.ok_bind]
            simp [boolAtom, Lynx.Except.guard, isMember]
          · obtain ⟨w, rfl⟩ := hρ
            rw [eval_leaf]
            apply Bool.eq_iff_iff.mpr
            rw [semli, Bool.and_eq_true, v₁, split, semi]
            constructor
            · rintro ⟨h, f₁, f₂⟩
              exact ⟨⟨h, f₁⟩, (rel w ((split w).mpr ⟨h, f₁⟩)).mpr f₂⟩
            · rintro ⟨⟨h, f₁⟩, r⟩
              exact ⟨h, f₁, (rel w ((split w).mpr ⟨h, f₁⟩)).mp r⟩
        · refine ⟨_, ?_, Or.inr (Or.inr (Or.inl ⟨_, .atom "bdd_bot", rfl, ad, Or.inl rfl, sad, fun _ ρ hρ => ?_,
            fun h => by simp at h, fun h => by simp at h⟩))⟩
          · rw [Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7».eq_def]
            simp only [runc, rune, runS, leafd, runi, runei, Lynx.Except.ok_bind]
            simp [boolAtom, Lynx.Except.guard, isMember]
          · obtain ⟨w, rfl⟩ := hρ
            symm
            apply Bool.eq_false_iff.mpr
            intro h
            rw [Bool.and_eq_true, v₁] at h
            obtain ⟨h₁, h₂⟩ := h
            have f₁ := ((split w).mp h₁).2
            exact (semei.mp rfl) (w (.atom a)) ((semi (w (.atom a))).mpr ⟨f₁, (rel w h₁).mp h₂⟩)
      · obtain ⟨cu, hcu, runu, semu⟩ := field_opt_union_val ef (m := m) (o₁ := o₁) (o₂ := o₂) (by omega) rfl rfl ht₁ ht₂ S
        obtain ⟨ku, lu, runSu, leafu, oku, semlu⟩ := store_leaf ef g sl a (d := .tuple #[cu, boolAtom (o₁ || o₂)])
          ⟨cu, _, rfl, hcu⟩
        refine ⟨_, ?_, Or.inr (Or.inr (Or.inl ⟨_, _, rfl, ad, Or.inr ⟨ku, _, _, rfl, oku⟩, sad, fun h => by simp at h,
          fun _ ρ hρ => ?_, fun h => by simp at h⟩))⟩
        · rw [Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7».eq_def]
          simp only [runc, rune, runS, leafd, runu, runSu, leafu, Lynx.Except.ok_bind]
          simp [boolAtom, Lynx.Except.guard, isMember]
        · obtain ⟨w, rfl⟩ := hρ
          rw [eval_leaf]
          apply Bool.eq_iff_iff.mpr
          rw [semlu, Bool.or_eq_true, v₁, split, full rfl w, semu]
          constructor
          · rintro ⟨h, f₁ | f₂⟩
            · exact Or.inl ⟨h, f₁⟩
            · exact Or.inr ⟨h, f₂⟩
          · rintro (⟨h, f₁⟩ | ⟨h, f₂⟩)
            · exact ⟨h, Or.inl f₁⟩
            · exact ⟨h, Or.inr f₂⟩

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-! Optimized differences of map literals. -/

    /-- `opt_map_difference_strategy/4` on literals of value maps. -/
    theorem dstrat_val (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) {t₁ t₂ : String} (g₁ : t₁ = "open" ∨ t₁ = "closed")
        (g₂ : t₂ = "open" ∨ t₂ = "closed") {l₁ l₂ : List (Term × Term)} (s₁ : FieldsV E l₁) (s₂ : FieldsV E l₂) :
        ∃ st, Elixir.Module.Types.Descr.«opt_map_difference_strategy/4» (D m) (fieldsTerm l₁) (fieldsTerm l₂) (.atom t₁)
          (.atom t₂) = .ok st ∧ DRes E den t₁ t₂ st l₁ l₂ := by
      have walk := fun st inv => dwalk ef hm t₁ t₂ g₁ g₂ _ l₁ l₂ [] [] st (Nat.le_refl _) (by simpa using s₁)
        (by simpa using s₂) (by simp) inv
      by_cases tc : t₁ = t₂ ∨ t₂ = "open"
      · obtain ⟨st, run, res⟩ := walk (.atom "all_equal") (Or.inl ⟨rfl, tc, fun s tag o => Iff.rfl⟩)
        refine ⟨st, ?_, by simpa using res⟩
        rw [Elixir.Module.Types.Descr.«opt_map_difference_strategy/4».eq_def]
        rcases g₁ with rfl | rfl <;> rcases g₂ with rfl | rfl <;>
          simp_all [Erlang.erlang.«is_atom/1», Lynx.Except.andAlso, Lynx.Except.orElse, Erlang.erlang.«==/2»]
      · obtain ⟨st, run, res⟩ := walk (.atom "none") (Or.inr (Or.inr (Or.inr rfl)))
        refine ⟨st, ?_, by simpa using res⟩
        rw [Elixir.Module.Types.Descr.«opt_map_difference_strategy/4».eq_def]
        rcases g₁ with rfl | rfl <;> rcases g₂ with rfl | rfl <;>
          simp_all [Erlang.erlang.«is_atom/1», Lynx.Except.andAlso, Lynx.Except.orElse, Erlang.erlang.«==/2»]

    /-- The general clause of `opt_map_leaf_difference/4`, which the single-key clause does not take. -/
    theorem leaf_diff_general {d : Dispatcher} {S type : Term} {k₁ k₂ : Int} {t₁ t₂ : Term}
        {l₁ l₂ : List (Term × Term)} {st r : Term}
        (h : t₂ = .atom "open" → (∃ key f, l₂ = [(key, f)]) → type = .atom "union")
        (hs : Elixir.Module.Types.Descr.«opt_map_difference_strategy/4» d (fieldsTerm l₁) (fieldsTerm l₂) t₁ t₂ = .ok st)
        (hr : st = .atom "disjoint" ∧ r = .atom "disjoint" ∨ st = .atom "left_subtype_of_right" ∧ r = .atom "subtype" ∨
          st = .atom "none" ∧ r = .atom "none" ∨ ∃ key v₁ v₂, st = .tuple #[.atom "one_key_difference", key, v₁, v₂] ∧
            Elixir.Module.Types.Descr.«opt_map_leaf_one_key_difference/7» d t₁ (fieldsTerm l₁) key v₁ v₂ type S =
              .ok r) :
        Elixir.Module.Types.Descr.«opt_map_leaf_difference/4» d (.tuple #[.integer k₁, t₁, fieldsTerm l₁])
          (.tuple #[.integer k₂, t₂, fieldsTerm l₂]) type S = .ok r := by
      rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
      split
      · rename_i heq₁ heq₂
        obtain ⟨-, e₂, e₃⟩ := tuple3_eq heq₂
        have hl : ∃ key f, l₂ = [(key, f)] := by
          cases l₂ with
          | nil => simp [fieldsTerm, Term.list] at e₃
          | cons x xs =>
            cases xs with
            | nil =>
              simp [fieldsTerm, Term.list] at e₃
              exact ⟨x.1, x.2, by obtain ⟨k, f⟩ := x; simp⟩
            | cons y ys => simp [fieldsTerm, Term.list] at e₃
        have hu := h e₂ hl
        subst hu
        rw [e₃, e₂] at hs
        rcases hr with ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨key, v₁, v₂, rfl, run⟩ <;>
          simp [Erlang.erlang.«/=/2», Lynx.Except.guard, hs, *]
      · rcases hr with ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨key, v₁, v₂, rfl, run⟩ <;> simp [hs, *]

    theorem lookup_fieldValue {l : List (Term × Term)} (sl : FieldsV E l) {s : String} {f : Term}
        (h : mapLookup l (.atom s) = some f) : FieldValue E f := by
      obtain ⟨e, me, -, fe⟩ := lookup_some_mem h
      rw [← fe]; exact (sl.1 e me).2

    /-- `opt_map_leaf_difference/4` compares map literals soundly. -/
    theorem map_leaf_cmp (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) (a₁ a₂ type : Term) (S : List (Term × Term)) (ht : TypeOk type) (h₁ : MLit E a₁)
        (h₂ : MLit E a₂) :
        ∃ res, Elixir.Module.Types.Descr.«opt_map_leaf_difference/4» (D m) a₁ a₂ type (.map S) = .ok res ∧
          CmpOk (ValM E den) (MLit E) a₁ a₂ type res := by
      obtain ⟨⟨k₁, t₁, l₁, rfl, g₁, s₁⟩, n₁, key₁⟩ := h₁
      obtain ⟨⟨k₂, t₂, l₂, rfl, g₂, s₂⟩, n₂, key₂⟩ := h₂
      have nt₁ : ¬(t₁ = .atom "open" ∧ l₁ = []) := fun ⟨a, b⟩ => n₁ ⟨_, by rw [a, b]; rfl⟩
      have nt₂ : ¬(t₂ = .atom "open" ∧ l₂ = []) := fun ⟨a, b⟩ => n₂ ⟨_, by rw [a, b]; rfl⟩
      have v₁ := valM_leaf ef (k := k₁) s₁ g₁
      have v₂ := valM_leaf ef (k := k₂) s₂ g₂
      by_cases c1 : (t₂ = .atom "open" ∧ ∃ b f, l₂ = [(.atom b, f)]) ∧ type ≠ .atom "union"
      · obtain ⟨⟨rfl, b, f₂, rfl⟩, nu⟩ := c1
        obtain ⟨u₂, o₂, rfl, hu₂⟩ := (s₂.1 (.atom b, f₂) (by simp)).2
        have rel₂ : ∀ w, valM E den w (.tuple #[.integer k₂, .atom "open", fieldsTerm [(.atom b, .tuple #[u₂, boolAtom o₂])]]) =
            Bool.true ↔ FieldSem den (.tuple #[u₂, boolAtom o₂]) (w (.atom b)) := fun w => by rw [v₂, msem_one]
        have e2 : fieldsTerm [(Term.atom b, Term.tuple #[u₂, boolAtom o₂])] =
            .cons (.tuple #[.atom b, .tuple #[u₂, boolAtom o₂]]) .nil := rfl
        have tyc : type = .atom "none" ∨ type = .atom "intersection" := by
          rcases ht with h | h | h
          · exact Or.inl h
          · exact Or.inr h
          · exact absurd h nu
        have fnd := find_val b s₁
        cases hl : mapLookup l₁ (.atom b) with
        | none =>
          rw [hl] at fnd
          rcases g₁ with rfl | rfl | ⟨dl, rfl, dv⟩
          · have nn : fieldsTerm l₁ ≠ .nil := fun e => nt₁ ⟨rfl, fieldsTerm_eq_nil.mp e⟩
            refine ⟨.atom "none", ?_, Or.inr (Or.inr (Or.inr rfl))⟩
            rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
            simp only [e2]
            rcases tyc with rfl | rfl <;>
              simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, Erlang.erlang.«==/2», Lynx.Except.andAlso,
                Erlang.erlang.«not/1», nn, Elixir.Module.Types.Descr.«map_key_tag_to_field/1»]
          · have absent : ∀ w, MSem den (.atom "closed") l₁ w → w (.atom b) = Option.none := fun w h => by
              rcases (fsem_none hl (w (.atom b))).mp (h b) with c | e
              · exact absurd c (by decide)
              · exact e
            cases o₂
            · refine ⟨.atom "disjoint", ?_, Or.inl ⟨rfl, fun ρ ⟨w, e⟩ => ?_⟩⟩
              · rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
                simp only [e2]
                rcases tyc with rfl | rfl <;>
                  simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, Erlang.erlang.«==/2», Lynx.Except.andAlso,
                    Erlang.erlang.«not/1», Elixir.Module.Types.Descr.«map_key_tag_to_field/1», boolAtom, isMember]
              · subst e
                apply Bool.eq_false_iff.mpr
                intro h
                rw [Bool.and_eq_true, v₁, rel₂] at h
                rw [absent w h.1, fieldSem_mk] at h
                simp [boolAtom] at h
            · refine ⟨.atom "subtype", ?_, Or.inr (Or.inl ⟨rfl, fun ρ ⟨w, e⟩ h => ?_⟩)⟩
              · rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
                simp only [e2]
                rcases tyc with rfl | rfl <;>
                  simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, Erlang.erlang.«==/2», Lynx.Except.andAlso,
                    Erlang.erlang.«not/1», Elixir.Module.Types.Descr.«map_key_tag_to_field/1», boolAtom, isMember]
              · subst e
                rw [v₁] at h
                rw [rel₂, absent w h, fieldSem_mk]
                simp [boolAtom]
          · -- the default field of the domains at the key meets the field of the negated literal
            have gd : TagV E (fieldsTerm dl) := Or.inr (Or.inr ⟨dl, rfl, dv⟩)
            have hu₁ := tagType_value ef.mopsE gd "atom"
            have split := msem_split_absent ef gd hl
            obtain ⟨bd, rund, soundd⟩ := field_disj_bool ef hm (f₁ := tagField (fieldsTerm dl)) ⟨_, Bool.true, rfl, hu₁⟩
              ⟨u₂, o₂, rfl, hu₂⟩
            have ne : ∀ s, Erlang.erlang.«==/2» (fieldsTerm dl) (.atom s) = .ok (.atom "false") := fun s => by
              simp [Erlang.erlang.«==/2», fieldsTerm_ne_atom, Term.false]
            cases bd
            · obtain ⟨res, run, cmp⟩ := one_key_val ef hm gd s₁ nt₁ key₁ (k₁ := k₁) (o₁ := Bool.true)
                (.tuple #[.integer k₂, .atom "open", fieldsTerm [(.atom b, .tuple #[u₂, boolAtom o₂])]]) hu₁ hu₂ split type S
                (by rcases tyc with h | h <;> simp [h]) (fun w _ => rel₂ w) (fun h => absurd h nu)
              refine ⟨res, ?_, cmp⟩
              rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
              simp only [e2]
              simp [tagField, boolAtom] at run rund
              rcases tyc with rfl | rfl <;>
                simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, ne, Lynx.Except.andAlso, key_tag_field gd, tagField,
                  Erlang.erlang.«not/1», rund, boolAtom, isMember, run]
            · refine ⟨.atom "disjoint", ?_, Or.inl ⟨rfl, fun ρ ⟨w, e⟩ => ?_⟩⟩
              · rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
                simp only [e2]
                simp [tagField, boolAtom] at rund
                rcases tyc with rfl | rfl <;>
                  simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, ne, Lynx.Except.andAlso, key_tag_field gd, tagField,
                    Erlang.erlang.«not/1», rund, boolAtom, isMember]
              · subst e
                apply Bool.eq_false_iff.mpr
                intro h
                rw [Bool.and_eq_true, v₁, rel₂, split] at h
                exact soundd rfl _ h.1.2 h.2
        | some f₁ =>
          rw [hl] at fnd
          obtain ⟨u₁, o₁, ef₁, hu₁⟩ := lookup_fieldValue s₁ hl
          subst ef₁
          obtain ⟨bd, rund, soundd⟩ := field_disj_bool ef hm ⟨u₁, o₁, rfl, hu₁⟩ ⟨u₂, o₂, rfl, hu₂⟩
          cases bd
          · obtain ⟨res, run, cmp⟩ := one_key_val ef hm g₁ s₁ nt₁ key₁ (k₁ := k₁)
              (.tuple #[.integer k₂, .atom "open", fieldsTerm [(.atom b, .tuple #[u₂, boolAtom o₂])]]) hu₁ hu₂ (msem_split hl) type S
              (by rcases tyc with h | h <;> simp [h]) (fun w _ => rel₂ w) (fun h => absurd h nu)
            refine ⟨res, ?_, cmp⟩
            rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
            simp only [e2]
            simp only [boolAtom] at run rund
            rcases g₁ with rfl | rfl | ⟨dl, rfl, -⟩ <;> rcases tyc with rfl | rfl <;>
              simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, Erlang.erlang.«==/2», Lynx.Except.andAlso,
                Erlang.erlang.«not/1», rund, boolAtom, isMember, run, fieldsTerm_ne_atom]
          · refine ⟨.atom "disjoint", ?_, Or.inl ⟨rfl, fun ρ ⟨w, e⟩ => ?_⟩⟩
            · rw [Elixir.Module.Types.Descr.«opt_map_leaf_difference/4».eq_def]
              simp only [e2]
              simp only [boolAtom] at rund
              rcases g₁ with rfl | rfl | ⟨dl, rfl, -⟩ <;> rcases tyc with rfl | rfl <;>
                simp [Lynx.Except.guard, Erlang.erlang.«/=/2», fnd, Erlang.erlang.«==/2», Lynx.Except.andAlso,
                  Erlang.erlang.«not/1», rund, boolAtom, isMember, fieldsTerm_ne_atom]
            · subst e
              apply Bool.eq_false_iff.mpr
              intro h
              rw [Bool.and_eq_true, v₁, rel₂, msem_split hl] at h
              exact soundd rfl _ h.1.2 h.2
      · have h : t₂ = .atom "open" → (∃ key f, l₂ = [(key, f)]) → type = .atom "union" := by
          rintro ho ⟨key, f, rfl⟩
          obtain ⟨b, rfl⟩ := (s₂.1 (key, f) (by simp)).1
          exact Classical.byContradiction fun nu => c1 ⟨⟨ho, b, f, rfl⟩, nu⟩
        -- literals with domains have no strategy
        by_cases atoms : ¬∃ x₁ x₂ : String, t₁ = .atom x₁ ∧ t₂ = .atom x₂
        · have hs : Elixir.Module.Types.Descr.«opt_map_difference_strategy/4» (D m) (fieldsTerm l₁) (fieldsTerm l₂) t₁ t₂ =
              .ok (.atom "none") := by
            rw [Elixir.Module.Types.Descr.«opt_map_difference_strategy/4».eq_def]
            simp [atoms_guard g₁ g₂ atoms]
          exact ⟨_, leaf_diff_general h hs (Or.inr (Or.inr (Or.inl ⟨rfl, rfl⟩))), Or.inr (Or.inr (Or.inr rfl))⟩
        obtain ⟨t₁, t₂, rfl, rfl⟩ := Classical.not_not.mp atoms
        have g₁' := g₁.of_atom
        have g₂' := g₂.of_atom
        obtain ⟨st, hs, dres⟩ := dstrat_val ef hm g₁' g₂' s₁ s₂
        rcases dres with ⟨rfl, s, hd⟩ | ⟨a, p₁, p₂, rfl, et, hp₁, hp₂, la₁, la₂, eqv⟩ | ⟨rfl, sub⟩ | rfl
        · refine ⟨_, leaf_diff_general h hs (Or.inl ⟨rfl, rfl⟩), Or.inl ⟨rfl, fun ρ ⟨w, e⟩ => ?_⟩⟩
          subst e
          apply Bool.eq_false_iff.mpr
          intro hh
          rw [Bool.and_eq_true, v₁, v₂] at hh
          exact hd (w (.atom s)) (hh.1 s) (hh.2 s)
        · obtain ⟨u₁, o₁, rfl, hu₁⟩ := hp₁
          obtain ⟨u₂, o₂, rfl, hu₂⟩ := hp₂
          subst et
          have full : ∀ w, valM E den w (.tuple #[.integer k₂, .atom t₁, fieldsTerm l₂]) = Bool.true ↔
              MSemExcept den (.atom t₁) l₁ a w ∧ FieldSem den (.tuple #[u₂, boolAtom o₂]) (w (.atom a)) := by
            intro w
            rw [v₂, msem_split la₂]
            constructor
            · rintro ⟨⟨hs', hd⟩, ha⟩; exact ⟨⟨fun s ne => (eqv s ne t₁ (w (.atom s))).mpr (hs' s ne), hd⟩, ha⟩
            · rintro ⟨⟨hs', hd⟩, ha⟩; exact ⟨⟨fun s ne => (eqv s ne t₁ (w (.atom s))).mp (hs' s ne), hd⟩, ha⟩
          obtain ⟨res, run, cmp⟩ := one_key_val ef hm g₁ s₁ nt₁ key₁ (k₁ := k₁) _ hu₁ hu₂ (msem_split la₁) type S ht
            (fun w hw => by rw [full w, msem_split la₁] at *; exact ⟨fun h => h.2, fun h => ⟨hw.1, h⟩⟩)
            (fun _ => full)
          exact ⟨res, leaf_diff_general h hs (Or.inr (Or.inr (Or.inr ⟨_, _, _, rfl, run⟩))), cmp⟩
        · refine ⟨_, leaf_diff_general h hs (Or.inr (Or.inl ⟨rfl, rfl⟩)), Or.inr (Or.inl ⟨rfl, fun ρ ⟨w, e⟩ hh => ?_⟩)⟩
          subst e
          rw [v₁] at hh
          rw [v₂]
          obtain ⟨v₀⟩ := ef.inhabited
          exact msem_of_atoms v₀ (fun s o => sub s o) hh
        · exact ⟨_, leaf_diff_general h hs (Or.inr (Or.inr (Or.inl ⟨rfl, rfl⟩))), Or.inr (Or.inr (Or.inr rfl))⟩

    theorem opt_map_seen {d : Dispatcher} {x y S : Term} (nx : ∀ k, x ≠ .tuple #[k, .atom "open", .nil])
        (ny : ∀ k, y ≠ .tuple #[k, .atom "open", .nil]) (ne : ∀ a b c, x = .tuple #[a, b, c] → exactCompare y x ≠ .eq)
        (hs : Elixir.Module.Types.Descr.«opt_bdd_seen/4» S (.atom "map_difference") x y = .ok (.atom "seen")) :
        Elixir.Module.Types.Descr.«opt_map_difference/3» d x y S = Elixir.Module.Types.Descr.«map_difference/2» x y := by
      rw [Elixir.Module.Types.Descr.«opt_map_difference/3».eq_def]
      split
      · exact absurd rfl (ny _)
      simp only [leaf_guard]
      split
      · rw [if_neg (ne _ _ _ rfl)]
        split
        · exfalso; simp_all
        · exfalso; simp_all
        · simp [hs]
      · split
        · exact absurd rfl (nx _)
        · exact absurd rfl (nx _)
        · simp [hs]

    theorem opt_map_ok {d : Dispatcher} {x y S S' : Term} (nx : ∀ k, x ≠ .tuple #[k, .atom "open", .nil])
        (ny : ∀ k, y ≠ .tuple #[k, .atom "open", .nil]) (ne : ∀ a b c, x = .tuple #[a, b, c] → exactCompare y x ≠ .eq)
        (hs : Elixir.Module.Types.Descr.«opt_bdd_seen/4» S (.atom "map_difference") x y = .ok (.tuple #[.atom "ok", S'])) :
        Elixir.Module.Types.Descr.«opt_map_difference/3» d x y S = Elixir.Module.Types.Descr.«bdd_difference/3» d x y
          (.function "Elixir.Module.Types.Descr" "-opt_map_difference/3-fun-0-" 3 #[S']) := by
      rw [Elixir.Module.Types.Descr.«opt_map_difference/3».eq_def]
      split
      · exact absurd rfl (ny _)
      simp only [leaf_guard]
      split
      · rw [if_neg (ne _ _ _ rfl)]
        split
        · exfalso; simp_all
        · exfalso; simp_all
        · simp [hs]
      · split
        · exact absurd rfl (nx _)
        · exact absurd rfl (nx _)
        · simp [hs]

    theorem opt_map_diff_same {d : Dispatcher} {S k a b y : Term} (ny : ∀ k, y ≠ .tuple #[k, .atom "open", .nil])
        (e : exactCompare y (.tuple #[k, a, b]) = .eq) :
        Elixir.Module.Types.Descr.«opt_map_difference/3» d (.tuple #[k, a, b]) y S = .ok (.atom "bdd_bot") := by
      rw [Elixir.Module.Types.Descr.«opt_map_difference/3».eq_def]
      split
      · exact absurd rfl (ny _)
      simp only [leaf_guard]
      rw [if_pos (by simpa using e)]
      rfl

    /-- Optimized differences of map types hold the maps of the first and not the second. -/
    theorem opt_map_diff_val (ef : EF nd E V den tl K) {n : Nat} (hn : K ≤ n) {x y : Term} (fx : MField E x) (fy : MField E y)
        (S : List (Term × Term)) :
        ∃ w, Elixir.Module.Types.Descr.«opt_map_difference/3» (D (n + 1)) x y (.map S) = .ok w ∧
          (kept (.atom "map", w) = Bool.true → MField E w ∧ ∀ v, denMF E den w v = (denMF E den x v && !denMF E den y v)) ∧
          (kept (.atom "map", w) = Bool.false → ∀ v, (denMF E den x v && !denMF E den y v) = Bool.false) := by
      rcases fy with ⟨k, rfl⟩ | wy
      · exact ⟨.atom "bdd_bot", by unfold Elixir.Module.Types.Descr.«opt_map_difference/3»; rfl,
          fun kw => by simp [kept] at kw, fun _ v => by rw [denMF_top]; simp⟩
      rcases fx with ⟨k₀, rfl⟩ | wx
      · obtain ⟨w, run, k, d⟩ := map_neg_valK ef k₀ (m := n + 1) (by omega) (Or.inr wy) S
        exact ⟨w, run, fun kw => ⟨(k kw).1, fun v => by rw [(k kw).2 v, denMF_top]; simp⟩,
          fun kw v => by rw [d kw v]; simp⟩
      have wxV := wx
      have wyV := wy
      have nx := not_top_of_ok wxV mlit_not
      have ny := not_top_of_ok wyV mlit_not
      by_cases same : ∃ a b c, x = .tuple #[a, b, c] ∧ exactCompare y x = .eq
      · obtain ⟨a, b, c, rfl, e⟩ := same
        exact ⟨_, opt_map_diff_same ny e, fun kw => by simp [kept] at kw, fun _ v => by
          rw [denMF_exact (Or.inr wxV) (Or.inr wyV) e, Bool.and_not_self]⟩
      have ne : ∀ a b c, x = .tuple #[a, b, c] → exactCompare y x ≠ .eq := fun a b c ex e => same ⟨a, b, c, ex, e⟩
      rcases opt_bdd_seen_map S (.atom "map_difference") x y with seen | ⟨S', ok⟩
      · obtain ⟨w, run, fw, sem⟩ := map_diff_val (Or.inr wxV) (Or.inr wyV)
        refine ⟨w, by rw [opt_map_seen nx ny ne seen, run], fun _ => ⟨fw, sem⟩, fun kw v => ?_⟩
        rw [← sem v]
        rcases fw with ⟨k', rfl⟩ | ww
        · simp [kept] at kw
        · rw [denMF_bdd ww]; exact drop_bdd ww kw _
      · obtain ⟨r, hr, okr, semr⟩ := diff3_ok valM_respM (d := D (n + 1))
          (cmp := .function "Elixir.Module.Types.Descr" "-opt_map_difference/3-fun-0-" 3 #[.map S'])
          (fun a₁ a₂ type ht h₁ h₂ => by
            obtain ⟨res, run, cmp⟩ := map_leaf_cmp ef (m := n) hn a₁ a₂ type S' ht h₁ h₂
            refine ⟨res, ?_, cmp⟩
            rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_map_difference/3-fun-0-/3».pure]
            simpa [Elixir.Module.Types.Descr.«-opt_map_difference/3-fun-0-/4»] using run)
          _ y wyV (fun _ h => h) x wxV
        have sem : ∀ v, denMF E den r v = (denMF E den x v && !denMF E den y v) := fun v => by
          rw [denMF_bdd okr, denMF_bdd wxV, denMF_bdd wyV, semr _ ⟨v, rfl⟩]
        refine ⟨r, by rw [opt_map_ok nx ny ne ok, hr], fun _ => ⟨Or.inr okr, sem⟩, fun kw v => ?_⟩
        rw [← sem v, denMF_bdd okr]; exact drop_bdd okr kw _

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Map lines found empty have no maps outside their negations: the soundness of map emptiness. -/

    variable {E : Term → Prop} {K : Nat} {V : Type} {den : Term → V → Prop} {Safe : List (Term × Term) → Prop}

    /-- Maps of a line with another field at a key, when they have a value of that field there. -/
    theorem msem_swap {tag : Term} {a : String} {A B : List (Term × Term)} (fresh : mapLookup A (.atom a) = Option.none)
        {f f' : Term} {w : MW V} (hw : MSem den tag (A ++ (.atom a, f) :: B) w) (h : FieldSem den f' (w (.atom a))) :
        MSem den tag (A ++ (.atom a, f') :: B) w := by
      refine hw.of_atoms fun s hs => ?_
      unfold FSem at hs ⊢
      rw [lookup_append] at hs ⊢
      cases e : mapLookup A (.atom s) with
      | some x => simpa [e] using hs
      | none =>
        rw [e] at hs
        simp only [Option.none_or] at hs ⊢
        rw [lookup_cons_atom] at hs ⊢
        by_cases as : a = s
        · subst as; simpa using h
        · simpa [as] using hs

    /-- One field of `map_line_meet_empty?/10`, read from a `true` answer. -/
    theorem meet_field_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 1 ≤ m) {S : List (Term × Term)} (hS : Safe S) (tag ntag : Term) (negs : List Term)
        (a : String) (f₁ f₂ : Term) (h₁ : FieldValue E f₁) (h₂ : FieldValue E f₂) (t₂ : Term) (t₁ acc : List (Term × Term))
        (sorted : FieldsV E (acc.reverse ++ (.atom a, f₁) :: t₁)) (fresh : mapLookup acc.reverse (.atom a) = Option.none)
        (lineS : ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l) (Term.list negs)
          (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w)
        {Goal : (MW V) → Prop}
        (rec : ∀ f, FieldValue E f → (∀ o, FieldSem den f o ↔ FieldSem den f₁ o ∧ FieldSem den f₂ o) →
          Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm t₁) t₂ tag ntag
            (fieldsTerm ((.atom a, f) :: acc)) (Term.list negs) (.map S) = .ok (.atom "true") →
          ∀ w, MSem den tag (acc.reverse ++ (.atom a, f) :: t₁) w → Goal w ∨ CovM den negs w)
        (run : Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) f₁ f₂ (fieldsTerm t₁) t₂ tag ntag
          (fieldsTerm acc) (Term.list negs) (.map S) = .ok (.atom "true")) :
        ∀ w, MSem den tag (acc.reverse ++ (.atom a, f₁) :: t₁) w → Goal w ∨ CovM den negs w := by
      obtain ⟨ty, o₁, rfl, hty⟩ := h₁
      obtain ⟨nt, o₂, rfl, hnt⟩ := h₂
      have hm2 : K ≤ m := by omega
      obtain ⟨meet, lmeet, hmeet⟩ := ops.inter hty hnt
      obtain ⟨bm, em⟩ := field_empty_total ops S lmeet (o₁ && o₂)
      obtain ⟨diff, ldiff, hdiff⟩ := dops.diff hty hnt
      obtain ⟨bd, ed⟩ := field_empty_total ops S ldiff (o₁ && !o₂)
      have semMeet := fieldSem_meet (t := meet) (esem.inter hty hnt hm2 (hmeet m hm2)) (o₁ := o₁) (o₂ := o₂)
      have semDiff := fieldSem_diff (t := diff) (esem.diff hty hnt hm2 (hdiff m hm2)) (o₁ := o₁) (o₂ := o₂)
      have emptyMeet := field_empty_sem ops dops esem lmeet hS hm2 (em m hm2)
      have emptyDiff := field_empty_sem ops dops esem ldiff hS hm2 (ed m hm2)
      have unfold10 :
          Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) (.tuple #[ty, boolAtom o₁])
            (.tuple #[nt, boolAtom o₂]) (fieldsTerm t₁) t₂ tag ntag (fieldsTerm acc) (Term.list negs) (.map S) =
          if bm then Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag
            (fieldsTerm (acc.reverse ++ (.atom a, .tuple #[ty, boolAtom o₁]) :: t₁)) (Term.list negs) (.map S)
          else if bd then Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm t₁) t₂ tag ntag
            (fieldsTerm ((.atom a, .tuple #[meet, boolAtom (o₁ && o₂)]) :: acc)) (Term.list negs) (.map S)
          else Lynx.Except.andAlso (Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag
              (fieldsTerm (acc.reverse ++ (.atom a, .tuple #[diff, boolAtom (o₁ && !o₂)]) :: t₁)) (Term.list negs) (.map S))
            (Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm t₁) t₂ tag ntag
              (fieldsTerm ((.atom a, .tuple #[meet, boolAtom (o₁ && o₂)]) :: acc)) (Term.list negs) (.map S)) Bool.true := by
        have e₁ := em m hm2
        have e₂ := ed m hm2
        have i₁ := hmeet m hm2
        have d₁ := hdiff m hm2
        have revD := reverse_fields acc ((.atom a, .tuple #[diff, boolAtom (o₁ && !o₂)]) :: t₁)
        have revT := reverse_fields acc ((.atom a, .tuple #[ty, boolAtom o₁]) :: t₁)
        simp only [fieldsTerm_cons] at revD revT ⊢
        rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/10».eq_def]
        cases bm <;> cases bd <;> simp [e₁, e₂, i₁, d₁, revD, revT, Lynx.Except.guard, isMember]
      rw [unfold10] at run
      have atA : ∀ w f, MSem den tag (acc.reverse ++ (.atom a, f) :: t₁) w → FieldSem den f (w (.atom a)) := by
        intro w f hw
        have := hw a
        unfold FSem at this
        rw [lookup_append, fresh] at this
        simpa [lookup_cons_atom] using this
      have recMeet := fun h => rec _ ⟨meet, _, rfl, lmeet⟩ semMeet h
      intro w hw
      have wa := atA w _ hw
      cases bm
      · cases bd
        · simp only [Bool.false_eq_true, ite_false, Lynx.Except.andAlso_eq_true] at run
          by_cases f₂a : FieldSem den (.tuple #[nt, boolAtom o₂]) (w (.atom a))
          · exact recMeet run.2 w (by simpa using msem_swap fresh hw ((semMeet (w (.atom a))).mpr ⟨wa, f₂a⟩))
          · exact Or.inr (lineS _ (fieldsV_mid sorted ⟨diff, _, rfl, ldiff⟩) run.1 w
              (msem_swap fresh hw ((semDiff (w (.atom a))).mpr ⟨wa, f₂a⟩)))
        · simp only [Bool.false_eq_true, ite_false, ite_true] at run
          have f₂a : FieldSem den (.tuple #[nt, boolAtom o₂]) (w (.atom a)) :=
            Classical.byContradiction fun nf => (emptyDiff.mp rfl) (w (.atom a)) ((semDiff (w (.atom a))).mpr ⟨wa, nf⟩)
          exact recMeet run w (by simpa using msem_swap fresh hw ((semMeet (w (.atom a))).mpr ⟨wa, f₂a⟩))
      · simp only [ite_true] at run
        exact Or.inr (lineS _ sorted run w hw)

    theorem fsem_lookup {tag : Term} {l : List (Term × Term)} {s : String} {f : Term}
        (h : mapLookup l (.atom s) = some f) (o : Option V) : FSem den tag l s o ↔ FieldSem den f o := by
      simp only [FSem, h]

    theorem fsem_default (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {tag : Term}
        (g : TagV E tag) {l : List (Term × Term)} {s : String} (h : mapLookup l (.atom s) = Option.none) (o : Option V) :
        FSem den tag l s o ↔ FieldSem den (tagField tag) o := by
      rw [fieldSem_tagV ops dops esem g]; simp only [FSem, h]

    /-- One key of a field walk, read from a `true` answer: a map of the line outside the remaining negations holds
    the negated field at the key. -/
    theorem recur_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 1 ≤ m) {S : List (Term × Term)} (hS : Safe S) {tag : Term} {negs : List Term}
        {fields : List (Term × Term)} (sf : FieldsV E fields)
        (lineS : ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l) (Term.list negs)
          (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w)
        (a : String) {f₁ f₂ : Term} (h₁ : FieldValue E f₁) (h₂ : FieldValue E f₂) {w : MW V}
        (hw : MSemExcept den tag fields a w) (wa : FieldSem den f₁ (w (.atom a))) (nc : ¬CovM den negs w)
        (run : Elixir.Module.Types.Descr.«map_line_fields_empty_recur?/7» (D m) (.atom a) f₁ f₂ tag (fieldsTerm fields)
          (Term.list negs) (.map S) = .ok (.atom "true")) :
        FieldSem den f₂ (w (.atom a)) := by
      obtain ⟨t₁, o₁, rfl, ht₁⟩ := h₁
      obtain ⟨t₂, o₂, rfl, ht₂⟩ := h₂
      have hm2 : K ≤ m := by omega
      obtain ⟨diff, ldiff, hdiff⟩ := dops.diff ht₁ ht₂
      obtain ⟨bd, ed⟩ := field_empty_total ops S ldiff (o₁ && !o₂)
      have semDiff := fieldSem_diff (t := diff) (esem.diff ht₁ ht₂ hm2 (hdiff m hm2)) (o₁ := o₁) (o₂ := o₂)
      have emptyDiff := field_empty_sem ops dops esem ldiff hS hm2 (ed m hm2)
      obtain ⟨l', runS, sl', -, look⟩ := store_val a ⟨diff, _, rfl, ldiff⟩ sf
      refine Classical.byContradiction fun nf => ?_
      have wd := (semDiff (w (.atom a))).mpr ⟨wa, nf⟩
      cases bd
      · have flag : Lynx.Except.andAlso (pure (boolAtom o₁)) (Erlang.erlang.«not/1» (boolAtom o₂)) Bool.true =
            .ok (boolAtom (o₁ && !o₂)) := by
          cases o₁ <;> cases o₂ <;> simp [boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1»]
        have e := ed m hm2
        have cover := fun r => nc (lineS l' sl' r w ((msem_store look w).mpr ⟨hw, wd⟩))
        generalize (o₁ && !o₂) = od at e runS flag
        rw [Elixir.Module.Types.Descr.«map_line_fields_empty_recur?/7».eq_def] at run
        simp only [hdiff m hm2, flag] at run
        simp [e, runS] at run
        exact cover run
      · exact (emptyDiff.mp rfl) _ wd

    /-- The fields left on the positive side of a field walk, read from a `true` answer. -/
    theorem pos_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 1 ≤ m) {S : List (Term × Term)} (hS : Safe S) {tag ntag : Term} (gn : TagV E ntag) {negs : List Term}
        {fields : List (Term × Term)} (sf : FieldsV E fields)
        (lineS : ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l) (Term.list negs)
          (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w)
        {nfields : List (Term × Term)} {w : MW V} (hw : MSem den tag fields w) (nc : ¬CovM den negs w) :
        ∀ (l P : List (Term × Term)), fields = P ++ l →
          (∀ e ∈ l, ∀ s : String, e.1 = .atom s → mapLookup nfields (.atom s) = Option.none) →
          Elixir.Module.Types.Descr.«map_line_fields_pos_empty?/6» (D m) (fieldsTerm l) (tagField ntag) tag
            (fieldsTerm fields) (Term.list negs) (.map S) = .ok (.atom "true") →
          ∀ e ∈ l, ∀ s : String, e.1 = .atom s → FSem den ntag nfields s (w (.atom s)) := by
      intro l
      induction l with
      | nil => intro _ _ _ _ e me; simp at me
      | cons x t ih =>
        intro P hP fresh run e me s es
        obtain ⟨k, f⟩ := x
        rw [Elixir.Module.Types.Descr.«map_line_fields_pos_empty?/6».eq_def] at run
        simp only [fieldsTerm_cons, Lynx.Except.andAlso_eq_true] at run
        have mem : (k, f) ∈ fields := by rw [hP]; simp
        obtain ⟨a, rfl⟩ := (sf.1 _ mem).1
        rcases List.mem_cons.mp me with rfl | me
        · simp only [Term.atom.injEq] at es
          subst es
          have wa := (fsem_lookup (lookup_of_mem sf mem rfl) _).mp (hw a)
          exact (fsem_default ops dops esem gn (fresh _ List.mem_cons_self _ rfl) _).mpr
            (recur_sound ops dops esem hm hS sf lineS a (sf.1 _ mem).2 (tagFieldV_value ops gn) ⟨fun s _ => hw s, hw.doms⟩
              wa nc run.1)
        · exact ih (P ++ [(.atom a, f)]) (by rw [hP]; simp) (fun e me => fresh e (List.mem_cons_of_mem _ me)) run.2 e me s es

    /-- The fields left on the negative side of a field walk, read from a `true` answer. -/
    theorem neg_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 1 ≤ m) {S : List (Term × Term)} (hS : Safe S) {tag ntag : Term} (gt : TagV E tag) {negs : List Term}
        {fields : List (Term × Term)} (sf : FieldsV E fields)
        (lineS : ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l) (Term.list negs)
          (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w)
        {nfields : List (Term × Term)} (snf : FieldsV E nfields) {w : MW V} (hw : MSem den tag fields w)
        (nc : ¬CovM den negs w) :
        ∀ (l Q : List (Term × Term)), nfields = Q ++ l →
          (∀ e ∈ l, ∀ s : String, e.1 = .atom s → mapLookup fields (.atom s) = Option.none) →
          Elixir.Module.Types.Descr.«map_line_fields_neg_empty?/6» (D m) (fieldsTerm l) (tagField tag) tag
            (fieldsTerm fields) (Term.list negs) (.map S) = .ok (.atom "true") →
          ∀ e ∈ l, ∀ s : String, e.1 = .atom s → FSem den ntag nfields s (w (.atom s)) := by
      intro l
      induction l with
      | nil => intro _ _ _ _ e me; simp at me
      | cons x t ih =>
        intro Q hQ fresh run e me s es
        obtain ⟨k, f⟩ := x
        rw [Elixir.Module.Types.Descr.«map_line_fields_neg_empty?/6».eq_def] at run
        simp only [fieldsTerm_cons, Lynx.Except.andAlso_eq_true] at run
        have mem : (k, f) ∈ nfields := by rw [hQ]; simp
        obtain ⟨a, rfl⟩ := (snf.1 _ mem).1
        rcases List.mem_cons.mp me with rfl | me
        · simp only [Term.atom.injEq] at es
          subst es
          have wa := (fsem_default ops dops esem gt (fresh _ List.mem_cons_self _ rfl) _).mp (hw a)
          exact (fsem_lookup (lookup_of_mem snf mem rfl) _).mpr
            (recur_sound ops dops esem hm hS sf lineS a (tagFieldV_value ops gt) (snf.1 _ mem).2 ⟨fun s _ => hw s, hw.doms⟩
              wa nc run.1)
        · exact ih (Q ++ [(.atom a, f)]) (by rw [hQ]; simp) (fun e me => fresh e (List.mem_cons_of_mem _ me)) run.2 e me s es

    /-- `map_line_fields_empty?/7` answers `true` only when every map of the line outside the remaining negations
    holds at the walked keys what the negated literal allows. -/
    theorem fields_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 1 ≤ m) {S : List (Term × Term)} (hS : Safe S) {tag ntag : Term} (gt : TagV E tag) (gn : TagV E ntag)
        {negs : List Term} {fields : List (Term × Term)} (sf : FieldsV E fields)
        (lineS : ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l) (Term.list negs)
          (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w)
        {nfields : List (Term × Term)} (snf : FieldsV E nfields) {w : MW V} (hw : MSem den tag fields w)
        (nc : ¬CovM den negs w) :
        ∀ N (P l₁ Q l₂ : List (Term × Term)), l₁.length + l₂.length ≤ N → fields = P ++ l₁ → nfields = Q ++ l₂ →
          (∀ a ∈ P ++ Q, ∀ b ∈ l₁ ++ l₂, Term.compare a.1 b.1 = .lt) →
          Elixir.Module.Types.Descr.«map_line_fields_empty?/7» (D m) (fieldsTerm l₁) (fieldsTerm l₂) tag ntag
            (fieldsTerm fields) (Term.list negs) (.map S) = .ok (.atom "true") →
          ∀ e ∈ l₁ ++ l₂, ∀ s : String, e.1 = .atom s → FSem den ntag nfields s (w (.atom s)) := by
      have d₁ := key_tag_field gt
      have d₂ := key_tag_field gn
      have recur := fun a {f₁ f₂ : Term} (h₁ : FieldValue E f₁) (h₂ : FieldValue E f₂) (wa : FieldSem den f₁ (w (.atom a))) r =>
        recur_sound ops dops esem hm hS sf lineS a h₁ h₂ (f₂ := f₂) ⟨fun s _ => hw s, hw.doms⟩ wa nc r
      -- lookups at a key of the walk in the walked sides and in the sides before it
      have lookPos : ∀ {P l₁ : List (Term × Term)} {a : String} {f : Term}, fields = P ++ l₁ → (.atom a, f) ∈ l₁ →
          mapLookup fields (.atom a) = some f := fun hP me => lookup_of_mem sf (e := (.atom _, _)) (by rw [hP]; simp [me]) rfl
      have lookNeg : ∀ {Q l₂ : List (Term × Term)} {a : String} {f : Term}, nfields = Q ++ l₂ → (.atom a, f) ∈ l₂ →
          mapLookup nfields (.atom a) = some f := fun hQ me => lookup_of_mem snf (e := (.atom _, _)) (by rw [hQ]; simp [me]) rfl
      have tails : ∀ P l₁ Q l₂, fields = P ++ l₁ → nfields = Q ++ l₂ →
          (∀ a ∈ P ++ Q, ∀ b ∈ l₁ ++ l₂, Term.compare a.1 b.1 = .lt) → (l₁ = [] ∨ l₂ = []) →
          Elixir.Module.Types.Descr.«map_line_fields_empty?/7» (D m) (fieldsTerm l₁) (fieldsTerm l₂) tag ntag
            (fieldsTerm fields) (Term.list negs) (.map S) = .ok (.atom "true") →
          ∀ e ∈ l₁ ++ l₂, ∀ s : String, e.1 = .atom s → FSem den ntag nfields s (w (.atom s)) := by
        intro P l₁ Q l₂ hP hQ below empty run
        have run' : Lynx.Except.andAlso
            (Elixir.Module.Types.Descr.«map_line_fields_pos_empty?/6» (D m) (fieldsTerm l₁) (tagField ntag) tag
              (fieldsTerm fields) (Term.list negs) (.map S))
            (Elixir.Module.Types.Descr.«map_line_fields_neg_empty?/6» (D m) (fieldsTerm l₂) (tagField tag) tag
              (fieldsTerm fields) (Term.list negs) (.map S)) Bool.true = .ok (.atom "true") := by
          rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
          rcases empty with rfl | rfl
          · cases l₂ <;> simpa [fieldsTerm, Term.list, d₁, d₂] using run
          · cases l₁ <;> simpa [fieldsTerm, Term.list, d₁, d₂] using run
        rw [Lynx.Except.andAlso_eq_true] at run'
        intro e me s es
        rcases List.mem_append.mp me with me | me
        · refine pos_sound ops dops esem hm hS gn sf lineS hw nc l₁ P hP (fun x mx s' es' => ?_) run'.1 e me s es
          rcases empty with rfl | rfl
          · simp at mx
          · rw [hQ]
            exact lookup_below fun y my => es' ▸ below y (by simp at my; simp [my]) x (by simp [mx])
        · refine neg_sound ops dops esem hm hS gt sf lineS snf hw nc l₂ Q hQ (fun x mx s' es' => ?_) run'.2 e me s es
          rcases empty with rfl | rfl
          · rw [hP]
            exact lookup_below fun y my => es' ▸ below y (by simp at my; simp [my]) x (by simp [mx])
          · simp at mx
      intro N
      induction N with
      | zero =>
        intro P l₁ Q l₂ size hP hQ below run
        exact tails P l₁ Q l₂ hP hQ below (Or.inl (List.eq_nil_of_length_eq_zero (by omega))) run
      | succ N ih =>
        intro P l₁ Q l₂ size hP hQ below run
        match l₁, l₂ with
        | [], l₂ => exact tails P [] Q l₂ hP hQ below (Or.inl rfl) run
        | x :: xs, [] => exact tails P _ Q [] hP hQ below (Or.inr rfl) run
        | (k₁, f₁) :: xs, (k₂, f₂) :: ys =>
          have m₁ : (k₁, f₁) ∈ fields := by rw [hP]; simp
          have m₂ : (k₂, f₂) ∈ nfields := by rw [hQ]; simp
          obtain ⟨a, rfl⟩ := (sf.1 _ m₁).1
          obtain ⟨b, rfl⟩ := (snf.1 _ m₂).1
          obtain ⟨t₁, o₁, rfl, ht₁⟩ := (sf.1 _ m₁).2
          obtain ⟨t₂, o₂, rfl, ht₂⟩ := (snf.1 _ m₂).2
          have fv₁ : FieldValue E (.tuple #[t₁, boolAtom o₁]) := ⟨t₁, o₁, rfl, ht₁⟩
          have fv₂ : FieldValue E (.tuple #[t₂, boolAtom o₂]) := ⟨t₂, o₂, rfl, ht₂⟩
          have s₁ : FieldsV E ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs) := by rw [hP] at sf; exact fieldsV_suffix sf
          have s₂ : FieldsV E ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys) := by rw [hQ] at snf; exact fieldsV_suffix snf
          have head₁ := fieldsV_head s₁
          have head₂ := fieldsV_head s₂
          simp only [List.length_cons] at size
          rcases cmp : Term.compare (.atom a) (.atom b)
          · -- the key is only in the positive map
            have above : ∀ y ∈ (Term.atom b, Term.tuple #[t₂, boolAtom o₂]) :: ys, Term.compare (.atom a) y.1 = .lt := by
              intro y my
              rcases List.mem_cons.mp my with rfl | my
              · exact cmp
              · exact cmp_lt_trans cmp (head₂ y my)
            have nnone : mapLookup nfields (.atom a) = Option.none := by
              rw [hQ, lookup_append, lookup_below fun e me => below e (by simp [me])
                (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) (by simp), lookup_above above]; rfl
            have below' : ∀ x ∈ (P ++ [(.atom a, .tuple #[t₁, boolAtom o₁])]) ++ Q, ∀ y ∈ xs ++ (.atom b, .tuple #[t₂, boolAtom o₂]) :: ys,
                Term.compare x.1 y.1 = .lt := by
              intro x mx y my
              simp only [List.mem_append, List.mem_singleton] at mx
              rcases mx with (mx | rfl) | mx
              · exact below x (by simp [mx]) y (by simp at my ⊢; rcases my with my | my <;> simp [my])
              · rcases List.mem_append.mp my with my | my
                · exact head₁ y my
                · exact above y my
              · exact below x (by simp [mx]) y (by simp at my ⊢; rcases my with my | my <;> simp [my])
            have rest := fun r => ih (P ++ [(.atom a, .tuple #[t₁, boolAtom o₁])]) xs Q _ (by simp; omega)
              (by rw [hP]; simp) hQ below' r
            have finish : (FSem den ntag nfields a (w (.atom a))) →
                Elixir.Module.Types.Descr.«map_line_fields_empty?/7» (D m) (fieldsTerm xs)
                  (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) tag ntag (fieldsTerm fields) (Term.list negs)
                  (.map S) = .ok (.atom "true") →
                ∀ e ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++ (.atom b, .tuple #[t₂, boolAtom o₂]) :: ys,
                  ∀ s : String, e.1 = .atom s → FSem den ntag nfields s (w (.atom s)) := by
              intro ha r e me s es
              rcases List.mem_cons.mp me with rfl | me
              · simp only [Term.atom.injEq] at es; subst es; exact ha
              · exact rest r e me s es
            have wa := (fsem_lookup (lookPos hP (List.mem_cons_self)) _).mp (hw a)
            by_cases no : ntag = .atom "open"
            · subst no
              rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
              simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», cmp] at run
              exact finish (by simp only [FSem, nnone]; exact Or.inl rfl) run
            by_cases nc' : ntag = .atom "closed"
            · subst nc'
              cases o₁
              · rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
                simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», cmp, boolAtom,
                  Lynx.Except.andAlso, Erlang.erlang.«not/1»] at run
              · rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
                simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», cmp, boolAtom,
                  Erlang.erlang.«not/1», d₂] at run
                exact finish ((fsem_default ops dops esem gn nnone _).mpr
                  (recur a fv₁ (tagFieldV_value ops gn) wa run.1)) run.2
            · rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
              simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», cmp, tag_eq_false no,
                tag_eq_false nc', d₂] at run
              exact finish ((fsem_default ops dops esem gn nnone _).mpr
                (recur a fv₁ (tagFieldV_value ops gn) wa run.1)) run.2
          · -- the key is in both maps
            have ab : a = b := Std.compare_eq_iff_eq.mp (by rw [← atoms_cmp]; exact cmp)
            subst ab
            rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
            simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», Erlang.erlang.«>/2», cmp] at run
            have wa := (fsem_lookup (lookPos hP (List.mem_cons_self (a := (Term.atom a, Term.tuple #[t₁, boolAtom o₁])))) _).mp
              (hw a)
            have ha := (fsem_lookup (tag := ntag) (lookNeg hQ (List.mem_cons_self (a := (Term.atom a, Term.tuple #[t₂, boolAtom o₂])))) _).mpr
              (recur a fv₁ fv₂ wa run.1)
            have below' : ∀ x ∈ (P ++ [(.atom a, .tuple #[t₁, boolAtom o₁])]) ++ (Q ++ [(.atom a, .tuple #[t₂, boolAtom o₂])]),
                ∀ y ∈ xs ++ ys, Term.compare x.1 y.1 = .lt := by
              intro x mx y my
              simp only [List.mem_append, List.mem_singleton] at mx
              have hy : Term.compare (.atom a) y.1 = .lt := by
                rcases List.mem_append.mp my with my | my
                · exact head₁ y my
                · exact head₂ y my
              rcases mx with (mx | rfl) | (mx | rfl)
              · exact below x (by simp [mx]) y (by rcases List.mem_append.mp my with my | my <;> simp [my])
              · exact hy
              · exact below x (by simp [mx]) y (by rcases List.mem_append.mp my with my | my <;> simp [my])
              · exact hy
            have rest := ih (P ++ [(.atom a, .tuple #[t₁, boolAtom o₁])]) xs (Q ++ [(.atom a, .tuple #[t₂, boolAtom o₂])]) ys
              (by omega) (by rw [hP]; simp) (by rw [hQ]; simp) below' run.2
            intro e me s es
            simp only [List.mem_append, List.mem_cons] at me
            rcases me with (rfl | me) | (rfl | me)
            · simp only [Term.atom.injEq] at es; subst es; exact ha
            · exact rest e (by simp [me]) s es
            · simp only [Term.atom.injEq] at es; subst es; exact ha
            · exact rest e (by simp [me]) s es
          · -- the key is only in the negative map
            have lt : Term.compare (.atom b) (.atom a) = .lt := Std.OrientedCmp.gt_iff_lt.mp cmp
            have above : ∀ y ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs, Term.compare (.atom b) y.1 = .lt := by
              intro y my
              rcases List.mem_cons.mp my with rfl | my
              · exact lt
              · exact cmp_lt_trans lt (head₁ y my)
            have pnone : mapLookup fields (.atom b) = Option.none := by
              rw [hP, lookup_append, lookup_below fun e me => below e (by simp [me])
                (Term.atom b, Term.tuple #[t₂, boolAtom o₂]) (by simp), lookup_above above]; rfl
            have below' : ∀ x ∈ P ++ (Q ++ [(.atom b, .tuple #[t₂, boolAtom o₂])]),
                ∀ y ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++ ys, Term.compare x.1 y.1 = .lt := by
              intro x mx y my
              have conv : y ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++ (.atom b, .tuple #[t₂, boolAtom o₂]) :: ys := by
                simp only [List.mem_append, List.mem_cons] at my ⊢
                rcases my with (my | my) | my
                · exact Or.inl (Or.inl my)
                · exact Or.inl (Or.inr my)
                · exact Or.inr (Or.inr my)
              simp only [List.mem_append, List.mem_singleton] at mx
              rcases mx with mx | (mx | rfl)
              · exact below x (by simp [mx]) y conv
              · exact below x (by simp [mx]) y conv
              · rcases List.mem_append.mp my with my | my
                · exact above y my
                · exact head₂ y my
            have rest := fun r => ih P _ (Q ++ [(.atom b, .tuple #[t₂, boolAtom o₂])]) ys (by simp; omega)
              hP (by rw [hQ]; simp) below' r
            have finish : FSem den ntag nfields b (w (.atom b)) →
                Elixir.Module.Types.Descr.«map_line_fields_empty?/7» (D m)
                  (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs)) (fieldsTerm ys) tag ntag (fieldsTerm fields)
                  (Term.list negs) (.map S) = .ok (.atom "true") →
                ∀ e ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++ (.atom b, .tuple #[t₂, boolAtom o₂]) :: ys,
                  ∀ s : String, e.1 = .atom s → FSem den ntag nfields s (w (.atom s)) := by
              intro hb r e me s es
              simp only [List.mem_append, List.mem_cons] at me
              rcases me with me | (rfl | me)
              · exact rest r e (by simp at me ⊢; rcases me with me | me <;> simp [me]) s es
              · simp only [Term.atom.injEq] at es; subst es; exact hb
              · exact rest r e (by simp [me]) s es
            have nb := lookNeg hQ (List.mem_cons_self (a := (Term.atom b, Term.tuple #[t₂, boolAtom o₂])))
            by_cases tc : tag = .atom "closed"
            · subst tc
              cases o₂
              · rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
                simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2»,
                  Erlang.erlang.«>/2», cmp, boolAtom, isMember] at run
              · rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
                simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2»,
                  Erlang.erlang.«>/2», cmp, boolAtom, isMember] at run
                have wb : w (.atom b) = Option.none := by
                  have := hw b
                  simp only [FSem, pnone, TagSem] at this
                  rcases this with h | h
                  · exact absurd h (by decide)
                  · exact h
                exact finish ((fsem_lookup nb _).mpr (by rw [wb, fieldSem_mk]; exact Or.inl ⟨rfl, rfl⟩)) run
            · rw [Elixir.Module.Types.Descr.«map_line_fields_empty?/7».eq_def] at run
              simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», Erlang.erlang.«>/2», cmp,
                tag_eq_false tc, d₁] at run
              have wb := (fsem_default ops dops esem gt pnone _).mp (hw b)
              exact finish ((fsem_lookup nb _).mpr (recur b (tagFieldV_value ops gt) fv₂ wb run.1)) run.2

    /-- `map_line_meet_empty?/7` answers `true` only when every map of the line, with the meets of the walked fields, is in
    the negated literal or covered by the remaining negations. -/
    theorem meet_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat} (hm : K + 1 ≤ m)
        {S : List (Term × Term)} (hS : Safe S) (tag ntag : Term) (gt : TagV E tag)
        (gn : TagV E ntag) (tagOk : tag = .atom "closed" ∨ ntag = .atom "open") (negs : List Term)
        (lineS : ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l)
          (Term.list negs) (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w)
        (nfields : List (Term × Term)) (snf : FieldsV E nfields) :
        ∀ N (l₁ l₂ : List (Term × Term)), l₁.length + l₂.length ≤ N →
        ∀ (pre acc : List (Term × Term)), nfields = pre ++ l₂ → FieldsV E (acc.reverse ++ l₁) →
          (∀ a ∈ pre ++ acc, ∀ b ∈ l₁ ++ l₂, Term.compare a.1 b.1 = .lt) →
          (∀ e ∈ acc, ∃ s : String, e.1 = .atom s ∧ ∀ o, FieldSem den e.2 o → FSem den ntag nfields s o) →
          (∀ e ∈ pre, ∃ e' ∈ acc, e.1 = e'.1) →
          Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm l₁) (fieldsTerm l₂) tag
            ntag (fieldsTerm acc) (Term.list negs) (.map S) = .ok (.atom "true") →
          ∀ w, MSem den tag (acc.reverse ++ l₁) w → MSem den ntag nfields w ∨ CovM den negs w := by
      -- the walk is over: the line is in the negated literal
      have base : ∀ (pre acc : List (Term × Term)), nfields = pre → FieldsV E acc.reverse →
          (∀ e ∈ acc, ∃ s : String, e.1 = .atom s ∧ ∀ o, FieldSem den e.2 o → FSem den ntag nfields s o) →
          (∀ e ∈ pre, ∃ e' ∈ acc, e.1 = e'.1) →
          ∀ w, MSem den tag acc.reverse w → MSem den ntag nfields w := by
        intro pre acc hpre sacc accN preIn w hw
        refine ⟨fun s => ?_, fun k i => ?_⟩
        rotate_left
        · rcases tagOk with rfl | rfl
          · exact (hw.doms k i).resolve_left (by decide) ▸ tagSem_none _ _
          · exact Or.inl rfl
        by_cases hs : ∃ e ∈ acc, e.1 = .atom s
        · obtain ⟨e, me, es⟩ := hs
          have look := lookup_of_mem sacc (List.mem_reverse.mpr me) es
          have := hw s
          unfold FSem at this
          rw [look] at this
          obtain ⟨s', es', ok⟩ := accN e me
          rw [es] at es'
          simp only [Term.atom.injEq] at es'
          subst es'
          exact ok _ this
        · have none₁ : mapLookup acc.reverse (.atom s) = Option.none :=
            lookup_none fun e me eq => hs ⟨e, List.mem_reverse.mp me, eq⟩
          have none₂ : mapLookup nfields (.atom s) = Option.none := by
            refine lookup_none fun e me eq => hs ?_
            rw [hpre] at me
            obtain ⟨e', me', ee⟩ := preIn e me
            exact ⟨e', me', ee ▸ eq⟩
          have := hw s
          simp only [FSem, none₁] at this
          simp only [FSem, none₂]
          rcases tagOk with rfl | rfl
          · exact (this.resolve_left (by decide)) ▸ tagSem_none _ _
          · exact Or.inl rfl
      intro N
      induction N with
      | zero =>
        intro l₁ l₂ size pre acc hpre sacc below accN preIn run
        have : l₁ = [] ∧ l₂ = [] := by constructor <;> (apply List.eq_nil_of_length_eq_zero; omega)
        obtain ⟨rfl, rfl⟩ := this
        intro w hw
        exact Or.inl (base pre acc (by simpa using hpre) (by simpa using sacc) accN preIn w (by simpa using hw))
      | succ N ih =>
        intro l₁ l₂ size pre acc hpre sacc below accN preIn run
        have s₂ : FieldsV E l₂ := by rw [hpre] at snf; exact fieldsV_suffix snf
        have s₁ : FieldsV E l₁ := fieldsV_suffix sacc
        have accBelow : ∀ e ∈ acc.reverse, ∀ b ∈ l₁ ++ l₂, Term.compare e.1 b.1 = .lt := fun e me b mb =>
          below e (by simp at me ⊢; simp [me]) b mb
        have preBelow : ∀ e ∈ pre, ∀ b ∈ l₁ ++ l₂, Term.compare e.1 b.1 = .lt := fun e me b mb =>
          below e (by simp [me]) b mb
        -- the key only in the positive map
        have posStep : ∀ (a : String) (f₁ : Term) (xs : List (Term × Term)), l₁ = (.atom a, f₁) :: xs →
            (∀ y ∈ l₂, Term.compare (.atom a) y.1 = .lt) →
            Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) f₁ (tagField ntag)
              (fieldsTerm xs) (fieldsTerm l₂) tag ntag (fieldsTerm acc) (Term.list negs) (.map S) =
                .ok (.atom "true") →
            ∀ w, MSem den tag (acc.reverse ++ l₁) w → MSem den ntag nfields w ∨ CovM den negs w := by
          intro a f₁ xs e₁ above r10
          subst e₁
          have mem₁ : (Term.atom a, f₁) ∈ (Term.atom a, f₁) :: xs ++ l₂ := by simp
          have fresh : mapLookup acc.reverse (.atom a) = Option.none :=
            lookup_below fun e me => accBelow e me _ mem₁
          have nnone : mapLookup nfields (.atom a) = Option.none := by
            rw [hpre, lookup_append, lookup_below fun e me => preBelow e me _ mem₁, lookup_above above]; rfl
          refine meet_field_sound ops dops esem hm hS tag ntag negs a f₁ (tagField ntag)
            (s₁.1 _ List.mem_cons_self).2 (tagFieldV_value ops gn) (fieldsTerm l₂) xs acc sacc fresh lineS
            (fun f hf sem r7 w hw => ?_) r10
          refine ih xs l₂ (by simp at size; omega) pre ((.atom a, f) :: acc) hpre (by simpa using fieldsV_mid sacc hf)
            (fun x mx y my => ?_) (fun e me => ?_) (fun e me => ?_) r7 w (by simpa using hw)
          · simp only [List.mem_append, List.mem_cons] at mx my
            have head := fieldsV_head s₁
            rcases mx with mx | rfl | mx
            · exact preBelow x mx y (by rcases my with my | my <;> simp [my])
            · rcases my with my | my
              · exact head y my
              · exact above y my
            · exact below x (by simp [mx]) y (by rcases my with my | my <;> simp [my])
          · rcases List.mem_cons.mp me with rfl | me
            · refine ⟨a, rfl, fun o ho => ?_⟩
              exact (fsem_default ops dops esem gn nnone o).mpr ((sem o).mp ho).2
            · exact accN e me
          · obtain ⟨e', me', ee⟩ := preIn e me
            exact ⟨e', List.mem_cons_of_mem _ me', ee⟩
        -- the key only in the negative map
        have negStep : ∀ (b : String) (f₂ : Term) (ys : List (Term × Term)), l₂ = (.atom b, f₂) :: ys →
            (∀ y ∈ l₁, Term.compare (.atom b) y.1 = .lt) →
            Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom b) (tagField tag) f₂
              (fieldsTerm l₁) (fieldsTerm ys) tag ntag (fieldsTerm acc) (Term.list negs) (.map S) =
                .ok (.atom "true") →
            ∀ w, MSem den tag (acc.reverse ++ l₁) w → MSem den ntag nfields w ∨ CovM den negs w := by
          intro b f₂ ys e₂ above r10
          subst e₂
          have mem₂ : (Term.atom b, f₂) ∈ l₁ ++ (Term.atom b, f₂) :: ys := by simp
          have fresh : mapLookup acc.reverse (.atom b) = Option.none :=
            lookup_below fun e me => accBelow e me _ mem₂
          have none₁ : mapLookup l₁ (.atom b) = Option.none := lookup_above above
          have nsome : mapLookup nfields (.atom b) = some f₂ := by
            rw [hpre]; exact lookup_head (lookup_below fun e me => preBelow e me _ mem₂)
          have sorted : FieldsV E (acc.reverse ++ (.atom b, tagField tag) :: l₁) :=
            fieldsV_insert sacc (fun e me => accBelow e me _ mem₂) above ⟨b, rfl⟩ (tagFieldV_value ops gt)
          intro w hw
          refine meet_field_sound ops dops esem hm hS tag ntag negs b (tagField tag) f₂
            (tagFieldV_value ops gt) (s₂.1 _ List.mem_cons_self).2 (fieldsTerm ys) l₁ acc sorted fresh lineS
            (fun f hf sem r7 w hw => ?_) r10 w ((msem_defaultV ops dops esem gt none₁ w).mpr hw)
          refine ih l₁ ys (by simp at size; omega) (pre ++ [(.atom b, f₂)]) ((.atom b, f) :: acc)
            (by rw [hpre]; simp) (by simpa using fieldsV_mid sorted hf) (fun x mx y my => ?_) (fun e me => ?_)
            (fun e me => ?_) r7 w (by simpa using hw)
          · simp only [List.mem_append, List.mem_cons, List.mem_singleton, List.not_mem_nil, or_false] at mx my
            have head := fieldsV_head s₂
            rcases mx with (mx | rfl) | rfl | mx
            · exact preBelow x mx y (by rcases my with my | my <;> simp [my])
            · rcases my with my | my
              · exact above y my
              · exact head y my
            · rcases my with my | my
              · exact above y my
              · exact head y my
            · exact below x (by simp [mx]) y (by rcases my with my | my <;> simp [my])
          · rcases List.mem_cons.mp me with rfl | me
            · refine ⟨b, rfl, fun o ho => ?_⟩
              unfold FSem
              rw [nsome]
              exact ((sem o).mp ho).2
            · exact accN e me
          · rcases List.mem_append.mp me with me | me
            · obtain ⟨e', me', ee⟩ := preIn e me
              exact ⟨e', List.mem_cons_of_mem _ me', ee⟩
            · simp at me; subst me; exact ⟨_, List.mem_cons_self, rfl⟩
        have key₁ : ∀ x ∈ l₁, ∃ a : String, x.1 = .atom a := fun x mx => (s₁.1 x mx).1
        have key₂ : ∀ x ∈ l₂, ∃ a : String, x.1 = .atom a := fun x mx => (s₂.1 x mx).1
        cases l₁ with
        | nil =>
          cases l₂ with
          | nil =>
            intro w hw
            exact Or.inl (base pre acc (by simpa using hpre) (by simpa using sacc) accN preIn w (by simpa using hw))
          | cons y ys =>
            obtain ⟨k₂, f₂⟩ := y
            obtain ⟨b, rfl⟩ := key₂ _ List.mem_cons_self
            have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm [])
                (fieldsTerm ((.atom b, f₂) :: ys)) tag ntag (fieldsTerm acc) (Term.list negs) (.map S) =
                Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom b) (tagField tag) f₂
                  (fieldsTerm []) (fieldsTerm ys) tag ntag (fieldsTerm acc) (Term.list negs) (.map S) := by
              rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
              simp [fieldsTerm, Term.list, key_tag_field gt]
            rw [e] at run
            exact negStep b f₂ ys rfl (by simp) run
        | cons x xs =>
          obtain ⟨k₁, f₁⟩ := x
          obtain ⟨a, rfl⟩ := key₁ _ List.mem_cons_self
          cases l₂ with
          | nil =>
            have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm ((.atom a, f₁) :: xs))
                (fieldsTerm []) tag ntag (fieldsTerm acc) (Term.list negs) (.map S) =
                Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) f₁ (tagField ntag)
                  (fieldsTerm xs) (fieldsTerm []) tag ntag (fieldsTerm acc) (Term.list negs) (.map S) := by
              rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
              simp [fieldsTerm, Term.list, key_tag_field gn]
            rw [e] at run
            exact posStep a f₁ xs rfl (by simp) run
          | cons y ys =>
            obtain ⟨k₂, f₂⟩ := y
            obtain ⟨b, rfl⟩ := key₂ _ List.mem_cons_self
            obtain ⟨t₁, o₁, rfl, ht₁⟩ := (s₁.1 _ List.mem_cons_self).2
            obtain ⟨t₂, o₂, rfl, ht₂⟩ := (s₂.1 _ List.mem_cons_self).2
            have head₁ := fieldsV_head s₁
            have head₂ := fieldsV_head s₂
            simp only [List.length_cons] at size
            rcases cmp : Term.compare (.atom a) (.atom b)
            · have above : ∀ y ∈ (Term.atom b, Term.tuple #[t₂, boolAtom o₂]) :: ys, Term.compare (.atom a) y.1 = .lt := by
                intro y my
                rcases List.mem_cons.mp my with rfl | my
                · exact cmp
                · exact cmp_lt_trans cmp (head₂ y my)
              rcases gn with rfl | rfl | ⟨dl, rfl, dv⟩
              · have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                    (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                    (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) tag (.atom "open") (fieldsTerm acc)
                    (Term.list negs) (.map S) =
                    Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm xs)
                    (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) tag (.atom "open")
                    (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: acc)) (Term.list negs) (.map S) := by
                  rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                  simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», cmp]
                rw [e] at run
                have mem₁ : (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++
                    (Term.atom b, Term.tuple #[t₂, boolAtom o₂]) :: ys := by simp
                have nnone : mapLookup nfields (.atom a) = Option.none := by
                  rw [hpre, lookup_append, lookup_below fun e me => preBelow e me _ mem₁, lookup_above above]; rfl
                intro w hw
                refine ih xs _ (by simp; omega) pre ((.atom a, .tuple #[t₁, boolAtom o₁]) :: acc) hpre (by simpa using sacc)
                  (fun x mx y my => ?_) (fun e me => ?_) (fun e me => ?_) run w (by simpa using hw)
                · simp only [List.mem_append, List.mem_cons] at mx my
                  rcases mx with mx | rfl | mx
                  · exact preBelow x mx y (by rcases my with my | my <;> simp [my])
                  · rcases my with my | my
                    · exact head₁ y my
                    · exact above y (by simpa using my)
                  · exact below x (by simp [mx]) y (by rcases my with my | my <;> simp [my])
                · rcases List.mem_cons.mp me with rfl | me
                  · exact ⟨a, rfl, fun o _ => by simp only [FSem, nnone]; exact Or.inl rfl⟩
                  · exact accN e me
                · obtain ⟨e', me', ee⟩ := preIn e me
                  exact ⟨e', List.mem_cons_of_mem _ me', ee⟩
              · cases o₁
                · exfalso
                  rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def] at run
                  simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», cmp, boolAtom,
                    Lynx.Except.andAlso, Erlang.erlang.«not/1»] at run
                · have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                      (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom Bool.true]) :: xs))
                      (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) tag (.atom "closed") (fieldsTerm acc)
                      (Term.list negs) (.map S) =
                      Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) (.tuple #[t₁, boolAtom Bool.true])
                        (tagField (.atom "closed")) (fieldsTerm xs) (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys))
                        tag (.atom "closed") (fieldsTerm acc) (Term.list negs) (.map S) := by
                    rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                    simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», cmp, boolAtom,
                      Lynx.Except.andAlso, Erlang.erlang.«not/1», tag_field, tagField, tagType]
                  rw [e] at run
                  exact posStep a _ xs rfl above run
              · have kd := key_tag_field (E := E) (Or.inr (Or.inr ⟨dl, rfl, dv⟩))
                have no := fieldsTerm_ne_atom dl "open"
                have nc := fieldsTerm_ne_atom dl "closed"
                have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                    (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                    (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) tag (fieldsTerm dl) (fieldsTerm acc)
                    (Term.list negs) (.map S) =
                    Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) (.tuple #[t₁, boolAtom o₁])
                      (tagField (fieldsTerm dl)) (fieldsTerm xs) (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys))
                      tag (fieldsTerm dl) (fieldsTerm acc) (Term.list negs) (.map S) := by
                  generalize fieldsTerm dl = T at kd no nc ⊢
                  rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                  simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», cmp, tag_eq_false no,
                    tag_eq_false nc, Lynx.Except.andAlso, kd]
                rw [e] at run
                exact posStep a _ xs rfl above run
            · have ab : a = b := Std.compare_eq_iff_eq.mp (by rw [← atoms_cmp]; exact cmp)
              subst ab
              have mem₁ : (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++
                  (Term.atom a, Term.tuple #[t₂, boolAtom o₂]) :: ys := by simp
              have mem₂ : (Term.atom a, Term.tuple #[t₂, boolAtom o₂]) ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs ++
                  (Term.atom a, Term.tuple #[t₂, boolAtom o₂]) :: ys := by simp
              have fresh : mapLookup acc.reverse (.atom a) = Option.none := lookup_below fun e me => accBelow e me _ mem₁
              have nsome : mapLookup nfields (.atom a) = some (.tuple #[t₂, boolAtom o₂]) := by
                rw [hpre]; exact lookup_head (lookup_below fun e me => preBelow e me _ mem₂)
              have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                  (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                  (fieldsTerm ((.atom a, .tuple #[t₂, boolAtom o₂]) :: ys)) tag ntag (fieldsTerm acc)
                  (Term.list negs) (.map S) =
                  Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom a) (.tuple #[t₁, boolAtom o₁])
                    (.tuple #[t₂, boolAtom o₂]) (fieldsTerm xs) (fieldsTerm ys) tag ntag (fieldsTerm acc)
                    (Term.list negs) (.map S) := by
                rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                have notLt : ¬(Term.compare (.atom a) (.atom a)).isLT = Bool.true := by simp [cmp]
                have notGt : ¬(Term.compare (.atom a) (.atom a)).isGT = Bool.true := by simp [cmp]
                simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2»,
                  Erlang.erlang.«>/2», cmp]
              rw [e] at run
              refine meet_field_sound ops dops esem hm hS tag ntag negs a _ _ ⟨t₁, o₁, rfl, ht₁⟩
                ⟨t₂, o₂, rfl, ht₂⟩ (fieldsTerm ys) xs acc sacc fresh lineS (fun f hf sem r7 w hw => ?_) run
              refine ih xs ys (by omega) (pre ++ [(.atom a, .tuple #[t₂, boolAtom o₂])]) ((.atom a, f) :: acc)
                (by rw [hpre]; simp) (by simpa using fieldsV_mid sacc hf) (fun x mx y my => ?_) (fun e me => ?_)
                (fun e me => ?_) r7 w (by simpa using hw)
              · simp only [List.mem_append, List.mem_cons, List.mem_singleton, List.not_mem_nil, or_false] at mx my
                have kx : ∀ y, y ∈ xs ∨ y ∈ ys → Term.compare (.atom a) y.1 = .lt := fun y my => by
                  rcases my with my | my
                  · exact head₁ y my
                  · exact head₂ y my
                rcases mx with (mx | rfl) | rfl | mx
                · exact preBelow x mx y (by rcases my with my | my <;> simp [my])
                · exact kx y my
                · exact kx y my
                · exact below x (by simp [mx]) y (by rcases my with my | my <;> simp [my])
              · rcases List.mem_cons.mp me with rfl | me
                · refine ⟨a, rfl, fun o ho => ?_⟩
                  unfold FSem
                  rw [nsome]
                  exact ((sem o).mp ho).2
                · exact accN e me
              · rcases List.mem_append.mp me with me | me
                · obtain ⟨e', me', ee⟩ := preIn e me
                  exact ⟨e', List.mem_cons_of_mem _ me', ee⟩
                · simp at me; subst me; exact ⟨_, List.mem_cons_self, rfl⟩
            · have lt : Term.compare (.atom b) (.atom a) = .lt := Std.OrientedCmp.gt_iff_lt.mp cmp
              have above : ∀ y ∈ (Term.atom a, Term.tuple #[t₁, boolAtom o₁]) :: xs, Term.compare (.atom b) y.1 = .lt := by
                intro y my
                rcases List.mem_cons.mp my with rfl | my
                · exact lt
                · exact cmp_lt_trans lt (head₁ y my)
              rcases gt with rfl | rfl | ⟨dl, rfl, dv⟩
              · have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                    (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                    (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) (.atom "open") ntag (fieldsTerm acc)
                    (Term.list negs) (.map S) =
                    Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom b) (tagField (.atom "open"))
                      (.tuple #[t₂, boolAtom o₂]) (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs)) (fieldsTerm ys)
                      (.atom "open") ntag (fieldsTerm acc) (Term.list negs) (.map S) := by
                  rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                  simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2», Erlang.erlang.«>/2»,
                    cmp, boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1», tag_field, tagField, tagType]
                rw [e] at run
                exact negStep b _ ys rfl above run
              · cases o₂
                · exfalso
                  rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def] at run
                  simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2»,
                    Erlang.erlang.«>/2», cmp, boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1»] at run
                · have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                      (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                      (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom Bool.true]) :: ys)) (.atom "closed") ntag
                      (fieldsTerm acc) (Term.list negs) (.map S) =
                      Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom b) (tagField (.atom "closed"))
                        (.tuple #[t₂, boolAtom Bool.true]) (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                        (fieldsTerm ys) (.atom "closed") ntag (fieldsTerm acc) (Term.list negs) (.map S) := by
                    rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                    simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«==/2», Erlang.erlang.«</2»,
                      Erlang.erlang.«>/2», cmp, boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1», tag_field, tagField, tagType]
                  rw [e] at run
                  exact negStep b _ ys rfl above run
              · have kd := key_tag_field (E := E) (Or.inr (Or.inr ⟨dl, rfl, dv⟩))
                have nc := fieldsTerm_ne_atom dl "closed"
                have e : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m)
                    (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs))
                    (fieldsTerm ((.atom b, .tuple #[t₂, boolAtom o₂]) :: ys)) (fieldsTerm dl) ntag (fieldsTerm acc)
                    (Term.list negs) (.map S) =
                    Elixir.Module.Types.Descr.«map_line_meet_empty?/10» (D m) (.atom b) (tagField (fieldsTerm dl))
                      (.tuple #[t₂, boolAtom o₂]) (fieldsTerm ((.atom a, .tuple #[t₁, boolAtom o₁]) :: xs)) (fieldsTerm ys)
                      (fieldsTerm dl) ntag (fieldsTerm acc) (Term.list negs) (.map S) := by
                  generalize fieldsTerm dl = T at kd nc ⊢
                  rw [Elixir.Module.Types.Descr.«map_line_meet_empty?/7».eq_def]
                  simp [fieldsTerm, Term.list, Lynx.Except.guard, Erlang.erlang.«</2», Erlang.erlang.«>/2», cmp,
                    tag_eq_false nc, Lynx.Except.andAlso, kd]
                rw [e] at run
                exact negStep b _ ys rfl above run

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    variable {E : Term → Prop} {K : Nat} {V : Type} {den : Term → V → Prop} {Safe : List (Term × Term) → Prop}

    theorem domKind_mem (k : Fin 11) : domKind k ∈ domainKinds := by
      revert k; decide

    /-- `map_line_empty?/4` answers `true` only when its negations cover every map of the line. -/
    theorem line_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 1 ≤ m) {S : List (Term × Term)} (hS : Safe S) :
        ∀ negs : List Term, (∀ t ∈ negs, MapLitV E t) → ∀ tag : Term, TagV E tag →
          ∀ l, FieldsV E l → Elixir.Module.Types.Descr.«map_line_empty?/4» (D m) tag (fieldsTerm l)
            (Term.list negs) (.map S) = .ok (.atom "true") → ∀ w, MSem den tag l w → CovM den negs w := by
      intro negs
      induction negs with
      | nil =>
        intro _ tag _ l _ run
        rw [Elixir.Module.Types.Descr.«map_line_empty?/4».eq_def] at run
        simp [Term.list] at run
      | cons N rest ih =>
        intro lits tag gt l sl run w hw
        obtain ⟨k, ntag, nl, rfl, gn, snl⟩ := lits _ List.mem_cons_self
        have lits' : ∀ t ∈ rest, MapLitV E t := fun t m => lits t (List.mem_cons_of_mem _ m)
        have later : CovM den rest w → CovM den (.tuple #[.integer k, ntag, fieldsTerm nl] :: rest) w :=
          fun ⟨N, mN, hN⟩ => ⟨N, List.mem_cons_of_mem _ mN, hN⟩
        by_cases top : ntag = .atom "open" ∧ nl = []
        · obtain ⟨rfl, rfl⟩ := top
          exact ⟨_, List.mem_cons_self, nsem_lit.mpr ⟨fun s => fsem_nil.mpr (Or.inl rfl), fun k i => Or.inl rfl⟩⟩
        by_cases skip : tag = .atom "open" ∧ ntag = .atom "closed"
        · obtain ⟨rfl, rfl⟩ := skip
          rw [list_cons, Elixir.Module.Types.Descr.«map_line_empty?/4».eq_def] at run
          exact later (ih lits' _ gt l sl (by simpa using run) w hw)
        by_cases cov : CovM den rest w
        · exact later cov
        have lineS := fun l' (sl' : FieldsV E l') r w' (hw' : MSem den tag l' w') => ih lits' tag gt l' sl' r w' hw'
        have hl : ∀ e ∈ l, FieldValue E e.2 := fun e me => (sl.1 e me).2
        have hnl : ∀ e ∈ nl, FieldValue E e.2 := fun e me => (snl.1 e me).2
        have ih' := map_line_total ops dops S rest fun t mt => (lits' t mt).plain
        obtain ⟨bc, runc, incl⟩ := check_val ops dops esem hm hS gt gn skip
        obtain ⟨c, hor, tagOk, branch⟩ := line_branch_of ops dops S ih' gt.plain gn.plain hl hnl
        obtain ⟨bk, hk⟩ := ih' tag gt.plain l hl
        have hk' := hk m hm
        -- the remaining negations answer `false`, as they do not cover the map
        have nk : bk = Bool.false := by
          cases bk
          · rfl
          · exact absurd (lineS l sl (by simpa [boolAtom] using hk') w hw) cov
        subst nk
        -- so the walk answers `true`, and the negated literal holds the map
        refine ⟨_, List.mem_cons_self, ?_⟩
        rcases branch with ⟨b, hb⟩ | hb
        · have r := line_general (k := k) top skip runc hor hk' (Or.inl (hb m hm))
          rw [r] at run
          cases bc
          · simp [boolAtom] at run
          cases b
          · simp [boolAtom] at run
          have hb' := hb m hm
          cases c
          · have walk : Elixir.Module.Types.Descr.«map_line_fields_empty?/7» (D m) (fieldsTerm l) (fieldsTerm nl) tag ntag
                (fieldsTerm l) (Term.list rest) (.map S) = .ok (.atom "true") := by simpa [boolAtom] using hb'
            have keys := fields_sound ops dops esem hm hS gt gn sl lineS snl hw cov _ [] l [] nl (Nat.le_refl _)
              (by simp) (by simp) (by simp) walk
            have tin := incl.mp rfl
            refine nsem_lit.mpr ⟨fun s => ?_, fun k i => tin _ (domKind_mem k) _ (hw.doms k i)⟩
            by_cases hs : ∃ e ∈ l ++ nl, e.1 = .atom s
            · obtain ⟨e, me, es⟩ := hs
              exact keys e me s es
            · have n₁ : mapLookup l (.atom s) = Option.none := lookup_none fun e me eq => hs ⟨e, by simp [me], eq⟩
              have n₂ : mapLookup nl (.atom s) = Option.none := lookup_none fun e me eq => hs ⟨e, by simp [me], eq⟩
              have := hw s
              simp only [FSem, n₁] at this
              simp only [FSem, n₂]
              exact tin "atom" (by simp [domainKinds]) _ this
          · have walk : Elixir.Module.Types.Descr.«map_line_meet_empty?/7» (D m) (fieldsTerm l) (fieldsTerm nl) tag ntag
                (fieldsTerm []) (Term.list rest) (.map S) = .ok (.atom "true") := by simpa [boolAtom] using hb'
            rcases meet_sound ops dops esem hm hS tag ntag gt gn (tagOk rfl) rest lineS nl snl _ l nl (Nat.le_refl _)
                [] [] (by simp) (by simpa using sl) (by simp) (by simp) (by simp) walk w (by simpa using hw) with h | h
            · exact nsem_lit.mpr h
            · exact absurd h cov
        · have r := line_general (k := k) top skip runc hor hk' (Or.inr ⟨hb m hm, rfl⟩)
          rw [r] at run
          cases bc <;> simp [boolAtom] at run

    /-- `init_map_line_empty?/4` answers `true` only when its negations cover every map of the line. -/
    theorem init_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat} (hm : K + 1 ≤ m)
        {S : List (Term × Term)} (hS : Safe S) {tag : Term} (gt : TagV E tag) {l : List (Term × Term)}
        (sl : FieldsV E l) {negs : List Term} (lits : ∀ t ∈ negs, MapLitV E t)
        (run : Elixir.Module.Types.Descr.«init_map_line_empty?/4» (D m) tag (fieldsTerm l) (Term.list negs)
          (.map S) = .ok (.atom "true")) :
        ∀ w, MSem den tag l w → CovM den negs w := by
      obtain ⟨n, rfl, hn⟩ := succ_of_le (show 1 ≤ m by omega)
      have each : ∀ x ∈ l.map (fun e => Term.tuple #[e.1, e.2]),
          Elixir.Module.Types.Descr.«-init_map_line_empty?/4-fun-0-/2» (D n) (.map S) x = .ok (boolAtom (reqEmpty den x)) := by
        intro x mx
        obtain ⟨e, me, rfl⟩ := List.mem_map.mp mx
        obtain ⟨t, o, ho, ht⟩ := (sl.1 e me).2
        rw [ho]
        cases o
        · obtain ⟨b, hb⟩ := ops.empty ht S
          have run := hb n (by omega)
          have sem := esem.empty ht hS (by omega) run
          simp only [Elixir.Module.Types.Descr.«-init_map_line_empty?/4-fun-0-/2», boolAtom, Bool.false_eq_true,
            ite_false, reqEmpty]
          rw [run]
          cases b <;> simp at sem <;> simp [sem, boolAtom]
        · simp [Elixir.Module.Types.Descr.«-init_map_line_empty?/4-fun-0-/2», boolAtom, reqEmpty]
      have anyRun := any_list (D (n + 1)) _ _ _ (reqEmpty den) _ fun x mx => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-init_map_line_empty?/4-fun-0-/1».pure]
        exact each x mx
      rw [Elixir.Module.Types.Descr.«init_map_line_empty?/4».eq_def] at run
      simp only [fieldsTerm] at anyRun run
      simp only [pure_bind, anyRun] at run
      intro w hw
      cases hany : (l.map fun e => Term.tuple #[e.1, e.2]).any (reqEmpty den)
      · rw [hany] at run
        have := line_sound ops dops esem (show K + 1 ≤ n + 1 by omega) hS negs lits tag gt l sl
          (by simpa [boolAtom, Lynx.Except.orElse, fieldsTerm] using run) w hw
        exact this
      · exfalso
        obtain ⟨x, mx, rx⟩ := List.any_eq_true.mp hany
        obtain ⟨e, me, rfl⟩ := List.mem_map.mp mx
        obtain ⟨t, o, ho, ht⟩ := (sl.1 e me).2
        obtain ⟨s, es⟩ := (sl.1 e me).1
        have look := lookup_of_mem sl me es
        have := hw s
        unfold FSem at this
        rw [look, ho] at this
        simp only at this
        rw [fieldSem_mk] at this
        rw [ho] at rx
        cases o
        · simp [reqEmpty, boolAtom] at rx
          rcases this with ⟨-, h⟩ | ⟨y, -, hy⟩
          · cases h
          · exact rx y hy
        · simp [reqEmpty] at rx

    /-- `map_bdd_empty?/4` answers `true` only when no map along the path, outside the negations, satisfies the BDD. -/
    theorem map_bdd_sound (ops : ElemOk E K) (dops : ElemDiff E K) (esem : ElemSem E K V den Safe) {m : Nat}
        (hm : K + 2 ≤ m) (S : List (Term × Term)) (hS : Safe S) {ok : Term → Prop} {r : Term} (wr : Bdd ok r) :
        (∀ t, ok t → MapLitV E t) → ∀ pos negs, MapPosV E pos → (∀ t ∈ negs, MapLitV E t) →
          Elixir.Module.Types.Descr.«map_bdd_empty?/4» (D m) pos (Term.list negs) r (.map S) = .ok (.atom "true") →
          ValUnsatM E den pos negs r := by
      refine Bdd.induction (P := fun ok r => (∀ t, ok t → MapLitV E t) → ∀ pos negs, MapPosV E pos →
        (∀ t ∈ negs, MapLitV E t) →
        Elixir.Module.Types.Descr.«map_bdd_empty?/4» (D m) pos (Term.list negs) r (.map S) = .ok (.atom "true") →
        ValUnsatM E den pos negs r) ?_ ?_ ?_ ?_ ok r wr
      · intro ok _ pos negs hp lits run w hw nn
        obtain ⟨tag, l, rfl, gt, sl⟩ := hp
        rw [Elixir.Module.Types.Descr.«map_bdd_empty?/4».eq_def] at run
        simp only at run
        obtain ⟨N, mN, hN⟩ := init_sound ops dops esem (by omega) hS gt sl lits run w (inPosM_iff.mp hw)
        exact (nn N mN hN).elim
      · intro ok _ pos negs _ _ _ w _ _
        rfl
      · intro ok k x y okl okLit pos negs hp lits run w hw nn
        have hl := okLit _ okl
        rw [eval_leaf]
        cases e : valM E den w (.tuple #[.integer k, x, y])
        · rfl
        exfalso
        have hlit := valM_lit ops dops esem hl e
        rw [Elixir.Module.Types.Descr.«map_bdd_empty?/4».eq_def] at run
        rcases inter_val ops dops esem hm hS hp hl with ⟨empty, disj⟩ | ⟨pos', r', hp', sem'⟩
        · exact disj w hw hlit
        obtain ⟨tag, l, rfl, gt, sl⟩ := hp'
        simp [r'] at run
        obtain ⟨N, mN, hN⟩ := init_sound ops dops esem (by omega) hS gt sl lits run w
          (inPosM_iff.mp ((sem' w).mpr ⟨hw, hlit⟩))
        exact nn N mN hN
      · intro ok h lit c u d leaf okl hc hu hd ic iu idd okLit pos negs hp lits run w hw nn
        have hl := okLit _ okl
        have okLit' : ∀ t, Above ok lit t → MapLitV E t := fun t ht => okLit t ht.1
        have hp₀ := hp
        obtain ⟨tag, l, rfl, gt, sl⟩ := hp
        rw [Elixir.Module.Types.Descr.«map_bdd_empty?/4».eq_def] at run
        rcases inter_val ops dops esem hm hS hp₀ hl with ⟨empty, disj⟩ | ⟨pos2, r2, hp2, sem2⟩
        · simp only [empty, list_cons, Lynx.Except.andAlso_eq_true, Lynx.Except.ok_bind] at run
          obtain ⟨⟨rd, -⟩, ru⟩ := run
          have nl : valM E den w lit = Bool.false := by
            cases e : valM E den w lit
            · rfl
            · exact (disj w hw (valM_lit ops dops esem hl e)).elim
          have ed := idd okLit' _ (lit :: negs) hp₀ (fun t mt => by
            rcases List.mem_cons.mp mt with rfl | mt
            · exact hl
            · exact lits t mt) (by rwa [list_cons]) w hw (fun N mN hN => by
              rcases List.mem_cons.mp mN with rfl | mN
              · rw [valM_true hl hN] at nl; cases nl
              · exact nn N mN hN)
          have eu := iu okLit' _ negs hp₀ lits ru w hw nn
          simp [eval_node, nl, ed, eu]
        · have hp2' := hp2
          obtain ⟨tag2, l2, rfl, -⟩ := hp2
          simp only [r2, list_cons, Lynx.Except.andAlso_eq_true, Lynx.Except.ok_bind] at run
          obtain ⟨⟨rd, rc⟩, ru⟩ := run
          have eu := iu okLit' _ negs hp₀ lits ru w hw nn
          cases e : valM E den w lit
          · have ed := idd okLit' _ (lit :: negs) hp₀ (fun t mt => by
              rcases List.mem_cons.mp mt with rfl | mt
              · exact hl
              · exact lits t mt) (by rwa [list_cons]) w hw (fun N mN hN => by
                rcases List.mem_cons.mp mN with rfl | mN
                · rw [valM_true hl hN] at e; cases e
                · exact nn N mN hN)
            simp [eval_node, e, ed, eu]
          · have ec := ic okLit' _ negs hp2' lits rc w ((sem2 w).mpr ⟨hw, valM_lit ops dops esem hl e⟩) nn
            simp [eval_node, e, ec, eu]

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Map emptiness is exact under seen sets of higher BDDs. -/

    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    theorem lh_pair (a b : Term) : lh (.tuple #[a, b]) = max (lh a) (lh b) := by
      show lh (.tuple ⟨[a, b]⟩) = _
      rw [lh]

    theorem lh_fields_mem {l : List (Term × Term)} {e : Term × Term} (me : e ∈ l) {t : Term} {o : Bool}
        (he : e.2 = .tuple #[t, boolAtom o]) : lh t ≤ lh (fieldsTerm l) := by
      have := lh_list_mem (l := l.map fun e => .tuple #[e.1, e.2]) (List.mem_map.mpr ⟨e, me, rfl⟩)
      rw [he, lh_pair, lh_pair] at this
      exact Nat.le_trans (by omega) this

    theorem lh_litM {k : Int} {tag : Term} {l : List (Term × Term)} (g : TagV E tag)
        (top : ¬(tag = .atom "open" ∧ l = [])) :
        lh (.tuple #[.integer k, tag, fieldsTerm l]) = max (lh tag) (lh (fieldsTerm l)) + 1 :=
      lh_leaf _ _ _ (fun ⟨h₁, h₂⟩ => top ⟨h₁, fieldsTerm_eq_nil.mp h₂⟩)
        (fun ⟨_, _, h⟩ => fieldsTerm_ne_atom l "term" h)
        (by rintro ⟨-, r, a, b, h⟩; cases l <;> simp [fieldsTerm, Term.list] at h) (by simp)

    /-- Map literals other than the top one are one higher than their parts. -/
    theorem mlit_litZ {k a b : Term} (h : MLit E (.tuple #[k, a, b])) : litZ a b = Bool.false := by
      obtain ⟨⟨k', tag, l, e, g, -⟩, nt, -⟩ := h
      obtain ⟨-, rfl, rfl⟩ := tuple3_inj e
      unfold litZ
      split
      · rename_i r a b h; cases l <;> simp [fieldsTerm, Term.list] at h
      · rfl

    theorem mlit_lh_eq {k a b : Term} (h : MLit E (.tuple #[k, a, b])) : lh (.tuple #[k, a, b]) = max (lh a) (lh b) + 1 := by
      obtain ⟨⟨k', tag, l, e, g, -⟩, nt, -⟩ := h
      obtain ⟨-, e₂, e₃⟩ := tuple3_inj e
      have top : ¬(tag = .atom "open" ∧ l = []) := fun ⟨h₁, h₂⟩ => nt ⟨_, by rw [e, h₁, h₂]; rfl⟩
      rw [e, lh_litM g top, ← e₂, ← e₃]

    theorem mlit_lh {t : Term} (h : MLit E t) : 1 ≤ lh t ∧ ∀ (k : Int) (tag : Term) (l : List (Term × Term)),
        t = .tuple #[.integer k, tag, fieldsTerm l] →
          (∀ e ∈ l, ∀ u o, e.2 = .tuple #[u, boolAtom o] → lh u < lh t) ∧ ∀ e ∈ domFields tag, lh e.2 < lh t := by
      obtain ⟨⟨k, tag, l, rfl, g, sl⟩, nt, key⟩ := h
      have e₀ := mlit_lh_eq ⟨⟨k, tag, l, rfl, g, sl⟩, nt, key⟩
      refine ⟨by rw [e₀]; omega, fun k' tag' l' e => ?_⟩
      obtain ⟨-, e₂, e₃⟩ := tuple3_inj e
      have := fieldsTerm_inj e₃
      subst this e₂
      refine ⟨fun x mx u o hx => ?_, fun x mx => ?_⟩
      · have := lh_fields_mem mx hx; rw [e₀]; omega
      · rcases g with rfl | rfl | ⟨dl, rfl, -⟩
        · simp [domFields] at mx
        · simp [domFields] at mx
        · rw [domFields_fieldsTerm] at mx
          have := lh_list_mem (l := dl.map fun e => .tuple #[e.1, e.2]) (List.mem_map.mpr ⟨x, mx, rfl⟩)
          rw [lh_pair] at this
          have le : lh x.2 ≤ lh (fieldsTerm dl) := Nat.le_trans (by omega) this
          rw [e₀]; omega

    /-- Literals of map BDDs are no higher than the BDD. -/
    theorem mbdd_lh_le {ok : Term → Prop} {x : Term} (wx : Bdd ok x) (lits : ∀ t, ok t → MLit E t) :
        ∀ M, lh x ≤ M → Bdd (fun t => ok t ∧ lh t ≤ M) x := by
      revert lits
      refine Bdd.induction (P := fun ok x => (∀ t, ok t → MLit E t) → ∀ M, lh x ≤ M → Bdd (fun t => ok t ∧ lh t ≤ M) x)
        ?_ ?_ ?_ ?_ ok x wx
      · intro _ _ _ _; exact Bdd.top
      · intro _ _ _ _; exact Bdd.bot
      · intro ok k x y okl _ M le
        exact Bdd.leaf_iff.mpr ⟨okl, le⟩
      · intro ok h lit c u d leaf okl hc hu hd ic iu idd lits M le
        obtain ⟨k, a, b, rfl⟩ := leaf
        have hl := mlit_lh_eq (lits _ okl)
        have nd := lh_node (.integer h) (.integer k) a b c u d (mlit_litZ (lits _ okl))
        change lh (.tuple ⟨[.integer h, .tuple ⟨[.integer k, a, b]⟩, c, u, d]⟩) ≤ M at le
        have hlit : lh (.tuple #[.integer k, a, b]) ≤ M := by omega
        have hc' : lh c ≤ M ∧ lh u ≤ M ∧ lh d ≤ M := by omega
        have lits' : ∀ t, Above ok (.tuple #[.integer k, a, b]) t → MLit E t := fun t ht => lits t ht.1
        refine Bdd.node_iff.mpr ⟨⟨k, _, _, rfl⟩, ⟨okl, hlit⟩, ?_, ?_, ?_⟩
        · exact (ic lits' M hc'.1).mono fun t ht => ⟨⟨ht.1.1, ht.2⟩, ht.1.2⟩
        · exact (iu lits' M hc'.2.1).mono fun t ht => ⟨⟨ht.1.1, ht.2⟩, ht.1.2⟩
        · exact (idd lits' M hc'.2.2).mono fun t ht => ⟨⟨ht.1.1, ht.2⟩, ht.1.2⟩

    theorem mbdd_lh {x : Term} (wx : Bdd (MLit E) x) (nt : x ≠ .atom "bdd_top") (nb : x ≠ .atom "bdd_bot") :
        1 ≤ lh x := by
      rcases wx.shape with rfl | rfl | ⟨k, a, b, rfl⟩ | ⟨h, lit, c, u, d, rfl⟩
      · exact absurd rfl nt
      · exact absurd rfl nb
      · exact (mlit_lh (Bdd.leaf_iff.mp wx)).1
      · obtain ⟨⟨k, a, b, rfl⟩, okl, -⟩ := Bdd.node_iff.mp wx
        have := mlit_lh_eq okl
        have := lh_node (.integer h) (.integer k) a b c u d (mlit_litZ okl)
        change 1 ≤ lh (.tuple ⟨[.integer h, .tuple ⟨[.integer k, a, b]⟩, c, u, d]⟩)
        omega

    theorem map_empty_step {d : Dispatcher} {x : Term} {S : List (Term × Term)}
        (fresh : S.any (fun e => Term.exactCompare (.cons (.atom "map") x) e.1 == .eq) = Bool.false) :
        Elixir.Module.Types.Descr.«map_empty?/2» d x (.map S) =
          Elixir.Module.Types.Descr.«map_bdd_empty?/4» d (.tuple #[.atom "open", .nil]) .nil x
            (.map ((.cons (.atom "map") x, .atom "true") :: S)) := by
      unfold Elixir.Module.Types.Descr.«map_empty?/2»
      simp [Elixir.Module.Types.Descr.«empty_bdd_seen_key/2», Erlang.erlang.«is_map_key/2», fresh, Term.true,
        Term.false, Erlang.maps.«put/3»]

    theorem mlit_ok {t : Term} (h : MLit E t) : MapOk E t := by
      obtain ⟨⟨k, tag, l, rfl, g, sl⟩, nt, -⟩ := h
      exact ⟨⟨k, tag, l, rfl, g.plain, fun e me => (sl.1 e me).2⟩, nt⟩

    theorem init_open_nil (d : Dispatcher) (S : Term) :
        Elixir.Module.Types.Descr.«init_map_line_empty?/4» d (.atom "open") .nil .nil S = .ok (.atom "false") := by
      rw [Elixir.Module.Types.Descr.«init_map_line_empty?/4».eq_def]
      simp [Erlang.lists.«any/2», Lynx.Except.orElse, Erlang.erlang.«is_function/2»]
      rw [Elixir.Module.Types.Descr.«map_line_empty?/4».eq_def]
      simp

    /-- Map types decide their emptiness exactly, when the seen BDDs are higher than them. -/
    theorem map_empty_exact (ef : EF nd E V den tl K) {x : Term} (fx : MField E x) (S : List (Term × Term)) :
        ∃ b : Bool, (∀ m, K + 2 ≤ m → Elixir.Module.Types.Descr.«map_empty?/2» (D m) x (.map S) = .ok (boolAtom b)) ∧
          ∀ N, lh x < N → SafeN N S → (b = Bool.true ↔ ∀ w, denMF E den x w = Bool.false) := by
      have field : MapField E x := fx.imp id fun w => w.mono fun _ h => mlit_ok h
      obtain ⟨b, hb⟩ := map_total ef.opsU ef.dopsU S field
      refine ⟨b, hb, fun N hx hS => ?_⟩
      have step := map_empty_step (d := D (K + 2)) (not_seen hS hx "map")
      have run := hb (K + 2) (Nat.le_refl _)
      dsimp only at run
      rw [step] at run
      have pos : ∀ {F : Term → Prop}, MapPosV F (.tuple #[.atom "open", .nil]) :=
        ⟨.atom "open", [], rfl, Or.inl rfl, by simp [FieldsV]⟩
      -- the top literal and BDDs without literals answer directly
      have direct : ∀ (c : Bool), Elixir.Module.Types.Descr.«map_bdd_empty?/4» (D (K + 2)) (.tuple #[.atom "open", .nil]) .nil x
          (.map ((.cons (.atom "map") x, .atom "true") :: S)) = .ok (boolAtom c) →
          (c = Bool.true ↔ ∀ w, denMF E den x w = Bool.false) → (b = Bool.true ↔ ∀ w, denMF E den x w = Bool.false) := by
        intro c hc sem
        rw [hc] at run
        have : b = c := by cases b <;> cases c <;> simp_all [boolAtom]
        rw [this]; exact sem
      have someW : Nonempty (MW V) := ⟨fun _ => Option.none⟩
      rcases fx with ⟨k, rfl⟩ | wx
      · refine direct Bool.false ?_ ⟨fun h => absurd h (by decide), fun h => absurd (h (fun _ => Option.none))
          (by rw [denMF_top]; simp)⟩
        have merge : ∀ (mod name : String) (caps : Array Term),
            Erlang.orddict.«merge/3» (D (K + 2)) (.function mod name 3 caps) .nil .nil = .ok .nil := by
          intro mod name caps; rw [Erlang.orddict.«merge/3».eq_def]; simp [Erlang.erlang.«is_function/2»]
        simp [Elixir.Module.Types.Descr.«map_bdd_empty?/4», Elixir.Module.Types.Descr.«map_line_intersection/3»,
          Elixir.Module.Types.Descr.«map_literal_intersection/6», Lynx.Except.tryWith, boolAtom, merge, init_open_nil]
      by_cases top : x = .atom "bdd_top"
      · subst top
        refine direct Bool.false ?_ ⟨fun h => absurd h (by decide), fun h => absurd (h (fun _ => Option.none))
          (by rw [denMF_bdd wx]; simp [eval])⟩
        simp [Elixir.Module.Types.Descr.«map_bdd_empty?/4», boolAtom, init_open_nil]
      by_cases bot : x = .atom "bdd_bot"
      · subst bot
        refine direct Bool.true ?_ ⟨fun _ w => by rw [denMF_bdd wx]; rfl, fun _ => rfl⟩
        simp [Elixir.Module.Types.Descr.«map_bdd_empty?/4», boolAtom]
      have one := mbdd_lh wx top bot
      have hS' := safe_put hS hx one "map"
      have ops := ef.ops (lh x) (by omega)
      have dops := ef.dops (lh x)
      have sem := ef.sem (lh x)
      have wb := mbdd_lh_le wx (fun _ h => h) (lh x) (Nat.le_refl _)
      have okLit : ∀ t, (MLit E t ∧ lh t ≤ lh x) → MapLitV (EB E (lh x)) t := by
        intro t ⟨ht, le⟩
        have hl := (mlit_lh ht).2
        obtain ⟨⟨k, tag, l, rfl, g, sl⟩, -, -⟩ := ht
        obtain ⟨hf, hd⟩ := hl k tag l rfl
        refine ⟨k, tag, l, rfl, ?_, fun e me => ⟨(sl.1 e me).1, ?_⟩, sl.2⟩
        · rcases g with rfl | rfl | ⟨dl, rfl, dv⟩
          · exact Or.inl rfl
          · exact Or.inr (Or.inl rfl)
          · refine Or.inr (Or.inr ⟨dl, rfl, fun e me => ⟨(dv.1 e me).1, (dv.1 e me).2, ?_⟩, dv.2⟩)
            have := hd e (by rw [domFields_fieldsTerm]; exact me); omega
        · obtain ⟨u, o, he, hu⟩ := (sl.1 e me).2
          exact ⟨u, o, he, hu, by have := hf e me u o he; omega⟩
      have agree : ∀ w, eval (valM (EB E (lh x)) den w) x = eval (valM E den w) x := fun w =>
        eval_ext wb fun t ht => by
          have h₁ := valM_iff ops dops sem (okLit t ht) (w := w)
          have h₂ := valM_iff ef.opsU ef.dopsU ef.semR ht.1.1 (w := w)
          cases e₁ : valM (EB E (lh x)) den w t <;> cases e₂ : valM E den w t <;> simp_all
      constructor
      · intro hbt w
        subst hbt
        rw [denMF_bdd wx]
        have v := map_bdd_sound ops dops sem (Nat.le_refl _) _ hS' wb okLit _ [] pos (by simp)
          (by simpa [boolAtom, Term.list] using run) w (inPosM_iff.mpr ⟨fun s => fsem_nil.mpr (Or.inl rfl), fun k i => Or.inl rfl⟩) (by simp)
        rwa [agree] at v
      · intro unsat
        have t := map_bdd_val ops dops sem (Nat.le_refl _) _ hS' wb okLit _ [] pos (by simp)
          fun w _ _ => by rw [agree]; have := unsat w; rwa [denMF_bdd wx] at this
        simp only [Term.list] at t
        rw [t] at run
        cases b <;> simp_all [boolAtom]

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Plain operations on map types keep literal heights. -/

    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- BDDs of map literals below a positive height are below it. -/
    theorem mbdd_lh_bound {ok : Term → Prop} {r : Term} (wr : Bdd ok r) {M : Nat}
        (lits : ∀ t, ok t → MLit E t ∧ lh t ≤ M) (top : 1 ≤ M) : lh r ≤ M := by
      revert lits top
      refine Bdd.induction (P := fun ok r => (∀ t, ok t → MLit E t ∧ lh t ≤ M) → 1 ≤ M → lh r ≤ M)
        ?_ ?_ ?_ ?_ ok r wr
      · intro _ _ top; simpa [lh] using top
      · intro _ _ top; simpa [lh] using top
      · intro ok k x y okl lits _
        exact (lits _ okl).2
      · intro ok h lit c u d leaf okl _ _ _ ic iu idd lits _
        obtain ⟨k, a, b, rfl⟩ := leaf
        have ⟨tl', le⟩ := lits _ okl
        have lits' : ∀ t, Above ok (.tuple #[.integer k, a, b]) t → MLit E t ∧ lh t ≤ M := fun t ht => lits t ht.1
        have hc := ic lits' (by omega)
        have hu := iu lits' (by omega)
        have hd := idd lits' (by omega)
        have hl := mlit_lh_eq tl'
        have hn := lh_node (.integer h) (.integer k) a b c u d (mlit_litZ tl')
        change lh (.tuple ⟨[.integer h, .tuple ⟨[.integer k, a, b]⟩, c, u, d]⟩) ≤ M
        omega

    theorem mfield_mono {x : Term} (wx : Bdd (MLit E) x) {M : Nat} (le : lh x ≤ M) :
        Bdd (fun t => MLit E t ∧ lh t ≤ M) x :=
      (mbdd_lh_le wx (fun _ h => h) M le).mono fun _ h => h

    /-- BDDs of map literals have a height. -/
    theorem mbdd_pos {x : Term} (wx : Bdd (MLit E) x) : 1 ≤ lh x := by
      by_cases t : x = .atom "bdd_top"
      · subst t; simp [lh]
      by_cases b : x = .atom "bdd_bot"
      · subst b; simp [lh]
      · exact mbdd_lh wx t b

    theorem mlh_top_leaf (k : Term) : lh (.tuple #[k, .atom "open", .nil]) = 0 := lh_leaf_top k

    /-- Plain unions of map types. -/
    theorem map_union_lh {x y : Term} (hx : MField E x) (hy : MField E y) :
        ∃ r, Elixir.Module.Types.Descr.«map_union/2» x y = .ok r ∧ MField E r ∧
          (∀ w, denMF E den r w = (denMF E den x w || denMF E den y w)) ∧ lh r ≤ max (lh x) (lh y) := by
      obtain ⟨r, run, fr, sem⟩ := map_union_field (den := den) hx hy
      refine ⟨r, run, fr, sem, ?_⟩
      rcases hx with ⟨k, rfl⟩ | wx
      · have e : Elixir.Module.Types.Descr.«map_union/2» (.tuple #[.integer k, .atom "open", .nil]) y =
            .ok (.tuple #[.integer k, .atom "open", .nil]) := by unfold Elixir.Module.Types.Descr.«map_union/2»; rfl
        rw [e] at run; cases run; rw [mlh_top_leaf]; omega
      rcases hy with ⟨k, rfl⟩ | wy
      · have nx := not_top_of_ok wx mlit_not
        have e : Elixir.Module.Types.Descr.«map_union/2» x (.tuple #[.integer k, .atom "open", .nil]) =
            .ok (.tuple #[.integer k, .atom "open", .nil]) := by
          unfold Elixir.Module.Types.Descr.«map_union/2»
          split
          · exact (nx _ rfl).elim
          · rename_i e; simp at e; subst e; rfl
          · rename_i h; exact (h _ rfl).elim
        rw [e] at run; cases run; rw [mlh_top_leaf]; omega
      obtain ⟨r', hr, okr, semr⟩ := union_ok wx wy
      rw [map_union_bdd (not_top_of_ok wx mlit_not) (not_top_of_ok wy mlit_not), hr] at run
      cases run
      exact mbdd_lh_bound (okr _ (mfield_mono wx (Nat.le_max_left _ _)) (mfield_mono wy (Nat.le_max_right _ _)))
        (fun _ h => h) (by have := mbdd_pos wx; omega)

    /-- Plain intersections of map types. -/
    theorem map_inter_lh {x y : Term} (hx : MField E x) (hy : MField E y) :
        ∃ r, Elixir.Module.Types.Descr.«map_intersection/2» x y = .ok r ∧ MField E r ∧
          (∀ w, denMF E den r w = (denMF E den x w && denMF E den y w)) ∧ lh r ≤ max (lh x) (lh y) := by
      rcases hx with ⟨k, rfl⟩ | wx
      · exact ⟨y, by unfold Elixir.Module.Types.Descr.«map_intersection/2»; rfl, hy, fun w => by simp [denMF_top],
          by omega⟩
      have nx := not_top_of_ok wx mlit_not
      rcases hy with ⟨k, rfl⟩ | wy
      · refine ⟨x, ?_, Or.inr wx, fun w => by simp [denMF_top], by omega⟩
        unfold Elixir.Module.Types.Descr.«map_intersection/2»
        split
        · exact (nx _ rfl).elim
        · simp_all
        · rename_i h₁ h₂; exact (h₂ _ rfl).elim
      · obtain ⟨r, hr, okr, semr⟩ := inter_ok wx wy
        have wr := okr _ wx wy
        refine ⟨r, by rw [map_intersection_bdd nx (not_top_of_ok wy mlit_not), hr], Or.inr wr, fun w => ?_, ?_⟩
        · rw [denMF_bdd wr, denMF_bdd wx, denMF_bdd wy, semr _ (valM_resp w)]
        · exact mbdd_lh_bound (okr _ (mfield_mono wx (Nat.le_max_left _ _)) (mfield_mono wy (Nat.le_max_right _ _)))
            (fun _ h => h) (by have := mbdd_pos wx; omega)

    /-- Plain differences of map types: non-empty results keep heights. -/
    theorem map_diff_lh {x y : Term} (fx : MField E x) (fy : MField E y) :
        ∃ w, Elixir.Module.Types.Descr.«map_difference/2» x y = .ok w ∧ MField E w ∧
          (∀ v, denMF E den w v = (denMF E den x v && !denMF E den y v)) ∧
          (w ≠ .atom "bdd_bot" → lh w ≤ max (lh x) (lh y)) := by
      obtain ⟨w₀, run₀, fw₀, sem₀⟩ := map_diff_val (den := den) fx fy
      refine ⟨w₀, run₀, fw₀, sem₀, fun nb => ?_⟩
      rcases fy with ⟨k, rfl⟩ | wy
      · have : w₀ = .atom "bdd_bot" := by
          have e : Elixir.Module.Types.Descr.«map_difference/2» x (.tuple #[.integer k, .atom "open", .nil]) =
              .ok (.atom "bdd_bot") := by unfold Elixir.Module.Types.Descr.«map_difference/2»; rfl
          rw [e] at run₀; cases run₀; rfl
        exact absurd this nb
      have ny := not_top_of_ok wy mlit_not
      rcases fx with ⟨kt, rfl⟩ | wx
      · rcases wy.shape with rfl | rfl | ⟨k', a, b, rfl⟩ | ⟨h, lit, c, u, d, rfl⟩
        · have e : Elixir.Module.Types.Descr.«map_difference/2» (.tuple #[.integer kt, .atom "open", .nil])
              (.atom "bdd_top") = .ok (.atom "bdd_bot") := by
            unfold Elixir.Module.Types.Descr.«map_difference/2»; simp [diff_leaf_top]
          rw [e] at run₀; cases run₀; exact absurd rfl nb
        · have e : Elixir.Module.Types.Descr.«map_difference/2» (.tuple #[.integer kt, .atom "open", .nil])
              (.atom "bdd_bot") = .ok (.tuple #[.integer kt, .atom "open", .nil]) := by
            unfold Elixir.Module.Types.Descr.«map_difference/2»; simp [diff_leaf_bot]
          rw [e] at run₀; cases run₀; omega
        all_goals
          obtain ⟨w, run, keep, sem⟩ := neg_ok wy
          rw [map_difference_neg ny _ rfl, run] at run₀
          cases run₀
          exact mbdd_lh_bound (keep _ (mfield_mono wy (Nat.le_max_right _ _))) (fun _ h => h)
            (by have := mbdd_lh wy (by simp) (by simp); omega)
      · obtain ⟨w, run, keep, sem⟩ := diff_ok wx wy
        rw [map_difference_bdd (not_top_of_ok wx mlit_not) ny, run] at run₀
        cases run₀
        exact mbdd_lh_bound (keep _ (mfield_mono wx (Nat.le_max_left _ _)) (mfield_mono wy (Nat.le_max_right _ _)))
          (fun _ h => h) (by have := mbdd_pos wx; omega)

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.unusedVariables false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Map fields of element types: what the descr level needs of them. -/

    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- Map fields that compare equal hold the same maps. -/
    theorem denMF_resp {x x' : Term} (fx : MField E x) (fx' : MField E x') (e : Term.compare x x' = .eq) (w : MW V) :
        denMF E den x w = denMF E den x' w := by
      rcases fx with ⟨k, rfl⟩ | wx
      · rcases fx' with ⟨k', rfl⟩ | wx'
        · rw [denMF_top, denMF_top]
        · exfalso
          obtain ⟨ys, rfl, ex⟩ : ∃ ys : Array Term, x' = .tuple ys ∧ True := by
            cases x' <;> rw [Term.compare_eq_step] at e <;> simp [Compare.compareStep] at e
            exact ⟨_, rfl, trivial⟩
          rw [compare_tuple] at e
          obtain ⟨l⟩ := ys
          simp only [Ordering.then_eq_eq] at e
          match l, e with
          | [a, b, c], e =>
            simp only [List.compareLex_cons_cons, Ordering.then_eq_eq] at e
            obtain ⟨-, eb, ec, -⟩ := e.2
            obtain rfl := (compare_eq_atom b "open").mp (Std.OrientedCmp.eq_symm eb)
            obtain rfl := (compare_eq_nil c).mp (Std.OrientedCmp.eq_symm ec)
            exact not_top_of_ok wx' mlit_not a rfl
          | [], e => simp at e
          | [_], e => simp at e
          | [_, _], e => simp at e
          | _ :: _ :: _ :: _ :: _, e => simp at e
      · rcases fx' with ⟨k', rfl⟩ | wx'
        · exfalso
          obtain ⟨ys, rfl, -⟩ : ∃ ys : Array Term, x = .tuple ys ∧ True := by
            cases x <;> rw [Term.compare_eq_step] at e <;> simp [Compare.compareStep] at e
            exact ⟨_, rfl, trivial⟩
          rw [compare_tuple] at e
          obtain ⟨l⟩ := ys
          simp only [Ordering.then_eq_eq] at e
          match l, e with
          | [a, b, c], e =>
            simp only [List.compareLex_cons_cons, Ordering.then_eq_eq] at e
            obtain ⟨-, eb, ec, -⟩ := e.2
            obtain rfl := (compare_eq_atom b "open").mp eb
            obtain rfl := (compare_eq_nil c).mp ec
            exact not_top_of_ok wx mlit_not a rfl
          | [], e => simp at e
          | [_], e => simp at e
          | [_, _], e => simp at e
          | _ :: _ :: _ :: _ :: _, e => simp at e
        · rw [denMF_bdd wx, denMF_bdd wx']
          exact eval_congr_cmp wx (valM_resp w) e

    /-! Field-level deliverables for maps. -/

    /-- F3: plain unions of map fields. -/
    theorem map_field_union {x y : Term} (fx : MField E x) (fy : MField E y) :
        ∃ r, (∀ d, Elixir.Module.Types.Descr.«bare_union/3» d (.atom "map") x y = .ok r) ∧ MField E r ∧
          (∀ w, denMF E den r w = (denMF E den x w || denMF E den y w)) ∧ lh r ≤ max (lh x) (lh y) := by
      obtain ⟨r, run, fr, sem, le⟩ := map_union_lh (den := den) fx fy
      exact ⟨r, fun d => by simpa [Elixir.Module.Types.Descr.«bare_union/3»] using run, fr, sem, le⟩

    /-- F3: plain intersections of map fields. -/
    theorem map_field_inter {x y : Term} (fx : MField E x) (fy : MField E y) :
        ∃ r, (∀ d, Elixir.Module.Types.Descr.«bare_intersection/3» d (.atom "map") x y = .ok r) ∧ MField E r ∧
          (∀ w, denMF E den r w = (denMF E den x w && denMF E den y w)) ∧ lh r ≤ max (lh x) (lh y) := by
      obtain ⟨r, run, fr, sem, le⟩ := map_inter_lh (den := den) fx fy
      exact ⟨r, fun d => by simpa [Elixir.Module.Types.Descr.«bare_intersection/3»] using run, fr, sem, le⟩

    /-- F3: plain differences of map fields. -/
    theorem map_field_diff {x y : Term} (fx : MField E x) (fy : MField E y) :
        ∃ r, (∀ d, Elixir.Module.Types.Descr.«bare_difference/3» d (.atom "map") x y = .ok r) ∧ MField E r ∧
          (∀ w, denMF E den r w = (denMF E den x w && !denMF E den y w)) ∧
          (r ≠ .atom "bdd_bot" → lh r ≤ max (lh x) (lh y)) := by
      obtain ⟨r, run, fr, sem, le⟩ := map_diff_lh (den := den) fx fy
      exact ⟨r, fun d => by simpa [Elixir.Module.Types.Descr.«bare_difference/3»] using run, fr, sem, le⟩

    /-- F4: optimized unions of map fields. -/
    theorem map_field_opt_union (ef : EF nd E V den tl K) {m : Nat} (hm : K ≤ m) {x y : Term} (fx : MField E x)
        (fy : MField E y) (S : List (Term × Term)) :
        ∃ r, Elixir.Module.Types.Descr.«opt_union/4» (D m) (.atom "map") x y (.map S) = .ok r ∧ MField E r ∧
          ∀ w, denMF E den r w = (denMF E den x w || denMF E den y w) := by
      obtain ⟨r, run, fr, sem⟩ := opt_map_union_sem ef hm fx fy S
      exact ⟨r, by simpa [Elixir.Module.Types.Descr.«opt_union/4»] using run, fr, sem⟩

    /-- F4: optimized intersections of map fields. -/
    theorem map_field_opt_inter (ef : EF nd E V den tl K) {m : Nat} (hm : K + 2 ≤ m) {x y : Term} (fx : MField E x)
        (fy : MField E y) (S : List (Term × Term)) :
        ∃ r, Elixir.Module.Types.Descr.«opt_intersection/4» (D m) (.atom "map") x y (.map S) = .ok r ∧ MField E r ∧
          ∀ w, denMF E den r w = (denMF E den x w && denMF E den y w) := by
      obtain ⟨r, run, fr, sem⟩ := opt_map_inter_val ef hm fx fy S
      exact ⟨r, by simpa [Elixir.Module.Types.Descr.«opt_intersection/4»] using run, fr, sem⟩

    /-- F4: optimized differences of map fields; dropped results have no maps. -/
    theorem map_field_opt_diff (ef : EF nd E V den tl K) {m : Nat} (hm : K + 1 ≤ m) {x y : Term} (fx : MField E x)
        (fy : MField E y) (S : List (Term × Term)) :
        ∃ r, Elixir.Module.Types.Descr.«opt_difference/4» (D m) (.atom "map") x y (.map S) = .ok r ∧
          (kept (.atom "map", r) = Bool.true → MField E r ∧ ∀ w, denMF E den r w = (denMF E den x w && !denMF E den y w)) ∧
          (kept (.atom "map", r) = Bool.false → ∀ w, (denMF E den x w && !denMF E den y w) = Bool.false) := by
      obtain ⟨n, rfl, hn⟩ := succ_of_le hm
      obtain ⟨r, run, k, d⟩ := opt_map_diff_val ef hn fx fy S
      exact ⟨r, by simpa [Elixir.Module.Types.Descr.«opt_difference/4»] using run, k, d⟩

    /-- F5: map fields decide their emptiness exactly, when the seen BDDs are higher than them. -/
    theorem map_field_empty (ef : EF nd E V den tl K) {x : Term} (fx : MField E x) (S : List (Term × Term)) :
        ∃ b : Bool, (∀ m, K + 2 ≤ m →
            Elixir.Module.Types.Descr.«empty_key?/3» (D m) (.atom "map") x (.map S) = .ok (boolAtom b)) ∧
          ∀ N, lh x < N → SafeN N S → (b = Bool.true ↔ ∀ w, denMF E den x w = Bool.false) := by
      obtain ⟨b, run, sem⟩ := map_empty_exact ef fx S
      exact ⟨b, fun m hm => by simpa [Elixir.Module.Types.Descr.«empty_key?/3»] using run m hm, sem⟩

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Maps are a structural kind, and the three kinds together. -/

    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- Valuations of map literals that maps of values induce. -/
    def ValMN (E : Term → Prop) (den : Term → V → Prop) (ρ : Term → Bool) : Prop := ∃ w : MW V, ρ = valM E den w

    theorem dn_mapW {x : Term} {p : Point} {w : MW V} (e : p.2.2 = valM E den w) :
        dn "map" (some x) p = denMF E den x w := by
      rw [dn_map, e]; rfl

    theorem mfield_nz {w : Term} (fw : MField E w) : w ≠ .integer 0 := by
      rcases fw with ⟨k, rfl⟩ | ww
      · simp
      · exact bdd_ne_zero ww

    theorem denMF_bot (w : MW V) : denMF E den (.atom "bdd_bot") w = Bool.false := by
      simp [denMF, denO, isOpenTop, eval]

    theorem mapKind (ef : EF nd E V den tl K) : KindOk (K + 2) "map" (MField E) (ValMN E den) where
      resp := fun _ ⟨w, e⟩ => e ▸ valM_resp w
      wit := ⟨_, fun _ => none, rfl⟩
      top := fun t ht => by
        rcases ht with ⟨h, _⟩ | ⟨h, _⟩ | ⟨h, _⟩ | ⟨h, _⟩ | ⟨h, _⟩ | ⟨-, rfl⟩ <;> try simp at h
        exact ⟨Or.inl ⟨_, rfl⟩, lh_top_leaf _, fun p _ => by rw [dn_map, denO_top]⟩
      congr := fun fx fx' e p ⟨w, hw⟩ => by
        rw [dn_mapW hw, dn_mapW hw]
        exact denMF_resp fx fx' e w
      union := fun fx fy => by
        obtain ⟨r, run, fr, sem, le⟩ := map_field_union (den := den) fx fy
        exact ⟨r, fun m _ => run _, fr, fun p ⟨w, hw⟩ => by rw [dn_mapW hw, dn_mapW hw, dn_mapW hw, sem], le⟩
      inter := fun fx fy => by
        obtain ⟨r, run, fr, sem, le⟩ := map_field_inter (den := den) fx fy
        refine ⟨r, fun m _ => run _, fun _ => ⟨fr, le⟩, fun p ⟨w, hw⟩ => ?_⟩
        cases k : kept (.atom "map", r)
        · rw [keptO_false k, dn_none, dn_mapW hw, dn_mapW hw, ← sem,
            dropped_bdd (by rw [kept_name]; exact k) (mfield_nz fr), denMF_bot]
        · rw [keptO_true k, dn_mapW hw, dn_mapW hw, dn_mapW hw, sem]
      diff := fun fx fy => by
        obtain ⟨r, run, fr, sem, le⟩ := map_field_diff (den := den) fx fy
        refine ⟨r, fun m _ => run _, fun k => ⟨fr, le (kept_ne_bot k)⟩, fun p ⟨w, hw⟩ => ?_⟩
        cases k : kept (.atom "map", r)
        · rw [keptO_false k, dn_none, dn_mapW hw, dn_mapW hw, ← sem,
            dropped_bdd (by rw [kept_name]; exact k) (mfield_nz fr), denMF_bot]
        · rw [keptO_true k, dn_mapW hw, dn_mapW hw, dn_mapW hw, sem]
      opt_union := by
        intro x y S m fx fy hm
        obtain ⟨r, run, fr, sem⟩ := map_field_opt_union ef (m := m) (by omega) fx fy S
        exact ⟨r, run, fr, fun p ⟨w, hw⟩ => by rw [dn_mapW hw, dn_mapW hw, dn_mapW hw, sem]⟩
      opt_inter := by
        intro x y S m fx fy hm
        obtain ⟨r, run, fr, sem⟩ := map_field_opt_inter ef (m := m) hm fx fy S
        refine ⟨r, run, fun _ => fr, fun p ⟨w, hw⟩ => ?_⟩
        cases k : kept (.atom "map", r)
        · rw [keptO_false k, dn_none, dn_mapW hw, dn_mapW hw, ← sem,
            dropped_bdd (by rw [kept_name]; exact k) (mfield_nz fr), denMF_bot]
        · rw [keptO_true k, dn_mapW hw, dn_mapW hw, dn_mapW hw, sem]
      opt_diff := by
        intro x y S m fx fy hm
        obtain ⟨r, run, k, d⟩ := map_field_opt_diff ef (m := m) (by omega) fx fy S
        refine ⟨r, run, fun kw => (k kw).1, fun p ⟨w, hw⟩ => ?_⟩
        cases kw : kept (.atom "map", r)
        · rw [keptO_false kw, dn_none, dn_mapW hw, dn_mapW hw, d kw]
        · rw [keptO_true kw, dn_mapW hw, dn_mapW hw, dn_mapW hw, (k kw).2]
      empty := fun S fx => by
        obtain ⟨b, run, ex⟩ := map_field_empty ef fx S
        refine ⟨b, run, fun N hx hS => (ex N hx hS).trans ⟨fun h p ⟨w, hw⟩ => by rw [dn_mapW hw]; exact h w,
          fun h w => by have := h (0, .nil, valM E den w) ⟨w, rfl⟩; rwa [dn_mapW rfl] at this⟩⟩

    /-- The structural kinds over element types. -/
    theorem kinds (ef : EF nd E V den tl K) : Kinds (K + 2) (TField E) (LF E) (MField E) (ValT E den) (ValLN E den tl)
        (ValMN E den) := ⟨tupleKind ef, listKind ef, mapKind ef⟩

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! The bottom level: top list and map fields, and tuple fields of the expansion literal of the node `t`. -/

    theorem sub_term_term (d : Dispatcher) :
        Elixir.Module.Types.Descr.«subtype?/2» d (.atom "term") (.atom "term") = .ok (.atom "true") := by
      obtain ⟨T, term, -, -, -, staticT⟩ := unfolded_term_fields
      unfold Elixir.Module.Types.Descr.«subtype?/2»
      simp [term, unfold_map, Erlang.erlang.«is_map_key/2», staticT, any_key, Lynx.Except.andAlso, Erlang.erlang.«/=/2»]
      unfold Elixir.Module.Types.Descr.«subtype_static?/2»
      simp [Lynx.Except.guard, Erlang.erlang.«=:=/2»]

    theorem empty_term_false (d : Dispatcher) :
        Elixir.Module.Types.Descr.«empty?/1» d (.atom "term") = .ok (boolAtom Bool.false) := by
      unfold Elixir.Module.Types.Descr.«empty?/1»; rfl

    theorem lh_list_top : lh (.tuple #[.integer 46675407, .atom "term", .atom "term"]) = 0 := by simp [lh]

    theorem topF_lh {name : String} {x : Term} (h : topValue name = some x) : lh x = 0 := by
      rcases top_cases h with ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ <;> simp [lh, lh_nil_map]

    theorem topF_dn {name : String} {x : Term} (hn : name = "list" ∨ name = "map") (h : topValue name = some x)
        (p : Point) : dn name (some x) p = Bool.true := by
      rcases hn with rfl | rfl <;> rcases top_cases h with ⟨e, rfl⟩ | ⟨e, rfl⟩ | ⟨e, rfl⟩ | ⟨e, rfl⟩ <;>
        simp at e <;> simp [dn_list, dn_map, denL_top, denO_top]

    /-- Top list and map fields: their operations keep the top value, and they are not empty. -/
    theorem topF_of {name : String} (hn : name = "list" ∨ name = "map") {x : Term} (h : FieldOk name x) :
        topValue name = some x := by
      rcases h with ⟨rfl, -⟩ | ⟨rfl, -⟩ | ⟨-, -, tx⟩ <;> first | exact tx | (rcases hn with h | h <;> simp at h)

    theorem topKind (name : String) (hn : name = "list" ∨ name = "map") {K : Nat} (hK : 1 ≤ K) :
        KindOk K name (FieldOk name) Resp where
      resp := fun _ h => h
      wit := ⟨_, resp_const Bool.true⟩
      top := fun t ht => by
        have nb : name ≠ "bitmap" := by rcases hn with rfl | rfl <;> decide
        have na : name ≠ "atom" := by rcases hn with rfl | rfl <;> decide
        have tv : topValue name = some t := by
          rcases hn with rfl | rfl <;>
            rcases ht with ⟨h, rfl⟩ | ⟨h, rfl⟩ | ⟨h, rfl⟩ | ⟨h, rfl⟩ | ⟨h, rfl⟩ | ⟨h, rfl⟩ <;> simp_all [topValue]
        exact ⟨Or.inr (Or.inr ⟨nb, na, tv⟩), topF_lh tv, fun p _ => topF_dn hn tv p⟩
      congr := fun fx fx' _ p _ => by
        rcases fx with ⟨rfl, -⟩ | ⟨rfl, -⟩ | ⟨-, -, tx⟩ <;> try (rcases hn with h | h <;> simp at h)
        rcases fx' with ⟨rfl, -⟩ | ⟨rfl, -⟩ | ⟨-, -, tx'⟩ <;> try (rcases hn with h | h <;> simp at h)
        rw [topF_dn hn tx, topF_dn hn tx']
      union := fun {x y} fx fy => by
        obtain ⟨r, run, fr⟩ := fieldok_union name fx fy
        have tr : topValue name = some r := by
          rcases fr with ⟨rfl, -⟩ | ⟨rfl, -⟩ | ⟨-, -, tr⟩ <;> first | exact tr | (rcases hn with h | h <;> simp at h)
        refine ⟨r, fun m hm => ?_, fr, fun p _ => by rw [topF_dn hn tr, topF_dn hn (topF_of hn fx)]; rfl,
          by rw [topF_lh tr]; omega⟩
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        exact run n
      inter := fun {x y} fx fy => by
        have nb : name ≠ "bitmap" := by rcases hn with rfl | rfl <;> decide
        have na : name ≠ "atom" := by rcases hn with rfl | rfl <;> decide
        obtain ⟨r, run, fr, -, -, kr⟩ := inter_key name x y fx fy
        have k := kr nb na
        have tr := topF_of hn (fr k)
        refine ⟨r, fun m _ => run _, fun _ => ⟨fr k, by rw [topF_lh tr]; omega⟩, fun p _ => ?_⟩
        rw [keptO_true k, topF_dn hn tr, topF_dn hn (topF_of hn fx), topF_dn hn (topF_of hn fy)]
        rfl
      diff := fun {x y} fx fy => by
        have nb : name ≠ "bitmap" := by rcases hn with rfl | rfl <;> decide
        have na : name ≠ "atom" := by rcases hn with rfl | rfl <;> decide
        obtain ⟨r, run, -, -, -, kr⟩ := diff_key name x y fx fy
        have k := kr nb na
        refine ⟨r, fun m _ => run _, fun h => absurd (h.symm.trans k) (by decide), fun p _ => ?_⟩
        rw [keptO_false k, dn_none, topF_dn hn (topF_of hn fy)]
        simp
      opt_union := fun {x y} S {m} fx fy hm => by
        have tx := topF_of hn fx
        have ty := topF_of hn fy
        rw [tx] at ty
        cases ty
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        exact ⟨x, opt_union_top n tx _, fx, fun p _ => by rw [topF_dn hn tx]; rfl⟩
      opt_inter := fun {x y} S {m} fx fy hm => by
        have nb : name ≠ "bitmap" := by rcases hn with rfl | rfl <;> decide
        have na : name ≠ "atom" := by rcases hn with rfl | rfl <;> decide
        obtain ⟨r, run, fr, -, -, kr⟩ := opt_inter_key m name x y (.map S) fx fy
        have k := kr nb na
        have tr := topF_of hn (fr k)
        refine ⟨r, run, fun _ => fr k, fun p _ => ?_⟩
        rw [keptO_true k, topF_dn hn tr, topF_dn hn (topF_of hn fx), topF_dn hn (topF_of hn fy)]
        rfl
      opt_diff := fun {x y} S {m} fx fy hm => by
        have nb : name ≠ "bitmap" := by rcases hn with rfl | rfl <;> decide
        have na : name ≠ "atom" := by rcases hn with rfl | rfl <;> decide
        have tx := topF_of hn fx
        have ty := topF_of hn fy
        rw [tx] at ty
        cases ty
        obtain ⟨r, run, -, -, -, kr⟩ := diff_key name x x fx fx
        have k := kr nb na
        refine ⟨r, by rw [opt_diff_top _ tx, run], fun h => absurd (h.symm.trans k) (by decide), fun p _ => ?_⟩
        rw [keptO_false k, dn_none, topF_dn hn tx]
        rfl
      empty := fun {x} S fx => by
        have tx := topF_of hn fx
        obtain ⟨b, run⟩ : ∃ b, ∀ d, Elixir.Module.Types.Descr.«empty_key?/3» d (.atom name) x (.map S) = .ok (boolAtom b) := by
          rcases hn with rfl | rfl <;> rcases top_cases tx with ⟨e, rfl⟩ | ⟨e, rfl⟩ | ⟨e, rfl⟩ | ⟨e, rfl⟩ <;> simp at e
          · refine ⟨Bool.false, fun d => ?_⟩
            simpa [Elixir.Module.Types.Descr.«empty_key?/3», boolAtom] using list_top_nonempty d (.map S)
          · obtain ⟨b, h⟩ := map_top_bool S
            exact ⟨b, fun d => by simpa [Elixir.Module.Types.Descr.«empty_key?/3»] using h d⟩
        refine ⟨b, fun m _ => run _, fun N _ hS => ?_⟩
        have e : b = Bool.false := by
          rcases hn with rfl | rfl <;> rcases top_cases tx with ⟨e, rfl⟩ | ⟨e, rfl⟩ | ⟨e, rfl⟩ | ⟨e, rfl⟩ <;> simp at e
          · have r₀ := list_top_nonempty (D 0) (.map S)
            have r₁ := run (D 0)
            simp only [Elixir.Module.Types.Descr.«empty_key?/3»] at r₁
            rw [r₀] at r₁
            cases b <;> simp_all [boolAtom]
          · have r₀ := map_top_nonempty (D 0) (safeF_of hS)
            have r₁ := run (D 0)
            simp only [Elixir.Module.Types.Descr.«empty_key?/3»] at r₁
            rw [r₀] at r₁
            cases b <;> simp_all [boolAtom]
        subst e
        refine ⟨fun h => by simp at h, fun h => ?_⟩
        have := h (0, .nil, fun _ => Bool.true) (resp_const _)
        rw [topF_dn hn tx] at this
        cases this

    /-! Tuple fields of the bottom level: BDDs of the expansion literal of `t`. -/

    section
    variable {t : Term}

    theorem pure_diff_sem {x y : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y) :
        ∃ w, Elixir.Module.Types.Descr.«tuple_difference/2» x y = .ok w ∧ OField (PureLit t) w ∧
          ∀ ρ, Resp ρ → denO w ρ = (denO x ρ && !denO y ρ) := by
      rcases fy with ⟨k, rfl⟩ | wy
      · exact ⟨.atom "bdd_bot", by unfold Elixir.Module.Types.Descr.«tuple_difference/2»; rfl, Or.inr Bdd.bot,
          fun ρ _ => by simp [denO_top, denO, isOpenTop, eval]⟩
      have ny := not_top_of_ok wy pureLit_not
      have special : ¬∃ k, y = .tuple #[k, .atom "closed", .nil] := by
        rintro ⟨k, rfl⟩
        unfold Bdd at wy
        split at wy <;> simp_all [PureLit, litN, Term.list]
        obtain ⟨e, -, -, h⟩ := wy
        cases h
      rcases fx with ⟨kt, rfl⟩ | wx
      · rcases wy.shape with rfl | rfl | ⟨k', a, b, rfl⟩ | ⟨h, lit, c, u, d, rfl⟩
        · refine ⟨.atom "bdd_bot", ?_, Or.inr Bdd.bot, fun ρ _ => by simp [denO_top, denO, isOpenTop, eval]⟩
          unfold Elixir.Module.Types.Descr.«tuple_difference/2»
          simp [diff_leaf_top]
        · refine ⟨_, ?_, Or.inl ⟨kt, rfl⟩, fun ρ _ => by simp [denO_top, denO, isOpenTop, eval]⟩
          unfold Elixir.Module.Types.Descr.«tuple_difference/2»
          simp [diff_leaf_bot]
        all_goals
          obtain ⟨w, run, keep, sem⟩ := neg_ok wy
          refine ⟨w, ?_, Or.inr (keep _ wy), fun ρ r => ?_⟩
          · rw [tuple_difference_neg ny (fun k e => special ⟨k, e⟩) _ rfl, run]
          · rw [denO_top, denO_bdd pureLit_not (keep _ wy), denO_bdd pureLit_not wy, sem ρ r]; rfl
      · obtain ⟨w, run, keep, sem⟩ := diff_ok wx wy
        refine ⟨w, by rw [tuple_difference_bdd (not_top_of_ok wx pureLit_not) ny (fun ⟨_, h⟩ => special h), run],
          Or.inr (keep _ wx wy), fun ρ r => ?_⟩
        rw [denO_bdd pureLit_not (keep _ wx wy), denO_bdd pureLit_not wx, denO_bdd pureLit_not wy, sem ρ r]

    end

    section
    variable {t : Term}

    /-- Optimized intersections of pure tuple fields are their plain ones. -/
    theorem pure_opt_inter {d : Dispatcher} {x y : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y) (S : Term) :
        ∃ w, Elixir.Module.Types.Descr.«opt_tuple_intersection/3» d x y S = .ok w ∧ OField (PureLit t) w ∧
          ∀ ρ, Resp ρ → denO w ρ = (denO x ρ && denO y ρ) := by
      rcases fx with ⟨k, rfl⟩ | wx
      · exact ⟨y, by unfold Elixir.Module.Types.Descr.«opt_tuple_intersection/3»; rfl, fy, fun ρ _ => by rw [denO_top]; rfl⟩
      rcases fy with ⟨k, rfl⟩ | wy
      · exact ⟨x, opt_tuple_inter_top_eq (not_top_of_ok wx pureLit_not), Or.inr wx, fun ρ _ => by rw [denO_top]; simp⟩
      have nx := not_top_of_ok wx pureLit_not
      have ny := not_top_of_ok wy pureLit_not
      have plain : Elixir.Module.Types.Descr.«opt_tuple_intersection/3» d x y S =
          Elixir.Module.Types.Descr.«tuple_intersection/2» x y →
          ∃ w, Elixir.Module.Types.Descr.«opt_tuple_intersection/3» d x y S = .ok w ∧ OField (PureLit t) w ∧
            ∀ ρ, Resp ρ → denO w ρ = (denO x ρ && denO y ρ) := by
        intro e
        obtain ⟨r, hr, okr, semr⟩ := inter_ok wx wy
        have wr := okr _ wx wy
        refine ⟨r, by rw [e, tuple_intersection_bdd nx ny, hr], Or.inr wr, fun ρ hρ => ?_⟩
        rw [denO_bdd pureLit_not wr, denO_bdd pureLit_not wx, denO_bdd pureLit_not wy, semr _ hρ]
      have plainEq := fun h3 h4 h5 => plain (opt_tuple_inter_plain_eq (d := d) (S := S) nx ny h3 h4 h5)
      have closed : ∀ {k fo}, PureLit t (.tuple #[k, .atom "open", fo]) → False := by
        rintro k fo ⟨e, -, h⟩
        simp [litN] at h
      have xAtom : ∀ {s : String}, x = .atom s → ∃ w, Elixir.Module.Types.Descr.«opt_tuple_intersection/3» d x y S = .ok w ∧
          OField (PureLit t) w ∧ ∀ ρ, Resp ρ → denO w ρ = (denO x ρ && denO y ρ) := fun e => by
        subst e
        exact plainEq (fun _ _ _ _ _ _ e _ => by cases e) (fun _ _ _ _ _ _ _ e _ => by cases e)
          (fun _ _ _ _ _ _ _ _ e => by cases e)
      have yAtom : ∀ {s : String}, y = .atom s → ∃ w, Elixir.Module.Types.Descr.«opt_tuple_intersection/3» d x y S = .ok w ∧
          OField (PureLit t) w ∧ ∀ ρ, Resp ρ → denO w ρ = (denO x ρ && denO y ρ) := fun e => by
        subst e
        exact plainEq (fun _ _ _ _ _ _ _ e => by cases e) (fun _ _ _ _ _ _ _ _ e => by cases e)
          (fun _ _ _ _ _ _ _ e _ => by cases e)
      rcases wx.shape with ex | ex | ⟨k₁, a₁, b₁, rfl⟩ | ⟨h₁, lit₁, c₁, u₁, d₁, rfl⟩
      · exact xAtom ex
      · exact xAtom ex
      all_goals rcases wy.shape with ey | ey | ⟨k₂, a₂, b₂, rfl⟩ | ⟨h₂, lit₂, c₂, u₂, d₂, rfl⟩
      all_goals try exact yAtom ey
      · have same := pureLit_exact (Bdd.leaf_iff.mp wx) (Bdd.leaf_iff.mp wy)
        exact ⟨_, opt_tuple_inter_same (pureLit_not _ (Bdd.leaf_iff.mp wx)) same, Or.inr wx,
          fun ρ hρ => by rw [denO_congr pureLit_not (Or.inr wy) (Or.inr wx) (compare_eq_of_exactCompare_eq _ _ same) hρ,
            Bool.and_self]⟩
      · exact plainEq (fun _ _ _ _ _ _ _ e => by simp at e) (fun k fo _ _ _ _ _ e _ => closed (e ▸ Bdd.leaf_iff.mp wx))
          (fun _ _ _ _ _ _ _ e => by simp at e)
      · exact plainEq (fun _ _ _ _ _ _ e _ => by simp at e) (fun _ _ _ _ _ _ _ e _ => by simp at e)
          (fun k fo _ _ _ _ _ e _ => closed (e ▸ Bdd.leaf_iff.mp wy))
      · exact plainEq (fun _ _ _ _ _ _ e _ => by simp at e) (fun _ _ _ _ _ _ _ e _ => by simp at e)
          (fun _ _ _ _ _ _ _ e _ => by simp at e)

    end

    section
    variable {t : Term}

    /-- Expansions of accepted nodes meet: both hold nil. -/
    theorem disj_expN {e e' : Term} (he : IsT t e) (he' : IsT t e') {m : Nat} (hm : 8 ≤ m) :
        Elixir.Module.Types.Descr.«disjoint?/2» (D m) (expN e (keyOf t)) (expN e' (keyOf t)) = .ok (.atom "false") := by
      obtain ⟨s, run⟩ := (pure_sub_disj t).2 (Or.inr ⟨_, rfl, expN_pure he⟩) (Or.inr ⟨_, rfl, expN_pure he'⟩)
      have r := run m (by omega)
      cases s
      · simpa [boolAtom, expN] using r
      exfalso
      have pA := expN_pure he
      have pB := expN_pure he'
      have calls : ∀ {X Y : List (Term × Term)}, PureMap t X → PureMap t Y → ∀ e ∈ mapEntries X,
          ∀ y d', 2 ≤ d' → mapLookup Y e.1 = some y → ∃ w,
            Elixir.Module.Types.Descr.«bare_intersection/3» (D d') e.1 e.2 y = .ok w ∧ (kept (e.1, w) = Bool.true →
              ∃ b : Bool, Elixir.Module.Types.Descr.«empty_key?/2» (D d') e.1 w = .ok (boolAtom b)) := by
        intro X Y sX sY x mx y d' hd hy
        have hx := mapLookup_of_mem_mapEntries mx
        obtain ⟨name, key⟩ := sX.atomKey hx
        rw [key] at hx hy ⊢
        obtain ⟨w, run, k⟩ := interP t name x.2 y (sX.fields name x.2 hx) (sY.fields name y hy)
        refine ⟨w, run _, fun kw => ?_⟩
        by_cases nt : name = "tuple"
        · subst nt
          obtain ⟨b, hb⟩ := pure_tuple_empty (fieldP_tuple (k kw)) []
          exact ⟨b, by simpa [Elixir.Module.Types.Descr.«empty_key?/2», Elixir.Module.Types.Descr.«empty_key?/3»] using hb d' hd⟩
        · have h := fieldok_empty (D d') name (fieldP_other (k kw) nt)
          exact ⟨Bool.false, by simpa [Elixir.Module.Types.Descr.«empty_key?/2»] using h⟩
      -- the walk finds the atom field, whose intersection holds nil
      have stA := pA.static
      have stB := pB.static
      have hit : ∀ {X Y : List (Term × Term)}, PureMap t X → PureMap t Y →
          mapLookup X (.atom "atom") = some (.tuple #[.atom "union", .map [(.atom "nil", .nil)]]) →
          mapLookup Y (.atom "atom") = some (.tuple #[.atom "union", .map [(.atom "nil", .nil)]]) →
          (∀ e ∈ mapEntries X, ∀ y, mapLookup Y e.1 = some y → ∃ d', 2 ≤ d' ∧ ∃ w,
            Elixir.Module.Types.Descr.«bare_intersection/3» (D d') e.1 e.2 y = .ok w ∧
            (kept (e.1, w) = Bool.false ∨ Elixir.Module.Types.Descr.«empty_key?/2» (D d') e.1 w = .ok (.atom "true"))) →
          False := by
        intro X Y sX sY hX hY walk
        obtain ⟨x, mx, qx, -⟩ : ∃ x ∈ mapEntries X, exactCompare (.atom "atom") x.1 = .eq ∧ True := by
          have : (mapLookup (mapEntries X) (.atom "atom")).isSome := by rw [mapLookup_mapEntries, hX]; rfl
          obtain ⟨x, mx, qx⟩ := (mapLookup_isSome _ _).mp this
          exact ⟨x, mx, qx, trivial⟩
        have key : x.1 = .atom "atom" := ((exactCompare_eq_atom _ _).mp (Std.OrientedCmp.eq_symm qx))
        have hx := mapLookup_of_mem_mapEntries mx
        rw [key, hX] at hx
        obtain ⟨d', -, w, run, out⟩ := walk x mx _ (by rw [key]; exact hY)
        rw [key] at run out
        have hx' : x.2 = .tuple #[.atom "union", .map [(.atom "nil", .nil)]] := (Option.some.inj hx).symm
        rw [hx'] at run
        have fa : FieldOk "atom" (.tuple #[.atom "union", .map [(.atom "nil", .nil)]]) :=
          fieldP_other (sX.fields "atom" _ hX) (by decide)
        obtain ⟨r₀, rr, -, -, am, -⟩ := inter_key "atom" _ _ fa fa
        have e₀ : r₀ = w := by have := (rr (D d')).symm.trans run; simpa using this
        subst e₀
        have kr : kept (.atom "atom", r₀) = Bool.true := by
          have := am rfl (.atom "nil")
          cases k : kept (.atom "atom", r₀)
          · simp [k, amemV, mapLookup] at this
          · rfl
        rcases out with k | em
        · rw [k] at kr; cases kr
        · simp [Elixir.Module.Types.Descr.«empty_key?/2», Elixir.Module.Types.Descr.«empty_key?/3»] at em
      obtain ⟨sa, hsa⟩ : ∃ sa : Int, Erlang.erlang.«map_size/1» (expN e (keyOf t)) = .ok (.integer sa) :=
        ⟨_, by simp [Erlang.erlang.«map_size/1»]; rfl⟩
      obtain ⟨sb, hsb⟩ : ∃ sb : Int, Erlang.erlang.«map_size/1» (expN e' (keyOf t)) = .ok (.integer sb) :=
        ⟨_, by simp [Erlang.erlang.«map_size/1»]; rfl⟩
      simp only [expN] at hsa hsb
      have ue := upper_expN (D m) e (keyOf t)
      have ue' := upper_expN (D m) e' (keyOf t)
      simp only [expN] at ue ue'
      have h := r
      simp only at h
      unfold Elixir.Module.Types.Descr.«disjoint?/2» at h
      simp [getMapKeys_single, stA, stB, ue, ue', unfold_map, mapLookup, boolAtom] at h
      unfold Elixir.Module.Types.Descr.«non_disjoint_intersection?/2» at h
      have hA : mapLookup [(.atom "tuple", litN e (keyOf t)), (.atom "atom", .tuple #[.atom "union", .map [(.atom "nil", .nil)]])]
          (.atom "atom") = some (.tuple #[.atom "union", .map [(.atom "nil", .nil)]]) := by simp [mapLookup]
      have hB : mapLookup [(.atom "tuple", litN e' (keyOf t)), (.atom "atom", .tuple #[.atom "union", .map [(.atom "nil", .nil)]])]
          (.atom "atom") = some (.tuple #[.atom "union", .map [(.atom "nil", .nil)]]) := by simp [mapLookup]
      by_cases g : sa > sb
      · simp [hsa, hsb, g, Erlang.maps.«iterator/1»] at h
        have walk := iter_disj_gen 2 _ (mapEntries _) (calls pB pA) m
          (by have := entries_le_six pB.keys; omega) (not_true (by rw [bind_assoc]; exact h))
        exact hit pB pA hB hA walk
      · simp [hsa, hsb, g, Erlang.maps.«iterator/1»] at h
        have walk := iter_disj_gen 2 _ (mapEntries _) (calls pA pB) m
          (by have := entries_le_six pA.keys; omega) (not_true (by rw [bind_assoc]; exact h))
        exact hit pA pB hA hB walk
    end

    section
    variable {t : Term}

    /-- `opt_tuple_leaf_difference/3` finds expansion literals in each other. -/
    theorem pure_cmp {n : Nat} (hn : 8 ≤ n) (a₁ a₂ type : Term) (h₁ : PureLit t a₁) (h₂ : PureLit t a₂) :
        ∃ res, (D (n + 1)).pure (.function "Elixir.Module.Types.Descr" "opt_tuple_leaf_difference" 3 #[])
          #[a₁, a₂, type] = .ok res ∧ CmpOk Resp (PureLit t) a₁ a₂ type res := by
      obtain ⟨e₁, he₁, rfl⟩ := h₁
      obtain ⟨e₂, he₂, rfl⟩ := h₂
      rw [Erlang.program.«Elixir.Module.Types.Descr:opt_tuple_leaf_difference/3».pure]
      obtain ⟨m, rfl⟩ : ∃ m, n = m + 1 := ⟨n - 1, by omega⟩
      have dtt : Elixir.Module.Types.Descr.«disjoint?/2» (D (m + 1)) (.atom "term") (.atom "term") = .ok (.atom "false") := by
        rw [disj_term_l, empty_term_false]; rfl
      have stt := sub_term_term (D (m + 1))
      have dee : Elixir.Module.Types.Descr.«disjoint?/2» (D (m + 1)) e₁ e₂ = .ok (.atom "false") := by
        rw [disj_node_l he₁.node m (expand_isT he₁ m) _ (node_ne_term he₂) (fun X h => by obtain ⟨S, rfl, -⟩ := he₂.node; cases h),
          disj_node_r he₂.node m (expand_isT he₂ m) _ (expN_ne_term _ _) (fun X h => by simp [expN] at h; subst h; simp [mapLookup])]
        exact disj_expN he₁ he₂ (by omega)
      obtain ⟨s, hs⟩ := (pure_sub_disj t).1 (Or.inr ⟨_, rfl, expN_pure he₁⟩) (Or.inr ⟨_, rfl, expN_pure he₂⟩)
      have see : Elixir.Module.Types.Descr.«subtype?/2» (D (m + 1)) e₁ e₂ = .ok (boolAtom s) := by
        rw [sub_node_l he₁.node m (expand_isT he₁ m), sub_node_r he₂.node m (expand_isT he₂ m)]
        exact hs _ (by omega)
      refine ⟨if s then .atom "subtype" else .atom "none", ?_, ?_⟩
      · simp only [litN, Term.list]
        rw [Elixir.Module.Types.Descr.«opt_tuple_leaf_difference/3».eq_def]
        simp [Erlang.erlang.«length/1», Elixir.Module.Types.Descr.«tuple_sizes_strategy/4», Lynx.Except.guard,
          Erlang.erlang.«/=/2», Erlang.erlang.«==/2»]
        rw [Elixir.Module.Types.Descr.«opt_tuple_leaf_difference/3».eq_def]
        simp [dtt, stt, Lynx.Except.guard, Erlang.erlang.«/=/2», Lynx.Except.andAlso]
        rw [Elixir.Module.Types.Descr.«opt_tuple_leaf_difference/3».eq_def]
        simp [dee, see, Lynx.Except.guard, Erlang.erlang.«/=/2», Lynx.Except.andAlso]
        cases s
        · simp [boolAtom, Lynx.Except.tryWith]
        · simp [boolAtom, Lynx.Except.tryWith]
          rw [Elixir.Module.Types.Descr.«opt_tuple_leaf_difference/3».eq_def]
          simp [Lynx.Except.guard, isMember]
      · cases s
        · exact Or.inr (Or.inr (Or.inr rfl))
        · refine Or.inr (Or.inl ⟨rfl, fun ρ hρ h => ?_⟩)
          rw [← hρ _ _ (compare_eq_of_exactCompare_eq _ _ (pureLit_exact ⟨e₂, he₂, rfl⟩ ⟨e₁, he₁, rfl⟩))]
          exact h

    /-- Optimized differences of pure tuple fields. -/
    theorem pure_opt_diff {n : Nat} (hn : 8 ≤ n) {x y : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y) :
        ∃ w, Elixir.Module.Types.Descr.«opt_tuple_difference/2» (D (n + 1)) x y = .ok w ∧ OField (PureLit t) w ∧
          ∀ ρ, Resp ρ → denO w ρ = (denO x ρ && !denO y ρ) := by
      obtain ⟨w, run, fw, sem⟩ := pure_diff_sem fx fy
      rcases opt_tuple_split (D (n + 1)) x y with e | ⟨e, eb, ny, nx⟩ | ⟨k, a, b, rfl, same, e⟩
      · exact ⟨w, by rw [e, run], fw, sem⟩
      rotate_left
      · refine ⟨_, e, Or.inr Bdd.bot, fun ρ hρ => ?_⟩
        rw [denO_congr pureLit_not fy fx (compare_eq_of_exactCompare_eq _ _ same) hρ,
          show denO (.atom "bdd_bot") ρ = Bool.false by simp [denO, isOpenTop, eval]]
        cases denO (.tuple #[k, a, b]) ρ <;> rfl
      rw [e]
      have wy : Bdd (PureLit t) y := by
        rcases fy with ⟨k, rfl⟩ | wy
        · exact absurd rfl (ny _)
        · exact wy
      rcases fx with ⟨k, rfl⟩ | wx
      · rcases nx with nx | nx
        · exact absurd rfl (nx _)
        have wx : Bdd (fun l => l = .tuple #[.integer k, .atom "open", .nil]) (.tuple #[.integer k, .atom "open", .nil]) :=
          Bdd.leaf_iff.mpr rfl
        rcases wy.shape with rfl | rfl | ⟨k', a, b, rfl⟩ | ⟨h, lit, c, u, d, rfl⟩
        · exact ⟨w, by rw [d3_atom_right _ wx, ← eb, run], fw, sem⟩
        · exact ⟨w, by rw [d3_atom_right _ wx, ← eb, run], fw, sem⟩
        · exact absurd rfl (nx _)
        · exact absurd rfl (nx _)
      obtain ⟨r, hr, okr, semr⟩ := diff3_ok (Val := Resp) (fun _ h => h)
        (fun a₁ a₂ type _ h₁ h₂ => pure_cmp hn a₁ a₂ type h₁ h₂) _ y wy (fun _ h => h) x wx
      refine ⟨r, hr, Or.inr okr, fun ρ hρ => ?_⟩
      rw [denO_bdd pureLit_not okr, denO_bdd pureLit_not wx, denO_bdd pureLit_not wy, semr _ hρ]

    /-- Expansion literals fuse into themselves. -/
    theorem pure_fuse_leaf (d : Dispatcher) {e e' : Term} (he : IsT t e) (he' : IsT t e') :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_leaf/2» d (litN e (keyOf t)) (litN e' (keyOf t)) = .ok (litN e (keyOf t)) := by
      have ee := isT_exact he' he
      have leaf := leaf_isT he
      simp only [litN, Term.list] at leaf ⊢
      unfold Elixir.Module.Types.Descr.«opt_tuple_fuse_leaf/2»
      simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», Erlang.erlang.«length/1», Erlang.erlang.«==/2», Erlang.erlang.«and/2»,
        Lynx.Except.tryWith, Term.true]
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_elements/4».eq_def]
      simp [Lynx.Except.guard, Erlang.erlang.«=:=/2»]
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_elements/4».eq_def]
      simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», ee]
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_elements/4».eq_def]
      simp [Erlang.lists.«reverse/1», leaf, isMember]
      done

    theorem pure_union {x y : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y) :
        ∃ w, Elixir.Module.Types.Descr.«tuple_union/2» x y = .ok w ∧ OField (PureLit t) w ∧
          ∀ ρ, Resp ρ → denO w ρ = (denO x ρ || denO y ρ) :=
      open_union_spec pureLit_not _ tuple_union_shape.1 tuple_union_shape.2.1 tuple_union_shape.2.2 fx fy

    theorem chain_atom (d : Dispatcher) (s : String) (leaf z : Term) :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3» d (.atom s) leaf z = .ok (.atom "nil") := by
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3».eq_def]
      split <;> first | rfl | simp_all

    theorem fuse_leaf_top (d : Dispatcher) (e : Term) (k k' : Int) :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_leaf/2» d (litN e k) (.tuple #[.integer k', .atom "open", .nil]) =
          .ok (.atom "nil") := by
      simp only [litN, Term.list]
      unfold Elixir.Module.Types.Descr.«opt_tuple_fuse_leaf/2»
      simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», Erlang.erlang.«and/2», Lynx.Except.tryWith, Term.false,
        Erlang.erlang.«length/1», Erlang.erlang.«==/2»]

    theorem hρ_same {e e' : Term} (he : IsT t e) (he' : IsT t e') (ρ : Term → Bool) (hρ : Resp ρ) :
        ρ (litN e' (keyOf t)) = ρ (litN e (keyOf t)) :=
      hρ _ _ (compare_eq_of_exactCompare_eq _ _ (pureLit_exact ⟨e, he, rfl⟩ ⟨e', he', rfl⟩))

    /-- Adding a leaf to a node of expansion literals. -/
    theorem pure_union_leaf (m : Nat) {j : Int} {e₀ : Term} (h₀ : IsT t e₀) (c u d : Bool)
        (fb : OField (PureLit t) (.tuple #[.integer j, litN e₀ (keyOf t), bt c, bt u, bt d])) {leaf : Term}
        (fl : OField (PureLit t) leaf) (lf : (∃ k, leaf = .tuple #[.integer k, .atom "open", .nil]) ∨ PureLit t leaf) :
        ∃ r, Elixir.Module.Types.Descr.«opt_tuple_union_leaf/2» (D m)
          (.tuple #[.integer j, litN e₀ (keyOf t), bt c, bt u, bt d]) leaf = .ok r ∧ OField (PureLit t) r ∧
          ∀ ρ, Resp ρ → denO r ρ = (denO (.tuple #[.integer j, litN e₀ (keyOf t), bt c, bt u, bt d]) ρ || denO leaf ρ) := by
      obtain ⟨w, run, fw, sem⟩ := pure_union fb fl
      have plain : Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3» (D m)
          (.tuple #[.integer j, litN e₀ (keyOf t), bt c, bt u, bt d]) leaf (.integer 64) = .ok (.atom "nil") →
          ∃ r, Elixir.Module.Types.Descr.«opt_tuple_union_leaf/2» (D m)
            (.tuple #[.integer j, litN e₀ (keyOf t), bt c, bt u, bt d]) leaf = .ok r ∧ OField (PureLit t) r ∧
            ∀ ρ, Resp ρ → denO r ρ = (denO (.tuple #[.integer j, litN e₀ (keyOf t), bt c, bt u, bt d]) ρ || denO leaf ρ) := by
        intro ch
        refine ⟨w, ?_, fw, sem⟩
        rw [Elixir.Module.Types.Descr.«opt_tuple_union_leaf/2».eq_def]
        simp [ch, run]
      by_cases shape : c = Bool.true ∧ d = Bool.false
      · obtain ⟨rfl, rfl⟩ := shape
        rcases lf with ⟨k, rfl⟩ | ⟨e', he', rfl⟩
        · apply plain
          rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3».eq_def]
          cases u <;> simp [bt, fuse_leaf_top, isMember, Lynx.Except.guard, chain_atom]
        · have fl' : Bdd (PureLit t) (litN e₀ (keyOf t)) := Bdd.leaf_iff.mpr ⟨e₀, h₀, rfl⟩
          have fl'' : Bdd (PureLit t) (litN e' (keyOf t)) := Bdd.leaf_iff.mpr ⟨e', he', rfl⟩
          have wb : Bdd (PureLit t) (.tuple #[.integer j, litN e₀ (keyOf t), bt Bool.true, bt u, bt Bool.false]) := by
            rcases fb with ⟨k, h⟩ | w
            · simp at h
            · exact w
          have same := hρ_same (t := t) h₀ he'
          have ch : ∀ uu : Term, Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3» (D m)
              (.tuple #[.integer j, litN e₀ (keyOf t), bt Bool.true, uu, bt Bool.false]) (litN e' (keyOf t)) (.integer 64) =
              .ok (.tuple #[litN e₀ (keyOf t), uu]) := by
            intro uu
            rw [show bt Bool.true = .atom "bdd_top" from rfl, show bt Bool.false = .atom "bdd_bot" from rfl,
              Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3».eq_def]
            simp only [pure_fuse_leaf (D m) h₀ he']
            simp [isMember, Lynx.Except.guard, litN, Term.list]
          cases u
          · refine ⟨_, ?_, Or.inr fl', fun ρ hρ => ?_⟩
            · rw [Elixir.Module.Types.Descr.«opt_tuple_union_leaf/2».eq_def, ch]
              rfl
            · rw [denO_bdd pureLit_not fl', denO_bdd pureLit_not fl'', denO_bdd pureLit_not wb]
              have s' := same ρ hρ
              simp only [litN, Term.list] at s' ⊢
              simp [eval, bt, s']
          · obtain ⟨w', run', fw', sem'⟩ := pure_union (Or.inr (Bdd.top (ok := PureLit t))) (Or.inr fl')
            refine ⟨w', ?_, fw', fun ρ hρ => ?_⟩
            · rw [Elixir.Module.Types.Descr.«opt_tuple_union_leaf/2».eq_def, ch]
              simp only [bt]
              simp
              rw [Elixir.Module.Types.Descr.«opt_tuple_union_leaf/2».eq_def]
              simp [chain_atom, run']
            · rw [sem' ρ hρ, denO_bdd pureLit_not (Bdd.top (ok := PureLit t)), denO_bdd pureLit_not wb]
              simp [eval, bt]
      · apply plain
        rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_chain/3».eq_def]
        cases c <;> cases d <;> simp_all [bt]
        all_goals done

    theorem via_pure_union {m : Nat} {x y : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y)
        (e : Elixir.Module.Types.Descr.«opt_tuple_union/2» (D m) x y = Elixir.Module.Types.Descr.«tuple_union/2» x y) :
        ∃ w, Elixir.Module.Types.Descr.«opt_tuple_union/2» (D m) x y = .ok w ∧ OField (PureLit t) w ∧
          ∀ ρ, Resp ρ → denO w ρ = (denO x ρ || denO y ρ) := by
      obtain ⟨w, run, fw, sem⟩ := pure_union fx fy
      exact ⟨w, by rw [e, run], fw, sem⟩

    /-- Optimized unions of pure tuple fields. -/
    theorem pure_opt_union (m : Nat) {x y : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y) :
        ∃ w, Elixir.Module.Types.Descr.«opt_tuple_union/2» (D m) x y = .ok w ∧ OField (PureLit t) w ∧
          ∀ ρ, Resp ρ → denO w ρ = (denO x ρ || denO y ρ) := by
      have fx' := fx
      have fy' := fy
      rcases pure_cases fx with ⟨k₁, rfl⟩ | rfl | rfl | ⟨e₁, h₁, rfl⟩ | ⟨j₁, e₁, c₁, u₁, d₁, h₁, rfl⟩ <;>
        rcases pure_cases fy with ⟨k₂, rfl⟩ | rfl | rfl | ⟨e₂, h₂, rfl⟩ | ⟨j₂, e₂, c₂, u₂, d₂, h₂, rfl⟩
      all_goals first
        | exact via_pure_union fx' fy' (by unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»; rfl)
        | (apply via_pure_union fx' fy'
           unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
           simp only [leaf_guard, atom_ne3, node_ne3, if_false, litN, Term.list]
           done)
        | skip
      -- two top leaves
      · by_cases same : exactCompare (.tuple #[.integer k₂, .atom "open", .nil]) (.tuple #[.integer k₁, .atom "open", .nil]) = .eq
        · refine ⟨_, by unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»; simp only [leaf_guard, if_pos same]; rfl,
            fx', fun ρ _ => by simp [denO_top]⟩
        have st := strategy_start (D m) "open" "open" (Or.inl rfl) (Or.inl rfl) [] []
        simp only [Term.list, List.length_nil, and_self, ite_true] at st
        rw [show Term.nil = Term.list [] from rfl, index_nil_left] at st
        refine ⟨_, ?_, fy', fun ρ _ => by simp [denO_top]⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», same, st, endSt]
      -- the top leaf and a literal
      · have same : ¬exactCompare (litN e₂ (keyOf t)) (.tuple #[.integer k₁, .atom "open", .nil]) = .eq := by
          simp [litN, Term.list, exactCompare_tuple, List.compareLex_cons_cons]
        have st := strategy_start (D m) "open" "closed" (Or.inl rfl) (Or.inr rfl) [] [.atom "term", e₂]
        simp only [List.length_nil, List.length_cons, String.reduceEq, false_and, if_false, true_and] at st
        rw [index_nil_left] at st
        refine ⟨_, ?_, fx', fun ρ _ => by simp [denO_top]⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», litN, Term.list, exactCompare_tuple, List.compareLex_cons_cons] at st ⊢
        simp [st, endSt]
      · obtain ⟨r, hr, fr, sr⟩ := pure_union_leaf m h₂ c₂ u₂ d₂ fy' fx' (Or.inl ⟨k₁, rfl⟩)
        refine ⟨r, ?_, fr, fun ρ hρ => by rw [sr ρ hρ, Bool.or_comm]⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp only [leaf_guard, node_ne3, if_false]
        exact hr
      · have same : ¬exactCompare (.tuple #[.integer k₂, .atom "open", .nil]) (litN e₁ (keyOf t)) = .eq := by
          simp [litN, Term.list, exactCompare_tuple, List.compareLex_cons_cons]
        have st := strategy_start (D m) "closed" "open" (Or.inr rfl) (Or.inl rfl) [.atom "term", e₁] []
        simp only [List.length_nil, List.length_cons, String.reduceEq, false_and, if_false, true_and] at st
        rw [index_nil_right] at st
        refine ⟨_, ?_, fy', fun ρ _ => by simp [denO_top]⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», litN, Term.list, exactCompare_tuple, List.compareLex_cons_cons] at st ⊢
        simp [st, endSt]
      · have same := pureLit_exact ⟨e₁, h₁, rfl⟩ ⟨e₂, h₂, rfl⟩
        refine ⟨_, ?_, fx', fun ρ hρ => by rw [denO_congr pureLit_not fy' fx' (compare_eq_of_exactCompare_eq _ _ same) hρ,
          Bool.or_self]⟩
        have same' := same
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp only [litN, Term.list] at same' ⊢
        simp only [leaf_guard, if_pos same']
        rfl
      · obtain ⟨r, hr, fr, sr⟩ := pure_union_leaf m h₂ c₂ u₂ d₂ fy' fx' (Or.inr ⟨e₁, h₁, rfl⟩)
        refine ⟨r, ?_, fr, fun ρ hρ => by rw [sr ρ hρ, Bool.or_comm]⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp only [leaf_guard, node_ne3, if_false, litN, Term.list]
        exact hr
      · obtain ⟨r, hr, fr, sr⟩ := pure_union_leaf m h₁ c₁ u₁ d₁ fx' fy' (Or.inl ⟨k₂, rfl⟩)
        refine ⟨r, ?_, fr, sr⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp only [leaf_guard, atom_ne3, node_ne3, if_false]
        exact hr
      · obtain ⟨r, hr, fr, sr⟩ := pure_union_leaf m h₁ c₁ u₁ d₁ fx' fy' (Or.inr ⟨e₂, h₂, rfl⟩)
        refine ⟨r, ?_, fr, sr⟩
        unfold Elixir.Module.Types.Descr.«opt_tuple_union/2»
        simp only [leaf_guard, atom_ne3, node_ne3, if_false, litN, Term.list]
        exact hr

    theorem pure_lh_bound {x y w : Term} (fx : OField (PureLit t) x) (fy : OField (PureLit t) y) (fw : OField (PureLit t) w)
        (tops : (∃ k, x = .tuple #[.integer k, .atom "open", .nil]) → (∃ k, y = .tuple #[.integer k, .atom "open", .nil]) →
          lh w = 0) : lh w ≤ max (lh x) (lh y) := by
      by_cases tx : ∃ k, x = .tuple #[.integer k, .atom "open", .nil]
      · by_cases ty : ∃ k, y = .tuple #[.integer k, .atom "open", .nil]
        · rw [tops tx ty]; omega
        · have := pure_one fy fun k h => ty ⟨k, h⟩
          have := pure_le fw
          omega
      · have := pure_one fx fun k h => tx ⟨k, h⟩
        have := pure_le fw
        omega

    theorem pure_nz {w : Term} (fw : OField (PureLit t) w) : w ≠ .integer 0 := by
      rcases fw with ⟨k, rfl⟩ | ww
      · simp
      · exact bdd_ne_zero ww

    /-- Tuple fields of expansion literals of the node `t`, at the bottom level. -/
    theorem pureKind {K : Nat} (hK : 10 ≤ K) : KindOk K "tuple" (OField (PureLit t)) Resp where
      resp := fun _ h => h
      wit := ⟨_, resp_const Bool.true⟩
      top := fun t' ht => by
        rcases ht with ⟨h, _⟩ | ⟨h, _⟩ | ⟨h, _⟩ | ⟨h, _⟩ | ⟨-, rfl⟩ | ⟨h, _⟩ <;> try simp at h
        exact ⟨Or.inl ⟨_, rfl⟩, lh_top_leaf _, fun p _ => by rw [dn_tuple, denO_top]⟩
      congr := fun fx fx' e p hp => by
        rw [dn_tuple, dn_tuple]
        exact denO_congr pureLit_not fx fx' e hp
      union := fun {x y} fx fy => by
        obtain ⟨w, run, fw, sem⟩ := pure_union fx fy
        refine ⟨w, fun m _ => by simp [Elixir.Module.Types.Descr.«bare_union/3», run], fw,
          fun p hp => by rw [dn_tuple, dn_tuple, dn_tuple, sem _ hp], pure_lh_bound fx fy fw fun ⟨k, ex⟩ _ => ?_⟩
        subst ex
        rw [tuple_union_shape.1] at run
        cases run
        exact lh_top_leaf _
      inter := fun {x y} fx fy => by
        obtain ⟨w, run, k, d⟩ := open_inter_spec pureLit_not _ tuple_inter_shape.1 tuple_inter_shape.2.1
          tuple_inter_shape.2.2 (.atom "tuple") fx fy
        refine ⟨w, fun m _ => by simp [Elixir.Module.Types.Descr.«bare_intersection/3», run],
          fun kw => ⟨(k kw).1, pure_lh_bound fx fy (k kw).1 fun ⟨k₁, ex⟩ ⟨k₂, ey⟩ => ?_⟩, fun p hp => ?_⟩
        · subst ex ey
          rw [tuple_inter_shape.1] at run
          cases run
          exact lh_top_leaf _
        · cases kk : kept (.atom "tuple", w)
          · rw [keptO_false kk, dn_none, dn_tuple, dn_tuple, d kk _ hp]
          · rw [keptO_true kk, dn_tuple, dn_tuple, dn_tuple, (k kk).2 _ hp]
      diff := fun {x y} fx fy => by
        obtain ⟨w, run, fw, sem⟩ := pure_diff_sem fx fy
        refine ⟨w, fun m _ => by simp [Elixir.Module.Types.Descr.«bare_difference/3», run],
          fun kw => ⟨fw, pure_lh_bound fx fy fw fun ⟨k₁, ex⟩ ⟨k₂, ey⟩ => ?_⟩, fun p hp => ?_⟩
        · subst ex ey
          have : w = .atom "bdd_bot" := by
            unfold Elixir.Module.Types.Descr.«tuple_difference/2» at run
            simp at run
            exact run.symm
          subst this
          simp [kept] at kw
        · cases kk : kept (.atom "tuple", w)
          · rw [keptO_false kk, dn_none, dn_tuple, dn_tuple, ← sem _ hp,
              dropped_bdd (by rw [kept_name]; exact kk) (pure_nz fw)]
            simp [denO, isOpenTop, eval]
          · rw [keptO_true kk, dn_tuple, dn_tuple, dn_tuple, sem _ hp]
      opt_union := fun {x y} S {m} fx fy hm => by
        obtain ⟨w, run, fw, sem⟩ := pure_opt_union m fx fy
        exact ⟨w, by simpa [Elixir.Module.Types.Descr.«opt_union/4»] using run, fw,
          fun p hp => by rw [dn_tuple, dn_tuple, dn_tuple, sem _ hp]⟩
      opt_inter := fun {x y} S {m} fx fy hm => by
        obtain ⟨w, run, fw, sem⟩ := pure_opt_inter (d := D m) fx fy (.map S)
        refine ⟨w, by simpa [Elixir.Module.Types.Descr.«opt_intersection/4»] using run, fun _ => fw, fun p hp => ?_⟩
        cases kk : kept (.atom "tuple", w)
        · rw [keptO_false kk, dn_none, dn_tuple, dn_tuple, ← sem _ hp,
            dropped_bdd (by rw [kept_name]; exact kk) (pure_nz fw)]
          simp [denO, isOpenTop, eval]
        · rw [keptO_true kk, dn_tuple, dn_tuple, dn_tuple, sem _ hp]
      opt_diff := fun {x y} S {m} fx fy hm => by
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        obtain ⟨w, run, fw, sem⟩ := pure_opt_diff (n := n) (by omega) fx fy
        refine ⟨w, by simpa [Elixir.Module.Types.Descr.«opt_difference/4»] using run, fun _ => fw, fun p hp => ?_⟩
        cases kk : kept (.atom "tuple", w)
        · rw [keptO_false kk, dn_none, dn_tuple, dn_tuple, ← sem _ hp,
            dropped_bdd (by rw [kept_name]; exact kk) (pure_nz fw)]
          simp [denO, isOpenTop, eval]
        · rw [keptO_true kk, dn_tuple, dn_tuple, dn_tuple, sem _ hp]
      empty := fun {x} S fx => by
        obtain ⟨b, run⟩ := pure_tuple_empty fx S
        refine ⟨b, fun m hm => by simpa [Elixir.Module.Types.Descr.«empty_key?/3»] using run m (by omega),
          fun N hx hS => ?_⟩
        have v := pure_empty_val fx (not_seen hS hx "tuple") (safeN_noid hS _) (m := 2) (by omega)
        rw [run 2 (by omega)] at v
        have hb : b = (!denO x (fun _ => Bool.true) && !denO x (fun _ => Bool.false)) := by
          cases b <;> cases h : (!denO x (fun _ => Bool.true) && !denO x (fun _ => Bool.false)) <;> simp_all [boolAtom]
        subst hb
        constructor
        · intro h p hp
          rw [dn_tuple]
          obtain ⟨c, hc⟩ := pure_val fx hp
          rw [hc]
          simp only [Bool.and_eq_true, Bool.not_eq_true'] at h
          cases c
          · exact h.2
          · exact h.1
        · intro h
          have h₁ := h (0, .nil, fun _ => Bool.true) (resp_const _)
          have h₂ := h (0, .nil, fun _ => Bool.false) (resp_const _)
          rw [dn_tuple] at h₁ h₂
          simp [h₁, h₂]

    end

    /-- The kinds of the bottom level. -/
    theorem kinds0 (t : Term) {K : Nat} (hK : 10 ≤ K) :
        Kinds K (OField (PureLit t)) (FieldOk "list") (FieldOk "map") Resp Resp Resp :=
      ⟨pureKind hK, topKind "list" (Or.inl rfl) (by omega), topKind "map" (Or.inr rfl) (by omega)⟩

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Element types hold only the top function type in their function fields. -/

    def funTopT : Term := .tuple #[.atom "negation", .map []]

    def FunTop (x : Term) : Prop := x = funTopT

    theorem fun_top_inter (n : Nat) :
        Elixir.Module.Types.Descr.«bare_intersection/3» (D (n + 1)) (.atom "fun") funTopT funTopT = .ok funTopT := by
      have mrun := merge_with_eq (D (n + 1)) "Elixir.Module.Types.Descr" "-fun_repr_union/2-fun-0-" #[] [] []
        (fun _ _ _ => .nil) (by intro e me; simp at me)
      simp only [mergeList, mapEntries_nil] at mrun
      simp [funTopT, Elixir.Module.Types.Descr.«bare_intersection/3», Elixir.Module.Types.Descr.«fun_intersection/2»,
        Elixir.Module.Types.Descr.«fun_repr_union/2», Elixir.Module.Types.Descr.«symmetrical_merge/3», mrun, Erlang.erlang.«==/2»]

    theorem fun_top_diff (n : Nat) :
        Elixir.Module.Types.Descr.«bare_difference/3» (D n) (.atom "fun") funTopT funTopT = .ok (.integer 0) := by
      simp [funTopT, Elixir.Module.Types.Descr.«bare_difference/3», Elixir.Module.Types.Descr.«fun_difference/2»,
        Elixir.Module.Types.Descr.«fun_repr_difference/2», Erlang.maps.«fold/3»,
        Erlang.erlang.«==/2», Erlang.erlang.«map_size/1»]

    theorem fun_top_ne : FunNE FunTop := by
      intro x hx d S
      subst hx
      simp [funTopT, Elixir.Module.Types.Descr.«empty_key?/3», Elixir.Module.Types.Descr.«fun_empty?/2»]

    theorem funF_top : FunF funTopT := ⟨Bool.false, [], rfl, fun q v h => by simp [mapLookup] at h⟩

    theorem lh_funTop : lh funTopT = 0 := by
      have := lh_nil_map
      simp [funTopT, lh] at this ⊢
      exact this

    theorem dn_funTop (p : Point) : dn "fun" (some funTopT) p = Bool.true := by
      simp [dn, funTopT, arityOf, mapLookup]

    theorem funTopC {K : Nat} (hK : 1 ≤ K) : FunC K FunTop (fun _ => True) True where
      funF := fun h => h ▸ funF_top
      union := fun {x y} hx hy m w hm run => by
        subst hx; subst hy
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        rw [funTopT, fun_top_union] at run
        cases run
        exact ⟨rfl, fun _ => by rw [← funTopT, lh_funTop]; simp⟩
      inter := fun {x y} hx hy m w hm run _ => by
        subst hx; subst hy
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        rw [fun_top_inter] at run
        cases run
        exact ⟨rfl, fun _ => by simp [lh_funTop]⟩
      diff := fun {x y} hx hy m w hm run k => by
        subst hx; subst hy
        rw [fun_top_diff] at run
        cases run
        simp [kept] at k
      empty := fun {x} S {m} hx _ _ => by
        subst hx
        refine ⟨fun h => ?_, fun _ => ⟨Bool.false, by simpa [boolAtom] using fun_top_ne _ rfl (D m) (.map S)⟩⟩
        have := h (0, .atom "x", fun _ => Bool.true) (fun _ _ _ => rfl)
        rw [dn_funTop] at this
        cases this

    /-! Element types are nested types of the plain laws, below their height. -/

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    theorem tfield_nest {x : Term} (fx : TField E x) {N : Nat} (h : lh x < N) : OField (TupleOk (EB E N)) x := by
      rcases fx with top | wx
      · exact Or.inl top
      refine Or.inr ((bdd_lh_le wx (fun _ h => h) (lh x) (Nat.le_refl _)).mono fun t ⟨ht, le⟩ => ?_)
      obtain ⟨-, below⟩ := tlit_lh ht
      obtain ⟨⟨⟨k, tag, l, rfl, g, els⟩, nt⟩, -⟩ := ht
      exact ⟨⟨k, tag, l, rfl, g, fun e me => ⟨els e me, by have := (below k tag l rfl e me).1; omega⟩⟩, nt⟩

    theorem mfield_nest {x : Term} (fx : MField E x) {N : Nat} (h : lh x < N) : OField (MapOk (EB E N)) x := by
      rcases fx with top | wx
      · exact Or.inl top
      refine Or.inr ((mbdd_lh_le wx (fun _ h => h) (lh x) (Nat.le_refl _)).mono fun t ⟨ht, le⟩ => ?_)
      obtain ⟨-, below⟩ := mlit_lh ht
      obtain ⟨⟨k, tag, l, rfl, g, ⟨fs, -⟩⟩, nt, -⟩ := ht
      obtain ⟨bf, bd⟩ := below k tag l rfl
      refine ⟨⟨k, tag, l, rfl, ?_, fun e me => ?_⟩, nt⟩
      · rcases g with rfl | rfl | ⟨dl, rfl, dv⟩
        · exact MapTag.atom_open
        · exact MapTag.atom_closed
        · refine Or.inr (Or.inr ⟨dl, rfl, fun e me => ⟨(dv.1 e me).2, ?_⟩⟩)
          have := bd e (by rw [domFields_fieldsTerm]; exact me); omega
      · obtain ⟨u, o, eu, hu⟩ := (fs e me).2
        exact ⟨u, o, eu, hu, by have := bf e me u o eu; omega⟩

    theorem lf_nest (ef : EF nd E V den tl K) {x : Term} (fx : LF E x) {N : Nat} (hN : 0 < N) (h : lh x < N) :
        Bdd (LLit (EB E N)) x := by
      refine (nl_lit_le ef fx (fun _ h => h) (max (lh x) 1) (by omega) (fun _ => by omega)).mono fun t ⟨ht, le⟩ => ?_
      obtain ⟨k, a, b, rfl, ha, hb⟩ := ht
      rw [litH_eq] at le
      exact ⟨k, a, b, rfl, ⟨ha, by omega⟩, ⟨hb, by omega⟩⟩

    /-- The element types of the next level, below a height. -/
    theorem descr_nest (ef : EF nd E V den tl K) {X : List (Term × Term)}
        (sX : DescrC FunTop (TField E) (LF E) (MField E) X) {N : Nat} (h : lh (.map X) < N) : NestFields (EB E N) X := by
      refine ⟨fun q hq => ?_, fun name w hw => ?_⟩
      · obtain ⟨name, m, rfl⟩ := sX.keys q hq
        simp [names] at m
        rcases m with rfl | rfl | rfl | rfl | rfl | rfl <;> simp
      · have le := lh_field_le hw
        rcases sX.fields name w hw with ⟨rfl, b⟩ | ⟨rfl, a⟩ | ⟨rfl, f⟩ | ⟨rfl, l⟩ | ⟨rfl, t⟩ | ⟨rfl, m⟩
        · exact Or.inl ⟨by simp, by simp, by simp, by simp, Or.inl ⟨rfl, b⟩⟩
        · exact Or.inl ⟨by simp, by simp, by simp, by simp, Or.inr (Or.inl ⟨rfl, a⟩)⟩
        · subst f; exact Or.inr (Or.inl ⟨rfl, Bool.false, [], rfl, fun q v h => by simp [mapLookup] at h⟩)
        · exact Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, lf_nest ef l (by omega) (by omega)⟩)))
        · exact Or.inr (Or.inr (Or.inl ⟨rfl, tfield_nest t (by omega)⟩))
        · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, mfield_nest m (by omega)⟩)))

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! The top type and `:term` operands, for types over the structural kinds. -/

    section
    variable {K : Nat} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}

    theorem topAt_fieldC (ks : Kinds K TF LF MF TV LV MV) {name : String} {t : Term} (ht : TopAt name t) :
        FieldC FunTop TF LF MF name t ∧ lh t = 0 ∧ ∀ p, PtOkC TV LV MV name p → dn name (some t) p = Bool.true := by
      have plain : name = "bitmap" ∨ name = "atom" ∨ name = "fun" →
          ∀ p, PtOkC TV LV MV name p → dn name (some t) p = Bool.true := fun h p ok =>
        (top_field (E := fun _ => True) ht).2.1 p ⟨ok.1, ok.2.1, fun e => by rcases h with rfl | rfl | rfl <;> simp at e⟩
      rcases ht with ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨rfl, rfl⟩ | ⟨rfl, e⟩ | ⟨rfl, e⟩ | ⟨rfl, e⟩
      · exact ⟨Or.inl ⟨rfl, 255, rfl, by decide, by decide⟩, lh_int _, plain (Or.inl rfl)⟩
      · refine ⟨Or.inr (Or.inl ⟨rfl, ⟨⟨Bool.false, [], rfl, no_atoms⟩, .nil, by simp [amemV, mapLookup]⟩⟩), ?_,
          plain (Or.inr (Or.inl rfl))⟩
        have := lh_nil_map
        simp [lh] at this ⊢; exact this
      · exact ⟨Or.inr (Or.inr (Or.inl ⟨rfl, rfl⟩)), lh_funTop, plain (Or.inr (Or.inr rfl))⟩
      · obtain ⟨f, l, d⟩ := ks.l.top t (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, e⟩))))
        exact ⟨Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, f⟩))), l, fun p ok => d p (ok.2.2.1 rfl)⟩
      · obtain ⟨f, l, d⟩ := ks.t.top t (Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, e⟩)))))
        exact ⟨Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, f⟩)))), l, fun p ok => d p (ok.2.2.2.1 rfl)⟩
      · obtain ⟨f, l, d⟩ := ks.m.top t (Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, e⟩)))))
        exact ⟨Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, f⟩)))), l, fun p ok => d p (ok.2.2.2.2 rfl)⟩

    /-- The unfolded top type holds every point, at no height. -/
    theorem termC (ks : Kinds K TF LF MF TV LV MV) : ∃ T, Elixir.Module.Types.Descr.«unfolded_term/0» = .ok (.map T) ∧
        DescrC FunTop TF LF MF T ∧ T ≠ [] ∧ lh (.map T) = 0 ∧
        ∀ name ∈ names, ∀ p, PtOkC TV LV MV name p → dn name (mapLookup T (.atom name)) p = Bool.true := by
      obtain ⟨T, term, -⟩ := unfolded_term_fields
      have keys : ∀ q, (mapLookup T q).isSome → ∃ name ∈ names, q = .atom name := fun q h => by
        obtain ⟨t, ht⟩ := Option.isSome_iff_exists.mp h
        obtain ⟨name, m, e, -⟩ := term_top term ht
        exact ⟨name, m, e⟩
      have fields : ∀ name t, mapLookup T (.atom name) = some t → TopAt name t := fun name t h => by
        obtain ⟨name', -, e, ht⟩ := term_top term h
        simp only [Term.atom.injEq] at e
        subst e; exact ht
      refine ⟨T, term, ⟨keys, fun name t h => (topAt_fieldC ks (fields name t h)).1⟩, term_ne_nil term,
        Nat.le_zero.mp (lh_descr_le keys fun name t h => by rw [(topAt_fieldC ks (fields name t h)).2.1]; omega),
        fun name m p ok => ?_⟩
      obtain ⟨t, ht, top⟩ := term_at term m
      rw [ht]
      exact (topAt_fieldC ks top).2.2 p ok

    end

    theorem diff_term_left (d : Dispatcher) {T B : List (Term × Term)}
        (term : Elixir.Module.Types.Descr.«unfolded_term/0» = .ok (.map T)) (sT : mapLookup T (.atom "dynamic") = none)
        (sB : mapLookup B (.atom "dynamic") = none) (ne : B ≠ []) :
        Elixir.Module.Types.Descr.«bare_difference/2» d (.atom "term") (.map B) =
          Elixir.Module.Types.Descr.«bare_difference/2» d (.map T) (.map B) := by
      unfold Elixir.Module.Types.Descr.«bare_difference/2»
      simp [Erlang.erlang.«==/2», unfold_map, static_map sT, static_map sB, ne]
      unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
      simp [Erlang.erlang.«==/2», ne, unfold_map, term]

    theorem opt_diff_term_left (d : Dispatcher) {T B : List (Term × Term)} (S : Term)
        (term : Elixir.Module.Types.Descr.«unfolded_term/0» = .ok (.map T)) (sT : mapLookup T (.atom "dynamic") = none)
        (sB : mapLookup B (.atom "dynamic") = none) (ne : B ≠ []) :
        Elixir.Module.Types.Descr.«opt_difference/3» d (.atom "term") (.map B) S =
          Elixir.Module.Types.Descr.«opt_difference/3» d (.map T) (.map B) S := by
      unfold Elixir.Module.Types.Descr.«opt_difference/3»
      simp [Erlang.erlang.«==/2», unfold_map, static_map sT, static_map sB, ne]
      unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
      simp [Erlang.erlang.«==/2», ne, unfold_map, term]

    theorem opt_union_term_r (d : Dispatcher) (a S : Term) :
        Elixir.Module.Types.Descr.«opt_union/3» d a (.atom "term") S = .ok (.atom "term") := by
      unfold Elixir.Module.Types.Descr.«opt_union/3»; split <;> simp_all

    theorem opt_inter_term_r (d : Dispatcher) (a S : Term) :
        Elixir.Module.Types.Descr.«opt_intersection/3» d a (.atom "term") S = .ok a := by
      unfold Elixir.Module.Types.Descr.«opt_intersection/3»; split <;> simp_all

    theorem fuse_term_l (d : Dispatcher) (b n : Term) :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» d (.atom "term") b n = .ok (.atom "nil") := by
      unfold Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3»
      simp [Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1», getMapKeys]

    theorem fuse_term_r (d : Dispatcher) (A : List (Term × Term)) (n : Term) :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» d (.map A) (.atom "term") n = .ok (.atom "nil") := by
      unfold Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3»
      simp only [Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1», getMapKeys]
      repeat' split
      all_goals simp_all [Lynx.Except.andAlso, Erlang.erlang.«==/2», Erlang.erlang.«map_size/1»]
      all_goals (repeat' split) <;> simp_all

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! The element types of the next level: the top type and types over the structural kinds of element types. -/

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    theorem EF.funB (ef : EF nd E V den tl K) (N : Nat) : ElemFun (EB E N) K where
      static := fun ha => ef.static ha.1
      union := fun ha hb => let ⟨c, hc, run, _, h⟩ := ef.union ha.1 hb.1; ⟨c, ⟨hc, h N ha.2 hb.2⟩, run⟩
      sub := fun ha hb => let ⟨s, run, _⟩ := ef.sub ha.1 hb.1; ⟨s, run⟩
      disj := fun ha hb => let ⟨s, run, _⟩ := ef.disj ha.1 hb.1; ⟨s, run⟩

    theorem EF.tailB (ef : EF nd E V den tl K) (N : Nat) : TailOk (EB E N) := fun _ he =>
      let ⟨e', run, he', _, hl⟩ := ef.tail he.1
      ⟨e', run, he', by have := he.2; omega⟩

    /-- Types over fields `TF`, `LF`, and `MF`, whose function fields are the top function type. -/
    def DEG (TF LF MF : Term → Prop) (a : Term) : Prop :=
      a = .atom "term" ∨ ∃ X, a = .map X ∧ DescrC FunTop TF LF MF X

    /-- Element types of the next level. -/
    abbrev DE (E : Term → Prop) : Term → Prop := DEG (TField E) (LF E) (MField E)

    /-- Points of types: a field name and a point valid there. -/
    abbrev PtG (TV LV MV : (Term → Bool) → Prop) : Type :=
      {q : String × Point // q.1 ∈ names ∧ PtOkC TV LV MV q.1 q.2}

    /-- Points of the next level. -/
    abbrev PtOkD (E : Term → Prop) (den : Term → V → Prop) (tl : V → Prop) (name : String) (p : Point) : Prop :=
      PtOkC (ValT E den) (ValLN E den tl) (ValMN E den) name p

    abbrev PtD (E : Term → Prop) (den : Term → V → Prop) (tl : V → Prop) : Type :=
      PtG (ValT E den) (ValLN E den tl) (ValMN E den)

    section
    variable {C : Nat → Term → Prop} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}

    def denD (a : Term) (q : PtG TV LV MV) : Prop :=
      a = .atom "term" ∨ ∃ X, a = .map X ∧ dn q.1.1 (mapLookup X (.atom q.1.1)) q.1.2 = Bool.true

    def tlD (q : PtG TV LV MV) : Prop := q.1.1 = "list"

    theorem denD_term (q : PtG TV LV MV) : denD (.atom "term") q := Or.inl rfl

    theorem denD_map {X : List (Term × Term)} (q : PtG TV LV MV) :
        denD (.map X) q ↔ dn q.1.1 (mapLookup X (.atom q.1.1)) q.1.2 = Bool.true := by
      simp [denD]

    end

    theorem de_nest (ef : EF nd E V den tl K) {a : Term} (ha : DE E a) {N : Nat} (h : lh a < N) : NestC (EB E N) a := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · exact Or.inl rfl
      · exact Or.inr ⟨X, rfl, descr_nest ef sX h⟩

    /-- The plain operations on element types of the next level, below a height, at every call depth. -/
    theorem nest_ops (ef : EF nd E V den tl K) (hnone : E (.map [])) {N : Nat} (hN : 0 < N) :
        ElemOk (NestC (EB E N)) (K + 8) ∧ ElemDiff (NestC (EB E N)) (K + 3) ∧ ElemFun (NestC (EB E N)) (K + 14) := by
      have none : EB E N (.map []) := ⟨hnone, by rw [lh_nil_map]; exact hN⟩
      have term : EB E N (.atom "term") := ⟨ef.term, by simp [lh]; exact hN⟩
      exact ⟨nestOk (ef.ops N hN) (ef.dops N) (ef.funB N) none (ef.tailB N), nestDiff term K,
        nestFun (ef.ops N hN) (ef.dops N) (ef.funB N) none (ef.tailB N)⟩

    theorem lh_term_zero : lh (.atom "term") = 0 := by simp [lh]

    abbrev ksOf (ef : EF nd E V den tl K) := kinds ef

    theorem fcOf (K : Nat) : FunC (K + 2) FunTop (fun _ => True) True := funTopC (by omega)

    /-- What the step to the next level needs: kinds of fields, and the plain operations on a class `C N` of types
    holding the types over those fields below each height `N`. -/
    structure StepOk (nd : Term) (C : Nat → Term → Prop) (K : Nat) (TF LF MF : Term → Prop)
        (TV LV MV : (Term → Bool) → Prop) : Prop where
      ks : Kinds (K + 2) TF LF MF TV LV MV
      nest : ∀ {a N}, DEG TF LF MF a → lh a < N → C N a
      ops : ∀ {N}, 0 < N → ElemOk (C N) (K + 8) ∧ ElemDiff (C N) (K + 3) ∧ ElemFun (C N) (K + 14)
      tz : ∀ {x}, TF x → lh x = 0 → ∃ k : Int, x = .tuple #[.integer k, .atom "open", .nil]
      lz : ∀ {x}, LF x → lh x = 0 → x = .tuple #[.integer 46675407, .atom "term", .atom "term"]
      mz : ∀ {x}, MF x → lh x = 0 → ∃ k : Int, x = .tuple #[.integer k, .atom "open", .nil]
      treal : ∀ (c : Bool) {x}, TF x → OField (PureLit nd) x → ∃ ρ, TV ρ ∧ denO x ρ = denO x (fun _ => c)

    theorem tz_of {x : Term} (fx : TField E x) (z : lh x = 0) : ∃ k : Int, x = .tuple #[.integer k, .atom "open", .nil] := by
      rcases fx with ⟨k, rfl⟩ | wx
      · exact ⟨k, rfl⟩
      · have := tbdd_pos wx; omega

    theorem mz_of {x : Term} (fx : MField E x) (z : lh x = 0) : ∃ k : Int, x = .tuple #[.integer k, .atom "open", .nil] := by
      rcases fx with ⟨k, rfl⟩ | wx
      · exact ⟨k, rfl⟩
      · have := mbdd_pos wx; omega

    theorem lz_of (ef : EF nd E V den tl K) {x : Term} (wx : LF E x) (z : lh x = 0) :
        x = .tuple #[.integer 46675407, .atom "term", .atom "term"] := by
      rcases wx.shape with rfl | rfl | ⟨k, a, c, rfl⟩ | ⟨h, lit, c, u, d, rfl⟩
      · simp [lh] at z
      · simp [lh] at z
      · obtain ⟨k', a', c', e, ha, hc⟩ := Bdd.leaf_iff.mp wx
        obtain ⟨-, e₂, e₃⟩ := tuple3_inj e
        subst e₂ e₃
        by_cases nt : k = 46675407 ∧ a = .atom "term" ∧ c = .atom "term"
        · obtain ⟨rfl, rfl, rfl⟩ := nt; rfl
        · rw [nl_lh_leaf (ef.shape hc) nt] at z; omega
      · obtain ⟨-, okl, -⟩ := Bdd.node_iff.mp wx
        obtain ⟨k', a', c', rfl, ha', -⟩ := okl
        rw [nl_lh_node (ef.shape ha')] at z
        omega

    /-- Tuple valuations of element types hold or leave out the expansion literal of the node, as wanted. -/
    theorem treal_of (ef : EF nd E V den tl K) (c : Bool) {x : Term} (fx : TField E x) (px : OField (PureLit nd) x) :
        ∃ ρ, ValT E den ρ ∧ denO x ρ = denO x (fun _ => c) := by
      rcases pure_cases px with ⟨k, rfl⟩ | rfl | rfl | ⟨e, he, rfl⟩ | ⟨j, e, c', u, d, he, rfl⟩
      · exact ⟨_, ⟨[], rfl⟩, by simp [denO_top]⟩
      · exact ⟨_, ⟨[], rfl⟩, rfl⟩
      · exact ⟨_, ⟨[], rfl⟩, rfl⟩
      · have hl : TLit E (litN e (keyOf nd)) := by
          rcases fx with ⟨k, h⟩ | wx
          · simp [litN, Term.list] at h
          · exact Bdd.leaf_iff.mp wx
        obtain ⟨⟨v₁, h₁⟩, ⟨v₀, h₀⟩⟩ := ef.litN_vals (litN_el hl) he (keyOf nd)
        cases c
        · exact ⟨_, ⟨v₀, rfl⟩, by simp [denO, isOpenTop, litN, Term.list] at h₀ ⊢; exact h₀⟩
        · exact ⟨_, ⟨v₁, rfl⟩, by simp [denO, isOpenTop, litN, Term.list] at h₁ ⊢; exact h₁⟩
      · have hl : TLit E (litN e (keyOf nd)) := by
          rcases fx with ⟨k, h⟩ | wx
          · simp at h
          · exact (Bdd.node_iff.mp wx).2.1
        obtain ⟨⟨v₁, h₁⟩, ⟨v₀, h₀⟩⟩ := ef.litN_vals (litN_el hl) he (keyOf nd)
        cases c
        · refine ⟨_, ⟨v₀, rfl⟩, ?_⟩
          simp only [litN, Term.list] at h₀
          cases c' <;> cases u <;> cases d <;> simp [denO, isOpenTop, eval, bt, litN, Term.list, h₀]
        · refine ⟨_, ⟨v₁, rfl⟩, ?_⟩
          simp only [litN, Term.list] at h₁
          cases c' <;> cases u <;> cases d <;> simp [denO, isOpenTop, eval, bt, litN, Term.list, h₁]

    theorem stepOf (ef : EF nd E V den tl K) (hnone : E (.map [])) :
        StepOk nd (fun N => NestC (EB E N)) K (TField E) (LF E) (MField E) (ValT E den) (ValLN E den tl) (ValMN E den) :=
      ⟨kinds ef, fun ha h => de_nest ef ha h, fun hN => nest_ops ef hnone hN, tz_of, lz_of ef, mz_of,
        fun c _ fx px => treal_of ef c fx px⟩

    end

    section
    variable {nd : Term} {C : Nat → Term → Prop} {K : Nat} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}

    /-- Unions of element types of the next level. -/
    theorem de_union (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (ha : DEG TF LF MF a) (hb : DEG TF LF MF b) :
        ∃ c, DEG TF LF MF c ∧ (∀ m, K + 14 ≤ m → Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok c) ∧
          (∀ v : PtG TV LV MV, denD c v ↔ denD a v ∨ denD b v) ∧ ∀ N, lh a < N → lh b < N → lh c < N := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, Or.inl rfl, fun m _ => union_term_l _ _, fun v => by simp [denD_term],
          fun N h _ => h⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inl rfl, fun m _ => union_term_r _ _, fun v => by simp [denD_term],
          fun N _ h => h⟩
      have hN : 0 < max (lh (.map A)) (lh (.map B)) + 1 := by omega
      obtain ⟨c, -, run⟩ := (st.ops hN).2.2.union (st.nest (Or.inr ⟨A, rfl, sA⟩) (by omega))
        (st.nest (Or.inr ⟨B, rfl, sB⟩) (by omega))
      obtain ⟨U, run', sU, sem, le'⟩ := descr_union st.ks (fcOf K) (m := K + 14) (by omega) sA sB
      have le := le' trivial
      have e := (run (K + 15) (by omega)).symm.trans run'
      simp only [Except.ok.injEq] at e
      subst e
      refine ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => ?_, fun N h₁ h₂ => by omega⟩
      simp only [denD_map, sem _ _ v.2.2, Bool.or_eq_true]

    /-- Intersections of element types of the next level. -/
    theorem de_inter (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (ha : DEG TF LF MF a) (hb : DEG TF LF MF b) :
        ∃ c, DEG TF LF MF c ∧ (∀ m, K + 8 ≤ m → Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok c) ∧
          (∀ v : PtG TV LV MV, denD c v ↔ denD a v ∧ denD b v) ∧ ∀ N, lh a < N → lh b < N → lh c < N := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨b, hb, fun m _ => inter_term_left _ _, fun v => by simp [denD_term], fun N _ h => h⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inr ⟨A, rfl, sA⟩, fun m _ => inter_term_right _ _, fun v => by simp [denD_term],
          fun N h _ => h⟩
      have hN : 0 < max (lh (.map A)) (lh (.map B)) + 1 := by omega
      obtain ⟨c, -, run⟩ := (st.ops hN).1.inter (st.nest (Or.inr ⟨A, rfl, sA⟩) (by omega))
        (st.nest (Or.inr ⟨B, rfl, sB⟩) (by omega))
      obtain ⟨U, run', sU, sem, le'⟩ := descr_inter st.ks (fcOf K) (m := K + 8) (by omega) sA sB
      have le := le' trivial
      have e := (run (K + 9) (by omega)).symm.trans run'
      simp only [Except.ok.injEq] at e
      subst e
      refine ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => ?_, fun N h₁ h₂ => by omega⟩
      simp only [denD_map, sem _ _ v.2.2, Bool.and_eq_true]

    theorem descrC_nil : DescrC FunTop TF LF MF [] :=
      ⟨fun q h => by simp [mapLookup] at h, fun name w h => by simp [mapLookup] at h⟩

    theorem lookup_out {X : List (Term × Term)} (sX : DescrC FunTop TF LF MF X) {name : String}
        (h : name ∉ names) : mapLookup X (.atom name) = none := by
      cases hx : mapLookup X (.atom name) with
      | none => rfl
      | some x =>
        obtain ⟨name', m, e⟩ := sX.keys _ (by rw [hx]; rfl)
        simp only [Term.atom.injEq] at e
        subst e; exact absurd m h

    def ptWit : PtG TV LV MV := ⟨("atom", (0, .nil, fun _ => Bool.true)), by simp [names],
      ⟨resp_const _, by simp, by simp, by simp, by simp⟩⟩

    theorem diff_none_right (d : Dispatcher) {a : Term} (ha : DEG TF LF MF a) :
        Elixir.Module.Types.Descr.«bare_difference/2» d a (.map []) = .ok a := by
      unfold Elixir.Module.Types.Descr.«bare_difference/2»
      rcases ha with rfl | ⟨A, rfl, -⟩ <;> simp [Erlang.erlang.«==/2»]

    /-- Differences of element types of the next level. -/
    theorem de_diff (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (ha : DEG TF LF MF a) (hb : DEG TF LF MF b) :
        ∃ c, DEG TF LF MF c ∧ (∀ m, K + 6 ≤ m → Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok c) ∧
          (∀ v : PtG TV LV MV, denD c v ↔ denD a v ∧ ¬denD b v) ∧ ∀ N, lh a < N → lh b < N → lh c < N := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · refine ⟨_, Or.inr ⟨[], rfl, descrC_nil⟩, fun m _ => diff_term_right _ _, fun v => ?_,
          fun N _ _ => by rw [lh_nil_map]; omega⟩
        simp [denD_map, mapLookup, dn_none, denD_term]
      by_cases nB : B = []
      · subst nB
        exact ⟨a, ha, fun m _ => diff_none_right _ ha, fun v => by simp [denD_map, mapLookup, dn_none],
          fun N h _ => h⟩
      have hN : 0 < max (lh a) (lh (.map B)) + 1 := by omega
      obtain ⟨c, -, run⟩ := (st.ops hN).2.1.diff (st.nest ha (by omega))
        (st.nest (Or.inr ⟨B, rfl, sB⟩) (by omega))
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · obtain ⟨T, term, sT, -, lT, all⟩ := termC st.ks
        obtain ⟨U, run', sU, sem, le'⟩ := descr_diff st.ks (fcOf K) (m := K + 4) (by omega) sT sB
        have le := le' trivial
        have e := (run (K + 6) (by omega)).symm.trans
          ((diff_term_left _ term sT.static sB.static nB).trans run')
        simp only [Except.ok.injEq] at e
        subst e
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, fun m hm => run m (by omega), fun v => ?_, fun N h₁ h₂ => by omega⟩
        simp only [denD_map, sem _ _ v.2.2, all _ v.2.1 _ v.2.2, denD_term, true_and, Bool.true_and,
          Bool.not_eq_true']
        cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp
      · obtain ⟨U, run', sU, sem, le'⟩ := descr_diff st.ks (fcOf K) (m := K + 4) (by omega) sA sB
        have le := le' trivial
        have e := (run (K + 6) (by omega)).symm.trans run'
        simp only [Except.ok.injEq] at e
        subst e
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, fun m hm => run m (by omega), fun v => ?_, fun N h₁ h₂ => by omega⟩
        simp only [denD_map, sem _ _ v.2.2]
        cases dn v.1.1 (mapLookup A (.atom v.1.1)) v.1.2 <;> cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp

    /-- Emptiness of element types of the next level, exact under safe seen sets. -/
    theorem de_empty (st : StepOk nd C K TF LF MF TV LV MV) {a : Term} (S : List (Term × Term)) (ha : DEG TF LF MF a) :
        ∃ b : Bool, (∀ m, K + 8 ≤ m → Elixir.Module.Types.Descr.«empty_seen?/2» (D m) a (.map S) = .ok (boolAtom b)) ∧
          ∀ N, lh a < N → SafeN N S → (b = Bool.true ↔ ∀ v : PtG TV LV MV, ¬denD a v) := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · refine ⟨Bool.false, fun m _ => by simpa [boolAtom] using empty_term _ _, fun N _ _ => ?_⟩
        refine ⟨fun h => absurd h (by simp), fun h => absurd (denD_term ptWit) (h ptWit)⟩
      have hN : 0 < lh (.map X) + 1 := by omega
      obtain ⟨b, run⟩ := (st.ops hN).1.empty (st.nest (Or.inr ⟨X, rfl, sX⟩) (by omega)) S
      obtain ⟨b', run', ex⟩ := descr_empty st.ks (fcOf K) trivial (m := K + 8) (by omega) sX S trivial
      have e := (run (K + 8) (by omega)).symm.trans run'
      have : b = b' := by cases b <;> cases b' <;> simp_all [boolAtom]
      subst this
      refine ⟨b, run, fun N hl hS => ?_⟩
      obtain ⟨comp, sound⟩ := ex N hl hS
      constructor
      · intro bt v hv
        have := sound (fun x hx => by
          have fx := fieldC_fun (sX.fields "fun" x hx)
          exact fun_top_ne x fx _ _) bt v.1.1 v.1.2 v.2.2
        rw [denD_map, this] at hv
        cases hv
      · intro none
        refine comp fun name p ok => ?_
        by_cases m : name ∈ names
        · have := none ⟨(name, p), m, ok⟩
          simpa [denD] using this
        · rw [lookup_out sX m, dn_none]

    theorem empty_map_seen (d : Dispatcher) (A : List (Term × Term)) :
        Elixir.Module.Types.Descr.«empty?/1» d (.map A) = Elixir.Module.Types.Descr.«empty_seen?/2» d (.map A) (.map []) := by
      unfold Elixir.Module.Types.Descr.«empty?/1»; rfl

    theorem bool_run {r : Except Exception Term} {s b : Bool} (h₁ : r = .ok (boolAtom s)) (h₂ : r = .ok (boolAtom b)) :
        s = b := by
      have := h₁.symm.trans h₂
      cases s <;> cases b <;> simp_all [boolAtom]

    /-- Optimized unions of element types of the next level. -/
    theorem de_opt_union (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (S : List (Term × Term)) {m : Nat} (ha : DEG TF LF MF a)
        (hb : DEG TF LF MF b) (hm : K + 4 ≤ m) : ∃ c, DEG TF LF MF c ∧
          Elixir.Module.Types.Descr.«opt_union/3» (D m) a b (.map S) = .ok c ∧
          ∀ v : PtG TV LV MV, denD c v ↔ denD a v ∨ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, Or.inl rfl, opt_union_term_left _ _ _, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inl rfl, opt_union_term_r _ _ _, fun v => by simp [denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
      obtain ⟨U, run, sU, sem⟩ := descr_opt_union st.ks (fcOf K) (m := n) (by omega) sA sB S
      exact ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.or_eq_true]⟩

    /-- Optimized intersections of element types of the next level. -/
    theorem de_opt_inter (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (S : List (Term × Term)) {m : Nat} (ha : DEG TF LF MF a)
        (hb : DEG TF LF MF b) (hm : K + 4 ≤ m) : ∃ c, DEG TF LF MF c ∧
          Elixir.Module.Types.Descr.«opt_intersection/3» (D m) a b (.map S) = .ok c ∧
          ∀ v : PtG TV LV MV, denD c v ↔ denD a v ∧ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨b, hb, opt_inter_term_l _ _ _, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inr ⟨A, rfl, sA⟩, opt_inter_term_r _ _ _, fun v => by simp [denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
      obtain ⟨U, run, sU, sem⟩ := descr_opt_inter st.ks (fcOf K) (m := n) (by omega) sA sB S
      exact ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.and_eq_true]⟩

    /-- Optimized differences of element types of the next level. -/
    theorem de_opt_diff (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (S : List (Term × Term)) {m : Nat} (ha : DEG TF LF MF a)
        (hb : DEG TF LF MF b) (hm : K + 6 ≤ m) : ∃ c, DEG TF LF MF c ∧
          Elixir.Module.Types.Descr.«opt_difference/3» (D m) a b (.map S) = .ok c ∧
          ∀ v : PtG TV LV MV, denD c v ↔ denD a v ∧ ¬denD b v := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · refine ⟨_, Or.inr ⟨[], rfl, descrC_nil⟩, difference_term_term _ _ _, fun v => ?_⟩
        simp [denD_map, mapLookup, dn_none, denD_term]
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · by_cases nB : B = []
        · subst nB
          exact ⟨_, Or.inl rfl, difference_term_none _ _, fun v => by simp [denD_map, mapLookup, dn_none, denD_term]⟩
        obtain ⟨T, term, sT, -, -, all⟩ := termC st.ks
        obtain ⟨U, run, sU, sem⟩ := descr_opt_diff st.ks (fcOf K) (m := n) (by omega) sT sB S
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, (opt_diff_term_left _ _ term sT.static sB.static nB).trans run, fun v => ?_⟩
        simp only [denD_map, sem _ _ v.2.2, all _ v.2.1 _ v.2.2, denD_term, true_and, Bool.true_and]
        cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp
      · obtain ⟨U, run, sU, sem⟩ := descr_opt_diff st.ks (fcOf K) (m := n) (by omega) sA sB S
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => ?_⟩
        simp only [denD_map, sem _ _ v.2.2]
        cases dn v.1.1 (mapLookup A (.atom v.1.1)) v.1.2 <;> cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp

    /-- Subtyping of element types of the next level: a uniform answer, sound. -/
    theorem de_sub (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (ha : DEG TF LF MF a) (hb : DEG TF LF MF b) :
        ∃ s : Bool, (∀ m, K + 14 ≤ m → Elixir.Module.Types.Descr.«subtype?/2» (D m) a b = .ok (boolAtom s)) ∧
          (s = Bool.true → ∀ v : PtG TV LV MV, denD a v → denD b v) := by
      have hN : 0 < max (lh a) (lh b) + 1 := by omega
      obtain ⟨s, run⟩ := (st.ops hN).2.2.sub (st.nest ha (by omega)) (st.nest hb (by omega))
      refine ⟨s, run, fun st v hv => ?_⟩
      subst st
      have h : Elixir.Module.Types.Descr.«subtype?/2» (D (K + 14)) a b = .ok (boolAtom Bool.true) := run (K + 14) (by omega)
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact denD_term v
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · obtain ⟨T, term, sT, -, -, all⟩ := termC st.ks
        rw [subtype_term_l term] at h
        have := descr_sub_sound st.ks (fcOf K) trivial fun_top_ne (by omega) sT sB h v.1.1 v.1.2 v.2.2
          (all _ v.2.1 _ v.2.2)
        exact (denD_map v).mpr this
      · exact (denD_map v).mpr (descr_sub_sound st.ks (fcOf K) trivial fun_top_ne (by omega) sA sB h v.1.1 v.1.2 v.2.2
          ((denD_map v).mp hv))

    theorem de_empty_sound (st : StepOk nd C K TF LF MF TV LV MV) {B : List (Term × Term)}
        (sB : DescrC FunTop TF LF MF B) {m : Nat} (hm : K + 8 ≤ m)
        (h : Elixir.Module.Types.Descr.«empty?/1» (D m) (.map B) = .ok (boolAtom Bool.true)) :
        ∀ v : PtG TV LV MV, ¬denD (.map B) v := by
      obtain ⟨b, run, ex⟩ := de_empty st [] (Or.inr ⟨B, rfl, sB⟩)
      rw [empty_map_seen] at h
      have := bool_run (run m hm) h
      subst this
      exact (ex _ (Nat.lt_succ_self _) (safeN_nil _)).mp rfl

    /-- Disjointness of element types of the next level: a uniform answer, sound. -/
    theorem de_disj (st : StepOk nd C K TF LF MF TV LV MV) {a b : Term} (ha : DEG TF LF MF a) (hb : DEG TF LF MF b) :
        ∃ s : Bool, (∀ m, K + 14 ≤ m → Elixir.Module.Types.Descr.«disjoint?/2» (D m) a b = .ok (boolAtom s)) ∧
          (s = Bool.true → ∀ v : PtG TV LV MV, denD a v → denD b v → False) := by
      have hN : 0 < max (lh a) (lh b) + 1 := by omega
      obtain ⟨s, run⟩ := (st.ops hN).2.2.disj (st.nest ha (by omega)) (st.nest hb (by omega))
      refine ⟨s, run, fun st v hva hvb => ?_⟩
      subst st
      have h : Elixir.Module.Types.Descr.«disjoint?/2» (D (K + 14)) a b = .ok (boolAtom Bool.true) := run (K + 14) (by omega)
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · rw [disjoint_term_l] at h
        rcases hb with rfl | ⟨B, rfl, sB⟩
        · rw [empty_term_false] at h; simp [boolAtom] at h
        · exact de_empty_sound st sB (by omega) h v hvb
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · rw [disjoint_term_r] at h
        exact de_empty_sound st sA (by omega) h v hva
      have := descr_disj_sound st.ks (fcOf K) trivial fun_top_ne trivial (by omega) sA sB h v.1.1 v.1.2 v.2.2
      rw [(denD_map v).mp hva, (denD_map v).mp hvb] at this
      cases this

    theorem de_resp (st : StepOk nd C K TF LF MF TV LV MV) {e e' : Term} {v : PtG TV LV MV} (he : DEG TF LF MF e) (he' : DEG TF LF MF e')
        (h : Term.compare e e' = .eq) (d : denD e' v) : denD e v := by
      rcases he with rfl | ⟨A, rfl, sA⟩
      · exact denD_term v
      rcases he' with rfl | ⟨B, rfl, sB⟩
      · obtain ⟨Y, e⟩ := map_cmp_shape h; cases e
      rw [denD_map] at d ⊢
      rw [descr_congr st.ks (fcOf K) sA sB h v.1.1 v.1.2 v.2.2, d]

    theorem noList_atom (M : List (Term × Term)) (name : String) :
        mapLookup (noList M) (.atom name) = if name = "list" then none else mapLookup M (.atom name) := by
      simp only [noList, mapLookup_filter, exactCompare_eq_atom, Term.atom.injEq]

    /-- Types without their list field. -/
    theorem descr_noList {X : List (Term × Term)} (sX : DescrC FunTop TF LF MF X) :
        DescrC FunTop TF LF MF (noList X) ∧ lh (.map (noList X)) ≤ lh (.map X) ∧
          ∀ v : PtG TV LV MV, denD (.map (noList X)) v ↔ denD (.map X) v ∧ ¬tlD v := by
      have keys : ∀ q, (mapLookup (noList X) q).isSome → ∃ name ∈ names, q = .atom name := fun q h =>
        sX.keys q (by rw [← noList_lookup X q h]; exact h)
      refine ⟨⟨keys, fun name w h => ?_⟩, lh_descr_le keys fun name w h => ?_, fun v => ?_⟩
      · rw [noList_lookup X _ (by rw [h]; rfl)] at h; exact sX.fields name w h
      · rw [noList_lookup X _ (by rw [h]; rfl)] at h; exact lh_field_le h
      · rw [denD_map, denD_map, noList_atom]
        unfold tlD
        split <;> simp_all [dn_none]

    theorem tailTerm_noList {T : List (Term × Term)} (term : Elixir.Module.Types.Descr.«unfolded_term/0» = .ok (.map T))
        (name : String) : mapLookup tailTerm (.atom name) = mapLookup (noList T) (.atom name) := by
      simp only [Elixir.Module.Types.Descr.«unfolded_term/0»] at term
      cases term
      rw [noList_atom]
      simp only [mapLookup, List.find?, tailTerm, exactCompare_eq_atom, Term.atom.injEq]
      by_cases b : name = "bitmap" <;> by_cases t : name = "tuple" <;> by_cases f : name = "fun" <;>
        by_cases m : name = "map" <;> by_cases a : name = "atom" <;> by_cases l : name = "list" <;> simp_all

    /-- `list_tail_unfold/1` of element types of the next level. -/
    theorem de_tail (st : StepOk nd C K TF LF MF TV LV MV) {e : Term} (he : DEG TF LF MF e) :
        ∃ e', (∀ d, Elixir.Module.Types.Descr.«list_tail_unfold/1» d e = .ok e') ∧ DEG TF LF MF e' ∧
          (∀ v : PtG TV LV MV, denD e' v ↔ denD e v ∧ ¬tlD v) ∧ lh e' ≤ lh e := by
      rcases he with rfl | ⟨X, rfl, sX⟩
      · obtain ⟨T', run, look⟩ := tail_term_lookup
        obtain ⟨T, term, sT, -, lT, all⟩ := termC st.ks
        obtain ⟨sN, lN, semN⟩ := descr_noList (TV := TV) (LV := LV) (MV := MV) sT
        have eq : ∀ name, mapLookup T' (.atom name) = mapLookup (noList T) (.atom name) := fun name =>
          (look _).trans (tailTerm_noList term name)
        have keys : ∀ q, (mapLookup T' q).isSome → ∃ name ∈ names, q = .atom name := fun q h => by
          rw [look] at h
          rcases tailTerm_basic.keys q h with e | e | e | e | e | e <;> exact ⟨_, by simp [names], e⟩
        refine ⟨_, run, Or.inr ⟨T', rfl, keys, fun name w h => sN.fields name w (by rw [← eq]; exact h)⟩, fun v => ?_,
          lh_descr_le keys fun name w h => ?_⟩
        · rw [denD_map, eq, ← denD_map, semN v, denD_map, all _ v.2.1 _ v.2.2]
          simp [denD_term]
        · rw [eq] at h; have := lh_field_le h; rw [lh_term_zero]; omega
      · obtain ⟨sN, lN, semN⟩ := descr_noList (TV := TV) (LV := LV) (MV := MV) sX
        exact ⟨_, fun d => tail_map d X, Or.inr ⟨_, rfl, sN⟩, semN, lN⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Fusing element types of the next level. -/

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- Tuple fields that are 3-tuples are leaves: the top leaf or tuple literals. -/
    theorem tfield_three {x a b c : Term} (fx : TField E x) (h : x = .tuple ⟨[a, b, c]⟩) :
        ∃ (k : Int) (tag : String) (l : List Term), x = .tuple #[.integer k, .atom tag, Term.list l] ∧
          (tag = "open" ∨ tag = "closed") ∧ (∀ e ∈ l, E e) := by
      rcases fx with ⟨k, rfl⟩ | wx
      · exact ⟨k, "open", [], rfl, Or.inl rfl, by simp⟩
      rcases wx.shape with rfl | rfl | ⟨k, y, z, rfl⟩ | ⟨h', lit, c', u, d, rfl⟩
      · cases h
      · cases h
      · obtain ⟨⟨⟨k', tag, l, e, g, els⟩, -⟩, key⟩ := Bdd.leaf_iff.mp wx
        exact ⟨k', tag, l, e, g, els⟩
      · simp at h

    theorem denTF_leaf (ef : EF nd E V den tl K) {k : Int} {tag : String} {l : List Term} (g : tag = "open" ∨ tag = "closed")
        (hl : ∀ e ∈ l, E e) (v : List V) :
        denTF E den (.tuple #[.integer k, .atom tag, Term.list l]) v = valT E den v (.tuple #[.integer k, .atom tag, Term.list l]) := by
      by_cases top : tag = "open" ∧ l = []
      · obtain ⟨rfl, rfl⟩ := top
        have : valT E den v (.tuple #[.integer k, .atom "open", Term.list []]) = Bool.true := by
          rw [vT_lit ef g hl]
          cases v <;> simp [InT]
        rw [this]; exact denTF_top _ _
      · have nt : isOpenTop (.tuple #[.integer k, .atom tag, Term.list l]) = Bool.false := by
          cases l with
          | nil =>
            have : tag ≠ "open" := fun e => top ⟨e, rfl⟩
            simp only [Term.list]
            unfold isOpenTop
            split
            · rename_i heq; simp at heq; exact absurd heq.2 this
            · rfl
          | cons _ _ => simp [isOpenTop, Term.list]
        simp [denTF, denO, nt]

    /-- A single tuple leaf, as a type of the next level. -/
    theorem fused_de {k : Int} {tag : String} {l : List Term} (g : tag = "open" ∨ tag = "closed") (hl : ∀ e ∈ l, E e)
        (key : KeyOk (.tuple #[.integer k, .atom tag, Term.list l])) :
        DE E (.map [(.atom "tuple", .tuple #[.integer k, .atom tag, Term.list l])]) := by
      refine Or.inr ⟨_, rfl, fun q h => ?_, fun name w h => ?_⟩
      · simp only [mapLookup, List.find?_cons, List.find?_nil] at h
        by_cases e : exactCompare q (.atom "tuple") = .eq
        · exact ⟨"tuple", by simp [names], (exactCompare_eq_atom _ _).mp e⟩
        · simp [e] at h
      · simp only [mapLookup, List.find?_cons, List.find?_nil, exactCompare_eq_atom, Term.atom.injEq] at h
        by_cases e : name = "tuple"
        · subst e
          simp at h
          subst h
          refine Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, ?_⟩))))
          by_cases top : tag = "open" ∧ l = []
          · obtain ⟨rfl, rfl⟩ := top; exact Or.inl ⟨k, rfl⟩
          · refine Or.inr (Bdd.leaf_iff.mpr ⟨⟨⟨k, tag, l, rfl, g, hl⟩, fun ⟨k', e⟩ => top ?_⟩, key⟩)
            simp only [Term.tuple.injEq] at e
            have e₁ := congrArg (fun a : Array Term => a[1]?) e
            have e₂ := congrArg (fun a : Array Term => a[2]?) e
            simp [list_eq_nil] at e₁ e₂
            exact ⟨e₁, e₂⟩
        · simp [e] at h

    theorem single_other {A : List (Term × Term)} {x : Term} (size : Erlang.erlang.«map_size/1» (.map A) = .ok (.integer 1))
        (hx : mapLookup A (.atom "tuple") = some x) {name : String} (hn : name ≠ "tuple") : mapLookup A (.atom name) = none := by
      cases h : mapLookup A (.atom name) with
      | none => rfl
      | some y => exact absurd ((exactCompare_eq_atom _ _).mp (size_one_keys size h hx)) (by simpa using hn)

    /-- The fused single tuple leaf holds the values of both single tuple leaves. -/
    theorem fused_sem (ef : EF nd E V den tl K) {A B : List (Term × Term)} {kA kB k : Int} {t : String} {lA lB l : List Term}
        (g : t = "open" ∨ t = "closed") (hA : ∀ e ∈ lA, E e) (hB : ∀ e ∈ lB, E e) (hl : ∀ e ∈ l, E e)
        (tA : mapLookup A (.atom "tuple") = some (.tuple #[.integer kA, .atom t, Term.list lA]))
        (sA : Erlang.erlang.«map_size/1» (.map A) = .ok (.integer 1))
        (tB : mapLookup B (.atom "tuple") = some (.tuple #[.integer kB, .atom t, Term.list lB]))
        (sB : Erlang.erlang.«map_size/1» (.map B) = .ok (.integer 1))
        (sem : ∀ w, InT den (t == "closed") l w ↔ InT den (t == "closed") lA w ∨ InT den (t == "closed") lB w)
        (v : PtD E den tl) :
        denD (.map [(.atom "tuple", .tuple #[.integer k, .atom t, Term.list l])]) v ↔ denD (.map A) v ∨ denD (.map B) v := by
      obtain ⟨⟨name, p⟩, m, ok⟩ := v
      simp only [denD_map]
      by_cases hn : name = "tuple"
      · subst hn
        obtain ⟨w, hw⟩ := ok.2.2.2.1 rfl
        have one : mapLookup [(.atom "tuple", .tuple #[.integer k, .atom t, Term.list l])] (.atom "tuple") =
            some (.tuple #[.integer k, .atom t, Term.list l]) := by simp [mapLookup]
        rw [one, tA, tB, dn_tupleT hw, dn_tupleT hw, dn_tupleT hw, denTF_leaf ef g hl, denTF_leaf ef g hA,
          denTF_leaf ef g hB, vT_fused ef (k₁ := kA) (k₂ := kB) g g hA hB hl sem, Bool.or_eq_true]
      · have none : mapLookup [(.atom "tuple", .tuple #[.integer k, .atom t, Term.list l])] (.atom name) = none := by
          simp [mapLookup, exactCompare_eq_atom, hn]
        rw [none, single_other sA tA hn, single_other sB tB hn]
        simp [dn_none]

    theorem de_fuse (ef : EF nd E V den tl K) (hnone : E (.map [])) {a b : Term} (n : Int) {m : Nat} (ha : DE E a)
        (hb : DE E b) (ne : exactCompare a b ≠ .eq) (hm : K + 14 ≤ m) : ∃ r,
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» (D m) a b (.integer n) = .ok r ∧
          (r = .atom "nil" ∨ (DE E r ∧ ∀ v : PtD E den tl, denD r v ↔ denD a v ∨ denD b v)) := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, fuse_term_l _ _ _, Or.inl rfl⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, fuse_term_r _ _ _, Or.inl rfl⟩
      obtain ⟨u, hu, urun, usem, -⟩ := de_union (stepOf ef hnone) (Or.inr ⟨A, rfl, sA⟩) (Or.inr ⟨B, rfl, sB⟩)
      have run := urun m hm
      obtain ⟨c₁, r₁⟩ := aob_bool (.map A)
      obtain ⟨c₂, r₂⟩ := aob_bool (.map B)
      have second : ∃ r, (do
          let _19 ← Lynx.Except.andAlso (Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map A))
            (Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map B)) Bool.true
          Lynx.Except.guard (Except.ok (_19.isMember [Term.atom "false", Term.atom "nil"]))
            (fun _ => pure (Term.atom "nil")) fun _ => Elixir.Module.Types.Descr.«bare_union/2» (D m) (.map A) (.map B)) = .ok r ∧
          (r = .atom "nil" ∨ (DE E r ∧ ∀ v : PtD E den tl, denD r v ↔ denD (.map A) v ∨ denD (.map B) v)) := by
        rw [r₁, r₂]
        cases c₁ <;> cases c₂ <;>
          simp [Lynx.Except.andAlso, boolAtom, Lynx.Except.guard, isMember, run, hu, usem]
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3».eq_def]
      simp only [getMapKeys_single]
      split
      · rename_i k₀ tag e₁ hA
        have hxA : mapLookup A (.atom "tuple") = some (.tuple ⟨[k₀, tag, e₁]⟩) := by
          cases h : mapLookup A (.atom "tuple") <;> simp_all
        obtain ⟨kA, tA, lA, eA, gA, elA⟩ := tfield_three (fieldC_tuple (sA.fields _ _ hxA)) rfl
        obtain ⟨rfl, rfl, rfl⟩ := tuple3_inj eA
        split
        · rename_i k₁ tag₂ e₂ hB
          have hxB : mapLookup B (.atom "tuple") = some (.tuple ⟨[k₁, tag₂, e₂]⟩) := by
            cases h : mapLookup B (.atom "tuple") <;> simp_all
          obtain ⟨kB, tB, lB, eB, gB, elB⟩ := tfield_three (fieldC_tuple (sB.fields _ _ hxB)) rfl
          obtain ⟨rfl, rfl, rfl⟩ := tuple3_inj eB
          obtain ⟨sa, hsa⟩ : ∃ sa : Int, Erlang.erlang.«map_size/1» (.map A) = .ok (.integer sa) :=
            ⟨_, by simp [Erlang.erlang.«map_size/1»]; rfl⟩
          obtain ⟨sb, hsb⟩ : ∃ sb : Int, Erlang.erlang.«map_size/1» (.map B) = .ok (.integer sb) :=
            ⟨_, by simp [Erlang.erlang.«map_size/1»]; rfl⟩
          have fallback : ∀ (x : Except Exception Term),
              (∀ c₁ c₂ : Bool, Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map A) = .ok (boolAtom c₁) →
                Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map B) = .ok (boolAtom c₂) →
                x = .ok (if c₁ && c₂ then u else .atom "nil")) →
              ∃ r, x = .ok r ∧ (r = .atom "nil" ∨ (DE E r ∧ ∀ v : PtD E den tl, denD r v ↔ denD (.map A) v ∨ denD (.map B) v)) := by
            intro x hx
            refine ⟨_, hx c₁ c₂ r₁ r₂, ?_⟩
            cases c₁ <;> cases c₂ <;> simp [hu, usem]
          by_cases G : tB = tA ∧ sa = 1 ∧ sb = 1 ∧ 0 < n
          · obtain ⟨rfl, rfl, rfl, pos⟩ := G
            have sub : Erlang.erlang.«-/2» (.integer n) (.integer 1) = .ok (.integer (n - 1)) := by
              rw [Erlang.erlang.«-/2_integers»]
            have pc : compare n 0 = Ordering.gt := by exact Int.compare_eq_gt.mpr pos
            obtain ⟨r, rr, out⟩ := fuse_elements_sem ef (m := m) (by omega) (n - 1) lA lB [] elA elB (by simp)
            rcases out with rfl | ⟨l, rfl, hl, ll, sl⟩
            · refine ⟨_, ?_, Or.inl rfl⟩
              simp only [Term.list] at rr
              simp [hsa, hsb, Erlang.erlang.«=:=/2», Lynx.Except.guard, Lynx.Except.tryWith, Lynx.Except.andAlso,
                Erlang.erlang.«and/2», Erlang.erlang.«==/2», Erlang.erlang.«>/2», sub, pc, rr, isMember]
            · obtain ⟨k, hk, key⟩ := leaf_new_key tB gA l
              have nf : (Term.list l).exactCompare (.atom "false") ≠ .eq ∧ (Term.list l).exactCompare (.atom "nil") ≠ .eq := by
                cases l <;> simp [Term.list]
              refine ⟨_, ?_, Or.inr ⟨fused_de gA hl key,
                fused_sem ef gA elA elB hl hxA hsa hxB hsb fun w => by simpa using sl (tB == "closed") w⟩⟩
              simp [hsa, hsb, Erlang.erlang.«=:=/2», Lynx.Except.guard, Lynx.Except.tryWith, Lynx.Except.andAlso,
                Erlang.erlang.«and/2», Erlang.erlang.«==/2», Erlang.erlang.«>/2», sub, pc, rr, isMember, hk, nf.1, nf.2]
          · refine fallback _ fun c₁ c₂ r₁ r₂ => ?_
            have pc : compare n 0 = Ordering.gt ↔ 0 < n := Int.compare_eq_gt
            by_cases e₁ : tB = tA <;> by_cases e₂ : sa = 1 <;> by_cases e₃ : sb = 1 <;> by_cases e₄ : 0 < n <;>
              simp only [e₁, e₂, e₃, e₄, and_self, not_true_eq_false] at G <;>
              cases c₁ <;> cases c₂ <;>
              simp [hsa, hsb, e₁, e₂, e₃, e₄, pc, r₁, r₂, run, Erlang.erlang.«=:=/2», Lynx.Except.guard,
                Lynx.Except.tryWith, Lynx.Except.andAlso, Erlang.erlang.«and/2», Erlang.erlang.«==/2»,
                Erlang.erlang.«>/2», isMember, boolAtom]
        · exact second
      · exact second

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Element types of one level give element types of the next. -/

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    theorem de_none : DE E (.map []) := Or.inr ⟨[], rfl, descrC_nil⟩

    end

    section
    variable {nd : Term} {C : Nat → Term → Prop} {K : Nat} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}

    /-- Maps that combine the node with types of height zero: a tuple field of the expansion literal of `nd`, and
    other fields of height zero. -/
    def ComboMap (nd : Term) (X : List (Term × Term)) : Prop :=
      (∀ w, mapLookup X (.atom "tuple") = some w → OField (PureLit nd) w) ∧
        ∀ name w, name ≠ "tuple" → mapLookup X (.atom name) = some w → lh w = 0

    theorem isT_map {nd : Term} {X : List (Term × Term)} : ¬IsT nd (.map X) := by
      rintro ⟨-, h⟩
      unfold «recursive_node?/1» at h
      simp at h

    theorem combo_map {nd : Term} {X : List (Term × Term)} : Combo nd (.map X) ↔ ComboMap nd X := by
      constructor
      · rintro (h | h | ⟨Y, h, ct, co⟩)
        · cases h
        · exact absurd h isT_map
        · cases h; exact ⟨ct, co⟩
      · exact fun ⟨ct, co⟩ => Or.inr (Or.inr ⟨X, rfl, ct, co⟩)

    /-- Pure tuple fields of `TF`. -/
    abbrev TFc (nd : Term) (TF : Term → Prop) (x : Term) : Prop := TF x ∧ OField (PureLit nd) x

    /-- Fields of height zero of `F`. -/
    abbrev ZF (F : Term → Prop) (x : Term) : Prop := F x ∧ lh x = 0

    theorem comboMap_descr {nd : Term} {TF LF MF : Term → Prop} {X : List (Term × Term)}
        (sX : DescrC FunTop TF LF MF X) (c : ComboMap nd X) : DescrC FunTop (TFc nd TF) (ZF LF) (ZF MF) X := by
      refine ⟨sX.keys, fun name x hx => ?_⟩
      have f := sX.fields name x hx
      by_cases nt : name = "tuple"
      · subst nt; exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, fieldC_tuple f, c.1 x hx⟩))))
      have z := c.2 name x nt hx
      rcases f with ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩
      · exact Or.inl ⟨h, f⟩
      · exact Or.inr (Or.inl ⟨h, f⟩)
      · exact Or.inr (Or.inr (Or.inl ⟨h, f⟩))
      · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨h, f, z⟩)))
      · exact absurd h nt
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨h, f, z⟩))))

    theorem descr_comboMap {nd : Term} {TF LF MF : Term → Prop} {X : List (Term × Term)}
        (sX : DescrC FunTop (TFc nd TF) (ZF LF) (ZF MF) X) : ComboMap nd X := by
      refine ⟨fun w hw => (fieldC_tuple (sX.fields _ w hw)).2, fun name w nt hw => ?_⟩
      rcases sX.fields name w hw with ⟨-, f⟩ | ⟨-, f⟩ | ⟨-, f⟩ | ⟨-, f⟩ | ⟨h, -⟩ | ⟨-, f⟩
      · exact lh_bitF f
      · exact lh_atomF f
      · rw [show w = funTopT from f]; exact lh_funTop
      · exact f.2
      · exact absurd h nt
      · exact f.2

    theorem descr_unrestrict {nd : Term} {TF LF MF : Term → Prop} {X : List (Term × Term)}
        (sX : DescrC FunTop (TFc nd TF) (ZF LF) (ZF MF) X) : DescrC FunTop TF LF MF X := by
      refine ⟨sX.keys, fun name x hx => ?_⟩
      rcases sX.fields name x hx with ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩
      · exact Or.inl ⟨h, f⟩
      · exact Or.inr (Or.inl ⟨h, f⟩)
      · exact Or.inr (Or.inr (Or.inl ⟨h, f⟩))
      · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨h, f.1⟩)))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨h, f.1⟩))))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨h, f.1⟩))))

    theorem descr_unrestrict' {nd : Term} {TF LF MF : Term → Prop} {name : String} {x : Term}
        (f : FieldC FunTop (TFc nd TF) (ZF LF) (ZF MF) name x) : FieldC FunTop TF LF MF name x := by
      rcases f with ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩
      · exact Or.inl ⟨h, f⟩
      · exact Or.inr (Or.inl ⟨h, f⟩)
      · exact Or.inr (Or.inr (Or.inl ⟨h, f⟩))
      · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨h, f.1⟩)))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨h, f.1⟩))))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨h, f.1⟩))))

    /-- Plain operations on fields keep pure tuple fields pure and fields of height zero at height zero. -/
    theorem restrict_field {nd : Term} {TF LF MF : Term → Prop} {name : String} {x y w : Term}
        (fx : FieldC FunTop (TFc nd TF) (ZF LF) (ZF MF) name x) (fy : FieldC FunTop (TFc nd TF) (ZF LF) (ZF MF) name y)
        (fw : FieldC FunTop TF LF MF name w) (lw : lh w ≤ max (lh x) (lh y))
        (pw : name = "tuple" → OField (PureLit nd) w) : FieldC FunTop (TFc nd TF) (ZF LF) (ZF MF) name w := by
      rcases fw with ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩ | ⟨h, f⟩
      · exact Or.inl ⟨h, f⟩
      · exact Or.inr (Or.inl ⟨h, f⟩)
      · exact Or.inr (Or.inr (Or.inl ⟨h, f⟩))
      · subst h
        have := (fieldC_list fx).2
        have := (fieldC_list fy).2
        exact Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, f, by omega⟩)))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨h, f, pw h⟩))))
      · subst h
        have := (fieldC_map fx).2
        have := (fieldC_map fy).2
        exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, f, by omega⟩))))

    /-- Plain intersections of combinations of the node with types of height zero are such combinations. -/
    theorem combo_inter {nd : Term} {K : Nat} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}
        (ks : Kinds K TF LF MF TV LV MV) (fc : FunC K FunTop (fun _ => True) True) {m : Nat} (hm : K + 1 ≤ m)
        {A B I : List (Term × Term)} (sA : DescrC FunTop TF LF MF A) (sB : DescrC FunTop TF LF MF B)
        (cA : ComboMap nd A) (cB : ComboMap nd B)
        (run : Elixir.Module.Types.Descr.«bare_intersection/2» (D (m + 1)) (.map A) (.map B) = .ok (.map I)) :
        ComboMap nd I := by
      have sA' := comboMap_descr sA cA
      have sB' := comboMap_descr sB cB
      obtain ⟨I', run', look, keysI⟩ := inter_lookup m A B sA.static sB.static fun q x y hx hy => by
        obtain ⟨name, -, rfl⟩ := sA.keys q (by simp [hx])
        obtain ⟨w, run, -⟩ := fieldC_inter ks fc hm (sA.fields name x hx) (sB.fields name y hy)
        exact ⟨w, run⟩
      have e := run.symm.trans run'
      simp only [Except.ok.injEq, Term.map.injEq] at e
      subst e
      obtain ⟨cI, -, -⟩ := inter_gen (slh := True) (TV := TV) (LV := LV) (MV := MV) sA' sB'
        (fun q x y => Elixir.Module.Types.Descr.«bare_intersection/3» (D m) q x y)
        (fun name => ⟨(look name).1, (look name).2.1, fun x y w hx hy r => by rw [(look name).2.2 x y w hx hy r]; rfl⟩)
        keysI (fun name x y fx fy => by
          obtain ⟨w, run, k, sem⟩ := fieldC_inter ks fc hm (descr_unrestrict' fx) (descr_unrestrict' fy)
          refine ⟨w, run, fun kw => ⟨restrict_field fx fy (k kw).1 ((k kw).2 trivial) fun h => ?_, fun _ => (k kw).2 trivial⟩,
            sem⟩
          subst h
          obtain ⟨w', run'', kk, -⟩ := open_inter_spec pureLit_not _ tuple_inter_shape.1 tuple_inter_shape.2.1
            tuple_inter_shape.2.2 (.atom "tuple") (fieldC_tuple fx).2 (fieldC_tuple fy).2
          have : w = w' := by
            have := run.symm.trans (by simpa [Elixir.Module.Types.Descr.«bare_intersection/3»] using run'')
            simpa using this
          subst this
          exact (kk kw).1)
      exact descr_comboMap cI

    /-- Plain differences of combinations of the node with types of height zero are such combinations. -/
    theorem combo_diff {nd : Term} {K : Nat} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}
        (ks : Kinds K TF LF MF TV LV MV) (fc : FunC K FunTop (fun _ => True) True) {m : Nat} (hm : K + 2 ≤ m)
        {A B O : List (Term × Term)} (sA : DescrC FunTop TF LF MF A) (sB : DescrC FunTop TF LF MF B)
        (cA : ComboMap nd A) (cB : ComboMap nd B)
        (run : Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 2)) (.map A) (.map B) = .ok (.map O)) :
        ComboMap nd O := by
      by_cases nB : B = []
      · subst nB
        have : Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 2)) (.map A) (.map []) = .ok (.map A) := by
          unfold Elixir.Module.Types.Descr.«bare_difference/2»; simp [Erlang.erlang.«==/2»]
        rw [this] at run
        simp only [Except.ok.injEq, Term.map.injEq] at run
        subst run
        exact cA
      have sA' := comboMap_descr sA cA
      have sB' := comboMap_descr sB cB
      obtain ⟨O', fold, sO, -, -⟩ := diff_gen (slh := True) (TV := TV) (LV := LV) (MV := MV) m
        (.function "Elixir.Module.Types.Descr" "bare_difference" 3 #[])
        (fun q x y => Elixir.Module.Types.Descr.«bare_difference/3» (D m) q x y) sA' sB'
        (fun q x y => by rw [Erlang.program.«Elixir.Module.Types.Descr:bare_difference/3».pure])
        (fun name x y fx fy => by
          obtain ⟨w, run, k, sem⟩ := fieldC_diff ks fc hm (descr_unrestrict' fx) (descr_unrestrict' fy)
          refine ⟨w, run, fun kw => ⟨restrict_field fx fy (k kw).1 ((k kw).2 trivial) fun h => ?_, fun _ => (k kw).2 trivial⟩,
            sem⟩
          subst h
          obtain ⟨w', run'', fw', -⟩ := pure_diff_sem (fieldC_tuple fx).2 (fieldC_tuple fy).2
          have : w = w' := by
            have := run.symm.trans (by simpa [Elixir.Module.Types.Descr.«bare_difference/3»] using run'')
            simpa using this
          subst this
          exact fw')
      have run' : Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 2)) (.map A) (.map B) = .ok (.map O') := by
        unfold Elixir.Module.Types.Descr.«bare_difference/2»
        simp [Erlang.erlang.«==/2», unfold_map, static_map sA.static, static_map sB.static, nB]
        unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
        simp [Erlang.erlang.«==/2», nB, unfold_map, Erlang.maps.«fold/3»]
        simpa using fold
      have e := run.symm.trans run'
      simp only [Except.ok.injEq, Term.map.injEq] at e
      subst e
      exact descr_comboMap sO

    section
    variable {nd : Term} {C : Nat → Term → Prop} {K : Nat} {TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop}

    theorem dg_low (st : StepOk nd C K TF LF MF TV LV MV) {a : Term} (ha : DEG TF LF MF a) (z : lh a = 0) : Combo nd a := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · exact Or.inl rfl
      refine combo_map.mpr ⟨fun w hw => ?_, fun name w _ hw => ?_⟩
      · obtain ⟨k, rfl⟩ := st.tz (fieldC_tuple (sX.fields _ w hw)) (by have := lh_field_le hw; omega)
        exact Or.inl ⟨k, rfl⟩
      · have := lh_field_le hw; omega

    theorem dg_cinter (st : StepOk nd C K TF LF MF TV LV MV) {a b c : Term} {m : Nat} (ha : DEG TF LF MF a)
        (hb : DEG TF LF MF b) (ca : Combo nd a) (cb : Combo nd b) (hm : K + 14 ≤ m)
        (run : Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok c) : Combo nd c := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · rw [inter_term_left] at run; cases run; exact cb
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · rw [inter_term_right] at run; cases run; exact ca
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      obtain ⟨I, runI, -, -, -⟩ := descr_inter st.ks (fcOf K) (m := m') (by omega) sA sB
      rw [runI] at run; cases run
      exact combo_map.mpr (combo_inter st.ks (fcOf K) (by omega) sA sB (combo_map.mp ca) (combo_map.mp cb) runI)

    theorem dg_cdiff (st : StepOk nd C K TF LF MF TV LV MV) {a b c : Term} {m : Nat} (ha : DEG TF LF MF a)
        (hb : DEG TF LF MF b) (ca : Combo nd a) (cb : Combo nd b) (hm : K + 14 ≤ m)
        (run : Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok c) : Combo nd c := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · rw [diff_term_right] at run; cases run; exact combo_none nd
      by_cases nB : B = []
      · subst nB
        rw [diff_none_right _ ha] at run; cases run; exact ca
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 2 := ⟨m - 2, by omega⟩
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · obtain ⟨T, term, sT, -, lT, -⟩ := termC st.ks
        rw [diff_term_left _ term sT.static sB.static nB] at run
        obtain ⟨O, runO, -, -, -⟩ := descr_diff st.ks (fcOf K) (m := m') (by omega) sT sB
        rw [runO] at run; cases run
        have cT : ComboMap nd T := ⟨fun w hw => by
            obtain ⟨k, rfl⟩ := st.tz (fieldC_tuple (sT.fields _ w hw)) (by have := lh_field_le hw; omega)
            exact Or.inl ⟨k, rfl⟩,
          fun name w _ hw => by have := lh_field_le hw; omega⟩
        exact combo_map.mpr (combo_diff st.ks (fcOf K) (by omega) sT sB cT (combo_map.mp cb) runO)
      · obtain ⟨O, runO, -, -, -⟩ := descr_diff st.ks (fcOf K) (m := m') (by omega) sA sB
        rw [runO] at run; cases run
        exact combo_map.mpr (combo_diff st.ks (fcOf K) (by omega) sA sB (combo_map.mp ca) (combo_map.mp cb) runO)

    theorem map_topk_nonempty (d : Dispatcher) (k : Int) {S : List (Term × Term)}
        (fresh : S.any (fun e => Term.exactCompare (.cons (.atom "map") (.tuple #[.integer k, .atom "open", .nil])) e.1 == .eq) =
          Bool.false) :
        Elixir.Module.Types.Descr.«map_empty?/2» d (.tuple #[.integer k, .atom "open", .nil]) (.map S) = .ok (.atom "false") := by
      unfold Elixir.Module.Types.Descr.«map_empty?/2»
      simp [Elixir.Module.Types.Descr.«empty_bdd_seen_key/2», Erlang.erlang.«is_map_key/2», fresh, Term.true,
        Term.false, Erlang.maps.«put/3»]
      rw [Elixir.Module.Types.Descr.«map_bdd_empty?/4».eq_def]
      have line := line_inter_open d k .nil
      simp [line, Elixir.Module.Types.Descr.«init_map_line_empty?/4», any_nil]
      rw [Elixir.Module.Types.Descr.«map_line_empty?/4».eq_def]
      simp

    /-- Combinations of the node with types of height zero decide their emptiness exactly, when no seen BDD is a tuple
    BDD of the expansion literal. -/
    theorem dg_cempty (st : StepOk nd C K TF LF MF TV LV MV) {a : Term} {S : List (Term × Term)} {m : Nat} {b : Bool}
        (ha : DEG TF LF MF a) (ca : Combo nd a) (hS : Safe1 nd S) (hm : K + 14 ≤ m)
        (run : Elixir.Module.Types.Descr.«empty_seen?/2» (D m) a (.map S) = .ok (boolAtom b)) :
        b = Bool.true ↔ ∀ v : PtG TV LV MV, ¬denD a v := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · rw [empty_term] at run
        have : b = Bool.false := by cases b <;> simp_all [boolAtom]
        subst this
        exact ⟨fun h => absurd h (by decide), fun h => absurd (denD_term ptWit) (h ptWit)⟩
      have cX := combo_map.mp ca
      by_cases ne : X = []
      · subst ne
        rw [empty_none_seen] at run
        have : b = Bool.true := by cases b <;> simp_all [boolAtom]
        subst this
        exact ⟨fun _ v => by simp [denD_map, mapLookup, dn_none], fun _ => rfl⟩
      have fresh : ∀ x, OField (PureLit nd) x →
          S.any (fun e => Term.exactCompare (.cons (.atom "tuple") x) e.1 == .eq) = Bool.false := by
        intro x px
        simp only [List.any_eq_false, beq_iff_eq]
        exact fun e me => hS.2 e me x px
      have ht : ∀ x, mapLookup X (.atom "tuple") = some x → Elixir.Module.Types.Descr.«tuple_empty?/2» (D m) x (.map S) =
          .ok (boolAtom (!denO x (fun _ => Bool.true) && !denO x (fun _ => Bool.false))) := fun x hx =>
        pure_empty_val (cX.1 x hx) (fresh x (cX.1 x hx)) (safeN_noid hS.1 _) (by omega)
      have hmf : ∀ x, mapLookup X (.atom "map") = some x → Elixir.Module.Types.Descr.«map_empty?/2» (D m) x (.map S) =
          .ok (boolAtom Bool.false) := fun x hx => by
        obtain ⟨k, rfl⟩ := st.mz (fieldC_map (sX.fields _ x hx)) (cX.2 "map" x (by decide) hx)
        exact map_topk_nonempty _ k (not_seen hS.1 (by simp [lh]) "map")
      have hl : ∀ x, mapLookup X (.atom "list") = some x → Elixir.Module.Types.Descr.«list_empty?/2» (D m) x (.map S) =
          .ok (boolAtom Bool.false) := fun x hx => by
        rw [st.lz (fieldC_list (sX.fields _ x hx)) (cX.2 "list" x (by decide) hx)]
        exact list_top_nonempty _ _
      have hf : ∀ x, mapLookup X (.atom "fun") = some x → Elixir.Module.Types.Descr.«fun_empty?/2» (D m) x (.map S) =
          .ok (boolAtom Bool.false) := fun x hx => by
        have hx' : FunTop x := fieldC_fun (sX.fields _ x hx)
        rw [hx']
        exact fun_top_nonempty _ _
      obtain ⟨bt, ht', hbt⟩ : ∃ bt : Bool, (∀ x, mapLookup X (.atom "tuple") = some x →
          Elixir.Module.Types.Descr.«tuple_empty?/2» (D m) x (.map S) = .ok (boolAtom bt)) ∧
          ∀ x, mapLookup X (.atom "tuple") = some x → bt = (!denO x (fun _ => Bool.true) && !denO x (fun _ => Bool.false)) := by
        cases h : mapLookup X (.atom "tuple") with
        | none => exact ⟨Bool.true, fun x hx => by simp at hx, fun x hx => by simp at hx⟩
        | some x =>
          refine ⟨(!denO x (fun _ => Bool.true) && !denO x (fun _ => Bool.false)), fun x' hx' => ?_, fun x' hx' => ?_⟩
          · simp only [Option.some.injEq] at hx'; subst hx'; exact ht x h
          · simp only [Option.some.injEq] at hx'; subst hx'; rfl
      rw [descr_empty_run (D m) sX.static ne ht' hmf hl hf] at run
      have hb : b = (!(mapLookup X (.atom "atom")).isSome && !(mapLookup X (.atom "bitmap")).isSome &&
          ((mapLookup X (.atom "tuple")).isNone || bt) && (mapLookup X (.atom "map")).isNone &&
          (mapLookup X (.atom "list")).isNone && (mapLookup X (.atom "fun")).isNone) := by
        simp only [boolAtom, Except.ok.injEq] at run
        cases b <;> cases h : (!(mapLookup X (.atom "atom")).isSome && !(mapLookup X (.atom "bitmap")).isSome &&
          ((mapLookup X (.atom "tuple")).isNone || bt) && (mapLookup X (.atom "map")).isNone &&
          (mapLookup X (.atom "list")).isNone && (mapLookup X (.atom "fun")).isNone) <;> simp_all
      subst hb
      have pt : ∀ (name : String) (p : Point), name ∈ names → PtOkC TV LV MV name p →
          dn name (mapLookup X (.atom name)) p = Bool.true → ∃ v : PtG TV LV MV, denD (.map X) v :=
        fun name p mn ok h => ⟨⟨(name, p), mn, ok⟩, (denD_map _).mpr h⟩
      constructor
      · intro h v hv
        rw [denD_map] at hv
        obtain ⟨⟨name, p⟩, mn, ok⟩ := v
        simp only [Bool.and_eq_true, Bool.not_eq_true', Option.isSome_eq_false_iff, Option.isNone_iff_eq_none,
          Bool.or_eq_true] at h
        obtain ⟨⟨⟨⟨⟨ha, hbm⟩, htp⟩, hmp⟩, hlp⟩, hfp⟩ := h
        rcases names_mem mn with rfl | rfl | rfl | rfl | rfl | rfl
        · simp [hbm, dn_none] at hv
        · simp [ha, dn_none] at hv
        · simp [hfp, dn_none] at hv
        · simp [hlp, dn_none] at hv
        · cases hx : mapLookup X (.atom "tuple") with
          | none => simp [hx, dn_none] at hv
          | some x =>
            rw [hx] at htp hv
            simp only [reduceCtorEq, false_or] at htp
            rw [hbt x hx] at htp
            simp only [Bool.and_eq_true, Bool.not_eq_true'] at htp
            rw [dn_tuple] at hv
            obtain ⟨c, hc⟩ := pure_val (cX.1 x hx) (st.ks.t.resp _ (ok.2.2.2.1 rfl))
            rw [hc] at hv
            cases c
            · rw [htp.2] at hv; cases hv
            · rw [htp.1] at hv; cases hv
        · simp [hmp, dn_none] at hv
      · intro h
        have no : ∀ (name : String) (p : Point), name ∈ names → PtOkC TV LV MV name p →
            dn name (mapLookup X (.atom name)) p = Bool.true → False := fun name p mn ok d => by
          obtain ⟨v, hv⟩ := pt name p mn ok d
          exact h v hv
        have atomN : mapLookup X (.atom "atom") = none := by
          cases hx : mapLookup X (.atom "atom") with
          | none => rfl
          | some x =>
            obtain ⟨p, ok, d⟩ := atom_full (TV := TV) (LV := LV) (MV := MV) sX hx
            exact (no "atom" p (by simp [names]) ok (by rw [hx]; exact d)).elim
        have bitN : mapLookup X (.atom "bitmap") = none := by
          cases hx : mapLookup X (.atom "bitmap") with
          | none => rfl
          | some x =>
            obtain ⟨p, ok, d⟩ := bitmap_full (TV := TV) (LV := LV) (MV := MV) sX hx
            exact (no "bitmap" p (by simp [names]) ok (by rw [hx]; exact d)).elim
        have funN : mapLookup X (.atom "fun") = none := by
          cases hx : mapLookup X (.atom "fun") with
          | none => rfl
          | some x =>
            have hx' : FunTop x := fieldC_fun (sX.fields _ x hx)
            refine (no "fun" (0, .nil, fun _ => Bool.true) (by simp [names])
              ⟨resp_const _, by simp, by simp, by simp, by simp⟩ ?_).elim
            rw [hx, hx', dn_fun]
            simp [funTopT, arityOf, mapLookup]
        have listN : mapLookup X (.atom "list") = none := by
          cases hx : mapLookup X (.atom "list") with
          | none => rfl
          | some x =>
            rw [st.lz (fieldC_list (sX.fields _ x hx)) (cX.2 "list" x (by decide) hx)] at hx
            obtain ⟨ρ, hρ⟩ := st.ks.l.wit
            refine (no "list" (0, .nil, ρ) (by simp [names])
              ⟨st.ks.l.resp ρ hρ, by simp, fun _ => hρ, by simp, by simp⟩ ?_).elim
            rw [hx, dn_list, denL_top]
        have mapN : mapLookup X (.atom "map") = none := by
          cases hx : mapLookup X (.atom "map") with
          | none => rfl
          | some x =>
            obtain ⟨k, rfl⟩ := st.mz (fieldC_map (sX.fields _ x hx)) (cX.2 "map" x (by decide) hx)
            obtain ⟨ρ, hρ⟩ := st.ks.m.wit
            refine (no "map" (0, .nil, ρ) (by simp [names])
              ⟨st.ks.m.resp ρ hρ, by simp, by simp, by simp, fun _ => hρ⟩ ?_).elim
            rw [hx, dn_map, denO_top]
        have tupB : (mapLookup X (.atom "tuple")).isNone || bt := by
          cases hx : mapLookup X (.atom "tuple") with
          | none => rfl
          | some x =>
            rw [hbt x hx]
            have fx := fieldC_tuple (sX.fields _ x hx)
            have none : ∀ c : Bool, denO x (fun _ => c) = Bool.false := by
              intro c
              cases hc : denO x (fun _ => c)
              · rfl
              · obtain ⟨ρ, hρ, e⟩ := st.treal c fx (cX.1 x hx)
                refine (no "tuple" (0, .nil, ρ) (by simp [names])
                  ⟨st.ks.t.resp ρ hρ, by simp, by simp, fun _ => hρ, by simp⟩ ?_).elim
                rw [hx, dn_tuple, e, hc]
            simp [none]
        simp [atomN, bitN, funN, listN, mapN, tupB]

    end

    /-- Fusing types over fields `TF`, `LF`, and `MF`. -/
    def FuseOk (K : Nat) (TF LF MF : Term → Prop) (TV LV MV : (Term → Bool) → Prop) : Prop :=
      ∀ {a b : Term} (n : Int) {m : Nat}, DEG TF LF MF a → DEG TF LF MF b → exactCompare a b ≠ .eq → K + 14 ≤ m → ∃ r,
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» (D m) a b (.integer n) = .ok r ∧
          (r = .atom "nil" ∨ (DEG TF LF MF r ∧ ∀ v : PtG TV LV MV, denD r v ↔ denD a v ∨ denD b v))

    /-- Types over the fields of a step are element types. -/
    theorem ef_gen (st : StepOk nd C K TF LF MF TV LV MV) (fu : FuseOk K TF LF MF TV LV MV) :
        EF nd (DEG TF LF MF) (PtG TV LV MV) denD tlD (K + 14) where
      pos := by omega
      term := Or.inl rfl
      none := Or.inr ⟨[], rfl, descrC_nil⟩
      den_term := denD_term
      static := fun {a} ha => by
        rcases ha with rfl | ⟨X, rfl, sX⟩
        · exact Or.inl rfl
        · exact Or.inr (Or.inl ⟨X, rfl, sX.static⟩)
      node := fun {a} ha hn => by
        rcases ha with rfl | ⟨X, rfl, -⟩ <;> obtain ⟨r, st, g, h⟩ := hn <;> simp at h
      low := fun ha z => dg_low st ha z
      cinter := fun ha hb ca cb hm run => dg_cinter st ha hb ca cb hm run
      cdiff := fun ha hb ca cb hm run => dg_cdiff st ha hb ca cb hm run
      cempty := fun ha ca hS hm run => dg_cempty st ha ca hS (by omega) run
      inhabited := ⟨ptWit⟩
      resp := fun he he' h d => de_resp st he he' h d
      union := fun ha hb => de_union st ha hb
      inter := fun ha hb =>
        let ⟨c, hc, run, sem, l⟩ := de_inter st ha hb
        ⟨c, hc, fun m hm => run m (by omega), sem, l⟩
      diff := fun ha hb =>
        let ⟨c, hc, run, sem, l⟩ := de_diff st ha hb
        ⟨c, hc, fun m hm => run m (by omega), sem, l⟩
      opt_union := by intro a b S m ha hb hm; exact de_opt_union st S ha hb (by omega)
      opt_inter := by intro a b S m ha hb hm; exact de_opt_inter st S ha hb (by omega)
      opt_diff := by intro a b S m ha hb hm; exact de_opt_diff st S ha hb (by omega)
      empty := fun S ha =>
        let ⟨b, run, ex⟩ := de_empty st S ha
        ⟨b, fun m hm => run m (by omega), ex⟩
      sub := fun ha hb => de_sub st ha hb
      disj := fun ha hb => de_disj st ha hb
      fuse := by intro a b n m ha hb ne hm; exact fu n ha hb ne hm
      tail := fun he => let ⟨e', run, he', sem, l⟩ := de_tail st he; ⟨e', fun m _ => run (D m), he', sem, l⟩
      tl_witness := ⟨ptWit, by simp [tlD, ptWit]⟩

    end

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- The step from element types to types over them. -/
    theorem ef_step (ef : EF nd E V den tl K) (hnone : E (.map [])) :
        EF nd (DE E) (PtD E den tl) denD tlD (K + 14) :=
      ef_gen (stepOf ef hnone) fun {_ _} n {_} ha hb ne hm => de_fuse ef hnone n ha hb ne hm

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Element types with the node: operations on the node compute on its expansion. -/

    theorem opt_union_node_l {r : List Nat} {e : Term} (h : NodeAt r e) (m : Nat) {k : Int}
        (run : Elixir.Module.Types.Descr.«expand_node/1» (D (m + 1)) e = .ok (expN e k)) (b S : Term)
        (hb : b ≠ .atom "term") (none : ¬b.compare (.map []) = .eq) :
        Elixir.Module.Types.Descr.«opt_union/3» (D (m + 1)) e b S =
          Elixir.Module.Types.Descr.«opt_union/3» (D (m + 1)) (expN e k) b S := by
      have ne := node_ne_none h
      have ne' := expN_ne_none e k
      obtain ⟨S₀, rfl, -⟩ := h
      rw [Elixir.Module.Types.Descr.«opt_union/3».eq_def, Elixir.Module.Types.Descr.«opt_union/3».eq_def]
      cases b
      case atom name =>
        by_cases ht : name = "term"
        · exact absurd (by rw [ht]) hb
        · simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN,
            Elixir.Module.Types.Descr.«unfold/1»]
      all_goals simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]

    theorem opt_union_node_r {r : List Nat} {e : Term} (h : NodeAt r e) (m : Nat) {k : Int}
        (run : Elixir.Module.Types.Descr.«expand_node/1» (D (m + 1)) e = .ok (expN e k)) (a S : Term)
        (ha : a ≠ .atom "term") (none : ¬a.compare (.map []) = .eq) :
        Elixir.Module.Types.Descr.«opt_union/3» (D (m + 1)) a e S =
          Elixir.Module.Types.Descr.«opt_union/3» (D (m + 1)) a (expN e k) S := by
      have ne := node_ne_none h
      have ne' := expN_ne_none e k
      obtain ⟨S₀, rfl, -⟩ := h
      rw [Elixir.Module.Types.Descr.«opt_union/3».eq_def, Elixir.Module.Types.Descr.«opt_union/3».eq_def]
      cases a
      case atom name =>
        by_cases ht : name = "term"
        · exact absurd (by rw [ht]) ha
        · simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]
      all_goals simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]

    theorem opt_inter_node_l {r : List Nat} {e : Term} (h : NodeAt r e) (m : Nat) {k : Int}
        (run : Elixir.Module.Types.Descr.«expand_node/1» (D (m + 1)) e = .ok (expN e k)) (b S : Term)
        (hb : b ≠ .atom "term") :
        Elixir.Module.Types.Descr.«opt_intersection/3» (D (m + 1)) e b S =
          Elixir.Module.Types.Descr.«opt_intersection/3» (D (m + 1)) (expN e k) b S := by
      obtain ⟨S₀, rfl, -⟩ := h
      rw [Elixir.Module.Types.Descr.«opt_intersection/3».eq_def, Elixir.Module.Types.Descr.«opt_intersection/3».eq_def]
      cases b
      case atom name =>
        by_cases ht : name = "term"
        · exact absurd (by rw [ht]) hb
        · simp_all [unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]
      all_goals simp_all [unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]

    theorem opt_inter_node_r {r : List Nat} {e : Term} (h : NodeAt r e) (m : Nat) {k : Int}
        (run : Elixir.Module.Types.Descr.«expand_node/1» (D (m + 1)) e = .ok (expN e k)) (a S : Term)
        (ha : a ≠ .atom "term") :
        Elixir.Module.Types.Descr.«opt_intersection/3» (D (m + 1)) a e S =
          Elixir.Module.Types.Descr.«opt_intersection/3» (D (m + 1)) a (expN e k) S := by
      obtain ⟨S₀, rfl, -⟩ := h
      rw [Elixir.Module.Types.Descr.«opt_intersection/3».eq_def, Elixir.Module.Types.Descr.«opt_intersection/3».eq_def]
      cases a
      case atom name =>
        by_cases ht : name = "term"
        · exact absurd (by rw [ht]) ha
        · simp_all [unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]
      all_goals simp_all [unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]

    theorem opt_diff_node_l {r : List Nat} {e : Term} (h : NodeAt r e) (m : Nat) {k : Int}
        (run : Elixir.Module.Types.Descr.«expand_node/1» (D (m + 1)) e = .ok (expN e k)) (b S : Term)
        (hb : b ≠ .atom "term") (none : ¬b.compare (.map []) = .eq) :
        Elixir.Module.Types.Descr.«opt_difference/3» (D (m + 1)) e b S =
          Elixir.Module.Types.Descr.«opt_difference/3» (D (m + 1)) (expN e k) b S := by
      obtain ⟨S₀, rfl, -⟩ := h
      have tne : (Term.tuple #[.reference r, .map S₀, gen]).compare (.atom "term") ≠ .eq := by
        rw [Term.compare_eq_step]; simp [Compare.compareStep]
      have ene : (expN (.tuple #[.reference r, .map S₀, gen]) k).compare (.atom "term") ≠ .eq := by
        simp only [expN]; rw [Term.compare_eq_step]; simp [Compare.compareStep]
      rw [Elixir.Module.Types.Descr.«opt_difference/3».eq_def, Elixir.Module.Types.Descr.«opt_difference/3».eq_def]
      cases b
      case atom name =>
        by_cases ht : name = "term"
        · exact absurd (by rw [ht]) hb
        · simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]
      all_goals simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]

    theorem opt_diff_node_r {r : List Nat} {e : Term} (h : NodeAt r e) (m : Nat) {k : Int}
        (run : Elixir.Module.Types.Descr.«expand_node/1» (D (m + 1)) e = .ok (expN e k)) (a S : Term) :
        Elixir.Module.Types.Descr.«opt_difference/3» (D (m + 1)) a e S =
          Elixir.Module.Types.Descr.«opt_difference/3» (D (m + 1)) a (expN e k) S := by
      have ne := node_ne_none h
      have ne' := expN_ne_none e k
      obtain ⟨S₀, rfl, -⟩ := h
      rw [Elixir.Module.Types.Descr.«opt_difference/3».eq_def, Elixir.Module.Types.Descr.«opt_difference/3».eq_def]
      simp_all [Lynx.Except.guard, Erlang.erlang.«==/2», unfold_map, expN, Elixir.Module.Types.Descr.«unfold/1»]

    theorem opt_union_none_l (d : Dispatcher) {a b S : Term} (at' : a ≠ .atom "term") (bt : b ≠ .atom "term")
        (none : a.compare (.map []) = .eq) : Elixir.Module.Types.Descr.«opt_union/3» d a b S = .ok b := by
      rw [Elixir.Module.Types.Descr.«opt_union/3».eq_def]
      split
      · exact absurd rfl at'
      · exact absurd rfl bt
      · simp_all [Lynx.Except.guard, Erlang.erlang.«==/2»]

    theorem opt_union_none_r (d : Dispatcher) {a b S : Term} (at' : a ≠ .atom "term") (bt : b ≠ .atom "term")
        (na : ¬a.compare (.map []) = .eq) (none : b.compare (.map []) = .eq) :
        Elixir.Module.Types.Descr.«opt_union/3» d a b S = .ok a := by
      rw [Elixir.Module.Types.Descr.«opt_union/3».eq_def]
      split
      · exact absurd rfl at'
      · exact absurd rfl bt
      · simp_all [Lynx.Except.guard, Erlang.erlang.«==/2»]

    theorem opt_diff_none_r (d : Dispatcher) {a b S : Term} (bt : b ≠ .atom "term") (none : b.compare (.map []) = .eq) :
        Elixir.Module.Types.Descr.«opt_difference/3» d a b S = .ok a := by
      rw [Elixir.Module.Types.Descr.«opt_difference/3».eq_def]
      cases b
      case atom name =>
        by_cases ht : name = "term"
        · exact absurd (by rw [ht]) bt
        · simp_all [Lynx.Except.guard, Erlang.erlang.«==/2»]
      all_goals simp_all [Lynx.Except.guard, Erlang.erlang.«==/2»]

    theorem fuse_node_l {r : List Nat} {e : Term} (h : NodeAt r e) (d : Dispatcher) (b n : Term) :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» d e b n = .ok (.atom "nil") := by
      obtain ⟨S, rfl, -⟩ := h
      unfold Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3»
      simp [Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1», getMapKeys, getMapKeys_tuple]
      repeat' split
      all_goals simp_all [Lynx.Except.andAlso, Erlang.erlang.«==/2», Erlang.erlang.«map_size/1»]

    theorem aob_node {r : List Nat} {S : List (Term × Term)} {g : Term} :
        Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.tuple #[.reference r, .map S, g]) = .ok (.atom "false") := by
      unfold Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1»
      simp [getMapKeys]

    theorem fuse_node_r {r : List Nat} {e : Term} (h : NodeAt r e) (d : Dispatcher) (a n : Term) :
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» d a e n = .ok (.atom "nil") := by
      obtain ⟨S, rfl, -⟩ := h
      obtain ⟨c, rc⟩ := aob_bool a
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3».eq_def]
      simp only [getMapKeys_tuple]
      split <;> cases c <;> simp [rc, aob_node, Lynx.Except.andAlso, boolAtom, Lynx.Except.guard, isMember]

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- Element types and the node `nd`. -/
    def DEN (nd : Term) (E : Term → Prop) (a : Term) : Prop := E a ∨ IsT nd a

    /-- The node holds the values of its expansion. -/
    def denN (nd : Term) (den : Term → V → Prop) (a : Term) (v : V) : Prop :=
      (IsT nd a ∧ den (expN a (keyOf nd)) v) ∨ (¬IsT nd a ∧ den a v)

    /-- Classes that hold the expansions of the node `nd`, and no node. -/
    structure NodeOk (nd : Term) (E : Term → Prop) : Prop where
      exp : ∀ {e}, IsT nd e → E (expN e (keyOf nd))
      notN : ∀ {a}, E a → ¬IsT nd a

    theorem isT_term : ¬IsT nd (.atom "term") := fun he => node_ne_term he rfl

    theorem lh_expN {e : Term} (he : IsT nd e) : lh (expN e (keyOf nd)) = 1 := by
      apply Nat.le_antisymm
      · refine lh_map_le.mpr fun x mx => ?_
        have := mem_of_mem_mapEntries mx
        simp only [List.mem_cons, List.mem_nil_iff, or_false] at this
        have la : lh (.tuple #[.atom "union", .map [(.atom "nil", .nil)]]) = 0 :=
          lh_atomF ⟨⟨Bool.true, [(.atom "nil", .nil)], rfl, by simp [Erlang.sets.elements?]⟩, .atom "nil",
            by simp [amemV, mapLookup]⟩
        rcases this with rfl | rfl
        · exact Nat.le_of_eq (lh_litN he _)
        · simp only [la]; omega
      · have := lh_field_le (X := [(.atom "tuple", litN e (keyOf nd)), (.atom "atom", .tuple #[.atom "union",
          .map [(.atom "nil", .nil)]])]) (q := .atom "tuple") (x := litN e (keyOf nd)) (by simp [mapLookup])
        rw [lh_litN he _] at this
        exact this

    theorem combo_expN {e : Term} (he : IsT nd e) : Combo nd (expN e (keyOf nd)) := by
      refine combo_map.mpr ⟨fun w hw => ?_, fun name w nt hw => ?_⟩
      · simp [mapLookup] at hw
        subst hw
        exact Or.inr (Bdd.leaf_iff.mpr ⟨e, he, rfl⟩)
      · simp only [mapLookup, List.find?_cons, exactCompare_eq_atom, Term.atom.injEq] at hw
        by_cases t : name = "tuple"
        · exact absurd t nt
        · by_cases a : name = "atom"
          · subst a; simp at hw; subst hw
            exact lh_atomF ⟨⟨Bool.true, [(.atom "nil", .nil)], rfl, by simp [Erlang.sets.elements?]⟩, .atom "nil",
              by simp [amemV, mapLookup]⟩
          · simp [t, a] at hw

    theorem denN_of {a : Term} {v : V} (hn : ¬IsT nd a) : denN nd den a v ↔ den a v := by
      simp [denN, hn]

    theorem denN_node {a : Term} {v : V} (hn : IsT nd a) : denN nd den a v ↔ den (expN a (keyOf nd)) v := by
      simp [denN, hn]

    /-- A type of the class with the node, as a type of the class: the node as its expansion. -/
    theorem NodeOk.red (h : NodeOk nd E) {a : Term} (ha : DEN nd E a) : ∃ A, E A ∧ (∀ v, denN nd den a v ↔ den A v) ∧
        lh A = lh a ∧ (Combo nd a → Combo nd A) ∧ (a = A ∨ (IsT nd a ∧ A = expN a (keyOf nd))) := by
      rcases ha with ha | ha
      · exact ⟨a, ha, fun v => denN_of (h.notN ha), rfl, id, Or.inl rfl⟩
      · exact ⟨_, h.exp ha, fun v => denN_node ha, by rw [lh_expN ha, lh_isT ha], fun _ => combo_expN ha, Or.inr ⟨ha, rfl⟩⟩

    theorem DEN.ne_term {a A : Term} (r : a = A ∨ (IsT nd a ∧ A = expN a (keyOf nd))) (at' : a ≠ .atom "term") :
        A ≠ .atom "term" := by
      rcases r with rfl | ⟨-, rfl⟩
      · exact at'
      · exact expN_ne_term _ _

    theorem DEN.ne_none {a A : Term} (r : a = A ∨ (IsT nd a ∧ A = expN a (keyOf nd)))
        (na : ¬a.compare (.map []) = .eq) : ¬A.compare (.map []) = .eq := by
      rcases r with rfl | ⟨-, rfl⟩
      · exact na
      · exact expN_ne_none _ _

    theorem isT_ne_none {a : Term} (ha : IsT nd a) : ¬a.compare (.map []) = .eq := node_ne_none ha.node

    theorem EF.den_none (ef : EF nd E V den tl K) (v : V) : ¬den (.map []) v := by
      obtain ⟨b, run, ex⟩ := ef.empty [] ef.none
      have r := run K (Nat.le_refl _)
      rw [empty_none_seen] at r
      have : b = Bool.true := by cases b <;> simp_all [boolAtom]
      subst this
      exact (ex 1 (by rw [lh_nil_map]; omega) (safeN_nil _)).mp rfl v

    theorem EF.den_none' (ef : EF nd E V den tl K) {a : Term} (ha : E a) (none : a.compare (.map []) = .eq) (v : V) :
        ¬den a v := fun d => ef.den_none v (ef.resp ef.none ha (Std.OrientedCmp.eq_symm none) d)

    theorem red_inter {a b A B : Term} (ra : a = A ∨ (IsT nd a ∧ A = expN a (keyOf nd)))
        (rb : b = B ∨ (IsT nd b ∧ B = expN b (keyOf nd))) (bt : b ≠ .atom "term") (nA : A ≠ .atom "term") (m : Nat) :
        Elixir.Module.Types.Descr.«bare_intersection/2» (D (m + 1)) a b =
          Elixir.Module.Types.Descr.«bare_intersection/2» (D (m + 1)) A B := by
      have e₁ : Elixir.Module.Types.Descr.«bare_intersection/2» (D (m + 1)) a b =
          Elixir.Module.Types.Descr.«bare_intersection/2» (D (m + 1)) A b := by
        rcases ra with rfl | ⟨t, rfl⟩
        · rfl
        · exact inter_node_l t.node m (expand_isT t m) b bt
      rw [e₁]
      rcases rb with rfl | ⟨t, rfl⟩
      · rfl
      · exact inter_node_r t.node m (expand_isT t m) A nA

    theorem red_diff {a b A B : Term} (ra : a = A ∨ (IsT nd a ∧ A = expN a (keyOf nd)))
        (rb : b = B ∨ (IsT nd b ∧ B = expN b (keyOf nd))) (nB : B ≠ .atom "term") (eB : ¬B.compare (.map []) = .eq)
        (m : Nat) :
        Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 1)) a b =
          Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 1)) A B := by
      have e₁ : Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 1)) a b =
          Elixir.Module.Types.Descr.«bare_difference/2» (D (m + 1)) a B := by
        rcases rb with rfl | ⟨t, rfl⟩
        · rfl
        · exact diff_node_r t.node m (expand_isT t m) a
      rw [e₁]
      rcases ra with rfl | ⟨t, rfl⟩
      · rfl
      · exact diff_node_l t.node m (expand_isT t m) B nB eB

    theorem an_inter (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (ha : DEN nd E a) (hb : DEN nd E b) :
        ∃ c, DEN nd E c ∧ (∀ m, K + 1 ≤ m → Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok c) ∧
          (∀ v, denN nd den c v ↔ denN nd den a v ∧ denN nd den b v) ∧ ∀ N, lh a < N → lh b < N → lh c < N := by
      have dt := fun v => (denN_of (nd := nd) (den := den) isT_term (v := v)).mpr (ef.den_term v)
      by_cases bt : b = .atom "term"
      · subst bt
        exact ⟨a, ha, fun m _ => inter_term_right _ _, fun v => ⟨fun x => ⟨x, dt v⟩, fun x => x.1⟩, fun N h₁ _ => h₁⟩
      by_cases at' : a = .atom "term"
      · subst at'
        exact ⟨b, hb, fun m _ => inter_term_left _ _, fun v => ⟨fun x => ⟨dt v, x⟩, fun x => x.2⟩, fun N _ h₂ => h₂⟩
      obtain ⟨A, eA, sA, lA, -, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, sB, lB, -, rB⟩ := h.red (den := den) hb
      obtain ⟨c, hc, run, sem, lc⟩ := ef.inter eA eB
      refine ⟨c, Or.inl hc, fun m hm => ?_, fun v => ?_, fun N h₁ h₂ => lc N (by omega) (by omega)⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        rw [red_inter rA rB bt (DEN.ne_term rA at') m']
        exact run _ (by omega)
      · rw [denN_of (h.notN hc), sA, sB]; exact sem v

    theorem an_diff (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (ha : DEN nd E a) (hb : DEN nd E b) :
        ∃ c, DEN nd E c ∧ (∀ m, K + 1 ≤ m → Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok c) ∧
          (∀ v, denN nd den c v ↔ denN nd den a v ∧ ¬denN nd den b v) ∧ ∀ N, lh a < N → lh b < N → lh c < N := by
      have dt := fun v => (denN_of (nd := nd) (den := den) isT_term (v := v)).mpr (ef.den_term v)
      have dn0 : ∀ v, ¬denN nd den (.map []) v := fun v d =>
        ef.den_none v ((denN_of (fun t => isT_map t)).mp d)
      by_cases bt : b = .atom "term"
      · subst bt
        exact ⟨_, Or.inl ef.none, fun m _ => diff_term_right _ _, fun v => ⟨fun x => absurd x (dn0 v),
          fun x => absurd (dt v) x.2⟩, fun N _ _ => by rw [lh_nil_map]; omega⟩
      obtain ⟨B, eB, sB, lB, -, rB⟩ := h.red (den := den) hb
      by_cases none : b.compare (.map []) = .eq
      · have nb : ∀ v, ¬denN nd den b v := by
          rcases rB with rfl | ⟨t, -⟩
          · exact fun v d => ef.den_none' eB none v ((sB v).mp d)
          · exact absurd none (isT_ne_none t)
        exact ⟨a, ha, fun m _ => diff_none _ a b bt none, fun v => ⟨fun x => ⟨x, nb v⟩, fun x => x.1⟩, fun N h₁ _ => h₁⟩
      obtain ⟨A, eA, sA, lA, -, rA⟩ := h.red (den := den) ha
      obtain ⟨c, hc, run, sem, lc⟩ := ef.diff eA eB
      refine ⟨c, Or.inl hc, fun m hm => ?_, fun v => ?_, fun N h₁ h₂ => lc N (by omega) (by omega)⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        rw [red_diff rA rB (DEN.ne_term rB bt) (DEN.ne_none rB none) m']
        exact run _ (by omega)
      · rw [denN_of (h.notN hc), sA, sB]; exact sem v

    theorem an_union (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (ha : DEN nd E a) (hb : DEN nd E b) :
        ∃ c, DEN nd E c ∧ (∀ m, K + 1 ≤ m → Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok c) ∧
          (∀ v, denN nd den c v ↔ denN nd den a v ∨ denN nd den b v) ∧ ∀ N, lh a < N → lh b < N → lh c < N := by
      have dt := fun v => (denN_of (nd := nd) (den := den) isT_term (v := v)).mpr (ef.den_term v)
      by_cases at' : a = .atom "term"
      · subst at'
        exact ⟨_, Or.inl ef.term, fun m _ => union_term_l _ _, fun v => ⟨fun _ => Or.inl (dt v), fun _ => dt v⟩,
          fun N h₁ _ => h₁⟩
      by_cases bt : b = .atom "term"
      · subst bt
        exact ⟨_, Or.inl ef.term, fun m _ => union_any_term _ _, fun v => ⟨fun _ => Or.inr (dt v), fun _ => dt v⟩,
          fun N _ h₂ => h₂⟩
      obtain ⟨A, eA, sA, lA, -, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, sB, lB, -, rB⟩ := h.red (den := den) hb
      have nemp : ∀ {x X}, DEN nd E x → x.compare (.map []) = .eq → (x = X ∨ (IsT nd x ∧ X = expN x (keyOf nd))) →
          E X → (∀ v, denN nd den x v ↔ den X v) → ∀ v, ¬denN nd den x v := by
        intro x X _ none r eX s v d
        rcases r with rfl | ⟨t, -⟩
        · exact ef.den_none' eX none v ((s v).mp d)
        · exact absurd none (isT_ne_none t)
      by_cases na : a.compare (.map []) = .eq
      · exact ⟨b, hb, fun m _ => union_none _ a b at' bt na,
          fun v => ⟨Or.inr, fun x => x.elim (fun d => absurd d (nemp ha na rA eA sA v)) id⟩, fun N _ h₂ => h₂⟩
      by_cases nb : b.compare (.map []) = .eq
      · exact ⟨a, ha, fun m _ => union_none_r _ a b at' bt na nb,
          fun v => ⟨Or.inl, fun x => x.elim id (fun d => absurd d (nemp hb nb rB eB sB v))⟩, fun N h₁ _ => h₁⟩
      obtain ⟨c, hc, run, sem, lc⟩ := ef.union eA eB
      refine ⟨c, Or.inl hc, fun m hm => ?_, fun v => ?_, fun N h₁ h₂ => lc N (by omega) (by omega)⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        have e₁ : Elixir.Module.Types.Descr.«bare_union/2» (D (m' + 1)) a b =
            Elixir.Module.Types.Descr.«bare_union/2» (D (m' + 1)) A b := by
          rcases rA with rfl | ⟨t, rfl⟩
          · rfl
          · exact union_node_l t.node m' (expand_isT t m') b bt nb
        have e₂ : Elixir.Module.Types.Descr.«bare_union/2» (D (m' + 1)) A b =
            Elixir.Module.Types.Descr.«bare_union/2» (D (m' + 1)) A B := by
          rcases rB with rfl | ⟨t, rfl⟩
          · rfl
          · exact union_node_r t.node m' (expand_isT t m') A (DEN.ne_term rA at') (DEN.ne_none rA na)
        rw [e₁, e₂]
        exact run _ (by omega)
      · rw [denN_of (h.notN hc), sA, sB]; exact sem v

    theorem an_opt_union (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (S : List (Term × Term)) {m : Nat}
        (ha : DEN nd E a) (hb : DEN nd E b) (hm : K + 1 ≤ m) : ∃ c, DEN nd E c ∧
          Elixir.Module.Types.Descr.«opt_union/3» (D m) a b (.map S) = .ok c ∧
          ∀ v, denN nd den c v ↔ denN nd den a v ∨ denN nd den b v := by
      have dt := fun v => (denN_of (nd := nd) (den := den) isT_term (v := v)).mpr (ef.den_term v)
      by_cases at' : a = .atom "term"
      · subst at'
        exact ⟨_, Or.inl ef.term, opt_union_term_left _ _ _, fun v => ⟨fun _ => Or.inl (dt v), fun _ => dt v⟩⟩
      by_cases bt : b = .atom "term"
      · subst bt
        exact ⟨_, Or.inl ef.term, opt_union_term_r _ _ _, fun v => ⟨fun _ => Or.inr (dt v), fun _ => dt v⟩⟩
      obtain ⟨A, eA, sA, lA, -, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, sB, lB, -, rB⟩ := h.red (den := den) hb
      have nemp : ∀ {x X}, DEN nd E x → x.compare (.map []) = .eq → (x = X ∨ (IsT nd x ∧ X = expN x (keyOf nd))) →
          E X → (∀ v, denN nd den x v ↔ den X v) → ∀ v, ¬denN nd den x v := by
        intro x X _ none r eX s v d
        rcases r with rfl | ⟨t, -⟩
        · exact ef.den_none' eX none v ((s v).mp d)
        · exact absurd none (isT_ne_none t)
      by_cases na : a.compare (.map []) = .eq
      · exact ⟨b, hb, opt_union_none_l _ at' bt na,
          fun v => ⟨Or.inr, fun x => x.elim (fun d => absurd d (nemp ha na rA eA sA v)) id⟩⟩
      by_cases nb : b.compare (.map []) = .eq
      · exact ⟨a, ha, opt_union_none_r _ at' bt na nb,
          fun v => ⟨Or.inl, fun x => x.elim id (fun d => absurd d (nemp hb nb rB eB sB v))⟩⟩
      obtain ⟨c, hc, run, sem⟩ := ef.opt_union S eA eB (show K ≤ m by omega)
      refine ⟨c, Or.inl hc, ?_, fun v => ?_⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        have e₁ : Elixir.Module.Types.Descr.«opt_union/3» (D (m' + 1)) a b (.map S) =
            Elixir.Module.Types.Descr.«opt_union/3» (D (m' + 1)) A b (.map S) := by
          rcases rA with rfl | ⟨t, rfl⟩
          · rfl
          · exact opt_union_node_l t.node m' (expand_isT t m') b _ bt nb
        have e₂ : Elixir.Module.Types.Descr.«opt_union/3» (D (m' + 1)) A b (.map S) =
            Elixir.Module.Types.Descr.«opt_union/3» (D (m' + 1)) A B (.map S) := by
          rcases rB with rfl | ⟨t, rfl⟩
          · rfl
          · exact opt_union_node_r t.node m' (expand_isT t m') A _ (DEN.ne_term rA at') (DEN.ne_none rA na)
        rw [e₁, e₂, run]
      · rw [denN_of (h.notN hc), sA, sB]; exact sem v

    theorem an_opt_inter (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (S : List (Term × Term)) {m : Nat}
        (ha : DEN nd E a) (hb : DEN nd E b) (hm : K + 1 ≤ m) : ∃ c, DEN nd E c ∧
          Elixir.Module.Types.Descr.«opt_intersection/3» (D m) a b (.map S) = .ok c ∧
          ∀ v, denN nd den c v ↔ denN nd den a v ∧ denN nd den b v := by
      have dt := fun v => (denN_of (nd := nd) (den := den) isT_term (v := v)).mpr (ef.den_term v)
      by_cases at' : a = .atom "term"
      · subst at'
        exact ⟨b, hb, opt_inter_term_l _ _ _, fun v => ⟨fun x => ⟨dt v, x⟩, fun x => x.2⟩⟩
      by_cases bt : b = .atom "term"
      · subst bt
        exact ⟨a, ha, opt_inter_term_r _ _ _, fun v => ⟨fun x => ⟨x, dt v⟩, fun x => x.1⟩⟩
      obtain ⟨A, eA, sA, lA, -, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, sB, lB, -, rB⟩ := h.red (den := den) hb
      obtain ⟨c, hc, run, sem⟩ := ef.opt_inter S eA eB (show K ≤ m by omega)
      refine ⟨c, Or.inl hc, ?_, fun v => ?_⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        have e₁ : Elixir.Module.Types.Descr.«opt_intersection/3» (D (m' + 1)) a b (.map S) =
            Elixir.Module.Types.Descr.«opt_intersection/3» (D (m' + 1)) A b (.map S) := by
          rcases rA with rfl | ⟨t, rfl⟩
          · rfl
          · exact opt_inter_node_l t.node m' (expand_isT t m') b _ bt
        have e₂ : Elixir.Module.Types.Descr.«opt_intersection/3» (D (m' + 1)) A b (.map S) =
            Elixir.Module.Types.Descr.«opt_intersection/3» (D (m' + 1)) A B (.map S) := by
          rcases rB with rfl | ⟨t, rfl⟩
          · rfl
          · exact opt_inter_node_r t.node m' (expand_isT t m') A _ (DEN.ne_term rA at')
        rw [e₁, e₂, run]
      · rw [denN_of (h.notN hc), sA, sB]; exact sem v

    theorem an_opt_diff (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (S : List (Term × Term)) {m : Nat}
        (ha : DEN nd E a) (hb : DEN nd E b) (hm : K + 1 ≤ m) : ∃ c, DEN nd E c ∧
          Elixir.Module.Types.Descr.«opt_difference/3» (D m) a b (.map S) = .ok c ∧
          ∀ v, denN nd den c v ↔ denN nd den a v ∧ ¬denN nd den b v := by
      have dt := fun v => (denN_of (nd := nd) (den := den) isT_term (v := v)).mpr (ef.den_term v)
      have dn0 : ∀ v, ¬denN nd den (.map []) v := fun v d =>
        ef.den_none v ((denN_of (fun t => isT_map t)).mp d)
      by_cases bt : b = .atom "term"
      · subst bt
        exact ⟨_, Or.inl ef.none, difference_term_term _ _ _, fun v => ⟨fun x => absurd x (dn0 v),
          fun x => absurd (dt v) x.2⟩⟩
      obtain ⟨B, eB, sB, lB, -, rB⟩ := h.red (den := den) hb
      by_cases none : b.compare (.map []) = .eq
      · have nb : ∀ v, ¬denN nd den b v := by
          rcases rB with rfl | ⟨t, -⟩
          · exact fun v d => ef.den_none' eB none v ((sB v).mp d)
          · exact absurd none (isT_ne_none t)
        exact ⟨a, ha, opt_diff_none_r _ bt none, fun v => ⟨fun x => ⟨x, nb v⟩, fun x => x.1⟩⟩
      obtain ⟨A, eA, sA, lA, -, rA⟩ := h.red (den := den) ha
      obtain ⟨c, hc, run, sem⟩ := ef.opt_diff S eA eB (show K ≤ m by omega)
      refine ⟨c, Or.inl hc, ?_, fun v => ?_⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        have e₁ : Elixir.Module.Types.Descr.«opt_difference/3» (D (m' + 1)) a b (.map S) =
            Elixir.Module.Types.Descr.«opt_difference/3» (D (m' + 1)) a B (.map S) := by
          rcases rB with rfl | ⟨t, rfl⟩
          · rfl
          · exact opt_diff_node_r t.node m' (expand_isT t m') a _
        have e₂ : Elixir.Module.Types.Descr.«opt_difference/3» (D (m' + 1)) a B (.map S) =
            Elixir.Module.Types.Descr.«opt_difference/3» (D (m' + 1)) A B (.map S) := by
          rcases rA with rfl | ⟨t, rfl⟩
          · rfl
          · exact opt_diff_node_l t.node m' (expand_isT t m') B _ (DEN.ne_term rB bt) (DEN.ne_none rB none)
        rw [e₁, e₂, run]
      · rw [denN_of (h.notN hc), sA, sB]; exact sem v

    theorem an_cinter (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b c : Term} {m : Nat} (ha : DEN nd E a)
        (hb : DEN nd E b) (ca : Combo nd a) (cb : Combo nd b) (hm : K + 1 ≤ m)
        (run : Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok c) : Combo nd c := by
      by_cases bt : b = .atom "term"
      · subst bt; rw [inter_term_right] at run; cases run; exact ca
      by_cases at' : a = .atom "term"
      · subst at'; rw [inter_term_left] at run; cases run; exact cb
      obtain ⟨A, eA, -, -, cA, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, -, -, cB, rB⟩ := h.red (den := den) hb
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      rw [red_inter rA rB bt (DEN.ne_term rA at') m'] at run
      exact ef.cinter eA eB (cA ca) (cB cb) (by omega) run

    theorem an_cdiff (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b c : Term} {m : Nat} (ha : DEN nd E a)
        (hb : DEN nd E b) (ca : Combo nd a) (cb : Combo nd b) (hm : K + 1 ≤ m)
        (run : Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok c) : Combo nd c := by
      by_cases bt : b = .atom "term"
      · subst bt; rw [diff_term_right] at run; cases run; exact combo_none nd
      by_cases none : b.compare (.map []) = .eq
      · rw [diff_none _ a b bt none] at run; cases run; exact ca
      obtain ⟨A, eA, -, -, cA, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, -, -, cB, rB⟩ := h.red (den := den) hb
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      rw [red_diff rA rB (DEN.ne_term rB bt) (DEN.ne_none rB none) m'] at run
      exact ef.cdiff eA eB (cA ca) (cB cb) (by omega) run

    /-- Expansions of the node hold values: nil. -/
    theorem EF.expN_inh (ef : EF nd E V den tl K) {e : Term} (he : E (expN e (keyOf nd))) :
        ∃ v, den (expN e (keyOf nd)) v := by
      obtain ⟨b, run, ex⟩ := ef.empty [] he
      have r := run K (Nat.le_refl _)
      rw [empty_expN] at r
      have : b = Bool.false := by cases b <;> simp_all [boolAtom]
      subst this
      have hx := ex (lh (expN e (keyOf nd)) + 1) (Nat.lt_succ_self _) (safeN_nil _)
      exact Classical.byContradiction fun hn => absurd (hx.mpr fun w hw => hn ⟨w, hw⟩) (by decide)

    theorem an_empty (ef : EF nd E V den tl K) (h : NodeOk nd E) {a : Term} (S : List (Term × Term)) (ha : DEN nd E a) :
        ∃ b : Bool, (∀ m, K + 1 ≤ m → Elixir.Module.Types.Descr.«empty_seen?/2» (D m) a (.map S) = .ok (boolAtom b)) ∧
          ∀ N, lh a < N → SafeN N S → (b = Bool.true ↔ ∀ v, ¬denN nd den a v) := by
      rcases ha with ha | ha
      · obtain ⟨b, run, ex⟩ := ef.empty S ha
        refine ⟨b, fun m hm => run m (by omega), fun N hN hS => ?_⟩
        rw [ex N hN hS]
        exact ⟨fun x v d => x v ((denN_of (h.notN ha)).mp d), fun x v d => x v ((denN_of (h.notN ha)).mpr d)⟩
      · refine ⟨idIn (refOf nd) S, fun m hm => ?_, fun N _ hS => ?_⟩
        · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
          exact empty_node ha.node m' S
        · rw [safeN_noid hS]
          obtain ⟨v, hv⟩ := ef.expN_inh (h.exp ha)
          exact ⟨fun x => absurd x (by decide), fun x => absurd ((denN_node ha).mpr hv) (x v)⟩

    theorem an_cempty (ef : EF nd E V den tl K) (h : NodeOk nd E) {a : Term} {S : List (Term × Term)} {m : Nat} {b : Bool}
        (ha : DEN nd E a) (ca : Combo nd a) (hS : Safe1 nd S) (hm : K + 1 ≤ m)
        (run : Elixir.Module.Types.Descr.«empty_seen?/2» (D m) a (.map S) = .ok (boolAtom b)) :
        b = Bool.true ↔ ∀ v, ¬denN nd den a v := by
      rcases ha with ha | ha
      · rw [ef.cempty ha ca hS (by omega) run]
        exact ⟨fun x v d => x v ((denN_of (h.notN ha)).mp d), fun x v d => x v ((denN_of (h.notN ha)).mpr d)⟩
      · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        rw [empty_node ha.node m' S] at run
        have := safeN_noid hS.1 (refOf nd)
        simp only [idIn] at this
        rw [this] at run
        have : b = Bool.false := by cases b <;> simp_all [boolAtom]
        subst this
        obtain ⟨v, hv⟩ := ef.expN_inh (h.exp ha)
        exact ⟨fun x => absurd x (by decide), fun x => absurd ((denN_node ha).mpr hv) (x v)⟩

    theorem an_sub (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (ha : DEN nd E a) (hb : DEN nd E b) :
        ∃ s : Bool, (∀ m, K + 1 ≤ m → Elixir.Module.Types.Descr.«subtype?/2» (D m) a b = .ok (boolAtom s)) ∧
          (s = Bool.true → ∀ v, denN nd den a v → denN nd den b v) := by
      obtain ⟨A, eA, sA, -, -, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, sB, -, -, rB⟩ := h.red (den := den) hb
      obtain ⟨s, run, sound⟩ := ef.sub eA eB
      refine ⟨s, fun m hm => ?_, fun st v d => (sB v).mpr (sound st v ((sA v).mp d))⟩
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      have e₁ : Elixir.Module.Types.Descr.«subtype?/2» (D (m' + 1)) a b =
          Elixir.Module.Types.Descr.«subtype?/2» (D (m' + 1)) A b := by
        rcases rA with rfl | ⟨t, rfl⟩
        · rfl
        · exact sub_node_l t.node m' (expand_isT t m') b
      have e₂ : Elixir.Module.Types.Descr.«subtype?/2» (D (m' + 1)) A b =
          Elixir.Module.Types.Descr.«subtype?/2» (D (m' + 1)) A B := by
        rcases rB with rfl | ⟨t, rfl⟩
        · rfl
        · exact sub_node_r t.node m' (expand_isT t m') A
      rw [e₁, e₂]
      exact run _ (by omega)

    theorem static_map_of (ef : EF nd E V den tl K) {b : Term} (hb : DEN nd E b) :
        ∀ X, b = .map X → mapLookup X (.atom "dynamic") = none := by
      intro X e
      subst e
      rcases hb with hb | hb
      · rcases ef.static hb with h | ⟨Y, h, sY⟩ | ⟨r, st, g, h⟩
        · cases h
        · cases h; exact sY
        · cases h
      · exact absurd hb isT_map

    theorem an_disj (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (ha : DEN nd E a) (hb : DEN nd E b) :
        ∃ s : Bool, (∀ m, K + 1 ≤ m → Elixir.Module.Types.Descr.«disjoint?/2» (D m) a b = .ok (boolAtom s)) ∧
          (s = Bool.true → ∀ v, denN nd den a v → denN nd den b v → False) := by
      -- the top type and the node: `disjoint?/2` checks the emptiness of the node, which holds nil
      by_cases ct : (a = .atom "term" ∧ IsT nd b) ∨ (IsT nd a ∧ b = .atom "term")
      · refine ⟨Bool.false, fun m hm => ?_, fun st => by cases st⟩
        obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        rcases ct with ⟨rfl, hb⟩ | ⟨ha, rfl⟩
        · rw [disjoint_term_l, empty_any_node hb m']; rfl
        · rw [disj_term_r, empty_any_node ha m']; rfl
      obtain ⟨A, eA, sA, -, -, rA⟩ := h.red (den := den) ha
      obtain ⟨B, eB, sB, -, -, rB⟩ := h.red (den := den) hb
      obtain ⟨s, run, sound⟩ := ef.disj eA eB
      refine ⟨s, fun m hm => ?_, fun st v da db => sound st v ((sA v).mp da) ((sB v).mp db)⟩
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      rw [← run (m' + 1) (by omega)]
      by_cases at' : a = .atom "term"
      · subst at'
        rcases rA with rfl | ⟨t, -⟩
        · rcases rB with rfl | ⟨t, -⟩
          · rfl
          · exact absurd (Or.inl ⟨rfl, t⟩) ct
        · exact absurd t isT_term
      by_cases bt : b = .atom "term"
      · subst bt
        rcases rB with rfl | ⟨t, -⟩
        · rcases rA with rfl | ⟨t, -⟩
          · rfl
          · exact absurd (Or.inr ⟨t, rfl⟩) ct
        · exact absurd t isT_term
      have e₁ : Elixir.Module.Types.Descr.«disjoint?/2» (D (m' + 1)) a b =
          Elixir.Module.Types.Descr.«disjoint?/2» (D (m' + 1)) A b := by
        rcases rA with rfl | ⟨t, rfl⟩
        · rfl
        · exact disj_node_l t.node m' (expand_isT t m') b bt (static_map_of ef hb)
      have e₂ : Elixir.Module.Types.Descr.«disjoint?/2» (D (m' + 1)) A b =
          Elixir.Module.Types.Descr.«disjoint?/2» (D (m' + 1)) A B := by
        rcases rB with rfl | ⟨t, rfl⟩
        · rfl
        · refine disj_node_r t.node m' (expand_isT t m') A (DEN.ne_term rA at') fun X e => ?_
          rcases rA with rfl | ⟨t', rfl⟩
          · exact static_map_of ef ha X e
          · simp [expN] at e; subst e; simp [mapLookup]
      rw [e₁, e₂]

    theorem an_fuse (ef : EF nd E V den tl K) (h : NodeOk nd E) {a b : Term} (n : Int) {m : Nat} (ha : DEN nd E a)
        (hb : DEN nd E b) (ne : exactCompare a b ≠ .eq) (hm : K + 1 ≤ m) : ∃ r,
        Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3» (D m) a b (.integer n) = .ok r ∧
          (r = .atom "nil" ∨ (DEN nd E r ∧ ∀ v, denN nd den r v ↔ denN nd den a v ∨ denN nd den b v)) := by
      rcases ha with ha | ha
      rotate_left
      · exact ⟨_, fuse_node_l ha.node _ _ _, Or.inl rfl⟩
      rcases hb with hb | hb
      rotate_left
      · exact ⟨_, fuse_node_r hb.node _ _ _, Or.inl rfl⟩
      obtain ⟨r, run, out⟩ := ef.fuse n ha hb ne (show K ≤ m by omega)
      refine ⟨r, run, out.imp id fun ⟨hr, sem⟩ => ⟨Or.inl hr, fun v => ?_⟩⟩
      rw [denN_of (h.notN hr), denN_of (h.notN ha), denN_of (h.notN hb)]
      exact sem v

    theorem noList_expN (e : Term) (k : Int) :
        noList [(.atom "tuple", litN e k), (.atom "atom", .tuple #[.atom "union", .map [(.atom "nil", .nil)]])] =
          [(.atom "tuple", litN e k), (.atom "atom", .tuple #[.atom "union", .map [(.atom "nil", .nil)]])] := by
      simp [noList]

    theorem an_tail (ef : EF nd E V den tl K) (h : NodeOk nd E) {e : Term} (he : DEN nd E e) :
        ∃ e', (∀ m, 1 ≤ m → Elixir.Module.Types.Descr.«list_tail_unfold/1» (D m) e = .ok e') ∧ DEN nd E e' ∧
          (∀ v, denN nd den e' v ↔ denN nd den e v ∧ ¬tl v) ∧ lh e' ≤ lh e := by
      rcases he with he | he
      · obtain ⟨e', run, he', sem, l⟩ := ef.tail he
        refine ⟨e', run, Or.inl he', fun v => ?_, l⟩
        rw [denN_of (h.notN he'), denN_of (h.notN he)]
        exact sem v
      · obtain ⟨e'', run'', -, sem'', -⟩ := ef.tail (h.exp he)
        have r := run'' 1 (Nat.le_refl _)
        simp only [expN] at r
        rw [tail_map, noList_expN] at r
        simp only [Except.ok.injEq] at r
        subst r
        refine ⟨_, fun m hm => ?_, Or.inl (h.exp he), fun v => ?_, Nat.le_of_eq (by rw [lh_expN he, lh_isT he])⟩
        · obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
          exact tail_node he.node m' (expand_isT he m')
        · rw [denN_of (h.notN (h.exp he)), denN_node he]
          simp only [expN] at sem'' ⊢
          exact ⟨fun d => ⟨d, ((sem'' v).mp d).2⟩, fun d => d.1⟩

    theorem node_cmp {r : List Nat} {S : List (Term × Term)} {g x : Term}
        (h : Term.compare (.tuple #[.reference r, .map S, g]) x = .eq) : IsNode x := by
      cases x <;> rw [compare_eq_step] at h <;> simp [Compare.compareStep] at h
      rename_i ys
      obtain ⟨l⟩ := ys
      match l, h with
      | [a, b, c], h =>
        simp only [List.compareLex_cons_cons, Ordering.then_eq_eq, List.size_toArray, List.length_cons,
          List.length_nil] at h
        obtain ⟨-, ha, hb, -⟩ := h
        cases a <;> rw [compare_eq_step] at ha <;> simp [Compare.compareStep] at ha
        obtain ⟨Y, rfl⟩ := map_cmp_shape hb
        exact ⟨_, _, _, rfl⟩
      | [], h => simp at h
      | [_], h => simp at h
      | [_, _], h => simp at h
      | _ :: _ :: _ :: _ :: _, h => simp at h

    theorem expN_exact {e e' : Term} (he : IsT nd e) (he' : IsT nd e') (k : Int) :
        exactCompare (expN e k) (expN e' k) = .eq := by
      have ee := isT_exact he he'
      apply map_exactCompare_eq_of_lookup
      intro q
      simp only [List.find?_cons, List.find?_nil]
      by_cases t : exactCompare q (.atom "tuple") = .eq
      · simp [t, litN, Term.list, exactCompare_tuple, List.compareLex_cons_cons, exactCompare_cons, ee,
          List.compareLex_nil_nil]
      by_cases a : exactCompare q (.atom "atom") = .eq
      · simp [t, a]
      · simp [t, a]

    theorem an_resp (ef : EF nd E V den tl K) (h : NodeOk nd E) {e e' : Term} {v : V} (he : DEN nd E e)
        (he' : DEN nd E e') (c : Term.compare e e' = .eq) (d : denN nd den e' v) : denN nd den e v := by
      rcases he with he | he <;> rcases he' with he' | he'
      · rw [denN_of (h.notN he')] at d
        rw [denN_of (h.notN he)]
        exact ef.resp he he' c d
      · obtain ⟨S, rfl, -⟩ := he'.node
        exact absurd (ef.node he (node_cmp (Std.OrientedCmp.eq_symm c))) (h.notN he)
      · obtain ⟨S, rfl, -⟩ := he.node
        exact absurd (ef.node he' (node_cmp c)) (h.notN he')
      · rw [denN_node he'] at d
        rw [denN_node he]
        exact ef.resp (h.exp he) (h.exp he') (compare_eq_of_exactCompare_eq _ _ (expN_exact he he' _)) d

    /-- Element types with the node: operations on the node compute on its expansion. -/
    theorem addNode (ef : EF nd E V den tl K) (h : NodeOk nd E) :
        EF nd (DEN nd E) V (denN nd den) tl (K + 1) where
      pos := by omega
      term := Or.inl ef.term
      none := Or.inl ef.none
      den_term := fun v => (denN_of isT_term).mpr (ef.den_term v)
      static := fun {a} ha => by
        rcases ha with ha | ha
        · exact ef.static ha
        · obtain ⟨S, rfl, -⟩ := ha.node; exact Or.inr (Or.inr ⟨_, _, _, rfl⟩)
      node := fun {a} ha hn => by
        rcases ha with ha | ha
        · exact ef.node ha hn
        · exact ha
      low := fun {a} ha z => by
        rcases ha with ha | ha
        · exact ef.low ha z
        · rw [lh_isT ha] at z; cases z
      cinter := fun ha hb ca cb hm run => an_cinter ef h ha hb ca cb hm run
      cdiff := fun ha hb ca cb hm run => an_cdiff ef h ha hb ca cb hm run
      cempty := fun ha ca hS hm run => an_cempty ef h ha ca hS hm run
      inhabited := ef.inhabited
      resp := fun he he' c d => an_resp ef h he he' c d
      union := fun ha hb => an_union ef h ha hb
      inter := fun ha hb => an_inter ef h ha hb
      diff := fun ha hb => an_diff ef h ha hb
      opt_union := by intro a b S m ha hb hm; exact an_opt_union ef h S ha hb hm
      opt_inter := by intro a b S m ha hb hm; exact an_opt_inter ef h S ha hb hm
      opt_diff := by intro a b S m ha hb hm; exact an_opt_diff ef h S ha hb hm
      empty := fun S ha => an_empty ef h S ha
      sub := fun ha hb => an_sub ef h ha hb
      disj := fun ha hb => an_disj ef h ha hb
      fuse := by intro a b n m ha hb ne hm; exact an_fuse ef h n ha hb ne hm
      tail := fun he => an_tail ef h he
      tl_witness := ef.tl_witness

    end


    /-! The bottom level: types over pure tuple fields, top list and map fields, and the node. -/

    theorem pure_of_descr {nd : Term} {X : List (Term × Term)}
        (sX : DescrC FunTop (OField (PureLit nd)) (FieldOk "list") (FieldOk "map") X) : PureMap nd X := by
      refine ⟨fun q h => ?_, fun name w hw => ?_⟩
      · obtain ⟨name, m, rfl⟩ := sX.keys q h
        rcases names_mem m with rfl | rfl | rfl | rfl | rfl | rfl <;> simp
      · rcases sX.fields name w hw with ⟨rfl, f⟩ | ⟨rfl, f⟩ | ⟨rfl, f⟩ | ⟨rfl, f⟩ | ⟨rfl, f⟩ | ⟨rfl, f⟩
        · obtain ⟨b, rfl, h₁, h₂⟩ := f
          exact Or.inl (Or.inl ⟨rfl, b, rfl, h₁, h₂⟩)
        · exact Or.inl (Or.inr (Or.inl ⟨rfl, f.1, f.2⟩))
        · exact Or.inl (Or.inr (Or.inr ⟨by decide, by decide, by rw [show w = funTopT from f]; rfl⟩))
        · exact Or.inl f
        · exact Or.inr ⟨rfl, f⟩
        · exact Or.inl f

    /-- The step to the bottom level. -/
    theorem step0 (nd : Term) : StepOk nd (fun _ => Pure nd) 8 (OField (PureLit nd)) (FieldOk "list") (FieldOk "map")
        Resp Resp Resp where
      ks := kinds0 nd (by omega)
      nest := fun {a N} ha _ => by
        rcases ha with rfl | ⟨X, rfl, sX⟩
        · exact Or.inl rfl
        · exact Or.inr (Or.inr ⟨X, rfl, pure_of_descr sX⟩)
      ops := fun _ => ⟨(pureOk nd).mono (by omega), (pureDiff nd).mono (by omega), (pureFun nd).mono (by omega)⟩
      tz := fun {x} fx z => by
        rcases fx with ⟨k, rfl⟩ | wx
        · exact ⟨k, rfl⟩
        · have := pure_one (Or.inr wx) (fun k h => by subst h; exact absurd (Bdd.leaf_iff.mp wx) (pureLit_not _ · ⟨_, rfl⟩))
          omega
      lz := fun {x} fx _ => by
        have := topF_of (Or.inl rfl) fx
        simp [topValue] at this
        exact this.symm
      mz := fun {x} fx _ => by
        have := topF_of (Or.inr rfl) fx
        simp [topValue] at this
        exact ⟨_, this.symm⟩
      treal := fun c {x} _ _ => ⟨fun _ => c, resp_const c, rfl⟩

    /-- Maps of a single tuple field are exactly equal when their fields are. -/
    theorem single_exact {A B : List (Term × Term)} {x y : Term}
        (tA : mapLookup A (.atom "tuple") = some x) (tB : mapLookup B (.atom "tuple") = some y)
        (sA : Erlang.erlang.«map_size/1» (.map A) = .ok (.integer 1))
        (sB : Erlang.erlang.«map_size/1» (.map B) = .ok (.integer 1)) (e : exactCompare x y = .eq) :
        exactCompare (.map A) (.map B) = .eq := by
      apply map_exactCompare_eq_of_lookup
      intro q
      change Option.Rel _ (mapLookup A q) (mapLookup B q)
      by_cases hq : exactCompare q (.atom "tuple") = .eq
      · rw [mapLookup_congr hq, mapLookup_congr hq, tA, tB]
        exact Option.Rel.some e
      · have nA : mapLookup A q = none := by
          cases h : mapLookup A q with
          | none => rfl
          | some x => exact absurd (size_one_keys sA h tA) hq
        have nB : mapLookup B q = none := by
          cases h : mapLookup B q with
          | none => rfl
          | some x => exact absurd (size_one_keys sB h tB) hq
        rw [nA, nB]; exact Option.Rel.none

    /-- Maps of a single top tuple field hold exactly the tuples. -/
    theorem den_single_top {A : List (Term × Term)} {k : Term}
        (tA : mapLookup A (.atom "tuple") = some (.tuple #[k, .atom "open", .nil]))
        (sA : Erlang.erlang.«map_size/1» (.map A) = .ok (.integer 1)) (v : PtG Resp Resp Resp) :
        denD (.map A) v ↔ v.1.1 = "tuple" := by
      obtain ⟨⟨name, p⟩, -, -⟩ := v
      rw [denD_map]
      by_cases hn : name = "tuple"
      · subst hn; simp [tA, dn_tuple, denO_top]
      · simp [single_other sA tA hn, dn_none, hn]

    /-- Leaves of pure tuple fields: the top leaf or the expansion literal. -/
    theorem pure3 {nd k tag e : Term} (h : OField (PureLit nd) (.tuple ⟨[k, tag, e]⟩)) :
        (tag = .atom "open" ∧ e = .nil) ∨
          ∃ e₀, IsT nd e₀ ∧ k = .integer (keyOf nd) ∧ tag = .atom "closed" ∧ e = Term.list [.atom "term", e₀] := by
      rcases pure_cases h with ⟨k', ex⟩ | ex | ex | ⟨e₀, h₀, ex⟩ | ⟨j, e₀, c, u, d, h₀, ex⟩
      · simp at ex; exact Or.inl ⟨ex.2.1, ex.2.2⟩
      · cases ex
      · cases ex
      · simp [litN] at ex; exact Or.inr ⟨e₀, h₀, ex.1, ex.2.1, ex.2.2⟩
      · simp at ex

    /-- Fusing types of the bottom level. -/
    theorem fuse0 (nd : Term) : FuseOk 8 (OField (PureLit nd)) (FieldOk "list") (FieldOk "map") Resp Resp Resp := by
      intro a b n m ha hb ne hm
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, fuse_term_l _ _ _, Or.inl rfl⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, fuse_term_r _ _ _, Or.inl rfl⟩
      obtain ⟨u, hu, urun, usem, -⟩ := de_union (step0 nd) (Or.inr ⟨A, rfl, sA⟩) (Or.inr ⟨B, rfl, sB⟩)
      have run := urun m hm
      obtain ⟨c₁, r₁⟩ := aob_bool (.map A)
      obtain ⟨c₂, r₂⟩ := aob_bool (.map B)
      have second : ∃ r, (do
          let _19 ← Lynx.Except.andAlso (Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map A))
            (Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map B)) Bool.true
          Lynx.Except.guard (Except.ok (_19.isMember [Term.atom "false", Term.atom "nil"]))
            (fun _ => pure (Term.atom "nil")) fun _ => Elixir.Module.Types.Descr.«bare_union/2» (D m) (.map A) (.map B)) = .ok r ∧
          (r = .atom "nil" ∨ (DEG (OField (PureLit nd)) (FieldOk "list") (FieldOk "map") r ∧
            ∀ v : PtG Resp Resp Resp, denD r v ↔ denD (.map A) v ∨ denD (.map B) v)) := by
        rw [r₁, r₂]
        cases c₁ <;> cases c₂ <;>
          simp [Lynx.Except.andAlso, boolAtom, Lynx.Except.guard, isMember, run, hu, usem]
      rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_element/3».eq_def]
      simp only [getMapKeys_single]
      split
      · rename_i k₀ tag e₁ hA
        have hxA : mapLookup A (.atom "tuple") = some (.tuple ⟨[k₀, tag, e₁]⟩) := by
          cases h : mapLookup A (.atom "tuple") <;> simp_all
        split
        · rename_i k₁ tag₂ e₂ hB
          have hxB : mapLookup B (.atom "tuple") = some (.tuple ⟨[k₁, tag₂, e₂]⟩) := by
            cases h : mapLookup B (.atom "tuple") <;> simp_all
          obtain ⟨sa, hsa⟩ : ∃ sa : Int, Erlang.erlang.«map_size/1» (.map A) = .ok (.integer sa) :=
            ⟨_, by simp [Erlang.erlang.«map_size/1»]; rfl⟩
          obtain ⟨sb, hsb⟩ : ∃ sb : Int, Erlang.erlang.«map_size/1» (.map B) = .ok (.integer sb) :=
            ⟨_, by simp [Erlang.erlang.«map_size/1»]; rfl⟩
          have pA := fieldC_tuple (sA.fields _ _ hxA)
          have pB := fieldC_tuple (sB.fields _ _ hxB)
          have fallback : ∀ (x : Except Exception Term),
              (∀ c₁ c₂ : Bool, Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map A) = .ok (boolAtom c₁) →
                Elixir.Module.Types.Descr.«atom_or_bitmap_only?/1» (.map B) = .ok (boolAtom c₂) →
                x = .ok (if c₁ && c₂ then u else .atom "nil")) →
              ∃ r, x = .ok r ∧ (r = .atom "nil" ∨ (DEG (OField (PureLit nd)) (FieldOk "list") (FieldOk "map") r ∧
                ∀ v : PtG Resp Resp Resp, denD r v ↔ denD (.map A) v ∨ denD (.map B) v)) := by
            intro x hx
            refine ⟨_, hx c₁ c₂ r₁ r₂, ?_⟩
            cases c₁ <;> cases c₂ <;> simp [hu, usem]
          by_cases G : exactCompare tag₂ tag = .eq ∧ sa = 1 ∧ sb = 1 ∧ 0 < n
          · obtain ⟨et, rfl, rfl, pos⟩ := G
            have sub : Erlang.erlang.«-/2» (.integer n) (.integer 1) = .ok (.integer (n - 1)) := by
              rw [Erlang.erlang.«-/2_integers»]
            have pc : compare n 0 = Ordering.gt := by exact Int.compare_eq_gt.mpr pos
            rcases pure3 pA with ⟨rfl, rfl⟩ | ⟨eA₀, hA₀, rfl, rfl, rfl⟩ <;>
              rcases pure3 pB with ⟨rfl, rfl⟩ | ⟨eB₀, hB₀, rfl, rfl, rfl⟩ <;> simp at et
            · obtain ⟨kf, hk, -⟩ := leaf_new_key "open" (Or.inl rfl) []
              simp only [Term.list] at hk
              refine ⟨_, ?_, Or.inr ⟨Or.inr ⟨[(.atom "tuple", .tuple #[.integer kf, .atom "open", .nil])], rfl,
                ⟨fun q h => ?_, fun name w h => ?_⟩⟩, fun v => ?_⟩⟩
              · simp [hsa, hsb, Erlang.erlang.«=:=/2», Lynx.Except.guard, Lynx.Except.tryWith, Lynx.Except.andAlso,
                  Erlang.erlang.«and/2», Erlang.erlang.«==/2», Erlang.erlang.«>/2», sub, pc, isMember, hk,
                  Erlang.erlang.«length/1»]
                rw [Elixir.Module.Types.Descr.«opt_tuple_fuse_elements/4».eq_def]
                simp [Erlang.lists.«reverse/1», isMember, hk]
              · simp only [mapLookup, List.find?_cons, List.find?_nil] at h
                by_cases e : exactCompare q (.atom "tuple") = .eq
                · exact ⟨"tuple", by simp [names], (exactCompare_eq_atom _ _).mp e⟩
                · simp [e] at h
              · simp only [mapLookup, List.find?_cons, List.find?_nil, exactCompare_eq_atom, Term.atom.injEq] at h
                by_cases e : name = "tuple"
                · subst e; simp at h; subst h
                  exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, Or.inl ⟨kf, rfl⟩⟩))))
                · simp [e] at h
              · have one : mapLookup [(.atom "tuple", .tuple #[.integer kf, .atom "open", .nil])] (.atom "tuple") =
                    some (.tuple #[.integer kf, .atom "open", .nil]) := by simp [mapLookup]
                rw [den_single_top one (by simp [Erlang.erlang.«map_size/1»]; rfl), den_single_top hxA hsa,
                  den_single_top hxB hsb, or_self]
            · exfalso
              apply ne
              refine single_exact hxA hxB hsa hsb ?_
              have := pureLit_exact ⟨eB₀, hB₀, rfl⟩ ⟨eA₀, hA₀, rfl⟩
              simpa [litN, Term.list] using this
          · refine fallback _ fun c₁ c₂ r₁ r₂ => ?_
            have pc : compare n 0 = Ordering.gt ↔ 0 < n := Int.compare_eq_gt
            by_cases e₁ : exactCompare tag₂ tag = .eq <;> by_cases e₂ : sa = 1 <;> by_cases e₃ : sb = 1 <;> by_cases e₄ : 0 < n <;>
              simp only [e₁, e₂, e₃, e₄, and_self, not_true_eq_false] at G <;>
              cases c₁ <;> cases c₂ <;>
              simp [hsa, hsb, e₁, e₂, e₃, e₄, pc, r₁, r₂, run, Erlang.erlang.«=:=/2», Lynx.Except.guard,
                Lynx.Except.tryWith, Lynx.Except.andAlso, Erlang.erlang.«and/2», Erlang.erlang.«==/2»,
                Erlang.erlang.«>/2», isMember, boolAtom]
        · exact second
      · exact second

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-- Element types at a nesting level, with their values. -/
    structure Level : Type 1 where
      nd : Term
      E : Term → Prop
      V : Type
      den : Term → V → Prop
      tl : V → Prop
      K : Nat
      ef : EF nd E V den tl K
      none : E (.map [])
      hasT : ∀ {e}, IsT nd e → E e

    theorem keyOf_neg (t : Term) : keyOf t < 0 := by
      obtain ⟨h, run, lt⟩ := Erlang.erlang.phash2_range (Term.list [.atom "term", t])
      simp only [keyOf, run]
      omega

    theorem expN_descr {nd : Term} {TF LF MF : Term → Prop} {e : Term} (tf : TF (litN e (keyOf nd))) :
        DEG TF LF MF (expN e (keyOf nd)) := by
      refine Or.inr ⟨_, rfl, fun q h => ?_, fun name w hw => ?_⟩
      · simp only [mapLookup, List.find?_cons, List.find?_nil] at h
        by_cases t : exactCompare q (.atom "tuple") = .eq
        · exact ⟨"tuple", by simp [names], (exactCompare_eq_atom _ _).mp t⟩
        · by_cases a : exactCompare q (.atom "atom") = .eq
          · exact ⟨"atom", by simp [names], (exactCompare_eq_atom _ _).mp a⟩
          · simp [t, a] at h
      · simp only [mapLookup, List.find?_cons, List.find?_nil, exactCompare_eq_atom, Term.atom.injEq] at hw
        by_cases t : name = "tuple"
        · subst t; simp at hw; subst hw; exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, tf⟩))))
        · by_cases a : name = "atom"
          · subst a; simp at hw; subst hw
            exact Or.inr (Or.inl ⟨rfl, ⟨Bool.true, [(.atom "nil", .nil)], rfl, by simp [Erlang.sets.elements?]⟩,
              .atom "nil", by simp [amemV, mapLookup]⟩)
          · simp [t, a] at hw

    theorem DEG.notT {nd : Term} {TF LF MF : Term → Prop} {a : Term} (ha : DEG TF LF MF a) : ¬IsT nd a := by
      rcases ha with rfl | ⟨X, rfl, -⟩
      · exact isT_term
      · exact isT_map

    theorem nodeOk0 (nd : Term) : NodeOk nd (DEG (OField (PureLit nd)) (FieldOk "list") (FieldOk "map")) :=
      ⟨fun he => expN_descr (Or.inr (Bdd.leaf_iff.mpr ⟨_, he, rfl⟩)), DEG.notT⟩

    theorem nodeOk_DE {nd : Term} {E : Term → Prop} (hterm : E (.atom "term")) (hasT : ∀ {e}, IsT nd e → E e) :
        NodeOk nd (DE E) := by
      refine ⟨fun {e} he => expN_descr (Or.inr (Bdd.leaf_iff.mpr ⟨⟨⟨keyOf nd, "closed", [.atom "term", e], rfl,
        Or.inr rfl, fun x mx => ?_⟩, fun ⟨k, h⟩ => by simp [litN, Term.list] at h⟩, fun k tag l h => ?_⟩)), DEG.notT⟩
      · simp at mx; rcases mx with h | h <;> subst h; exact hterm; exact hasT he
      · obtain ⟨e₁, e₂, -⟩ := tuple3_inj h
        simp only [Term.integer.injEq, Term.atom.injEq] at e₁ e₂
        subst e₁ e₂
        exact ⟨fun _ => keyOf_neg nd, fun h => by simp at h⟩

    /-- The element types of each level, with the node `t`. -/
    def level (t : Term) : Nat → Level
      | 0 => ⟨t, DEN t (DEG (OField (PureLit t)) (FieldOk "list") (FieldOk "map")), PtG Resp Resp Resp, denN t denD, tlD,
          23, addNode (ef_gen (step0 t) (fuse0 t)) (nodeOk0 t), Or.inl (Or.inr ⟨[], rfl, descrC_nil⟩), fun h => Or.inr h⟩
      | n + 1 =>
        let L := level t n
        ⟨L.nd, DEN L.nd (DE L.E), PtD L.E L.den L.tl, denN L.nd denD, tlD, L.K + 15, addNode (ef_step L.ef L.none)
          (nodeOk_DE L.ef.term L.hasT), Or.inl de_none, fun h => Or.inr h⟩

    theorem level_nd (t : Term) : ∀ n, (level t n).nd = t
      | 0 => rfl
      | n + 1 => level_nd t n

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Function fields of top-level types: any function types, whose emptiness is complete. -/

    theorem funFC : FunC 2 FunF (fun S => S = []) False where
      funF := id
      union := fun {x y} hx hy m w hm run => by
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        obtain ⟨w', run', fw, -⟩ := fun_union_spec n hx hy
        rw [run'] at run; cases run
        exact ⟨fw, False.elim⟩
      inter := fun {x y} hx hy m w hm run kw => by
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
        obtain ⟨w', run', k, -⟩ := fun_inter_spec n hx hy
        rw [run'] at run; cases run
        exact ⟨(k kw).1, False.elim⟩
      diff := fun {x y} hx hy m w hm run kw => by
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
        obtain ⟨w', run', k, -⟩ := fun_diff_spec n hx hy
        rw [run'] at run; cases run
        exact ⟨(k kw).1, False.elim⟩
      empty := fun {x} S {m} hx hS hm => by
        subst hS
        refine ⟨fun h => ?_, False.elim⟩
        obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
        have := (fun_sub_spec n hx none (fun y h => by cases h) fun q ρ resp hq => by
          have := h (0, q, ρ) resp
          rw [dn_fun] at this
          rw [this] at hq; cases hq).2 rfl
        simpa [Elixir.Module.Types.Descr.«empty_key?/3»] using this

    section
    variable {K : Nat} {Fn TF LF MF : Term → Prop} {TV LV MV : (Term → Bool) → Prop} {FS : List (Term × Term) → Prop}
      {H : Prop}

    theorem FunC.mono (fc : FunC K Fn FS H) {K' : Nat} (le : K ≤ K') : FunC K' Fn FS H where
      funF := fc.funF
      union := fun hx hy m w hm run => fc.union hx hy m w (by omega) run
      inter := fun hx hy m w hm run kw => fc.inter hx hy m w (by omega) run kw
      diff := fun hx hy m w hm run kw => fc.diff hx hy m w (by omega) run kw
      empty := by intro x S m hx hS hm; exact fc.empty S hx hS (by omega)

    /-- Types with no points are checked empty. -/
    theorem descr_empty_none (ks : Kinds K TF LF MF TV LV MV) (fc : FunC K Fn FS H) (hS : FS []) {m : Nat} (hm : K ≤ m)
        {X : List (Term × Term)} (sX : DescrC Fn TF LF MF X)
        (none : ∀ name p, PtOkC TV LV MV name p → dn name (mapLookup X (.atom name)) p = Bool.false) :
        Elixir.Module.Types.Descr.«empty_seen?/2» (D m) (.map X) (.map []) = .ok (.atom "true") := by
      by_cases ne : X = []
      · subst ne
        simpa [boolAtom] using empty_none_seen (D m) (.map [])
      have key : ∀ name x, mapLookup X (.atom name) = some x →
          Elixir.Module.Types.Descr.«empty_key?/3» (D m) (.atom name) x (.map []) = .ok (.atom "true") :=
        fun name x h => fieldC_empty_none ks fc hm (sX.fields name x h) (fun _ => hS) fun p ok => by
          have := none name p ok; rwa [h] at this
      have run := descr_empty_run (D m) (S := .map []) (bt := Bool.true) (bm := Bool.true) (bl := Bool.true)
        (bf := Bool.true) sX.static ne
        (fun x h => by simpa [Elixir.Module.Types.Descr.«empty_key?/3», boolAtom] using key "tuple" x h)
        (fun x h => by simpa [Elixir.Module.Types.Descr.«empty_key?/3», boolAtom] using key "map" x h)
        (fun x h => by simpa [Elixir.Module.Types.Descr.«empty_key?/3», boolAtom] using key "list" x h)
        (fun x h => by simpa [Elixir.Module.Types.Descr.«empty_key?/3», boolAtom] using key "fun" x h)
      have noA : (mapLookup X (.atom "atom")).isSome = Bool.false := by
        cases h : mapLookup X (.atom "atom") with
        | none => rfl
        | some x =>
          obtain ⟨p, ok, hp⟩ := atom_full sX h
          have := none "atom" p ok; rw [h, hp] at this; cases this
      have noB : (mapLookup X (.atom "bitmap")).isSome = Bool.false := by
        cases h : mapLookup X (.atom "bitmap") with
        | none => rfl
        | some x =>
          obtain ⟨p, ok, hp⟩ := bitmap_full sX h
          have := none "bitmap" p ok; rw [h, hp] at this; cases this
      rw [noA, noB] at run
      simpa [boolAtom] using run

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Top-level types over the element types of a level: the top type or types whose function fields are any function
    types. Their plain and optimized operations hold the expected points, and their emptiness and subtyping checks are
    complete. -/

    /-- Top-level types over the element types of a level. -/
    def TC (L : Level) (a : Term) : Prop :=
      a = .atom "term" ∨ ∃ X, a = .map X ∧ DescrC FunF (TField L.E) (LF L.E) (MField L.E) X

    abbrev TP (L : Level) : Type := PtD L.E L.den L.tl

    abbrev tks (L : Level) := kinds L.ef

    theorem tfc (L : Level) : FunC (L.K + 2) FunF (fun S => S = []) False := funFC.mono (by omega)

    theorem DescrC.funF {TF LF MF : Term → Prop} {X : List (Term × Term)} (s : DescrC FunTop TF LF MF X) :
        DescrC FunF TF LF MF X := by
      refine ⟨s.keys, fun name x h => ?_⟩
      rcases s.fields name x h with h | h | ⟨e, f⟩ | h | h | h
      · exact Or.inl h
      · exact Or.inr (Or.inl h)
      · subst f; exact Or.inr (Or.inr (Or.inl ⟨e, funF_top⟩))
      · exact Or.inr (Or.inr (Or.inr (Or.inl h)))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl h))))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr h))))

    theorem lookup_out' {Fn TF LF MF : Term → Prop} {X : List (Term × Term)} (sX : DescrC Fn TF LF MF X) {name : String}
        (h : name ∉ names) : mapLookup X (.atom name) = none := by
      cases hx : mapLookup X (.atom name) with
      | none => rfl
      | some x =>
        obtain ⟨name', m, e⟩ := sX.keys _ (by rw [hx]; rfl)
        simp only [Term.atom.injEq] at e
        subst e; exact absurd m h

    section
    variable {L : Level}

    theorem termT (L : Level) : ∃ T, Elixir.Module.Types.Descr.«unfolded_term/0» = .ok (.map T) ∧
        DescrC FunF (TField L.E) (LF L.E) (MField L.E) T ∧ T ≠ [] ∧
        ∀ v : TP L, denD (.map T) v := by
      obtain ⟨T, term, sT, ne, -, all⟩ := termC (tks L)
      exact ⟨T, term, sT.funF, ne, fun v => (denD_map v).mpr (all _ v.2.1 _ v.2.2)⟩

    theorem tc_nil : TC L (.map []) := Or.inr ⟨[], rfl, descrC_nil.funF⟩

    theorem denD_nil (v : TP L) : ¬denD (.map []) v := by simp [denD_map, mapLookup, dn_none]

    theorem tc_union {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 4 ≤ m) :
        ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∨ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, Or.inl rfl, union_term_l _ _, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inl rfl, union_term_r _ _, fun v => by simp [denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
      obtain ⟨U, run, sU, sem, -⟩ := descr_union (tks L) (tfc L) (m := n) (by omega) sA sB
      exact ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.or_eq_true]⟩

    theorem tc_inter {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 4 ≤ m) :
        ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∧ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨b, hb, inter_term_left _ _, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inr ⟨A, rfl, sA⟩, inter_term_right _ _, fun v => by simp [denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
      obtain ⟨U, run, sU, sem, -⟩ := descr_inter (tks L) (tfc L) (m := n) (by omega) sA sB
      exact ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.and_eq_true]⟩

    theorem diff_none_right' (d : Dispatcher) {a : Term} (ha : TC L a) :
        Elixir.Module.Types.Descr.«bare_difference/2» d a (.map []) = .ok a := by
      unfold Elixir.Module.Types.Descr.«bare_difference/2»
      rcases ha with rfl | ⟨A, rfl, -⟩ <;> simp [Erlang.erlang.«==/2»]

    theorem tc_diff {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 6 ≤ m) :
        ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∧ ¬denD b v := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, tc_nil, diff_term_right _ _, fun v => by simp [denD_nil, denD_term]⟩
      by_cases nB : B = []
      · subst nB
        exact ⟨a, ha, diff_none_right' _ ha, fun v => by simp [denD_nil]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · obtain ⟨T, term, sT, -, all⟩ := termT L
        obtain ⟨U, run, sU, sem, -⟩ := descr_diff (tks L) (tfc L) (m := n) (by omega) sT sB
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, (diff_term_left _ term sT.static sB.static nB).trans run, fun v => ?_⟩
        have := (denD_map v).mp (all v)
        simp only [denD_map, sem _ _ v.2.2, this, denD_term, true_and, Bool.true_and]
        cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp
      · obtain ⟨U, run, sU, sem, -⟩ := descr_diff (tks L) (tfc L) (m := n) (by omega) sA sB
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => ?_⟩
        simp only [denD_map, sem _ _ v.2.2]
        cases dn v.1.1 (mapLookup A (.atom v.1.1)) v.1.2 <;> cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp

    theorem tc_opt_union {a b : Term} (ha : TC L a) (hb : TC L b) (S : List (Term × Term)) {m : Nat}
        (hm : L.K + 4 ≤ m) : ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«opt_union/3» (D m) a b (.map S) = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∨ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, Or.inl rfl, opt_union_term_left _ _ _, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inl rfl, opt_union_term_r _ _ _, fun v => by simp [denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
      obtain ⟨U, run, sU, sem⟩ := descr_opt_union (tks L) (tfc L) (m := n) (by omega) sA sB S
      exact ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.or_eq_true]⟩

    theorem tc_opt_inter {a b : Term} (ha : TC L a) (hb : TC L b) (S : List (Term × Term)) {m : Nat}
        (hm : L.K + 4 ≤ m) : ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«opt_intersection/3» (D m) a b (.map S) = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∧ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨b, hb, opt_inter_term_l _ _ _, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inr ⟨A, rfl, sA⟩, opt_inter_term_r _ _ _, fun v => by simp [denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 1 := ⟨m - 1, by omega⟩
      obtain ⟨U, run, sU, sem⟩ := descr_opt_inter (tks L) (tfc L) (m := n) (by omega) sA sB S
      exact ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.and_eq_true]⟩

    theorem tc_opt_diff {a b : Term} (ha : TC L a) (hb : TC L b) (S : List (Term × Term)) {m : Nat}
        (hm : L.K + 6 ≤ m) : ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«opt_difference/3» (D m) a b (.map S) = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∧ ¬denD b v := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, tc_nil, difference_term_term _ _ _, fun v => by simp [denD_nil, denD_term]⟩
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · by_cases nB : B = []
        · subst nB
          exact ⟨_, Or.inl rfl, difference_term_none _ _, fun v => by simp [denD_nil, denD_term]⟩
        obtain ⟨T, term, sT, -, all⟩ := termT L
        obtain ⟨U, run, sU, sem⟩ := descr_opt_diff (tks L) (tfc L) (m := n) (by omega) sT sB S
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, (opt_diff_term_left _ _ term sT.static sB.static nB).trans run, fun v => ?_⟩
        have := (denD_map v).mp (all v)
        simp only [denD_map, sem _ _ v.2.2, this, denD_term, true_and, Bool.true_and]
        cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp
      · obtain ⟨U, run, sU, sem⟩ := descr_opt_diff (tks L) (tfc L) (m := n) (by omega) sA sB S
        refine ⟨_, Or.inr ⟨U, rfl, sU⟩, run, fun v => ?_⟩
        simp only [denD_map, sem _ _ v.2.2]
        cases dn v.1.1 (mapLookup A (.atom v.1.1)) v.1.2 <;> cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp

    /-- Types without points are checked empty. -/
    theorem tc_empty {a : Term} (ha : TC L a) {m : Nat} (hm : L.K + 2 ≤ m) (none : ∀ v : TP L, ¬denD a v) :
        Elixir.Module.Types.Descr.«empty?/1» (D m) a = .ok (.atom "true") := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · exact absurd (denD_term ptWit) (none ptWit)
      rw [empty_map_seen]
      refine descr_empty_none (tks L) (tfc L) rfl hm sX fun name p ok => ?_
      by_cases mem : name ∈ names
      · have := none ⟨(name, p), mem, ok⟩
        simpa [denD] using this
      · rw [lookup_out' sX mem, dn_none]

    /-- Subtyping of top-level types is complete. -/
    theorem tc_sub {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 4 ≤ m)
        (incl : ∀ v : TP L, denD a v → denD b v) :
        Elixir.Module.Types.Descr.«subtype?/2» (D m) a b = .ok (.atom "true") := by
      obtain ⟨T, term, sT, -, all⟩ := termT L
      have left : ∃ A, DescrC FunF (TField L.E) (LF L.E) (MField L.E) A ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) a b = Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map A) b ∧
          ∀ v : TP L, denD a v ↔ denD (.map A) v := by
        rcases ha with rfl | ⟨A, rfl, sA⟩
        · exact ⟨T, sT, subtype_term_l term _ _, fun v => ⟨fun _ => all v, fun _ => denD_term v⟩⟩
        · exact ⟨A, sA, rfl, fun v => Iff.rfl⟩
      obtain ⟨A, sA, eA, dA⟩ := left
      have right : ∃ B, DescrC FunF (TField L.E) (LF L.E) (MField L.E) B ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map A) b =
            Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map A) (.map B) ∧
          ∀ v : TP L, denD b v ↔ denD (.map B) v := by
        rcases hb with rfl | ⟨B, rfl, sB⟩
        · exact ⟨T, sT, subtype_term_r term _ _, fun v => ⟨fun _ => all v, fun _ => denD_term v⟩⟩
        · exact ⟨B, sB, rfl, fun v => Iff.rfl⟩
      obtain ⟨B, sB, eB, dB⟩ := right
      rw [eA, eB]
      refine descr_sub_complete (tks L) (tfc L) rfl (by omega) sA sB fun name p ok h => ?_
      by_cases mem : name ∈ names
      · have := (dB ⟨(name, p), mem, ok⟩).mp (incl _ ((dA _).mpr ((denD_map _).mpr h)))
        exact (denD_map _).mp this
      · rw [lookup_out' sA mem, dn_none] at h; cases h

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Nested types of the specification whose literals are keyed are element types of their level. -/

    /-- All literals of a BDD satisfy `Q`. -/
    def AllLits (Q : Term → Prop) : Term → Prop
      | .tuple ⟨[_, lit, c, u, d]⟩ => Q lit ∧ AllLits Q c ∧ AllLits Q u ∧ AllLits Q d
      | .tuple ⟨[k, x, y]⟩ => Q (.tuple #[k, x, y])
      | _ => True

    theorem bdd_allLits {ok Q : Term → Prop} {w : Term} (wb : Bdd ok w) (all : AllLits Q w) :
        Bdd (fun t => ok t ∧ Q t) w := by
      revert all
      refine Bdd.induction (P := fun ok w => AllLits Q w → Bdd (fun t => ok t ∧ Q t) w) ?_ ?_ ?_ ?_ ok w wb
      · intro _ _; exact Bdd.top
      · intro _ _; exact Bdd.bot
      · intro ok k x y okl all
        exact Bdd.leaf_iff.mpr ⟨okl, by simpa [AllLits] using all⟩
      · intro ok h lit c u d isLeaf okl _ _ _ ic iu id all
        simp only [AllLits] at all
        obtain ⟨ql, ac, au, ad⟩ := all
        have mono : ∀ {x}, Bdd (fun t => Above ok lit t ∧ Q t) x → Bdd (Above (fun t => ok t ∧ Q t) lit) x :=
          fun hx => hx.mono fun t ⟨⟨o, l⟩, q⟩ => ⟨⟨o, q⟩, l⟩
        exact Bdd.node_iff.mpr ⟨isLeaf, ⟨okl, ql⟩, mono (ic ac), mono (iu au), mono (id ad)⟩

    /-- Keyed tuple literals whose elements satisfy `P`. -/
    def TQ (P : Term → Prop) (t : Term) : Prop :=
      KeyOk t ∧ ∀ (k : Int) (tag : String) (l : List Term), t = .tuple #[.integer k, .atom tag, Term.list l] → ∀ e ∈ l, P e

    /-- Keyed map literals with atom keys in order whose field types satisfy `P`. -/
    def MQ (P : Term → Prop) (t : Term) : Prop :=
      KeyOk t ∧ ∀ (k : Int) (tag : Term) (l : List (Term × Term)), t = .tuple #[.integer k, tag, fieldsTerm l] →
        l.Pairwise (fun a b => Term.compare a.1 b.1 = .lt) ∧
        (∀ e ∈ l, (∃ s : String, e.1 = .atom s) ∧ ∀ u o, e.2 = .tuple #[u, boolAtom o] → P u) ∧
        ∀ dl, tag = fieldsTerm dl → DomsV P dl

    /-- List literals whose element and tail types satisfy `P`. -/
    def LQ (P : Term → Prop) (t : Term) : Prop := ∀ (k : Int) (a b : Term), t = .tuple #[.integer k, a, b] → P a ∧ P b

    /-- The literal invariants the optimized operations expect of the fields of a type whose literals hold types `P`:
    keyed tuple and map literals, map literals with atom keys in order, and, for element types, the top function type. -/
    structure KeyedF (P : Term → Prop) (el : Bool) (X : List (Term × Term)) : Prop where
      funs : el = Bool.true → ∀ w, mapLookup X (.atom "fun") = some w → w = funTopT
      tuples : ∀ w, mapLookup X (.atom "tuple") = some w → AllLits (TQ P) w
      maps : ∀ w, mapLookup X (.atom "map") = some w → AllLits (MQ P) w
      lists : ∀ w, mapLookup X (.atom "list") = some w → AllLits (LQ P) w

    /-- Keyed element types at each nesting depth. -/
    def Keyed : Nat → Term → Prop
      | 0, _ => True
      | d + 1, e => e = .atom "term" ∨ (∃ a b c, e = .tuple #[a, b, c]) ∨ ∃ X, e = .map X ∧ KeyedF (Keyed d) Bool.true X

    section
    variable {E P E' : Term → Prop}

    theorem tfield_of (conv : ∀ e, E e → P e → E' e) {w : Term} (tf : TupleField E w)
        (keys : AllLits (fun t => KeyOk t ∧ ∀ (k : Int) (tag : String) (l : List Term),
          t = .tuple #[.integer k, .atom tag, Term.list l] → ∀ e ∈ l, P e) w) : TField E' w := by
      rcases tf with top | b
      · exact Or.inl top
      refine Or.inr ((bdd_allLits b keys).mono fun t ⟨⟨⟨k, tag, l, e, g, els⟩, nt⟩, key, pe⟩ => ?_)
      subst e
      exact ⟨⟨⟨k, tag, l, rfl, g, fun x mx => conv x (els x mx) (pe k tag l rfl x mx)⟩, nt⟩, key⟩

    theorem lf_of (conv : ∀ e, E e → P e → E' e) (hterm : E' (.atom "term")) {w : Term} (lf : LField E w)
        (keys : AllLits (fun t => ∀ (k : Int) (a b : Term), t = .tuple #[.integer k, a, b] → P a ∧ P b) w) :
        LF E' w := by
      rcases lf with ⟨k, rfl⟩ | b
      · exact Bdd.leaf_iff.mpr ⟨k, _, _, rfl, hterm, hterm⟩
      refine (bdd_allLits b keys).mono fun t ⟨⟨_, k, a, c, e, ha, hc⟩, pe⟩ => ?_
      subst e
      obtain ⟨pa, pc⟩ := pe k a c rfl
      exact ⟨k, a, c, rfl, conv a ha pa, conv c hc pc⟩

    theorem mfield_of (conv : ∀ e, E e → P e → E' e) {w : Term} (mf : MapField E w) (keys : AllLits (MQ P) w) :
        MField E' w := by
      rcases mf with top | b
      · exact Or.inl top
      refine Or.inr ((bdd_allLits b keys).mono fun t ⟨⟨⟨k, tag, l, e, g, fv⟩, nt⟩, key, pe⟩ => ?_)
      subst e
      obtain ⟨sorted, each, doms⟩ := pe k tag l rfl
      refine ⟨⟨k, tag, l, rfl, ?_, fun x mx => ⟨(each x mx).1, ?_⟩, sorted⟩, nt, key⟩
      · rcases g with rfl | rfl | ⟨dl, rfl, hdl⟩
        · exact Or.inl rfl
        · exact Or.inr (Or.inl rfl)
        · obtain ⟨dk, dp⟩ := doms dl rfl
          exact Or.inr (Or.inr ⟨dl, rfl, fun e me => ⟨(dk e me).1, conv _ (hdl e me) (dk e me).2⟩, dp⟩)
      · obtain ⟨u, o, eu, hu⟩ := fv x mx
        exact ⟨u, o, eu, conv u hu ((each x mx).2 u o eu)⟩

    end

    /-- Flat types are types of the bottom level. -/
    theorem lelem_deg0 {t e : Term} (h : LElem e) :
        DEG (OField (PureLit t)) (FieldOk "list") (FieldOk "map") e := by
      rcases h with rfl | ⟨M, rfl, bM⟩
      · exact Or.inl rfl
      refine Or.inr ⟨M, rfl, fun q hq => ?_, fun name w hw => ?_⟩
      · rcases bM.keys q hq with rfl | rfl | rfl | rfl | rfl | rfl <;> exact ⟨_, by simp [names], rfl⟩
      · rcases bM.keys (.atom name) (by rw [hw]; rfl) with e | e | e | e | e | e <;> simp only [Term.atom.injEq] at e <;>
          subst e
        · exact Or.inl ⟨rfl, bM.bitmap w hw⟩
        · exact Or.inr (Or.inl ⟨rfl, bM.atom w hw |>.1, by
            obtain ⟨q, hq⟩ := (bM.atom w hw).2; exact ⟨q, by simpa [amem, hw] using hq⟩⟩)
        · have := bM.top "fun" w (by decide) (by decide) hw
          simp [topValue] at this
          exact Or.inr (Or.inr (Or.inl ⟨rfl, this.symm⟩))
        · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, Or.inr (Or.inr ⟨by decide, by decide,
            bM.top "list" w (by decide) (by decide) hw⟩)⟩)))
        · have := bM.top "tuple" w (by decide) (by decide) hw
          simp [topValue] at this
          exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, Or.inl ⟨_, this.symm⟩⟩))))
        · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, Or.inr (Or.inr ⟨by decide, by decide,
            bM.top "map" w (by decide) (by decide) hw⟩)⟩))))

    /-- Keyed nested types of the specification are element types of their level. -/
    theorem nest_level (t : Term) : ∀ (d : Nat) (e : Term), Nest t d e → Keyed d e → (level t d).E e
      | 0, _, h, _ => by
        rcases h with h | h
        · exact Or.inl (lelem_deg0 (elem_lelem h))
        · exact Or.inr h
      | d + 1, _, h, k => by
        rcases h with h | h
        rotate_left
        · exact Or.inr (by rw [level_nd]; exact h)
        rcases h with rfl | ⟨X, rfl, v⟩
        · exact Or.inl (Or.inl rfl)
        obtain ⟨X', e, kf⟩ := (k.resolve_left (by simp)).resolve_left (by simp)
        simp only [Term.map.injEq] at e
        subst e
        have conv : ∀ e, Nest t d e → Keyed d e → (level t d).E e := nest_level t d
        refine Or.inl (Or.inr ⟨X, rfl, fun q hq => ?_, fun name w h => ?_⟩)
        · rcases v.keys q hq with rfl | rfl | rfl | rfl | rfl | rfl <;> exact ⟨_, by simp [names], rfl⟩
        · rcases v.keys (.atom name) (by rw [h]; rfl) with e | e | e | e | e | e <;> simp only [Term.atom.injEq] at e <;>
            subst e
          · exact Or.inl ⟨rfl, v.bitmap w h⟩
          · obtain ⟨p, S, rfl, set⟩ := v.atom w h
            exact Or.inr (Or.inl ⟨rfl, ⟨p, S, rfl, set⟩, atom_nonempty p S fun hp => v.atomUnion S (by subst hp; simpa using h)⟩)
          · exact Or.inr (Or.inr (Or.inl ⟨rfl, kf.funs rfl w h⟩))
          · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, lf_of conv (level t d).ef.term (v.lists w h) (kf.lists w h)⟩)))
          · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, tfield_of conv (v.tuples w h) (kf.tuples w h)⟩))))
          · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, mfield_of conv (v.maps w h) (kf.maps w h)⟩))))

    /-- Keyed negatable types are top-level types over the element types of their depth. -/
    theorem negatable_tc (t : Term) (d : Nat) {X : List (Term × Term)} (v : Negatable (Nest t d) X)
        (kf : KeyedF (Keyed d) Bool.false X) : TC (level t d) (.map X) := by
      have conv : ∀ e, Nest t d e → Keyed d e → (level t d).E e := nest_level t d
      refine Or.inr ⟨X, rfl, fun q hq => ?_, fun name w h => ?_⟩
      · rcases v.keys q hq with rfl | rfl | rfl | rfl | rfl | rfl <;> exact ⟨_, by simp [names], rfl⟩
      · rcases v.keys (.atom name) (by rw [h]; rfl) with e | e | e | e | e | e <;> simp only [Term.atom.injEq] at e <;>
          subst e
        · exact Or.inl ⟨rfl, v.bitmap w h⟩
        · obtain ⟨p, S, rfl, set⟩ := v.atom w h
          exact Or.inr (Or.inl ⟨rfl, ⟨p, S, rfl, set⟩, atom_nonempty p S fun hp => v.atomUnion S (by subst hp; simpa using h)⟩)
        · obtain ⟨pos, R, rfl⟩ := v.funs w h
          exact Or.inr (Or.inr (Or.inl ⟨rfl, pos, R, rfl, fun q x hx => v.arities _ h _ R rfl q x hx⟩))
        · exact Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, lf_of conv (level t d).ef.term (v.lists w h) (kf.lists w h)⟩)))
        · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, tfield_of conv (v.tuples w h) (kf.tuples w h)⟩))))
        · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr ⟨rfl, mfield_of conv (v.maps w h) (kf.maps w h)⟩))))

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! The top type is a top-level type at every level, and the laws use the level of their depth. -/

    section
    variable {L : Level} {m : Nat}

    theorem tc_term : TC L (.atom "term") := Or.inl rfl

    end

    theorem level_K (t : Term) : ∀ n, (level t n).K = 23 + 15 * n
      | 0 => rfl
      | n + 1 => by
        show (level t n).K + 15 = _
        rw [level_K t n]
        omega

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! What the specification of the optimized laws checks: keyed literals at every depth. -/

    theorem sizeOf_children5 (h lit c u d : Term) :
        sizeOf lit < sizeOf (Term.tuple ⟨[h, lit, c, u, d]⟩) ∧
        sizeOf c < sizeOf (Term.tuple ⟨[h, lit, c, u, d]⟩) ∧ sizeOf u < sizeOf (Term.tuple ⟨[h, lit, c, u, d]⟩) ∧
          sizeOf d < sizeOf (Term.tuple ⟨[h, lit, c, u, d]⟩) := by
      simp only [Term.tuple.sizeOf_spec, List.size_toArray, Array.mk.sizeOf_spec, List.cons.sizeOf_spec,
        List.nil.sizeOf_spec]
      omega

    theorem int_lt_true {a b : Int} (h : Erlang.erlang.«</2» (.integer a) (.integer b) = .ok Term.true) : a < b := by
      refine Classical.byContradiction fun hk => ?_
      have : Ord.compare a b ≠ .lt := fun e => hk (Int.compare_eq_lt.mp e)
      simp [Erlang.erlang.«</2», this, Term.true] at h

    theorem int_ge_true {a b : Int} (h : Erlang.erlang.«>=/2» (.integer a) (.integer b) = .ok Term.true) : b ≤ a := by
      refine Classical.byContradiction fun hk => ?_
      have : Ord.compare a b = .lt := Int.compare_eq_lt.mpr (by omega)
      simp [Erlang.erlang.«>=/2», this, Term.true] at h

    /-- Element checks of `keyed?/2` at a depth that ensure `P`. -/
    def KeyedOk (P : Term → Prop) (depth : Term) : Prop := ∀ e, «keyed?/2» e depth = .ok Term.true → P e

    section
    variable {P : Term → Prop} {depth : Term}

    theorem keyed_elements_spec (hP : KeyedOk P depth) :
        ∀ l : List Term, «keyed_elements?/2» (Term.list l) depth = .ok Term.true → ∀ e ∈ l, P e
      | [], _ => by simp
      | x :: xs, h => by
        rw [«keyed_elements?/2».eq_def] at h
        simp only [Term.list, Term.true, Lynx.Except.andAlso_eq_true] at h
        intro e me
        rcases List.mem_cons.mp me with rfl | me
        · exact hP _ h.1
        · exact keyed_elements_spec hP xs h.2 e me

    end

    section
    variable {P : Term → Prop} {depth : Term}

    theorem keyed_tuple_spec (hP : KeyedOk P depth) :
        ∀ n t, sizeOf t ≤ n → «keyed_tuple_bdd?/2» t depth = .ok Term.true → TQ P t ∧ AllLits (TQ P) t := by
      intro n
      induction n with
      | zero => intro t size; cases t <;> simp at size <;> omega
      | succ n ih =>
        intro t size h
        rw [«keyed_tuple_bdd?/2».eq_def] at h
        split at h
        · rename_i h₀ lit c u d
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          obtain ⟨⟨⟨hl, hc⟩, hu⟩, hd⟩ := h
          obtain ⟨sl, sc, su, sd⟩ := sizeOf_children5 h₀ lit c u d
          have il := ih lit (by omega) hl
          refine ⟨⟨fun k tag l e => by simp at e, fun k tag l e => by simp at e⟩, ?_⟩
          exact ⟨il.1, (ih c (by omega) hc).2, (ih u (by omega) hu).2, (ih d (by omega) hd).2⟩
        · rename_i key elements
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          obtain ⟨hk, he⟩ := h
          have tq : TQ P (.tuple ⟨[key, .atom "closed", elements]⟩) := by
            refine ⟨fun k tag l e => ?_, fun k tag l e => ?_⟩
            · obtain ⟨rfl, e₂, rfl⟩ := tuple3_eq e
              simp only [Term.atom.injEq] at e₂
              subst e₂
              exact ⟨fun _ => int_lt_true (by simpa using hk), fun h => by simp at h⟩
            · obtain ⟨rfl, -, rfl⟩ := tuple3_eq e
              exact keyed_elements_spec hP l he
          exact ⟨tq, tq⟩
        · rename_i key tag elements notClosed
          simp only [Term.true, Lynx.Except.andAlso_eq_true, Lynx.Except.orElse_eq_true] at h
          obtain ⟨hk, he⟩ := h
          have tq : TQ P (.tuple ⟨[key, tag, elements]⟩) := by
            refine ⟨fun k tag' l e => ?_, fun k tag' l e => ?_⟩
            · obtain ⟨rfl, rfl, rfl⟩ := tuple3_eq e
              refine ⟨fun c => by subst c; exact absurd rfl notClosed, fun _ ne => ?_⟩
              rcases hk with hk | ⟨-, hk⟩
              · cases l with
                | nil => exact absurd rfl ne
                | cons _ _ => simp [Erlang.erlang.«==/2», Term.list] at hk
              · exact int_ge_true (by simpa using hk)
            · obtain ⟨rfl, -, rfl⟩ := tuple3_eq e
              exact keyed_elements_spec hP l he
          exact ⟨tq, tq⟩
        · rename_i other notNode notClosed notLeaf
          refine ⟨⟨fun k tag l e => absurd e (notLeaf _ _ _), fun k tag l e => absurd e (notLeaf _ _ _)⟩, ?_⟩
          unfold AllLits
          split
          · exact (notNode _ _ _ _ _ rfl).elim
          · exact (notLeaf _ _ _ rfl).elim
          · trivial

    end

    section
    variable {P : Term → Prop} {depth : Term}

    theorem keyed_values_spec (hP : KeyedOk P depth) :
        ∀ l : List (Term × Term), «keyed_values?/2» (fieldsTerm l) depth = .ok Term.true →
          ∀ e ∈ l, ∀ u o, e.2 = .tuple #[u, boolAtom o] → P u
      | [], _ => by simp
      | (k, v) :: rest, h => by
        rw [«keyed_values?/2».eq_def] at h
        simp only [fieldsTerm, List.map, Term.list] at h
        by_cases shape : ∃ a b, v = .tuple #[a, b]
        · obtain ⟨a, b, rfl⟩ := shape
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          intro e me u o hv
          rcases List.mem_cons.mp me with rfl | me'
          · simp only [Term.tuple.injEq] at hv
            have := congrArg (fun a : Array Term => a[0]?) hv
            simp at this
            subst this
            exact hP _ h.1
          · exact keyed_values_spec hP rest (by simpa [fieldsTerm, Term.list] using h.2) e me' u o hv
        · exfalso
          split at h
          · rename_i heq
            simp only [Term.cons.injEq, Term.tuple.injEq] at heq
            have := congrArg (fun a : Array Term => a[1]?) heq.1
            simp at this
            exact shape ⟨_, _, this⟩
          · rename_i heq; simp at heq
          · simp at h

    theorem domain_kind_spec {k : Term} (h : «domain_kind?/1» k = .ok Term.true) : ∃ s, k = .atom s ∧ s ∈ domainKinds := by
      have mem : ∀ L : List String, isMember k (L.map Term.atom) = .atom "true" → ∃ s, k = .atom s ∧ s ∈ L := by
        intro L
        induction L with
        | nil => simp
        | cons x xs ih =>
          intro hm
          simp only [List.map, isMember_cons] at hm
          split at hm
          · rename_i e
            exact ⟨x, (compare_eq_atom _ _).mp (compare_eq_of_exactCompare_eq _ _ e), List.mem_cons_self⟩
          · obtain ⟨s, rfl, ms⟩ := ih hm
            exact ⟨s, rfl, List.mem_cons_of_mem _ ms⟩
      apply mem domainKinds
      unfold «domain_kind?/1» at h
      simp only [domainKinds, List.map]
      refine Classical.byContradiction fun hm => ?_
      simp [Lynx.Except.guard, Lynx.Except.tryWith, Term.true] at h
      split at h
      · exact hm (by assumption)
      · simp at h

    theorem domain_kinds_spec : ∀ dl : List (Term × Term), «domain_kinds?/1» (fieldsTerm dl) = .ok Term.true →
        (∀ e ∈ dl, ∃ s, e.1 = .atom s ∧ s ∈ domainKinds) ∧ dl.Pairwise (fun a b => Term.compare a.1 b.1 = .lt)
      | [], _ => ⟨by simp, by simp⟩
      | [(k, v)], h => by
        rw [«domain_kinds?/1».eq_def] at h
        simp only [fieldsTerm, List.map, Term.list] at h
        exact ⟨by simpa using domain_kind_spec h, by simp⟩
      | (k, v) :: (k', v') :: rest, h => by
        rw [«domain_kinds?/1».eq_def] at h
        simp only [fieldsTerm, List.map, Term.list] at h
        simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
        obtain ⟨⟨ha, hlt⟩, hr⟩ := h
        obtain ⟨keys, pw⟩ := domain_kinds_spec ((k', v') :: rest) (by simpa [fieldsTerm, Term.list] using hr)
        have lt := lt_true (by simpa [Term.true] using hlt)
        refine ⟨fun e me => ?_, List.pairwise_cons.mpr ⟨fun e me => ?_, pw⟩⟩
        · rcases List.mem_cons.mp me with rfl | me
          · exact domain_kind_spec (by simpa [Term.true] using ha)
          · exact keys e me
        · rcases List.mem_cons.mp me with rfl | me
          · exact lt
          · exact cmp_lt_trans lt ((List.pairwise_cons.mp pw).1 e me)

    theorem keyed_domains_spec (hP : KeyedOk P depth) : ∀ n T, sizeOf T ≤ n →
        «keyed_domains?/2» T depth = .ok Term.true → ∃ dl : List (Term × Term), T = fieldsTerm dl ∧ ∀ e ∈ dl, P e.2 := by
      intro n
      induction n with
      | zero => intro T size; cases T <;> simp at size <;> omega
      | succ n ih =>
        intro T size h
        rw [«keyed_domains?/2».eq_def] at h
        split at h
        · rename_i kind type rest
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          obtain ⟨dl, rfl, hdl⟩ := ih rest (by simp at size; omega) h.2
          refine ⟨(kind, type) :: dl, rfl, fun e me => ?_⟩
          rcases List.mem_cons.mp me with rfl | me
          · exact hP _ h.1
          · exact hdl e me
        · exact ⟨[], rfl, by simp⟩
        · simp [Term.true] at h

    /-- Map leaves other than closed ones, read from the spec. -/
    theorem mq_leaf (hP : KeyedOk P depth) {key tag fields : Term} (notClosed : tag ≠ .atom "closed")
        (hk : ∀ (k : Int) (l : List Term), key = .integer k → fields = Term.list l → l ≠ [] → 0 ≤ k)
        (hs : «sorted_keys?/1» fields = .ok Term.true) (hv : «keyed_values?/2» fields depth = .ok Term.true)
        (hd : ∀ dl, tag = fieldsTerm dl → DomsV P dl) : MQ P (.tuple ⟨[key, tag, fields]⟩) := by
      refine ⟨fun k tag' l e => ?_, fun k tag' l e => ?_⟩
      · obtain ⟨rfl, rfl, rfl⟩ := tuple3_eq e
        exact ⟨fun c => by subst c; exact absurd rfl notClosed, fun _ ne => hk k l rfl rfl ne⟩
      · obtain ⟨rfl, rfl, rfl⟩ := tuple3_eq e
        obtain ⟨keys, pw⟩ := sorted_keys_spec l hs
        exact ⟨pw, fun e me => ⟨keys e me, keyed_values_spec hP l hv e me⟩, hd⟩

    theorem keyed_map_spec (hP : KeyedOk P depth) :
        ∀ n t, sizeOf t ≤ n → «keyed_map_bdd?/2» t depth = .ok Term.true → MQ P t ∧ AllLits (MQ P) t := by
      intro n
      induction n with
      | zero => intro t size; cases t <;> simp at size <;> omega
      | succ n ih =>
        intro t size h
        rw [«keyed_map_bdd?/2».eq_def] at h
        split at h
        · rename_i h₀ lit c u d
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          obtain ⟨⟨⟨hl, hc⟩, hu⟩, hd⟩ := h
          obtain ⟨sl, sc, su, sd⟩ := sizeOf_children5 h₀ lit c u d
          have il := ih lit (by omega) hl
          refine ⟨⟨fun k tag l e => by simp at e, fun k tag l e => by simp at e⟩, ?_⟩
          exact ⟨il.1, (ih c (by omega) hc).2, (ih u (by omega) hu).2, (ih d (by omega) hd).2⟩
        · rename_i key fields
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          obtain ⟨⟨hk, hs⟩, hv⟩ := h
          have mq : MQ P (.tuple ⟨[key, .atom "closed", fields]⟩) := by
            refine ⟨fun k tag l e => ?_, fun k tag l e => ?_⟩
            · obtain ⟨rfl, e₂, rfl⟩ := tuple3_eq e
              simp only [Term.atom.injEq] at e₂
              subst e₂
              exact ⟨fun _ => int_lt_true (by simpa using hk), fun h => by simp at h⟩
            · obtain ⟨rfl, rfl, rfl⟩ := tuple3_eq e
              obtain ⟨keys, pw⟩ := sorted_keys_spec l hs
              exact ⟨pw, fun e me => ⟨keys e me, keyed_values_spec hP l hv e me⟩,
                fun dl e => absurd e.symm (fieldsTerm_ne_atom dl "closed")⟩
          exact ⟨mq, mq⟩
        · rename_i T notNode notClosed
          simp only at h
          split at h
          · rename_i key tag fields
            have nc : tag ≠ .atom "closed" := fun e => notClosed key fields (by rw [e])
            -- the leaf keys the tag clause reads
            have tagClause : ∀ {key fields : Term}, ((Erlang.erlang.«==/2» fields Term.nil = .ok (.atom "true") ∨
                Erlang.erlang.«==/2» fields Term.nil = .ok (.atom "false") ∧
                  Erlang.erlang.«>=/2» key (Term.integer 0) = .ok (.atom "true")) ∧
                «sorted_keys?/1» fields = .ok (.atom "true")) ∧ «keyed_values?/2» fields depth = .ok (.atom "true") →
                (∀ dl, tag = fieldsTerm dl → DomsV P dl) → MQ P (.tuple ⟨[key, tag, fields]⟩) := by
              intro key fields h hd
              obtain ⟨⟨hk, hs⟩, hv⟩ := h
              refine mq_leaf hP nc (fun k l ek el ne => ?_) hs hv hd
              subst ek el
              rcases hk with hk | ⟨-, hk⟩
              · cases l with
                | nil => exact absurd rfl ne
                | cons _ _ => simp [Erlang.erlang.«==/2», Term.list] at hk
              · exact int_ge_true (by simpa using hk)
            have mq : MQ P (.tuple ⟨[key, tag, fields]⟩) := by
              cases tag with
              | nil =>
                simp [Lynx.Except.guard, Lynx.Except.tryWith, Erlang.erlang.«is_list/1», Term.true,
                  Lynx.Except.andAlso_eq_true] at h
                obtain ⟨⟨⟨⟨hk, -⟩, -⟩, hs⟩, hv⟩ := h
                refine mq_leaf hP nc (fun k l ek _ _ => by subst ek; exact int_ge_true (by simpa using hk)) hs hv
                  fun dl e => ?_
                have : dl = [] := fieldsTerm_eq_nil.mp e.symm
                subst this
                exact ⟨by simp, by simp⟩
              | cons a b =>
                simp [Lynx.Except.guard, Lynx.Except.tryWith, Erlang.erlang.«is_list/1», Term.true,
                  Lynx.Except.andAlso_eq_true] at h
                obtain ⟨⟨⟨⟨hk, hkinds⟩, hdoms⟩, hs⟩, hv⟩ := h
                obtain ⟨dl, edl, hdl⟩ := keyed_domains_spec hP _ _ (Nat.le_refl _) hdoms
                refine mq_leaf hP nc (fun k l ek _ _ => by subst ek; exact int_ge_true (by simpa using hk)) hs hv
                  fun dl' e => ?_
                rw [edl] at e hkinds
                obtain rfl := fieldsTerm_inj e
                obtain ⟨dk, dp⟩ := domain_kinds_spec dl hkinds
                exact ⟨fun e me => ⟨dk e me, hdl e me⟩, dp⟩
              | _ =>
                simp [Lynx.Except.guard, Lynx.Except.tryWith, Erlang.erlang.«is_list/1», Term.false] at h
                exact tagClause h fun dl e => absurd e (by cases dl <;> simp [fieldsTerm, Term.list])
            exact ⟨mq, mq⟩
          · rename_i notLeaf
            refine ⟨⟨fun k tag l e => absurd e (notLeaf _ _ _), fun k tag l e => absurd e (notLeaf _ _ _)⟩, ?_⟩
            unfold AllLits
            split
            · exact (notNode _ _ _ _ _ rfl).elim
            · exact (notLeaf _ _ _ rfl).elim
            · trivial

    theorem keyed_list_spec (hP : KeyedOk P depth) :
        ∀ n t, sizeOf t ≤ n → «keyed_list_bdd?/2» t depth = .ok Term.true → LQ P t ∧ AllLits (LQ P) t := by
      intro n
      induction n with
      | zero => intro t size; cases t <;> simp at size <;> omega
      | succ n ih =>
        intro t size h
        rw [«keyed_list_bdd?/2».eq_def] at h
        split at h
        · rename_i h₀ lit c u d
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          obtain ⟨⟨⟨hl, hc⟩, hu⟩, hd⟩ := h
          obtain ⟨sl, sc, su, sd⟩ := sizeOf_children5 h₀ lit c u d
          have il := ih lit (by omega) hl
          refine ⟨fun k a b e => by simp at e, ?_⟩
          exact ⟨il.1, (ih c (by omega) hc).2, (ih u (by omega) hu).2, (ih d (by omega) hd).2⟩
        · rename_i key list last
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          have lq : LQ P (.tuple ⟨[key, list, last]⟩) := fun k a b e => by
            obtain ⟨-, rfl, rfl⟩ := tuple3_eq e
            exact ⟨hP _ h.1, hP _ h.2⟩
          exact ⟨lq, lq⟩
        · rename_i other notNode notLeaf
          refine ⟨fun k a b e => absurd e (notLeaf _ _ _), ?_⟩
          unfold AllLits
          split
          · exact (notNode _ _ _ _ _ rfl).elim
          · exact (notLeaf _ _ _ rfl).elim
          · trivial

    end

    section
    variable {P : Term → Prop} {depth : Term}

    /-- What `keyed_fields?/3` checks of a field. -/
    def FQ (P : Term → Prop) (el : Bool) (e : Term × Term) : Prop :=
      (e.1 = .atom "fun" → el = Bool.true → e.2 = funTopT) ∧ (e.1 = .atom "tuple" → AllLits (TQ P) e.2) ∧
        (e.1 = .atom "map" → AllLits (MQ P) e.2) ∧ (e.1 = .atom "list" → AllLits (LQ P) e.2)

    theorem map_size_zero {a : Term} (h : (do
          let s ← Erlang.erlang.«map_size/1» a
          Erlang.erlang.«==/2» s (.integer 0)) = .ok (.atom "true")) : a = .map [] := by
      cases a with
      | map Y =>
        cases Y with
        | nil => rfl
        | cons e rest =>
          have ne : ((e :: rest).map Prod.fst).eraseDupsBy (fun a b => Term.exactCompare a b == .eq) ≠ [] := by
            rw [List.map_cons, List.eraseDupsBy_cons]; simp
          have pos : 0 < (((e :: rest).map Prod.fst).eraseDupsBy (fun a b => Term.exactCompare a b == .eq)).length :=
            List.length_pos_iff.mpr ne
          simp only [Erlang.erlang.«map_size/1», Lynx.Except.ok_bind, Erlang.erlang.«==/2»] at h
          split at h
          · rename_i c
            have : (((e :: rest).map Prod.fst).eraseDupsBy (fun a b => Term.exactCompare a b == .eq)).length = 0 := by
              simpa using c
            omega
          · simp at h
      | _ => simp [Erlang.erlang.«map_size/1»] at h

    /-- One field of `keyed_fields?/3`. -/
    theorem keyed_fields_step (hP : KeyedOk P depth) (el : Bool) (k v rest : Term)
        (h : «keyed_fields?/3» (.cons (.tuple #[k, v]) rest) depth (boolAtom el) = .ok Term.true) :
        FQ P el (k, v) ∧ «keyed_fields?/3» rest depth (boolAtom el) = .ok Term.true := by
      rw [«keyed_fields?/3».eq_def] at h
      simp only [boolAtom] at h
      have elT : ∀ {el : Bool}, Term.atom (if el = Bool.true then "true" else "false") = .atom "true" → el = Bool.true := by
        intro el e; cases el <;> simp_all
      split at h
      · rename_i arities fields heq₁ heq₂
        have e₀ := elT heq₂
        subst e₀
        simp only [Term.cons.injEq, Term.tuple.injEq] at heq₁
        obtain ⟨e₁, rfl⟩ := heq₁
        have hk := congrArg (fun a : Array Term => a[0]?) e₁
        have hv := congrArg (fun a : Array Term => a[1]?) e₁
        simp at hk hv
        subst hk hv
        cases hc : (do
            let s ← Erlang.erlang.«map_size/1» arities
            Erlang.erlang.«==/2» s (.integer 0) : Except Exception Term) with
        | error x =>
          simp only [hc, Lynx.Except.tryWith, Lynx.Except.guard] at h
          cases x <;> simp at h
        | ok r =>
          by_cases rt : r = .atom "true"
          · subst rt
            have := map_size_zero hc
            subst this
            simp only [hc, Lynx.Except.tryWith, Lynx.Except.guard] at h
            refine ⟨⟨fun _ _ => rfl, fun e => by simp at e, fun e => by simp at e, fun e => by simp at e⟩, by simpa [boolAtom] using h⟩
          · simp only [hc, Lynx.Except.tryWith, Lynx.Except.guard] at h
            split at h <;> simp_all
      · rename_i notFun
        split at h
        · simp at h
        · rename_i heq
          simp only [Term.cons.injEq, Term.tuple.injEq] at heq
          obtain ⟨e₁, rfl⟩ := heq
          have hk := congrArg (fun a : Array Term => a[0]?) e₁
          have hv := congrArg (fun a : Array Term => a[1]?) e₁
          simp at hk hv
          subst hk hv
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          exact ⟨⟨fun e => by simp at e, fun _ => (keyed_tuple_spec hP _ _ (Nat.le_refl _) h.1).2, fun e => by simp at e,
            fun e => by simp at e⟩, by simpa [boolAtom] using h.2⟩
        · rename_i heq
          simp only [Term.cons.injEq, Term.tuple.injEq] at heq
          obtain ⟨e₁, rfl⟩ := heq
          have hk := congrArg (fun a : Array Term => a[0]?) e₁
          have hv := congrArg (fun a : Array Term => a[1]?) e₁
          simp at hk hv
          subst hk hv
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          exact ⟨⟨fun e => by simp at e, fun e => by simp at e, fun _ => (keyed_map_spec hP _ _ (Nat.le_refl _) h.1).2,
            fun e => by simp at e⟩, by simpa [boolAtom] using h.2⟩
        · rename_i heq
          simp only [Term.cons.injEq, Term.tuple.injEq] at heq
          obtain ⟨e₁, rfl⟩ := heq
          have hk := congrArg (fun a : Array Term => a[0]?) e₁
          have hv := congrArg (fun a : Array Term => a[1]?) e₁
          simp at hk hv
          subst hk hv
          simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
          exact ⟨⟨fun e => by simp at e, fun e => by simp at e, fun e => by simp at e,
            fun _ => (keyed_list_spec hP _ _ (Nat.le_refl _) h.1).2⟩, by simpa [boolAtom] using h.2⟩
        · rename_i field fields notT notM notL heq notF
          simp only [Term.cons.injEq] at heq
          obtain ⟨rfl, rfl⟩ := heq
          refine ⟨⟨fun e et => ?_, fun e => ?_, fun e => ?_, fun e => ?_⟩, by simpa [boolAtom] using h⟩
          · simp only at e; subst e; subst et
            exact (notF v (by simp) rfl).elim
          · simp only at e; subst e; exact (notT v rfl).elim
          · simp only at e; subst e; exact (notM v rfl).elim
          · simp only at e; subst e; exact (notL v rfl).elim
        · rename_i heq; simp at heq
        · simp at h

    end

    section
    variable {P : Term → Prop} {depth : Term}

    theorem keyed_fields_spec (hP : KeyedOk P depth) (el : Bool) :
        ∀ es : List (Term × Term), «keyed_fields?/3» (Term.list (es.map fun e => .tuple #[e.1, e.2])) depth (boolAtom el) =
          .ok Term.true → ∀ e ∈ es, FQ P el e
      | [], _ => by simp
      | (k, v) :: rest, h => by
        obtain ⟨fq, hr⟩ := keyed_fields_step hP el k v _ (by simpa [Term.list] using h)
        intro e me
        rcases List.mem_cons.mp me with rfl | me
        · exact fq
        · exact keyed_fields_spec hP el rest hr e me

    /-- The fields of a map that `keyed_fields?/3` accepts. -/
    theorem keyedF_of (hP : KeyedOk P depth) (el : Bool) (X : List (Term × Term))
        (h : (do
          let l ← Erlang.maps.«to_list/1» (.map X)
          «keyed_fields?/3» l depth (boolAtom el)) = .ok Term.true) : KeyedF P el X := by
      simp only [Erlang.maps.«to_list/1», Lynx.Except.ok_bind] at h
      have each := keyed_fields_spec hP el (mapEntries X) h
      have entry (q w : Term) (lookup : mapLookup X q = some w) :
          ∃ p ∈ mapEntries X, exactCompare q p.1 = .eq ∧ p.2 = w :=
        lookup_found _ q w (by rw [mapLookup_mapEntries]; exact lookup)
      refine ⟨fun et w hw => ?_, fun w hw => ?_, fun w hw => ?_, fun w hw => ?_⟩
      · obtain ⟨p, mp, qp, rfl⟩ := entry _ w hw
        exact (each p mp).1 ((exactCompare_eq_atom _ _).mp (Std.OrientedCmp.eq_symm qp)) et
      · obtain ⟨p, mp, qp, rfl⟩ := entry _ w hw
        exact (each p mp).2.1 ((exactCompare_eq_atom _ _).mp (Std.OrientedCmp.eq_symm qp))
      · obtain ⟨p, mp, qp, rfl⟩ := entry _ w hw
        exact (each p mp).2.2.1 ((exactCompare_eq_atom _ _).mp (Std.OrientedCmp.eq_symm qp))
      · obtain ⟨p, mp, qp, rfl⟩ := entry _ w hw
        exact (each p mp).2.2.2 ((exactCompare_eq_atom _ _).mp (Std.OrientedCmp.eq_symm qp))

    end

    /-- What `keyed?/2` checks at each depth. -/
    theorem keyed_spec : ∀ d : Nat, KeyedOk (Keyed d) (.integer d)
      | 0, _, _ => trivial
      | d + 1, e, h => by
        rw [«keyed?/2».eq_def] at h
        split at h
        · exact Or.inl rfl
        · exact Or.inr (Or.inl ⟨_, _, _, rfl⟩)
        · rename_i _ _ heq; simp at heq; omega
        · rename_i e₀ _ _ _ _ _
          cases e₀ with
          | map X =>
            have sub : Erlang.erlang.«-/2» (.integer ((d + 1 : Nat) : Int)) (.integer 1) = .ok (.integer (d : Int)) := by
              rw [Erlang.erlang.«-/2_integers»]; congr 2; omega
            refine Or.inr (Or.inr ⟨X, rfl, keyedF_of (keyed_spec d) Bool.true X ?_⟩)
            simpa [sub, boolAtom] using h
          | _ => simp [Erlang.maps.«to_list/1»] at h

    /-- The depths of the laws are natural numbers. -/
    theorem depth_nat {depth : Term} (h : «depth?/1» depth = .ok Term.true) : ∃ n : Nat, depth = .integer n := by
      cases depth <;> simp [«depth?/1», Erlang.erlang.«is_integer/1», Lynx.Except.andAlso, Term.true, Erlang.erlang.«>=/2»,
        Int.isGE_compare] at h
      rename_i z
      exact ⟨z.toNat, by simp only [Term.integer.injEq]; omega⟩

    theorem negatable_cases (t : Term) (n : Nat) (descr : Term)
        (h : «negatable?/2» descr (.tuple #[.integer n, t]) = .ok Term.true) :
        descr = .atom "term" ∨ ∃ X, descr = .map X ∧ Negatable (Nest t n) X :=
      negatable_map t n descr h

    /-- The types of `opt_negatable?/2` are top-level types over the element types of their depth. -/
    theorem opt_negatable_tc (t : Term) (n : Nat) (descr : Term)
        (h : «opt_negatable?/2» descr (.tuple #[.integer n, t]) = .ok Term.true) : TC (level t n) descr := by
      unfold «opt_negatable?/2» at h
      split at h
      · exact Or.inl rfl
      · rename_i d nn notTerm heq
        obtain ⟨rfl, rfl⟩ : d = .integer n ∧ nn = t := by simp at heq; exact ⟨heq.1.symm, heq.2.symm⟩
        simp only [Term.true, Lynx.Except.andAlso_eq_true] at h
        obtain ⟨hn, hk⟩ := h
        rcases negatable_cases _ n _ hn with rfl | ⟨X, rfl, v⟩
        · exact (notTerm rfl).elim
        · exact negatable_tc _ n v (keyedF_of (keyed_spec n) Bool.false X (by simpa [boolAtom] using hk))
      · simp at h

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    namespace Elixir.STTDescrProofsTest
    open Lynx Lynx.Term BddProofs

    /-! The top type in the negation and De Morgan laws of the plain operations. -/

    /-- Intersecting the empty type with a map of fields keeps no field. -/
    theorem symmetrical_none_left (d : Dispatcher) (X : List (Term × Term)) :
        Elixir.Module.Types.Descr.«symmetrical_intersection/3» d (.map []) (.map X)
          (.function "Elixir.Module.Types.Descr" "bare_intersection" 3 #[]) = .ok (.map []) := by
      obtain ⟨I, runI, lookI⟩ := Erlang.maps.intersect_with_lookup d "Elixir.Module.Types.Descr"
        "bare_intersection" #[] [] X (fun _ _ _ => .nil) (by intro e me; simp at me)
      obtain rfl : I = [] := nil_of_lookup_none I fun q => by rw [lookI]; simp
      obtain ⟨out, runO, lookO⟩ := Erlang.maps.filter_lookup d "Elixir.Module.Types.Descr"
        "-symmetrical_intersection/3-fun-0-" #[] [] kept (by intro e member; simp at member)
      obtain rfl : out = [] := nil_of_lookup_none out fun q => by rw [lookO]; simp
      unfold Elixir.Module.Types.Descr.«symmetrical_intersection/3»
      simp [runI, runO]

    theorem intersection_none_left (depth : Nat) (X : List (Term × Term))
        (static : mapLookup X (.atom "dynamic") = Option.none) :
        Elixir.Module.Types.Descr.«bare_intersection/2»
          (Dispatcher.ofTable Erlang.program.fun_table (depth + 1)) (.map []) (.map X) = .ok (.map []) := by
      have absent : mapLookup ([] : List (Term × Term)) (.atom "dynamic") = Option.none := rfl
      unfold Elixir.Module.Types.Descr.«bare_intersection/2»
      simp [getMapKeys_single, static, absent, symmetrical_none_left]

    theorem negation_term_none (d : Dispatcher) :
        Elixir.Module.Types.Descr.«bare_negation/1» d (.atom "term") = .ok (.map []) := by
      simp [Elixir.Module.Types.Descr.«bare_negation/1», Elixir.Module.Types.Descr.«none/0»]

    /-- The negation of a negatable type, or of the top type, is a static map of fields. -/
    theorem negation_static (δ : Nat) {t : Term} {n : Nat} (hn : 23 + 15 * n ≤ δ + 90) {a : Term}
        (ha : a = .atom "term" ∨ ∃ X, a = .map X ∧ Negatable (Nest t n) X) :
        (∃ N, Elixir.Module.Types.Descr.«bare_negation/1» (D (δ + 100)) a = .ok (.map N) ∧
          mapLookup N (.atom "dynamic") = Option.none) ∨
        Elixir.Module.Types.Descr.«bare_negation/1» (D (δ + 100)) a = .ok (.atom "term") := by
      obtain ⟨ops, -, -, -, -⟩ := closed_ok t n
      rcases ha with rfl | ⟨X, rfl, v⟩
      · exact Or.inl ⟨[], negation_term_none _, rfl⟩
      by_cases e : X = []
      · subst e; exact Or.inr (negation_none_term δ)
      obtain ⟨N, neg, sN, -⟩ := sem_neg δ ops.term X (v.mono (nest_closed t n)).sem e
      exact Or.inl ⟨N, neg, sN.static⟩

    /-- De Morgan's law for any two negatable types or top types. -/
    theorem de_morgan_union_any (δ : Nat) {t : Term} {n : Nat} (hn : 23 + 15 * n ≤ δ + 90) {l r : Term}
        (hl : l = .atom "term" ∨ ∃ L, l = .map L ∧ Negatable (Nest t n) L)
        (hr : r = .atom "term" ∨ ∃ R, r = .map R ∧ Negatable (Nest t n) R) :
        (do
          let u ← Elixir.Module.Types.Descr.«bare_union/2» (D (δ + 100)) l r
          let a ← Elixir.Module.Types.Descr.«bare_negation/1» (D (δ + 100)) u
          let nl ← Elixir.Module.Types.Descr.«bare_negation/1» (D (δ + 100)) l
          let nr ← Elixir.Module.Types.Descr.«bare_negation/1» (D (δ + 100)) r
          let b ← Elixir.Module.Types.Descr.«bare_intersection/2» (D (δ + 100)) nl nr
          Elixir.Module.Types.Descr.«equal?/2» (D (δ + 100)) a b) = .ok (.atom "true") := by
      rcases hl with rfl | ⟨L, rfl, vL⟩
      · rcases negation_static δ hn hr with ⟨N, neg, sN⟩ | neg
        · simp [union_term_l, negation_term_none, neg, intersection_none_left (δ + 99) N sN, equal_self]
        · simp [union_term_l, negation_term_none, neg, inter_term_right, equal_self]
      rcases hr with rfl | ⟨R, rfl, vR⟩
      · rcases negation_static δ hn (Or.inr ⟨L, rfl, vL⟩) with ⟨N, neg, sN⟩ | neg
        · simp [union_term_r, negation_term_none, neg, intersection_none_static (δ + 99) N sN, equal_self]
        · simp [union_term_r, negation_term_none, neg, inter_term_left, equal_self]
      obtain ⟨ops, dops, -, -, -⟩ := closed_ok t n
      exact de_morgan_union_law δ ops dops (by omega) L R (vL.mono (nest_closed t n)) (vR.mono (nest_closed t n))

    end Elixir.STTDescrProofsTest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Merging maps field by field, whatever their keys. -/

    /-- The bindings of a map other than its dynamic part, as `maps:remove/2` and `maps:take/2` leave them. -/
    def rmDyn (X : List (Term × Term)) : List (Term × Term) :=
      X.filter fun entry => exactCompare (.atom "dynamic") entry.1 != .eq

    theorem lookup_rmDyn (X : List (Term × Term)) (q : Term) :
        mapLookup (rmDyn X) q = if exactCompare q (.atom "dynamic") = .eq then none else mapLookup X q := by
      rw [rmDyn, mapLookup_filter]

    theorem lookup_rmDyn_name (X : List (Term × Term)) {name : String} (h : name ≠ "dynamic") :
        mapLookup (rmDyn X) (.atom name) = mapLookup X (.atom name) := by
      simp [lookup_rmDyn, h]

    theorem rmDyn_static {X : List (Term × Term)} (h : mapLookup X (.atom "dynamic") = none) : rmDyn X = X := by
      refine List.filter_eq_self.mpr fun e me => ?_
      cases c : exactCompare (.atom "dynamic") e.1 <;> simp
      have : (mapLookup X (.atom "dynamic")).isSome := (mapLookup_isSome X _).mpr ⟨e, me, c⟩
      rw [h] at this; cases this

    theorem names_ne_dyn {name : String} (h : name ∈ names) : name ≠ "dynamic" := by
      simp [names] at h; rintro rfl; simp at h

    /-- Merging maps with atom keys looks up the combined values of shared keys and the others' values. -/
    theorem merge_gen (d : Dispatcher) (module name : String) (caps : Array Term)
        (f : Term → Term → Term → Except Exception Term)
        (call : ∀ q v₁ v₂, d.pure (.function module name 3 caps) #[q, v₁, v₂] = f q v₁ v₂)
        (L R : List (Term × Term)) (keysR : ∀ q, (mapLookup R q).isSome → ∃ n, q = .atom n)
        (calls : ∀ q x y, mapLookup L q = some x → mapLookup R q = some y → ∃ u, f q x y = .ok u) :
        ∃ U, Elixir.Module.Types.Descr.«symmetrical_merge/3» d (.map L) (.map R) (.function module name 3 caps) =
            .ok (.map U) ∧
          ∀ q, (mapLookup R q = none → mapLookup U q = mapLookup L q) ∧
            (∀ y, mapLookup R q = some y → mapLookup L q = none → mapLookup U q = some y) ∧
            (∀ x y u, mapLookup L q = some x → mapLookup R q = some y → f q x y = .ok u → mapLookup U q = some u) := by
      let g : Term → Term → Term → Term := fun k₀ v₁ v₂ =>
        match f k₀ v₁ v₂ with
        | .ok w => w
        | .error _ => .nil
      have value : ∀ q x y u, f q x y = .ok u → g q x y = u := by
        intro q x y u run; simp [g, run]
      unfold Elixir.Module.Types.Descr.«symmetrical_merge/3»
      obtain ⟨out, run, look⟩ := Erlang.maps.merge_with_lookup d module name caps L R g (by
        intro e me x hx
        have hy := mapLookup_of_mem_mapEntries me
        obtain ⟨u, ru⟩ := calls e.1 x e.2 hx hy
        rw [call, ru, value _ _ _ _ ru])
      refine ⟨out, by simpa using run, fun q => ⟨fun hR => ?_, fun y hR hL => ?_, fun x y u hL hR ru => ?_⟩⟩
      · rw [look q]
        cases hit : (mapEntries R).find? (fun e => decide (exactCompare q e.1 = .eq)) with
        | none => rfl
        | some e => rw [(find_entry hit).2] at hR; cases hR
      · rw [look q]
        cases hit : (mapEntries R).find? (fun e => decide (exactCompare q e.1 = .eq)) with
        | none => rw [find_none hit] at hR; cases hR
        | some e =>
          obtain ⟨qe, h⟩ := find_entry hit
          rw [h] at hR; cases hR
          simp [← mapLookup_congr qe, hL]
      · rw [look q]
        cases hit : (mapEntries R).find? (fun e => decide (exactCompare q e.1 = .eq)) with
        | none => rw [find_none hit] at hR; cases hR
        | some e =>
          obtain ⟨qe, h⟩ := find_entry hit
          rw [h] at hR; cases hR
          obtain ⟨n, hn⟩ := keysR e.1 (by rw [← mapLookup_congr qe, h]; rfl)
          rw [hn] at qe
          obtain rfl := (exactCompare_eq_atom q n).mp qe
          simp [hn, hL, value _ _ _ _ ru]

    /-- Intersecting maps looks up the kept combined values of shared keys. -/
    theorem intersect_gen (n : Nat) (module name : String) (caps : Array Term)
        (f : Term → Term → Term → Except Exception Term)
        (call : ∀ q v₁ v₂, (D (n + 1)).pure (.function module name 3 caps) #[q, v₁, v₂] = f q v₁ v₂)
        (L R : List (Term × Term)) (keysL : ∀ q, (mapLookup L q).isSome → ∃ n, q = .atom n)
        (calls : ∀ q x y, mapLookup L q = some x → mapLookup R q = some y → ∃ u, f q x y = .ok u) :
        ∃ I, Elixir.Module.Types.Descr.«symmetrical_intersection/3» (D (n + 1)) (.map L) (.map R) (.function module name 3 caps) =
            .ok (.map I) ∧
          ∀ q, (mapLookup L q = none → mapLookup I q = none) ∧ (mapLookup R q = none → mapLookup I q = none) ∧
            (∀ x y u, mapLookup L q = some x → mapLookup R q = some y → f q x y = .ok u →
              mapLookup I q = if kept (q, u) then some u else none) := by
      let g : Term → Term → Term → Term := fun k₀ v₁ v₂ =>
        match f k₀ v₁ v₂ with
        | .ok w => w
        | .error _ => .nil
      have value : ∀ q x y u, f q x y = .ok u → g q x y = u := by
        intro q x y u run; simp [g, run]
      obtain ⟨I, runI, lookI⟩ := Erlang.maps.intersect_with_lookup (D (n + 1)) module name caps L R g (by
        intro e member y hy
        obtain ⟨w, run⟩ := calls e.1 e.2 y (mapLookup_of_mem_mapEntries member) hy
        rw [call, run, value _ _ _ _ run])
      have lookI' : ∀ q, mapLookup I q =
          match mapLookup L q, mapLookup R q with
          | some x, some y => some (g q x y)
          | _, _ => none := by
        intro q
        rw [lookI]
        cases hit : (mapEntries L).find? (fun e => decide (exactCompare q e.1 = .eq)) with
        | none => rw [find_none hit]
        | some e =>
          obtain ⟨qe, h⟩ := find_entry hit
          obtain ⟨n, hn⟩ := keysL e.1 (by rw [← mapLookup_congr qe, h]; rfl)
          rw [hn] at qe
          obtain rfl := (exactCompare_eq_atom q n).mp qe
          rw [h, ← hn]
          dsimp only
          cases mapLookup R e.1 <;> rfl
      obtain ⟨out, runO, lookO⟩ := Erlang.maps.filter_lookup (D (n + 1)) "Elixir.Module.Types.Descr"
        "-symmetrical_intersection/3-fun-0-" #[] I kept (by
          intro e _
          rw [Erlang.program.«Elixir.Module.Types.Descr:-symmetrical_intersection/3-fun-0-/2».pure, keep_field])
      refine ⟨out, ?_, fun q => ?_⟩
      · unfold Elixir.Module.Types.Descr.«symmetrical_intersection/3»
        simp [runI, runO]
      have look : mapLookup out q =
          match mapLookup L q, mapLookup R q with
          | some x, some y => if kept (q, g q x y) then some (g q x y) else none
          | _, _ => none := by
        rw [lookO]
        cases hit : (mapEntries I).find? (fun e => decide (exactCompare q e.1 = .eq)) with
        | none =>
          have := find_none hit
          rw [lookI'] at this
          revert this
          cases mapLookup L q <;> cases mapLookup R q <;> simp
        | some e =>
          obtain ⟨qe, h⟩ := find_entry hit
          rw [lookI'] at h
          revert h
          cases mapLookup L q <;> cases mapLookup R q <;> simp
          intro h
          simp only [kept]
          rw [h]
          rfl
      refine ⟨fun hL => by rw [look, hL], fun hR => by rw [look, hR]; cases mapLookup L q <;> rfl,
        fun x y w hL hR run => by rw [look, hL, hR]; simp only [value _ _ _ _ run]⟩

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Gradual top-level types: a static part and a dynamic part that includes it. -/

    section
    variable {L : Level}

    abbrev DC (L : Level) := DescrC FunF (TField L.E) (LF L.E) (MField L.E)
    abbrev FC (L : Level) := FieldC FunF (TField L.E) (LF L.E) (MField L.E)

    theorem denD_rmDyn (X : List (Term × Term)) (v : TP L) : denD (.map (rmDyn X)) v ↔ denD (.map X) v := by
      simp only [denD_map, lookup_rmDyn_name X (names_ne_dyn v.2.1)]

    /-- Field operations a union merges fields with: they unite the points of their fields. -/
    structure UnionOp (L : Level) (d : Dispatcher) (module name : String) (caps : Array Term)
        (f : Term → Term → Term → Except Exception Term) : Prop where
      call : ∀ q v₁ v₂, d.pure (.function module name 3 caps) #[q, v₁, v₂] = f q v₁ v₂
      spec : ∀ name x y, FC L name x → FC L name y → ∃ u, f (.atom name) x y = .ok u ∧ FC L name u ∧
        ∀ p, PtOkD L.E L.den L.tl name p → dn name (some u) p = (dn name (some x) p || dn name (some y) p)

    theorem DC.atoms {X : List (Term × Term)} (sX : DC L X) : ∀ q, (mapLookup X q).isSome → ∃ n, q = .atom n :=
      fun q h => let ⟨n, _, e⟩ := sX.keys q h; ⟨n, e⟩

    /-- Maps whose bindings other than the dynamic one are fields have atom keys. -/
    theorem rmDyn_atoms {X : List (Term × Term)} (sX : DC L (rmDyn X)) : ∀ q, (mapLookup X q).isSome → ∃ n, q = .atom n := by
      intro q h
      by_cases e : exactCompare q (.atom "dynamic") = .eq
      · exact ⟨"dynamic", (exactCompare_eq_atom q _).mp e⟩
      · exact sX.atoms q (by rw [lookup_rmDyn, if_neg e]; exact h)

    /-- Merging static types unites them. -/
    theorem merge_descr {d : Dispatcher} {module name : String} {caps : Array Term}
        {f : Term → Term → Term → Except Exception Term} (op : UnionOp L d module name caps f)
        {A B : List (Term × Term)} (sA : DC L A) (sB : DC L B) :
        ∃ U, Elixir.Module.Types.Descr.«symmetrical_merge/3» d (.map A) (.map B) (.function module name 3 caps) =
            .ok (.map U) ∧ DC L U ∧ ∀ v : TP L, denD (.map U) v ↔ denD (.map A) v ∨ denD (.map B) v := by
      obtain ⟨U, run, look⟩ := merge_gen d module name caps f op.call A B sB.atoms (fun q x y hx hy => by
        obtain ⟨n, -, rfl⟩ := sA.keys q (by simp [hx])
        obtain ⟨u, ru, -⟩ := op.spec n x y (sA.fields n x hx) (sB.fields n y hy)
        exact ⟨u, ru⟩)
      have keysU : ∀ q, (mapLookup U q).isSome → (mapLookup A q).isSome ∨ (mapLookup B q).isSome := by
        intro q h
        cases hB : mapLookup B q with
        | none => rw [(look q).1 hB] at h; exact Or.inl h
        | some y => exact Or.inr (by simp)
      obtain ⟨cU, sem, -⟩ := union_gen (slh := False) sA sB f
        (fun n => ⟨(look _).1, (look _).2.1, (look _).2.2⟩) keysU
        (fun n x y fx fy => let ⟨u, ru, fu, su⟩ := op.spec n x y fx fy; ⟨u, ru, fu, su, False.elim⟩)
      exact ⟨U, run, cU, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.or_eq_true]⟩

    /-- Unions of dynamic parts: top-level types merged field by field. -/
    theorem dyn_union_tc {d : Dispatcher} {module name : String} {caps : Array Term}
        {f : Term → Term → Term → Except Exception Term} (op : UnionOp L d module name caps f)
        {a b : Term} (ha : TC L a) (hb : TC L b) :
        ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«dynamic_union/3» d a b (.function module name 3 caps) = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∨ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨_, Or.inl rfl, by unfold Elixir.Module.Types.Descr.«dynamic_union/3»; rfl, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inl rfl, by unfold Elixir.Module.Types.Descr.«dynamic_union/3»; rfl, fun v => by simp [denD_term]⟩
      obtain ⟨U, run, sU, sem⟩ := merge_descr op sA sB
      refine ⟨_, Or.inr ⟨U, rfl, sU⟩, ?_, sem⟩
      unfold Elixir.Module.Types.Descr.«dynamic_union/3»
      simpa [unfold_map] using run

    /-- The upper bound of a type: its dynamic part, or the type itself when it is static. -/
    def upper (a : Term) : Term :=
      match a with
      | .map X => (mapLookup X (.atom "dynamic")).getD a
      | _ => a

    /-- Gradual top-level types: top-level types, or maps of fields with a dynamic part, a top-level type that holds
    every point of the fields, as Descr maintains. -/
    def GC (L : Level) (a : Term) : Prop :=
      TC L a ∨ ∃ X Dy, a = .map X ∧ mapLookup X (.atom "dynamic") = some Dy ∧ TC L Dy ∧ DC L (rmDyn X) ∧
        ∀ v : TP L, denD a v → denD Dy v

    theorem upper_tc {a : Term} (ha : TC L a) : upper a = a := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · rfl
      · simp [upper, sX.static]

    theorem upper_dyn {X : List (Term × Term)} {Dy : Term} (h : mapLookup X (.atom "dynamic") = some Dy) :
        upper (.map X) = Dy := by
      simp [upper, h]

    theorem GC.tc {a : Term} (ha : TC L a) : GC L a := Or.inl ha

    theorem GC.up_tc {a : Term} (ha : GC L a) : TC L (upper a) := by
      rcases ha with ha | ⟨X, Dy, rfl, hD, tD, -, -⟩
      · rwa [upper_tc ha]
      · rwa [upper_dyn hD]

    theorem GC.inv {a : Term} (ha : GC L a) (v : TP L) (h : denD a v) : denD (upper a) v := by
      rcases ha with ha | ⟨X, Dy, rfl, hD, -, -, inv⟩
      · rwa [upper_tc ha]
      · rw [upper_dyn hD]; exact inv v h

    /-- A static operand meets a gradual one as its own dynamic part. -/
    def alignT (X : List (Term × Term)) : List (Term × Term) :=
      match mapLookup X (.atom "dynamic") with
      | some _ => X
      | none => (.atom "dynamic", .map X) :: X

    theorem rmDyn_cons_dyn (X : List (Term × Term)) (w : Term) : rmDyn ((.atom "dynamic", w) :: X) = rmDyn X := by
      simp [rmDyn]

    /-- Aligned maps of gradual types: their dynamic part is the upper bound, and their fields those of the type. -/
    theorem align_gc {X : List (Term × Term)} (hX : GC L (.map X)) :
        mapLookup (alignT X) (.atom "dynamic") = some (upper (.map X)) ∧ DC L (rmDyn (alignT X)) ∧
          ∀ v : TP L, denD (.map (alignT X)) v ↔ denD (.map X) v := by
      rcases hX with (h | ⟨X', e, sX⟩) | ⟨X', Dy, e, hD, -, sX, -⟩
      · cases h
      · simp only [Term.map.injEq] at e; subst e
        have st := sX.static
        refine ⟨by rw [alignT, st, upper_tc (Or.inr ⟨X, rfl, sX⟩)]; simp [mapLookup], ?_, fun v => ?_⟩
        · rw [alignT, st]; simp only; rw [rmDyn_cons_dyn, rmDyn_static st]; exact sX
        · rw [alignT, st]; simp only
          rw [← denD_rmDyn, rmDyn_cons_dyn, denD_rmDyn]
      · simp only [Term.map.injEq] at e; subst e
        refine ⟨by simp [alignT, hD, upper], by simpa [alignT, hD] using sX, fun v => by simp [alignT, hD]⟩

    /-- Merging maps with dynamic parts merges their fields and their dynamic parts. -/
    theorem merge_grad {d : Dispatcher} {module name : String} {caps : Array Term}
        {f : Term → Term → Term → Except Exception Term} (op : UnionOp L d module name caps f)
        {X Y : List (Term × Term)} {Dx Dy Du : Term} (hX : mapLookup X (.atom "dynamic") = some Dx)
        (hY : mapLookup Y (.atom "dynamic") = some Dy) (sX : DC L (rmDyn X)) (sY : DC L (rmDyn Y))
        (du : f (.atom "dynamic") Dx Dy = .ok Du) :
        ∃ U, Elixir.Module.Types.Descr.«symmetrical_merge/3» d (.map X) (.map Y) (.function module name 3 caps) =
            .ok (.map U) ∧ mapLookup U (.atom "dynamic") = some Du ∧ DC L (rmDyn U) ∧
            ∀ v : TP L, denD (.map U) v ↔ denD (.map X) v ∨ denD (.map Y) v := by
      obtain ⟨U, run, look⟩ := merge_gen d module name caps f op.call X Y (rmDyn_atoms sY) (fun q x y hx hy => by
        by_cases e : exactCompare q (.atom "dynamic") = .eq
        · obtain rfl := (exactCompare_eq_atom q _).mp e
          rw [hX] at hx; rw [hY] at hy; cases hx; cases hy
          exact ⟨Du, du⟩
        · have hx' : mapLookup (rmDyn X) q = some x := by rw [lookup_rmDyn, if_neg e]; exact hx
          have hy' : mapLookup (rmDyn Y) q = some y := by rw [lookup_rmDyn, if_neg e]; exact hy
          obtain ⟨n, -, rfl⟩ := sX.keys q (by simp [hx'])
          obtain ⟨u, ru, -⟩ := op.spec n x y (sX.fields n x hx') (sY.fields n y hy')
          exact ⟨u, ru⟩)
      have lookR : ∀ q, (mapLookup (rmDyn Y) q = none → mapLookup (rmDyn U) q = mapLookup (rmDyn X) q) ∧
          (∀ y, mapLookup (rmDyn Y) q = some y → mapLookup (rmDyn X) q = none → mapLookup (rmDyn U) q = some y) ∧
          (∀ x y u, mapLookup (rmDyn X) q = some x → mapLookup (rmDyn Y) q = some y → f q x y = .ok u →
            mapLookup (rmDyn U) q = some u) := by
        intro q
        simp only [lookup_rmDyn]
        by_cases e : exactCompare q (.atom "dynamic") = .eq
        · simp [e]
        · simp only [e, if_false]; exact look q
      have keysU : ∀ q, (mapLookup (rmDyn U) q).isSome → (mapLookup (rmDyn X) q).isSome ∨ (mapLookup (rmDyn Y) q).isSome := by
        intro q h
        cases hB : mapLookup (rmDyn Y) q with
        | none => rw [(lookR q).1 hB] at h; exact Or.inl h
        | some y => exact Or.inr (by simp)
      obtain ⟨cU, sem, -⟩ := union_gen (slh := False) sX sY f
        (fun n => ⟨(lookR _).1, (lookR _).2.1, (lookR _).2.2⟩) keysU
        (fun n x y fx fy => let ⟨u, ru, fu, su⟩ := op.spec n x y fx fy; ⟨u, ru, fu, su, False.elim⟩)
      refine ⟨U, run, (look _).2.2 Dx Dy Du hX hY du, cU, fun v => ?_⟩
      rw [← denD_rmDyn U, ← denD_rmDyn X, ← denD_rmDyn Y]
      simp only [denD_map, sem _ _ v.2.2, Bool.or_eq_true]

    /-- Merging aligned gradual types unites their fields and their upper bounds. -/
    theorem merge_aligned {d d' : Dispatcher} {module name module' name' : String} {caps caps' : Array Term}
        {f f' : Term → Term → Term → Except Exception Term} (op : UnionOp L d module name caps f)
        (op' : UnionOp L d' module' name' caps' f')
        (dyn : ∀ x y, f (.atom "dynamic") x y =
          Elixir.Module.Types.Descr.«dynamic_union/3» d' x y (.function module' name' 3 caps'))
        {X Y : List (Term × Term)} (hX : GC L (.map X)) (hY : GC L (.map Y)) :
        ∃ c, GC L c ∧
          Elixir.Module.Types.Descr.«symmetrical_merge/3» d (.map (alignT X)) (.map (alignT Y))
            (.function module name 3 caps) = .ok c ∧
          (∀ v : TP L, denD c v ↔ denD (.map X) v ∨ denD (.map Y) v) ∧
          (∀ v : TP L, denD (upper c) v ↔ denD (upper (.map X)) v ∨ denD (upper (.map Y)) v) := by
      obtain ⟨dX, sX, eX⟩ := align_gc hX
      obtain ⟨dY, sY, eY⟩ := align_gc hY
      obtain ⟨Du, tu, ru, su⟩ := dyn_union_tc op' hX.up_tc hY.up_tc
      obtain ⟨U, run, dU, sU, sem⟩ := merge_grad op dX dY sX sY (by rw [dyn]; exact ru)
      have lo : ∀ v : TP L, denD (.map U) v ↔ denD (.map X) v ∨ denD (.map Y) v := fun v => by
        rw [sem, eX, eY]
      refine ⟨_, Or.inr ⟨U, Du, rfl, dU, tu, sU, fun v h => ?_⟩, run, lo, fun v => by rw [upper_dyn dU, su]⟩
      rw [su]
      rcases (lo v).mp h with h | h
      · exact Or.inl (hX.inv v h)
      · exact Or.inr (hY.inv v h)

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Unions of gradual types. -/

    section
    variable {L : Level}

    theorem bare_union_op {n : Nat} (hm : L.K + 3 ≤ n) :
        UnionOp L (D (n + 1)) "Elixir.Module.Types.Descr" "bare_union" #[]
          (Elixir.Module.Types.Descr.«bare_union/3» (D n)) where
      call := fun q v₁ v₂ => Erlang.program.«Elixir.Module.Types.Descr:bare_union/3».pure n q v₁ v₂
      spec := fun _ _ _ fx fy =>
        let ⟨u, ru, fu, su, _⟩ := fieldC_union (tks L) (tfc L) (by omega) fx fy; ⟨u, ru, fu, su⟩

    theorem opt_union_op {n : Nat} (hm : L.K + 3 ≤ n) (S : List (Term × Term)) :
        UnionOp L (D (n + 1)) "Elixir.Module.Types.Descr" "-opt_union/3-anonymous-0-" #[.map S]
          (fun q x y => Elixir.Module.Types.Descr.«opt_union/4» (D n) q x y (.map S)) where
      call := fun q v₁ v₂ => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_union/3-anonymous-0-/3».pure]; rfl
      spec := fun _ _ _ fx fy => fieldC_opt_union (tks L) (tfc L) (by omega) fx fy S

    theorem opt_union_dyn_op {n : Nat} (hm : L.K + 3 ≤ n) (S : List (Term × Term)) :
        UnionOp L (D (n + 1)) "Elixir.Module.Types.Descr" "-opt_union/4-fun-0-" #[.map S]
          (fun q x y => Elixir.Module.Types.Descr.«opt_union/4» (D n) q x y (.map S)) where
      call := fun q v₁ v₂ => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_union/4-fun-0-/3».pure]; rfl
      spec := fun _ _ _ fx fy => fieldC_opt_union (tks L) (tfc L) (by omega) fx fy S

    theorem bare_union_dyn (d : Dispatcher) (x y : Term) :
        Elixir.Module.Types.Descr.«bare_union/3» d (.atom "dynamic") x y =
          Elixir.Module.Types.Descr.«dynamic_union/3» d x y (.function "Elixir.Module.Types.Descr" "bare_union" 3 #[]) := by
      unfold Elixir.Module.Types.Descr.«bare_union/3»; rfl

    theorem opt_union_dyn (d : Dispatcher) (x y S : Term) :
        Elixir.Module.Types.Descr.«opt_union/4» d (.atom "dynamic") x y S =
          Elixir.Module.Types.Descr.«dynamic_union/3» d x y (.function "Elixir.Module.Types.Descr" "-opt_union/4-fun-0-" 3 #[S]) := by
      unfold Elixir.Module.Types.Descr.«opt_union/4»; rfl

    theorem union_run_grad (d : Dispatcher) {X Y : List (Term × Term)} (nX : X ≠ []) (nY : Y ≠ [])
        (g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome) :
        Elixir.Module.Types.Descr.«bare_union/2» d (.map X) (.map Y) =
          Elixir.Module.Types.Descr.«symmetrical_merge/3» d (.map (alignT X)) (.map (alignT Y))
            (.function "Elixir.Module.Types.Descr" "bare_union" 3 #[]) := by
      unfold Elixir.Module.Types.Descr.«bare_union/2»
      cases hX : mapLookup X (.atom "dynamic") <;> cases hY : mapLookup Y (.atom "dynamic") <;> rw [hX, hY] at g <;>
        simp at g <;>
        simp [getMapKeys_single, Erlang.erlang.«==/2», hX, hY, nX, nY, unfold_map, Erlang.maps.«put/3», alignT]

    theorem opt_union_run_grad (d : Dispatcher) {X Y : List (Term × Term)} (S : Term) (nX : X ≠ []) (nY : Y ≠ [])
        (g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome) :
        Elixir.Module.Types.Descr.«opt_union/3» d (.map X) (.map Y) S =
          Elixir.Module.Types.Descr.«symmetrical_merge/3» d (.map (alignT X)) (.map (alignT Y))
            (.function "Elixir.Module.Types.Descr" "-opt_union/3-anonymous-0-" 3 #[S]) := by
      unfold Elixir.Module.Types.Descr.«opt_union/3»
      cases hX : mapLookup X (.atom "dynamic") <;> cases hY : mapLookup Y (.atom "dynamic") <;> rw [hX, hY] at g <;>
        simp at g <;>
        simp [getMapKeys_single, Erlang.erlang.«==/2», hX, hY, nX, nY, unfold_map, Erlang.maps.«put/3», alignT]

    theorem GC.shape {a : Term} (ha : GC L a) : a = .atom "term" ∨ ∃ X, a = .map X := by
      rcases ha with (h | ⟨X, rfl, -⟩) | ⟨X, -, rfl, -⟩
      · exact Or.inl h
      · exact Or.inr ⟨X, rfl⟩
      · exact Or.inr ⟨X, rfl⟩

    theorem GC.static {X : List (Term × Term)} (hX : GC L (.map X)) (st : mapLookup X (.atom "dynamic") = none) :
        TC L (.map X) := by
      rcases hX with h | ⟨X', Dy, e, hD, -⟩
      · exact h
      · simp only [Term.map.injEq] at e; subst e; rw [st] at hD; cases hD

    theorem upper_term : upper (.atom "term") = .atom "term" := rfl

    theorem upper_nil : upper (.map []) = .map [] := rfl

    /-- Unions hold the points of either type, at both bounds. -/
    def USem (L : Level) (a b c : Term) : Prop :=
      (∀ v : TP L, denD c v ↔ denD a v ∨ denD b v) ∧ ∀ v : TP L, denD (upper c) v ↔ denD (upper a) v ∨ denD (upper b) v

    theorem usem_term_l (a : Term) : USem L (.atom "term") a (.atom "term") :=
      ⟨fun v => by simp [denD_term], fun v => by simp [upper_term, denD_term]⟩

    theorem usem_term_r (a : Term) : USem L a (.atom "term") (.atom "term") :=
      ⟨fun v => by simp [denD_term], fun v => by simp [upper_term, denD_term]⟩

    theorem usem_nil_l (a : Term) : USem L (.map []) a a :=
      ⟨fun v => by simp [denD_nil], fun v => by simp [upper_nil, denD_nil]⟩

    theorem usem_nil_r (a : Term) : USem L a (.map []) a :=
      ⟨fun v => by simp [denD_nil], fun v => by simp [upper_nil, denD_nil]⟩

    theorem usem_tc {a b c : Term} (ha : TC L a) (hb : TC L b) (hc : TC L c)
        (sem : ∀ v : TP L, denD c v ↔ denD a v ∨ denD b v) : USem L a b c :=
      ⟨sem, by rw [upper_tc ha, upper_tc hb, upper_tc hc]; exact sem⟩

    theorem union_nil_l (d : Dispatcher) (Y : List (Term × Term)) :
        Elixir.Module.Types.Descr.«bare_union/2» d (.map []) (.map Y) = .ok (.map Y) := by
      unfold Elixir.Module.Types.Descr.«bare_union/2»; simp [Erlang.erlang.«==/2»]

    theorem union_nil_r (d : Dispatcher) (X : List (Term × Term)) :
        Elixir.Module.Types.Descr.«bare_union/2» d (.map X) (.map []) = .ok (.map X) := by
      unfold Elixir.Module.Types.Descr.«bare_union/2»
      by_cases h : X = [] <;> simp [Erlang.erlang.«==/2», h]

    theorem opt_union_nil_l (d : Dispatcher) (Y : List (Term × Term)) (S : Term) :
        Elixir.Module.Types.Descr.«opt_union/3» d (.map []) (.map Y) S = .ok (.map Y) := by
      unfold Elixir.Module.Types.Descr.«opt_union/3»; simp [Erlang.erlang.«==/2»]

    theorem opt_union_nil_r (d : Dispatcher) (X : List (Term × Term)) (S : Term) :
        Elixir.Module.Types.Descr.«opt_union/3» d (.map X) (.map []) S = .ok (.map X) := by
      unfold Elixir.Module.Types.Descr.«opt_union/3»
      by_cases h : X = [] <;> simp [Erlang.erlang.«==/2», h]

    theorem dyn_isSome {X : List (Term × Term)} (st : ¬TC L (.map X)) (hX : GC L (.map X)) :
        (mapLookup X (.atom "dynamic")).isSome := by
      cases h : mapLookup X (.atom "dynamic")
      · exact absurd (hX.static h) st
      · rfl

    theorem gc_union {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 5 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok c ∧ USem L a b c := by
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 2 := ⟨m - 2, by omega⟩
      rcases ha.shape with rfl | ⟨X, rfl⟩
      · exact ⟨_, GC.tc tc_term, union_term_l _ _, usem_term_l _⟩
      rcases hb.shape with rfl | ⟨Y, rfl⟩
      · exact ⟨_, GC.tc tc_term, union_term_r _ _, usem_term_r _⟩
      by_cases nX : X = []
      · subst nX; exact ⟨_, hb, union_nil_l _ _, usem_nil_l _⟩
      by_cases nY : Y = []
      · subst nY; exact ⟨_, ha, union_nil_r _ _, usem_nil_r _⟩
      by_cases st : TC L (.map X) ∧ TC L (.map Y)
      · obtain ⟨c, hc, run, sem⟩ := tc_union st.1 st.2 (m := k + 2) (by omega)
        exact ⟨c, GC.tc hc, run, usem_tc st.1 st.2 hc sem⟩
      have g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome := by
        by_cases sX : TC L (.map X)
        · exact Or.inr (dyn_isSome (fun h => st ⟨sX, h⟩) hb)
        · exact Or.inl (dyn_isSome sX ha)
      obtain ⟨c, hc, run, lo, up⟩ := merge_aligned (bare_union_op (n := k + 1) (by omega))
        (bare_union_op (n := k) (by omega)) (bare_union_dyn _) ha hb
      exact ⟨c, hc, (union_run_grad _ nX nY g).trans run, lo, up⟩

    theorem gc_opt_union {a b : Term} (ha : GC L a) (hb : GC L b) (S : List (Term × Term)) {m : Nat} (hm : L.K + 5 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_union/3» (D m) a b (.map S) = .ok c ∧ USem L a b c := by
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 2 := ⟨m - 2, by omega⟩
      rcases ha.shape with rfl | ⟨X, rfl⟩
      · exact ⟨_, GC.tc tc_term, opt_union_term_left _ _ _, usem_term_l _⟩
      rcases hb.shape with rfl | ⟨Y, rfl⟩
      · exact ⟨_, GC.tc tc_term, opt_union_term_r _ _ _, usem_term_r _⟩
      by_cases nX : X = []
      · subst nX; exact ⟨_, hb, opt_union_nil_l _ _ _, usem_nil_l _⟩
      by_cases nY : Y = []
      · subst nY; exact ⟨_, ha, opt_union_nil_r _ _ _, usem_nil_r _⟩
      by_cases st : TC L (.map X) ∧ TC L (.map Y)
      · obtain ⟨c, hc, run, sem⟩ := tc_opt_union st.1 st.2 S (m := k + 2) (by omega)
        exact ⟨c, GC.tc hc, run, usem_tc st.1 st.2 hc sem⟩
      have g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome := by
        by_cases sX : TC L (.map X)
        · exact Or.inr (dyn_isSome (fun h => st ⟨sX, h⟩) hb)
        · exact Or.inl (dyn_isSome sX ha)
      obtain ⟨c, hc, run, lo, up⟩ := merge_aligned (opt_union_op (n := k + 1) (by omega) S)
        (opt_union_dyn_op (n := k) (by omega) S) (fun x y => opt_union_dyn _ x y _) ha hb
      exact ⟨c, hc, (opt_union_run_grad _ _ nX nY g).trans run, lo, up⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Intersections of gradual types. -/

    section
    variable {L : Level}

    /-- Field operations an intersection combines fields with: they keep the common points of their fields. -/
    structure InterOp (L : Level) (n : Nat) (module name : String) (caps : Array Term)
        (f : Term → Term → Term → Except Exception Term) : Prop where
      call : ∀ q v₁ v₂, (D (n + 1)).pure (.function module name 3 caps) #[q, v₁, v₂] = f q v₁ v₂
      spec : ∀ name x y, FC L name x → FC L name y → ∃ w, f (.atom name) x y = .ok w ∧
        (kept (.atom name, w) = Bool.true → FC L name w) ∧
        ∀ p, PtOkD L.E L.den L.tl name p → dn name (keptO name w) p = (dn name (some x) p && dn name (some y) p)

    /-- Intersecting static types keeps their common points. -/
    theorem inter_descr {n : Nat} {module name : String} {caps : Array Term}
        {f : Term → Term → Term → Except Exception Term} (op : InterOp L n module name caps f)
        {A B : List (Term × Term)} (sA : DC L A) (sB : DC L B) :
        ∃ I, Elixir.Module.Types.Descr.«symmetrical_intersection/3» (D (n + 1)) (.map A) (.map B)
            (.function module name 3 caps) = .ok (.map I) ∧ DC L I ∧
          ∀ v : TP L, denD (.map I) v ↔ denD (.map A) v ∧ denD (.map B) v := by
      obtain ⟨I, run, look⟩ := intersect_gen n module name caps f op.call A B sA.atoms (fun q x y hx hy => by
        obtain ⟨k, -, rfl⟩ := sA.keys q (by simp [hx])
        obtain ⟨w, rw', -⟩ := op.spec k x y (sA.fields k x hx) (sB.fields k y hy)
        exact ⟨w, rw'⟩)
      have keysI : ∀ q, (mapLookup I q).isSome → (mapLookup A q).isSome := by
        intro q h
        cases hA : mapLookup A q with
        | none => rw [(look q).1 hA] at h; cases h
        | some _ => rfl
      obtain ⟨cI, sem, -⟩ := inter_gen (slh := False) sA sB f
        (fun k => ⟨(look _).1, (look _).2.1, fun x y w hx hy rw' => (look _).2.2 x y w hx hy rw'⟩) keysI
        (fun k x y fx fy => let ⟨w, rw', kw, sw⟩ := op.spec k x y fx fy; ⟨w, rw', fun h => ⟨kw h, False.elim⟩, sw⟩)
      exact ⟨I, run, cI, fun v => by simp only [denD_map, sem _ _ v.2.2, Bool.and_eq_true]⟩

    /-- Intersections of dynamic parts. -/
    theorem dyn_inter_tc {n : Nat} {module name : String} {caps : Array Term}
        {f : Term → Term → Term → Except Exception Term} (op : InterOp L n module name caps f)
        {a b : Term} (ha : TC L a) (hb : TC L b) :
        ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«dynamic_intersection/3» (D (n + 1)) a b (.function module name 3 caps) =
          .ok c ∧ ∀ v : TP L, denD c v ↔ denD a v ∧ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · exact ⟨b, hb, by unfold Elixir.Module.Types.Descr.«dynamic_intersection/3»; rfl, fun v => by simp [denD_term]⟩
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact ⟨_, Or.inr ⟨A, rfl, sA⟩, by unfold Elixir.Module.Types.Descr.«dynamic_intersection/3»; rfl,
          fun v => by simp [denD_term]⟩
      obtain ⟨I, run, sI, sem⟩ := inter_descr op sA sB
      refine ⟨_, Or.inr ⟨I, rfl, sI⟩, ?_, sem⟩
      unfold Elixir.Module.Types.Descr.«dynamic_intersection/3»
      simpa [unfold_map] using run

    /-- The dynamic field of an intersection: dropped when empty. -/
    def dynZero : Term → Term
      | .map [] => .integer 0
      | c => c

    theorem bare_inter_dyn (d : Dispatcher) {x y c : Term}
        (run : Elixir.Module.Types.Descr.«dynamic_intersection/3» d x y
          (.function "Elixir.Module.Types.Descr" "bare_intersection" 3 #[]) = .ok c) (hc : TC L c) :
        Elixir.Module.Types.Descr.«bare_intersection/3» d (.atom "dynamic") x y = .ok (dynZero c) := by
      unfold Elixir.Module.Types.Descr.«bare_intersection/3»
      rcases hc with rfl | ⟨C, rfl, -⟩
      · have c : Term.compare (.atom "term") (.map []) ≠ .eq := by rw [compare_eq_step]; simp [Compare.compareStep]
        simp [run, Erlang.erlang.«==/2», dynZero, c]
      · cases C <;> simp [run, Erlang.erlang.«==/2», dynZero]

    theorem opt_inter_dyn (d : Dispatcher) {x y c S : Term}
        (run : Elixir.Module.Types.Descr.«dynamic_intersection/3» d x y
          (.function "Elixir.Module.Types.Descr" "-opt_intersection/4-fun-0-" 3 #[S]) = .ok c) (hc : TC L c) :
        Elixir.Module.Types.Descr.«opt_intersection/4» d (.atom "dynamic") x y S = .ok (dynZero c) := by
      unfold Elixir.Module.Types.Descr.«opt_intersection/4»
      rcases hc with rfl | ⟨C, rfl, -⟩
      · have c : Term.compare (.atom "term") (.map []) ≠ .eq := by rw [compare_eq_step]; simp [Compare.compareStep]
        simp [run, Erlang.erlang.«==/2», dynZero, c]
      · cases C <;> simp [run, Erlang.erlang.«==/2», dynZero]

    /-- Intersections hold the common points of the types, at both bounds. -/
    def ISem (L : Level) (a b c : Term) : Prop :=
      (∀ v : TP L, denD c v ↔ denD a v ∧ denD b v) ∧ ∀ v : TP L, denD (upper c) v ↔ denD (upper a) v ∧ denD (upper b) v

    /-- Intersecting aligned gradual types intersects their fields and their upper bounds. When the upper bounds do not
    meet, the dynamic part is dropped, and so are the points of the fields, which the upper bounds include. -/
    theorem inter_aligned {n : Nat} {module name module' name' : String} {caps caps' : Array Term}
        {f f' : Term → Term → Term → Except Exception Term} (op : InterOp L (n + 1) module name caps f)
        (op' : InterOp L n module' name' caps' f')
        (dyn : ∀ x y c, Elixir.Module.Types.Descr.«dynamic_intersection/3» (D (n + 1)) x y
          (.function module' name' 3 caps') = .ok c → TC L c → f (.atom "dynamic") x y = .ok (dynZero c))
        {X Y : List (Term × Term)} (hX : GC L (.map X)) (hY : GC L (.map Y)) :
        ∃ c, GC L c ∧
          Elixir.Module.Types.Descr.«symmetrical_intersection/3» (D (n + 2)) (.map (alignT X)) (.map (alignT Y))
            (.function module name 3 caps) = .ok c ∧ ISem L (.map X) (.map Y) c := by
      obtain ⟨dX, sX, eX⟩ := align_gc hX
      obtain ⟨dY, sY, eY⟩ := align_gc hY
      obtain ⟨Di, ti, ri, si⟩ := dyn_inter_tc op' hX.up_tc hY.up_tc
      have rD := dyn _ _ _ ri ti
      obtain ⟨I, run, look⟩ := intersect_gen (n + 1) module name caps f op.call (alignT X) (alignT Y)
        (rmDyn_atoms sX) (fun q x y hx hy => by
          by_cases e : exactCompare q (.atom "dynamic") = .eq
          · obtain rfl := (exactCompare_eq_atom q _).mp e
            rw [dX] at hx; rw [dY] at hy; cases hx; cases hy
            exact ⟨_, rD⟩
          · have hx' : mapLookup (rmDyn (alignT X)) q = some x := by rw [lookup_rmDyn, if_neg e]; exact hx
            have hy' : mapLookup (rmDyn (alignT Y)) q = some y := by rw [lookup_rmDyn, if_neg e]; exact hy
            obtain ⟨k, -, rfl⟩ := sX.keys q (by simp [hx'])
            obtain ⟨w, rw', -⟩ := op.spec k x y (sX.fields k x hx') (sY.fields k y hy')
            exact ⟨w, rw'⟩)
      have lookR : ∀ k, (mapLookup (rmDyn (alignT X)) (.atom k) = none → mapLookup (rmDyn I) (.atom k) = none) ∧
          (mapLookup (rmDyn (alignT Y)) (.atom k) = none → mapLookup (rmDyn I) (.atom k) = none) ∧
          (∀ x y w, mapLookup (rmDyn (alignT X)) (.atom k) = some x → mapLookup (rmDyn (alignT Y)) (.atom k) = some y →
            f (.atom k) x y = .ok w → mapLookup (rmDyn I) (.atom k) = keptO k w) := by
        intro k
        simp only [lookup_rmDyn]
        by_cases e : exactCompare (.atom k) (.atom "dynamic") = .eq
        · simp [e]
        · simp only [e, if_false]; exact ⟨(look _).1, (look _).2.1, fun x y w hx hy rw' => (look _).2.2 x y w hx hy rw'⟩
      have keysI : ∀ q, (mapLookup (rmDyn I) q).isSome → (mapLookup (rmDyn (alignT X)) q).isSome := by
        intro q h
        simp only [lookup_rmDyn] at h ⊢
        by_cases e : exactCompare q (.atom "dynamic") = .eq
        · simp [e] at h
        · simp only [e, if_false] at h ⊢
          cases hA : mapLookup (alignT X) q with
          | none => rw [(look q).1 hA] at h; cases h
          | some _ => rfl
      obtain ⟨cI, sem, -⟩ := inter_gen (slh := False) sX sY f lookR keysI
        (fun k x y fx fy => let ⟨w, rw', kw, sw⟩ := op.spec k x y fx fy; ⟨w, rw', fun h => ⟨kw h, False.elim⟩, sw⟩)
      have lo : ∀ v : TP L, denD (.map I) v ↔ denD (.map X) v ∧ denD (.map Y) v := fun v => by
        rw [← denD_rmDyn I, ← eX, ← eY, ← denD_rmDyn (alignT X), ← denD_rmDyn (alignT Y)]
        simp only [denD_map, sem _ _ v.2.2, Bool.and_eq_true]
      have dI := (look _).2.2 _ _ _ dX dY rD
      -- The upper bounds meet unless their intersection is the empty map.
      by_cases z : Di = .map []
      · subst z
        have none : mapLookup I (.atom "dynamic") = none := by rw [dI]; simp [dynZero, kept]
        have tI : TC L (.map I) := Or.inr ⟨I, rfl, by rw [← rmDyn_static none]; exact cI⟩
        have empty : ∀ v : TP L, ¬(denD (upper (.map X)) v ∧ denD (upper (.map Y)) v) := fun v h =>
          denD_nil v ((si v).mpr h)
        refine ⟨_, GC.tc tI, run, lo, fun v => ?_⟩
        rw [upper_tc tI, lo]
        exact ⟨fun h => absurd ⟨hX.inv v h.1, hY.inv v h.2⟩ (empty v), fun h => absurd h (empty v)⟩
      · have kD : dynZero Di = Di := by
          rcases ti with rfl | ⟨C, rfl, -⟩
          · rfl
          · cases C
            · exact absurd rfl z
            · rfl
        have keep : kept (.atom "dynamic", Di) = Bool.true := by
          rcases ti with rfl | ⟨C, rfl, -⟩
          · simp [kept]
          · simp [kept]
        have hD : mapLookup I (.atom "dynamic") = some Di := by rw [dI, kD]; simp [keep]
        refine ⟨_, Or.inr ⟨I, Di, rfl, hD, ti, cI, fun v h => ?_⟩, run, lo, fun v => by rw [upper_dyn hD, si]⟩
        rw [si]
        obtain ⟨h₁, h₂⟩ := (lo v).mp h
        exact ⟨hX.inv v h₁, hY.inv v h₂⟩

    theorem bare_inter_op {n : Nat} (hm : L.K + 3 ≤ n) :
        InterOp L n "Elixir.Module.Types.Descr" "bare_intersection" #[]
          (Elixir.Module.Types.Descr.«bare_intersection/3» (D n)) where
      call := fun q v₁ v₂ => Erlang.program.«Elixir.Module.Types.Descr:bare_intersection/3».pure n q v₁ v₂
      spec := fun _ _ _ fx fy =>
        let ⟨w, rw', k, sw⟩ := fieldC_inter (tks L) (tfc L) (by omega) fx fy; ⟨w, rw', fun h => (k h).1, sw⟩

    theorem opt_inter_op {n : Nat} (hm : L.K + 3 ≤ n) (S : List (Term × Term)) :
        InterOp L n "Elixir.Module.Types.Descr" "-opt_intersection/3-anonymous-0-" #[.map S]
          (fun q x y => Elixir.Module.Types.Descr.«opt_intersection/4» (D n) q x y (.map S)) where
      call := fun q v₁ v₂ => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_intersection/3-anonymous-0-/3».pure]; rfl
      spec := fun _ _ _ fx fy => fieldC_opt_inter (tks L) (tfc L) (by omega) fx fy S

    theorem opt_inter_dyn_op {n : Nat} (hm : L.K + 3 ≤ n) (S : List (Term × Term)) :
        InterOp L n "Elixir.Module.Types.Descr" "-opt_intersection/4-fun-0-" #[.map S]
          (fun q x y => Elixir.Module.Types.Descr.«opt_intersection/4» (D n) q x y (.map S)) where
      call := fun q v₁ v₂ => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_intersection/4-fun-0-/3».pure]; rfl
      spec := fun _ _ _ fx fy => fieldC_opt_inter (tks L) (tfc L) (by omega) fx fy S

    theorem inter_run_grad (d : Dispatcher) {X Y : List (Term × Term)}
        (g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome) :
        Elixir.Module.Types.Descr.«bare_intersection/2» d (.map X) (.map Y) =
          Elixir.Module.Types.Descr.«symmetrical_intersection/3» d (.map (alignT X)) (.map (alignT Y))
            (.function "Elixir.Module.Types.Descr" "bare_intersection" 3 #[]) := by
      unfold Elixir.Module.Types.Descr.«bare_intersection/2»
      cases hX : mapLookup X (.atom "dynamic") <;> cases hY : mapLookup Y (.atom "dynamic") <;> rw [hX, hY] at g <;>
        simp at g <;>
        simp [getMapKeys_single, hX, hY, unfold_map, Erlang.maps.«put/3», alignT]

    theorem opt_inter_run_grad (d : Dispatcher) {X Y : List (Term × Term)} (S : Term)
        (g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome) :
        Elixir.Module.Types.Descr.«opt_intersection/3» d (.map X) (.map Y) S =
          Elixir.Module.Types.Descr.«symmetrical_intersection/3» d (.map (alignT X)) (.map (alignT Y))
            (.function "Elixir.Module.Types.Descr" "-opt_intersection/3-anonymous-0-" 3 #[S]) := by
      unfold Elixir.Module.Types.Descr.«opt_intersection/3»
      cases hX : mapLookup X (.atom "dynamic") <;> cases hY : mapLookup Y (.atom "dynamic") <;> rw [hX, hY] at g <;>
        simp at g <;>
        simp [getMapKeys_single, hX, hY, unfold_map, Erlang.maps.«put/3», alignT]

    theorem isem_term_l (a : Term) : ISem L (.atom "term") a a :=
      ⟨fun v => by simp [denD_term], fun v => by simp [upper_term, denD_term]⟩

    theorem isem_term_r (a : Term) : ISem L a (.atom "term") a :=
      ⟨fun v => by simp [denD_term], fun v => by simp [upper_term, denD_term]⟩

    theorem isem_tc {a b c : Term} (ha : TC L a) (hb : TC L b) (hc : TC L c)
        (sem : ∀ v : TP L, denD c v ↔ denD a v ∧ denD b v) : ISem L a b c :=
      ⟨sem, by rw [upper_tc ha, upper_tc hb, upper_tc hc]; exact sem⟩

    theorem gc_inter {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 5 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok c ∧ ISem L a b c := by
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 2 := ⟨m - 2, by omega⟩
      rcases ha.shape with rfl | ⟨X, rfl⟩
      · exact ⟨_, hb, inter_term_left _ _, isem_term_l _⟩
      rcases hb.shape with rfl | ⟨Y, rfl⟩
      · exact ⟨_, ha, inter_term_right _ _, isem_term_r _⟩
      by_cases st : TC L (.map X) ∧ TC L (.map Y)
      · obtain ⟨c, hc, run, sem⟩ := tc_inter st.1 st.2 (m := k + 2) (by omega)
        exact ⟨c, GC.tc hc, run, isem_tc st.1 st.2 hc sem⟩
      have g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome := by
        by_cases sX : TC L (.map X)
        · exact Or.inr (dyn_isSome (fun h => st ⟨sX, h⟩) hb)
        · exact Or.inl (dyn_isSome sX ha)
      obtain ⟨c, hc, run, sem⟩ := inter_aligned (bare_inter_op (n := k + 1) (by omega))
        (bare_inter_op (n := k) (by omega)) (fun _ _ _ r t => bare_inter_dyn _ r t) ha hb
      exact ⟨c, hc, (inter_run_grad _ g).trans run, sem⟩

    theorem gc_opt_inter {a b : Term} (ha : GC L a) (hb : GC L b) (S : List (Term × Term)) {m : Nat} (hm : L.K + 5 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_intersection/3» (D m) a b (.map S) = .ok c ∧ ISem L a b c := by
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 2 := ⟨m - 2, by omega⟩
      rcases ha.shape with rfl | ⟨X, rfl⟩
      · exact ⟨_, hb, opt_inter_term_l _ _ _, isem_term_l _⟩
      rcases hb.shape with rfl | ⟨Y, rfl⟩
      · exact ⟨_, ha, opt_inter_term_r _ _ _, isem_term_r _⟩
      by_cases st : TC L (.map X) ∧ TC L (.map Y)
      · obtain ⟨c, hc, run, sem⟩ := tc_opt_inter st.1 st.2 S (m := k + 2) (by omega)
        exact ⟨c, GC.tc hc, run, isem_tc st.1 st.2 hc sem⟩
      have g : (mapLookup X (.atom "dynamic")).isSome ∨ (mapLookup Y (.atom "dynamic")).isSome := by
        by_cases sX : TC L (.map X)
        · exact Or.inr (dyn_isSome (fun h => st ⟨sX, h⟩) hb)
        · exact Or.inl (dyn_isSome sX ha)
      obtain ⟨c, hc, run, sem⟩ := inter_aligned (opt_inter_op (n := k + 1) (by omega) S)
        (opt_inter_dyn_op (n := k) (by omega) S) (fun _ _ _ r t => opt_inter_dyn _ r t) ha hb
      exact ⟨c, hc, (opt_inter_run_grad _ _ g).trans run, sem⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Differences of gradual types. -/

    section
    variable {L : Level}

    /-- Field operations a difference removes fields with: they keep the points of the first field outside the second. -/
    structure DiffOp (L : Level) (n : Nat) (fn : Term) (f : Term → Term → Term → Except Exception Term) : Prop where
      call : ∀ q v₁ v₂, (D (n + 1)).pure fn #[q, v₁, v₂] = f q v₁ v₂
      spec : ∀ name x y, FC L name x → FC L name y → ∃ w, f (.atom name) x y = .ok w ∧
        (kept (.atom name, w) = Bool.true → FC L name w) ∧
        ∀ p, PtOkD L.E L.den L.tl name p → dn name (keptO name w) p = (dn name (some x) p && !dn name (some y) p)

    /-- Differences of static parts. -/
    theorem dyn_diff_tc {n : Nat} {fn : Term} {f : Term → Term → Term → Except Exception Term} (op : DiffOp L n fn f)
        {a b : Term} (ha : TC L a) (hb : TC L b) :
        ∃ c, TC L c ∧ Elixir.Module.Types.Descr.«dynamic_difference/3» (D (n + 2)) a b fn = .ok c ∧
          ∀ v : TP L, denD c v ↔ denD a v ∧ ¬denD b v := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · have c : Term.compare (.atom "term") (.map []) ≠ .eq := by rw [compare_eq_step]; simp [Compare.compareStep]
        refine ⟨_, tc_nil, ?_, fun v => by simp [denD_nil, denD_term]⟩
        unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
        simp [Erlang.erlang.«==/2», c]
      by_cases nB : B = []
      · subst nB
        refine ⟨a, ha, ?_, fun v => by simp [denD_nil]⟩
        unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
        simp [Erlang.erlang.«==/2»]
      have left : ∃ A, DC L A ∧ (∀ v : TP L, denD a v ↔ denD (.map A) v) ∧
          Elixir.Module.Types.Descr.«dynamic_difference/3» (D (n + 2)) a (.map B) fn =
            Elixir.Module.Types.Descr.«dynamic_difference/3» (D (n + 2)) (.map A) (.map B) fn := by
        rcases ha with rfl | ⟨A, rfl, sA⟩
        · obtain ⟨T, term, sT, -, all⟩ := termT L
          refine ⟨T, sT, fun v => ⟨fun _ => all v, fun _ => denD_term v⟩, ?_⟩
          unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
          simp [Erlang.erlang.«==/2», nB, unfold_map, term]
        · exact ⟨A, sA, fun v => Iff.rfl, rfl⟩
      obtain ⟨A, sA, eA, rA⟩ := left
      obtain ⟨O, fold, sO, dO, -⟩ := diff_gen (slh := False) n fn f sA sB op.call
        (fun k x y fx fy => let ⟨w, rw', kw, sw⟩ := op.spec k x y fx fy; ⟨w, rw', fun h => ⟨kw h, False.elim⟩, sw⟩)
      refine ⟨_, Or.inr ⟨O, rfl, sO⟩, ?_, fun v => ?_⟩
      · rw [rA]
        unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
        simp [Erlang.erlang.«==/2», nB, unfold_map, Erlang.maps.«fold/3»]
        simpa using fold
      · rw [eA]
        simp only [denD_map, dO _ _ v.2.2]
        cases dn v.1.1 (mapLookup A (.atom v.1.1)) v.1.2 <;> cases dn v.1.1 (mapLookup B (.atom v.1.1)) v.1.2 <;> simp

    /-- The static part of a type, as `pop_dynamic/1` takes it. -/
    def lower (a : Term) : Term :=
      match a with
      | .map X => .map (rmDyn X)
      | _ => a

    theorem GC.low_tc {a : Term} (ha : GC L a) : TC L (lower a) := by
      rcases ha with (rfl | ⟨X, rfl, sX⟩) | ⟨X, -, rfl, -, -, sX, -⟩
      · exact tc_term
      · exact Or.inr ⟨_, rfl, by rw [rmDyn_static sX.static]; exact sX⟩
      · exact Or.inr ⟨_, rfl, sX⟩

    theorem denD_lower (a : Term) (v : TP L) : denD (lower a) v ↔ denD a v := by
      cases a <;> simp [lower, denD_rmDyn]

    theorem pop_dyn (Y : List (Term × Term)) :
        Elixir.Map.«pop/3» (.map Y) (.atom "dynamic") (.map Y) = .ok (.tuple #[upper (.map Y), lower (.map Y)]) := by
      cases h : mapLookup Y (.atom "dynamic") <;>
        simp [Elixir.Map.«pop/3», Erlang.maps.«take/2», h, upper, lower, rmDyn]
      rw [← rmDyn, rmDyn_static h]

    /-- Differences with a gradual type subtract the upper bound from the static part, and the static part from the
    upper bound. -/
    theorem diff_run_grad (d : Dispatcher) {a : Term} {Y : List (Term × Term)} (nY : Y ≠ [])
        (ha : a = .atom "term" ∨ ∃ X, a = .map X)
        (g : (∃ X, a = .map X ∧ (mapLookup X (.atom "dynamic")).isSome) ∨ (mapLookup Y (.atom "dynamic")).isSome) :
        Elixir.Module.Types.Descr.«bare_difference/2» d a (.map Y) = (do
          let dp ← Elixir.Module.Types.Descr.«dynamic_difference/3» d (upper a) (lower (.map Y))
            (.function "Elixir.Module.Types.Descr" "bare_difference" 3 #[])
          let sp ← Elixir.Module.Types.Descr.«dynamic_difference/3» d (lower a) (upper (.map Y))
            (.function "Elixir.Module.Types.Descr" "bare_difference" 3 #[])
          Elixir.Module.Types.Descr.«put_dynamic/2» sp dp) := by
      unfold Elixir.Module.Types.Descr.«bare_difference/2»
      rcases ha with rfl | ⟨X, rfl⟩
      · cases hY : mapLookup Y (.atom "dynamic") <;> simp [hY] at g
        simp [Erlang.erlang.«==/2», nY, unfold_map, getMapKeys_single, hY, Erlang.erlang.«is_map_key/2», any_key, pop_dyn]
        rfl
      · have c : Term.compare (.map X) (.atom "term") ≠ .eq := by rw [compare_eq_step]; simp [Compare.compareStep]
        have gr : ((mapLookup X (.atom "dynamic")).isSome || (mapLookup Y (.atom "dynamic")).isSome) = Bool.true := by
          rcases g with ⟨X', e, h⟩ | h
          · simp only [Term.map.injEq] at e; subst e; simp [h]
          · simp [h]
        cases hX : mapLookup X (.atom "dynamic") <;> cases hY : mapLookup Y (.atom "dynamic") <;> simp [hX, hY] at gr <;>
          simp [Erlang.erlang.«==/2», nY, c, unfold_map, getMapKeys_single, hX, hY, Erlang.erlang.«is_map_key/2», any_key,
            pop_dyn, Lynx.Except.orElse]

    theorem opt_diff_run_grad (d : Dispatcher) {a : Term} {Y : List (Term × Term)} (S : Term) (nY : Y ≠ [])
        (ha : a = .atom "term" ∨ ∃ X, a = .map X)
        (g : (∃ X, a = .map X ∧ (mapLookup X (.atom "dynamic")).isSome) ∨ (mapLookup Y (.atom "dynamic")).isSome) :
        Elixir.Module.Types.Descr.«opt_difference/3» d a (.map Y) S = (do
          let dp ← Elixir.Module.Types.Descr.«dynamic_difference/3» d (upper a) (lower (.map Y))
            (.function "Elixir.Module.Types.Descr" "-opt_difference/3-anonymous-1-" 3 #[S])
          let sp ← Elixir.Module.Types.Descr.«dynamic_difference/3» d (lower a) (upper (.map Y))
            (.function "Elixir.Module.Types.Descr" "-opt_difference/3-anonymous-2-" 3 #[S])
          Elixir.Module.Types.Descr.«put_dynamic/2» sp dp) := by
      unfold Elixir.Module.Types.Descr.«opt_difference/3»
      rcases ha with rfl | ⟨X, rfl⟩
      · cases hY : mapLookup Y (.atom "dynamic") <;> simp [hY] at g
        simp [Erlang.erlang.«==/2», nY, unfold_map, getMapKeys_single, hY, Erlang.erlang.«is_map_key/2», any_key, pop_dyn]
        rfl
      · have c : Term.compare (.map X) (.atom "term") ≠ .eq := by rw [compare_eq_step]; simp [Compare.compareStep]
        have gr : ((mapLookup X (.atom "dynamic")).isSome || (mapLookup Y (.atom "dynamic")).isSome) = Bool.true := by
          rcases g with ⟨X', e, h⟩ | h
          · simp only [Term.map.injEq] at e; subst e; simp [h]
          · simp [h]
        cases hX : mapLookup X (.atom "dynamic") <;> cases hY : mapLookup Y (.atom "dynamic") <;> simp [hX, hY] at gr <;>
          simp [Erlang.erlang.«==/2», nY, c, unfold_map, getMapKeys_single, hX, hY, Erlang.erlang.«is_map_key/2», any_key,
            pop_dyn, Lynx.Except.orElse]

    /-- Top-level types equal by comparison hold the same points. -/
    theorem tc_congr {a b : Term} (ha : TC L a) (hb : TC L b) (e : Term.compare a b = .eq) (v : TP L) :
        denD a v ↔ denD b v := by
      rcases ha with rfl | ⟨A, rfl, sA⟩ <;> rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact Iff.rfl
      · rw [compare_eq_step] at e; simp [Compare.compareStep] at e
      · rw [compare_eq_step] at e; simp [Compare.compareStep] at e
      · simp only [denD_map, descr_congr (tks L) (tfc L) sA sB e v.1.1 v.1.2 v.2.2]

    /-- Putting a dynamic part that includes the static one: a gradual type with these bounds. -/
    theorem put_dyn_sem {sp dp : Term} (hs : TC L sp) (hd : TC L dp) (inv : ∀ v : TP L, denD sp v → denD dp v) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«put_dynamic/2» sp dp = .ok c ∧
          (∀ v : TP L, denD c v ↔ denD sp v) ∧ ∀ v : TP L, denD (upper c) v ↔ denD dp v := by
      rcases hs with rfl | ⟨S, rfl, sS⟩
      · exact ⟨_, GC.tc tc_term, by unfold Elixir.Module.Types.Descr.«put_dynamic/2»; rfl, fun v => Iff.rfl,
          fun v => ⟨fun _ => inv v (denD_term v), fun _ => denD_term v⟩⟩
      have tS : TC L (.map S) := Or.inr ⟨S, rfl, sS⟩
      by_cases e₁ : Term.compare (.map S) dp = .eq
      · refine ⟨_, GC.tc tS, ?_, fun v => Iff.rfl, fun v => by rw [upper_tc tS]; exact tc_congr tS hd e₁ v⟩
        unfold Elixir.Module.Types.Descr.«put_dynamic/2»
        simp [Erlang.erlang.«==/2», e₁, Lynx.Except.guard]
      by_cases e₂ : Term.compare dp (.map []) = .eq
      · have none : ∀ v : TP L, ¬denD dp v := fun v h => denD_nil v ((tc_congr hd tc_nil e₂ v).mp h)
        refine ⟨_, GC.tc tc_nil, ?_, fun v => ⟨fun h => absurd h (denD_nil v), fun h => absurd (inv v h) (none v)⟩,
          fun v => ⟨fun h => absurd h (denD_nil v), fun h => absurd h (none v)⟩⟩
        unfold Elixir.Module.Types.Descr.«put_dynamic/2»
        simp [Erlang.erlang.«==/2», e₁, e₂, Lynx.Except.guard]
      have st := sS.static
      have hD : mapLookup ((.atom "dynamic", dp) :: S) (.atom "dynamic") = some dp := by simp [mapLookup]
      have same : ∀ v : TP L, denD (.map ((.atom "dynamic", dp) :: S)) v ↔ denD (.map S) v := fun v => by
        rw [← denD_rmDyn, rmDyn_cons_dyn, rmDyn_static st]
      refine ⟨_, Or.inr ⟨_, dp, rfl, hD, hd, by rw [rmDyn_cons_dyn, rmDyn_static st]; exact sS,
        fun v h => inv v ((same v).mp h)⟩, ?_, same, fun v => by rw [upper_dyn hD]⟩
      unfold Elixir.Module.Types.Descr.«put_dynamic/2»
      simp [Erlang.erlang.«==/2», e₁, e₂, Lynx.Except.guard, Erlang.maps.«put/3»]

    /-- Differences hold the points of the first type outside the second, crossing the bounds. -/
    def DSem (L : Level) (a b c : Term) : Prop :=
      (∀ v : TP L, denD c v ↔ denD a v ∧ ¬denD (upper b) v) ∧
        ∀ v : TP L, denD (upper c) v ↔ denD (upper a) v ∧ ¬denD b v

    theorem bare_diff_op {n : Nat} (hm : L.K + 4 ≤ n) :
        DiffOp L n (.function "Elixir.Module.Types.Descr" "bare_difference" 3 #[])
          (Elixir.Module.Types.Descr.«bare_difference/3» (D n)) where
      call := fun q v₁ v₂ => Erlang.program.«Elixir.Module.Types.Descr:bare_difference/3».pure n q v₁ v₂
      spec := fun _ _ _ fx fy =>
        let ⟨w, rw', k, sw⟩ := fieldC_diff (tks L) (tfc L) (by omega) fx fy; ⟨w, rw', fun h => (k h).1, sw⟩

    theorem opt_diff_op₁ {n : Nat} (hm : L.K + 4 ≤ n) (S : List (Term × Term)) :
        DiffOp L n (.function "Elixir.Module.Types.Descr" "-opt_difference/3-anonymous-1-" 3 #[.map S])
          (fun q x y => Elixir.Module.Types.Descr.«opt_difference/4» (D n) q x y (.map S)) where
      call := fun q v₁ v₂ => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_difference/3-anonymous-1-/3».pure]; rfl
      spec := fun _ _ _ fx fy => fieldC_opt_diff (tks L) (tfc L) (by omega) fx fy S

    theorem opt_diff_op₂ {n : Nat} (hm : L.K + 4 ≤ n) (S : List (Term × Term)) :
        DiffOp L n (.function "Elixir.Module.Types.Descr" "-opt_difference/3-anonymous-2-" 3 #[.map S])
          (fun q x y => Elixir.Module.Types.Descr.«opt_difference/4» (D n) q x y (.map S)) where
      call := fun q v₁ v₂ => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-opt_difference/3-anonymous-2-/3».pure]; rfl
      spec := fun _ _ _ fx fy => fieldC_opt_diff (tks L) (tfc L) (by omega) fx fy S

    /-- The gradual difference: the dynamic part and the static part, put together. -/
    theorem diff_grad {n : Nat} {fn₁ fn₂ : Term} {f₁ f₂ : Term → Term → Term → Except Exception Term}
        (op₁ : DiffOp L n fn₁ f₁) (op₂ : DiffOp L n fn₂ f₂) {a b : Term} (ha : GC L a) (hb : GC L b) :
        ∃ c, GC L c ∧ (do
          let dp ← Elixir.Module.Types.Descr.«dynamic_difference/3» (D (n + 2)) (upper a) (lower b) fn₁
          let sp ← Elixir.Module.Types.Descr.«dynamic_difference/3» (D (n + 2)) (lower a) (upper b) fn₂
          Elixir.Module.Types.Descr.«put_dynamic/2» sp dp) = .ok c ∧ DSem L a b c := by
      obtain ⟨dp, tdp, rdp, sdp⟩ := dyn_diff_tc op₁ ha.up_tc hb.low_tc
      obtain ⟨sp, tsp, rsp, ssp⟩ := dyn_diff_tc op₂ ha.low_tc hb.up_tc
      obtain ⟨c, hc, rc, lo, up⟩ := put_dyn_sem tsp tdp fun v h => by
        rw [ssp, denD_lower] at h
        rw [sdp, denD_lower]
        exact ⟨ha.inv v h.1, fun h' => h.2 (hb.inv v h')⟩
      refine ⟨c, hc, by simp [rdp, rsp, rc], fun v => ?_, fun v => ?_⟩
      · rw [lo, ssp, denD_lower]
      · rw [up, sdp, denD_lower]

    theorem diff_nil_r (d : Dispatcher) (a : Term) :
        Elixir.Module.Types.Descr.«bare_difference/2» d a (.map []) = .ok a := by
      unfold Elixir.Module.Types.Descr.«bare_difference/2»; simp [Erlang.erlang.«==/2»]

    theorem opt_diff_nil_r (d : Dispatcher) (a S : Term) :
        Elixir.Module.Types.Descr.«opt_difference/3» d a (.map []) S = .ok a := by
      unfold Elixir.Module.Types.Descr.«opt_difference/3»; simp [Erlang.erlang.«==/2»]

    theorem dsem_term_r (a : Term) : DSem L a (.atom "term") (.map []) :=
      ⟨fun v => by simp [denD_nil, upper_term, denD_term], fun v => by simp [upper_nil, denD_nil, denD_term]⟩

    theorem dsem_nil_r (a : Term) : DSem L a (.map []) a :=
      ⟨fun v => by simp [denD_nil, upper_nil], fun v => by simp [denD_nil]⟩

    theorem dsem_tc {a b c : Term} (ha : TC L a) (hb : TC L b) (hc : TC L c)
        (sem : ∀ v : TP L, denD c v ↔ denD a v ∧ ¬denD b v) : DSem L a b c :=
      ⟨by rw [upper_tc hb]; exact sem, by rw [upper_tc ha, upper_tc hc]; exact sem⟩

    theorem gc_diff {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 6 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok c ∧ DSem L a b c := by
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
      rcases hb.shape with rfl | ⟨Y, rfl⟩
      · exact ⟨_, GC.tc tc_nil, diff_term_right _ _, dsem_term_r _⟩
      by_cases nY : Y = []
      · subst nY; exact ⟨a, ha, diff_nil_r _ _, dsem_nil_r _⟩
      by_cases st : TC L a ∧ TC L (.map Y)
      · obtain ⟨c, hc, run, sem⟩ := tc_diff st.1 st.2 (m := n + 2) (by omega)
        exact ⟨c, GC.tc hc, run, dsem_tc st.1 st.2 hc sem⟩
      have g : (∃ X, a = .map X ∧ (mapLookup X (.atom "dynamic")).isSome) ∨ (mapLookup Y (.atom "dynamic")).isSome := by
        by_cases sY : TC L (.map Y)
        · rcases ha.shape with rfl | ⟨X, rfl⟩
          · exact absurd ⟨tc_term, sY⟩ st
          · exact Or.inl ⟨X, rfl, dyn_isSome (fun h => st ⟨h, sY⟩) ha⟩
        · exact Or.inr (dyn_isSome sY hb)
      obtain ⟨c, hc, run, sem⟩ := diff_grad (bare_diff_op (n := n) (by omega)) (bare_diff_op (n := n) (by omega)) ha hb
      exact ⟨c, hc, (diff_run_grad _ nY ha.shape g).trans run, sem⟩

    theorem gc_opt_diff {a b : Term} (ha : GC L a) (hb : GC L b) (S : List (Term × Term)) {m : Nat} (hm : L.K + 6 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_difference/3» (D m) a b (.map S) = .ok c ∧ DSem L a b c := by
      obtain ⟨n, rfl⟩ : ∃ n, m = n + 2 := ⟨m - 2, by omega⟩
      rcases hb.shape with rfl | ⟨Y, rfl⟩
      · exact ⟨_, GC.tc tc_nil, difference_term_term _ _ _, dsem_term_r _⟩
      by_cases nY : Y = []
      · subst nY; exact ⟨a, ha, opt_diff_nil_r _ _ _, dsem_nil_r _⟩
      by_cases st : TC L a ∧ TC L (.map Y)
      · obtain ⟨c, hc, run, sem⟩ := tc_opt_diff st.1 st.2 S (m := n + 2) (by omega)
        exact ⟨c, GC.tc hc, run, dsem_tc st.1 st.2 hc sem⟩
      have g : (∃ X, a = .map X ∧ (mapLookup X (.atom "dynamic")).isSome) ∨ (mapLookup Y (.atom "dynamic")).isSome := by
        by_cases sY : TC L (.map Y)
        · rcases ha.shape with rfl | ⟨X, rfl⟩
          · exact absurd ⟨tc_term, sY⟩ st
          · exact Or.inl ⟨X, rfl, dyn_isSome (fun h => st ⟨h, sY⟩) ha⟩
        · exact Or.inr (dyn_isSome sY hb)
      obtain ⟨c, hc, run, sem⟩ := diff_grad (opt_diff_op₁ (n := n) (by omega) S) (opt_diff_op₂ (n := n) (by omega) S) ha hb
      exact ⟨c, hc, (opt_diff_run_grad _ _ nY ha.shape g).trans run, sem⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Negations of gradual types, and subtyping of gradual types by both bounds. -/

    section
    variable {L : Level}

    /-- Negations swap the bounds. -/
    def GNSem (L : Level) (a c : Term) : Prop :=
      (∀ v : TP L, denD c v ↔ ¬denD (upper a) v) ∧ ∀ v : TP L, denD (upper c) v ↔ ¬denD a v

    theorem nsem_of_dsem {a c : Term} (h : DSem L (.atom "term") a c) : GNSem L a c :=
      ⟨fun v => by simp [h.1 v, denD_term], fun v => by simp [h.2 v, upper_term, denD_term]⟩

    theorem nsem_term : GNSem L (.atom "term") (.map []) :=
      ⟨fun v => by simp [denD_nil, upper_term, denD_term], fun v => by simp [upper_nil, denD_nil, denD_term]⟩

    theorem gc_neg {a : Term} (ha : GC L a) {m : Nat} (hm : L.K + 6 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«bare_negation/1» (D m) a = .ok c ∧ GNSem L a c := by
      rcases ha.shape with rfl | ⟨X, rfl⟩
      · exact ⟨_, GC.tc tc_nil, by simp [Elixir.Module.Types.Descr.«bare_negation/1», Elixir.Module.Types.Descr.«none/0»],
          nsem_term⟩
      obtain ⟨c, hc, run, sem⟩ := gc_diff (GC.tc tc_term) ha hm
      exact ⟨c, hc, by simpa [Elixir.Module.Types.Descr.«bare_negation/1», Elixir.Module.Types.Descr.«term/0»] using run,
        nsem_of_dsem sem⟩

    theorem gc_opt_neg {a : Term} (ha : GC L a) {m : Nat} (hm : L.K + 6 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_negation/1» (D m) a = .ok c ∧ GNSem L a c := by
      rcases ha.shape with rfl | ⟨X, rfl⟩
      · refine ⟨_, GC.tc tc_nil, ?_, nsem_term⟩
        rw [Elixir.Module.Types.Descr.«opt_negation/1».eq_def]
        simp [Elixir.Module.Types.Descr.«none/0»]
      obtain ⟨c, hc, run, sem⟩ := gc_opt_diff (GC.tc tc_term) ha [] hm
      refine ⟨c, hc, ?_, nsem_of_dsem sem⟩
      rw [Elixir.Module.Types.Descr.«opt_negation/1».eq_def]
      simpa [Elixir.Module.Types.Descr.«opt_difference/2», Elixir.Module.Types.Descr.«term/0», unfold_map] using run

    theorem gc_opt_union2 {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 5 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_union/2» (D m) a b = .ok c ∧ USem L a b c := by
      simpa [Elixir.Module.Types.Descr.«opt_union/2»] using gc_opt_union ha hb [] hm

    theorem gc_opt_inter2 {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 5 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_intersection/2» (D m) a b = .ok c ∧ ISem L a b c := by
      simpa [Elixir.Module.Types.Descr.«opt_intersection/2»] using gc_opt_inter ha hb [] hm

    theorem gc_opt_diff2 {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 6 ≤ m) :
        ∃ c, GC L c ∧ Elixir.Module.Types.Descr.«opt_difference/2» (D m) a b = .ok c ∧ DSem L a b c := by
      simpa [Elixir.Module.Types.Descr.«opt_difference/2»] using gc_opt_diff ha hb [] hm

    /-- Each field of an included static type is covered by the other type. -/
    theorem keysub_complete {m : Nat} (hm : L.K + 4 ≤ m) {A B : List (Term × Term)} (sA : DC L A) (sB : DC L B)
        (incl : ∀ v : TP L, denD (.map A) v → denD (.map B) v) : ∀ e ∈ mapEntries A, KeySub (D m) B e.1 e.2 := by
      intro e me
      have hx := mapLookup_of_mem_mapEntries me
      obtain ⟨name, mem, key⟩ := sA.keys e.1 (by simp [hx])
      rw [key] at hx ⊢
      have fx := sA.fields name e.2 hx
      have none : ∀ w, FC L name w → (∀ p, PtOkD L.E L.den L.tl name p → dn name (some w) p = Bool.false) →
          Elixir.Module.Types.Descr.«empty_key?/3» (D m) (.atom name) w (.map []) = .ok (.atom "true") :=
        fun w fw empty => fieldC_empty_none (tks L) (tfc L) (show L.K + 2 ≤ m by omega) fw (fun _ => rfl) empty
      have inc : ∀ p, PtOkD L.E L.den L.tl name p → dn name (some e.2) p = Bool.true →
          dn name (mapLookup B (.atom name)) p = Bool.true := fun p ok h =>
        (denD_map ⟨(name, p), mem, ok⟩).mp (incl ⟨(name, p), mem, ok⟩ ((denD_map _).mpr (by rw [hx]; exact h)))
      cases hy : mapLookup B (.atom name) with
      | none =>
        refine Or.inr ⟨hy, none _ fx fun p ok => ?_⟩
        cases h : dn name (some e.2) p
        · rfl
        · have := inc p ok h; rw [hy, dn_none] at this; cases this
      | some y =>
        obtain ⟨w, run, k, sem⟩ := fieldC_diff (tks L) (tfc L) (show L.K + 2 + 2 ≤ m by omega) fx (sB.fields name y hy)
        refine Or.inl ⟨y, w, hy, run, ?_⟩
        cases kw : kept (.atom name, w)
        · rcases kept_of_ne kw with h | h
          · exact Or.inl h
          · exact Or.inr (Or.inl h)
        · refine Or.inr (Or.inr (none w (k kw).1 fun p ok => ?_))
          have := sem p ok
          rw [keptO_true kw] at this
          rw [this]
          cases h : dn name (some e.2) p
          · rfl
          · have := inc p ok h; rw [hy] at this; simp [this]

    /-- The subtraction check of `subtype?/2` is complete on top-level types. -/
    theorem esub_complete {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 4 ≤ m)
        (incl : ∀ v : TP L, denD a v → denD b v) :
        Elixir.Module.Types.Descr.«empty_difference_subtype?/3» (D m) a b (.map []) = .ok (.atom "true") := by
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · rw [Elixir.Module.Types.Descr.«empty_difference_subtype?/3».eq_def]
        rcases ha with rfl | ⟨A, rfl, sA⟩
        · simp [getMapKeys]
        · simp [getMapKeys_single, sA.static]
      have left : ∃ A, DC L A ∧ (∀ v : TP L, denD a v ↔ denD (.map A) v) ∧
          Elixir.Module.Types.Descr.«empty_difference_subtype?/3» (D m) a (.map B) (.map []) =
            (do
              let it ← Erlang.maps.«next/1» (Term.list ((mapEntries A).map fun (e : Term × Term) => .tuple #[e.1, e.2]))
              Elixir.Module.Types.Descr.«iterator_empty_difference_subtype?/3» (D m) it (.map B) (.map [])) := by
        rw [Elixir.Module.Types.Descr.«empty_difference_subtype?/3».eq_def]
        rcases ha with rfl | ⟨A, rfl, sA⟩
        · obtain ⟨T, term, sT, -, all⟩ := termT L
          refine ⟨T, sT, fun v => ⟨fun _ => all v, fun _ => denD_term v⟩, ?_⟩
          simp [getMapKeys, term, unfold_map, Erlang.maps.«iterator/1»]
        · exact ⟨A, sA, fun v => Iff.rfl, by simp [getMapKeys_single, sA.static, unfold_map, Erlang.maps.«iterator/1»]⟩
      obtain ⟨A, sA, eA, rA⟩ := left
      rw [rA]
      exact iterator_sub (D m) B (mapEntries A) (keysub_complete hm sA sB fun v h => incl v ((eA v).mpr h))

    theorem sstatic_complete {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 4 ≤ m)
        (incl : ∀ v : TP L, denD a v → denD b v) :
        Elixir.Module.Types.Descr.«subtype_static?/2» (D m) a b = .ok (.atom "true") := by
      unfold Elixir.Module.Types.Descr.«subtype_static?/2»
      by_cases same : exactCompare b a = .eq
      · simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», same]
      · simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», same, Elixir.Module.Types.Descr.«empty_difference_subtype?/2»,
          esub_complete ha hb hm incl]

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Subtyping and equality of gradual types are complete for both bounds. -/

    section
    variable {L : Level}

    theorem map_get_dyn {X : List (Term × Term)} {Dx : Term} (h : mapLookup X (.atom "dynamic") = some Dx) :
        Elixir.Map.«get/2» (.map X) (.atom "dynamic") = .ok Dx := by
      simp [Elixir.Map.«get/2», Elixir.Map.«get/3», getMapKeys_single, h]

    theorem tc_rmDyn {X : List (Term × Term)} (hX : GC L (.map X)) : TC L (.map (rmDyn X)) := hX.low_tc

    /-- Gradual subtyping on maps: compares the bounds. -/
    theorem gc_sub_maps {X Y : List (Term × Term)} (hX : GC L (.map X)) (hY : GC L (.map Y)) {m : Nat} (hm : L.K + 4 ≤ m)
        (lo : ∀ v : TP L, denD (.map X) v → denD (.map Y) v)
        (up : ∀ v : TP L, denD (upper (.map X)) v → denD (upper (.map Y)) v) :
        Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map X) (.map Y) = .ok (.atom "true") := by
      have lo' : ∀ v : TP L, denD (.map (rmDyn X)) v → denD (.map (rmDyn Y)) v := fun v h =>
        (denD_rmDyn Y v).mpr (lo v ((denD_rmDyn X v).mp h))
      cases hx : mapLookup X (.atom "dynamic") with
      | none =>
        have tX := hX.static hx
        cases hy : mapLookup Y (.atom "dynamic") with
        | none => exact tc_sub tX (hY.static hy) hm lo
        | some Dy =>
          have run := sstatic_complete tX (tc_rmDyn hY) hm fun v h => by
            have := lo' v; rw [rmDyn_static hx] at this; exact this h
          unfold Elixir.Module.Types.Descr.«subtype?/2»
          simp [unfold_map, Erlang.erlang.«is_map_key/2», getMapKeys_single, hx, hy, any_key, Lynx.Except.andAlso,
            Erlang.erlang.«not/1», Lynx.Except.guard, Erlang.erlang.«/=/2», Erlang.maps.«remove/2»]
          simpa [rmDyn] using run
      | some Dx =>
        cases hy : mapLookup Y (.atom "dynamic") with
        | none =>
          have tY := hY.static hy
          have run := sstatic_complete hX.up_tc tY hm fun v h => by
            have := up v; rw [upper_tc tY] at this; exact this h
          rw [upper_dyn hx] at run
          unfold Elixir.Module.Types.Descr.«subtype?/2»
          simp [unfold_map, Erlang.erlang.«is_map_key/2», getMapKeys_single, hx, hy, any_key, Lynx.Except.andAlso,
            Erlang.erlang.«not/1», Lynx.Except.guard, Erlang.erlang.«/=/2», map_get_dyn hx, run]
        | some Dy =>
          have tX := hX.up_tc; have tY := hY.up_tc
          rw [upper_dyn hx] at tX; rw [upper_dyn hy] at tY
          have r₁ := esub_complete tX tY hm fun v h => by
            have := up v; rw [upper_dyn hx, upper_dyn hy] at this; exact this h
          have r₂ := esub_complete (tc_rmDyn hX) (tc_rmDyn hY) hm lo'
          unfold Elixir.Module.Types.Descr.«subtype?/2»
          simp [unfold_map, Erlang.erlang.«is_map_key/2», getMapKeys_single, hx, hy, any_key, Lynx.Except.andAlso,
            Erlang.erlang.«not/1», Lynx.Except.guard, Erlang.erlang.«/=/2»]
          unfold Elixir.Module.Types.Descr.«subtype_static?/2»
          by_cases same : exactCompare (.map Y) (.map X) = .eq
          · simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», same]
          · simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», same, Elixir.Module.Types.Descr.«empty_difference_subtype?/2»]
            rw [Elixir.Module.Types.Descr.«empty_difference_subtype?/3».eq_def]
            simp [getMapKeys_single, hx, hy, r₁, Erlang.maps.«remove/2», Lynx.Except.andAlso]
            simpa [rmDyn] using r₂

    /-- Gradual subtyping is complete for both bounds. -/
    theorem gc_sub {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 4 ≤ m)
        (lo : ∀ v : TP L, denD a v → denD b v) (up : ∀ v : TP L, denD (upper a) v → denD (upper b) v) :
        Elixir.Module.Types.Descr.«subtype?/2» (D m) a b = .ok (.atom "true") := by
      obtain ⟨T, term, sT, -, all⟩ := termT L
      have tT : GC L (.map T) := GC.tc (Or.inr ⟨T, rfl, sT⟩)
      have uT : upper (.map T) = .map T := upper_tc (Or.inr ⟨T, rfl, sT⟩)
      have left : ∃ X, GC L (.map X) ∧ (∀ v : TP L, denD a v ↔ denD (.map X) v) ∧
          (∀ v : TP L, denD (upper a) v ↔ denD (upper (.map X)) v) ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) a b = Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map X) b := by
        rcases ha.shape with rfl | ⟨X, rfl⟩
        · exact ⟨T, tT, fun v => ⟨fun _ => all v, fun _ => denD_term v⟩,
            fun v => by rw [upper_term, uT]; exact ⟨fun _ => all v, fun _ => denD_term v⟩, subtype_term_l term _ _⟩
        · exact ⟨X, ha, fun v => Iff.rfl, fun v => Iff.rfl, rfl⟩
      obtain ⟨X, hX, eX, uX, rX⟩ := left
      have right : ∃ Y, GC L (.map Y) ∧ (∀ v : TP L, denD b v ↔ denD (.map Y) v) ∧
          (∀ v : TP L, denD (upper b) v ↔ denD (upper (.map Y)) v) ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map X) b =
            Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map X) (.map Y) := by
        rcases hb.shape with rfl | ⟨Y, rfl⟩
        · exact ⟨T, tT, fun v => ⟨fun _ => all v, fun _ => denD_term v⟩,
            fun v => by rw [upper_term, uT]; exact ⟨fun _ => all v, fun _ => denD_term v⟩, subtype_term_r term _ _⟩
        · exact ⟨Y, hb, fun v => Iff.rfl, fun v => Iff.rfl, rfl⟩
      obtain ⟨Y, hY, eY, uY, rY⟩ := right
      rw [rX, rY]
      exact gc_sub_maps hX hY hm (fun v h => (eY v).mp (lo v ((eX v).mpr h)))
        (fun v h => (uY v).mp (up v ((uX v).mpr h)))

    /-- Gradual equality is complete for both bounds. -/
    theorem gc_equal {a b : Term} (ha : GC L a) (hb : GC L b) {m : Nat} (hm : L.K + 4 ≤ m)
        (lo : ∀ v : TP L, denD a v ↔ denD b v) (up : ∀ v : TP L, denD (upper a) v ↔ denD (upper b) v) :
        Elixir.Module.Types.Descr.«equal?/2» (D m) a b = .ok (.atom "true") := by
      have s₁ := gc_sub ha hb hm (fun v => (lo v).mp) (fun v => (up v).mp)
      have s₂ := gc_sub hb ha hm (fun v => (lo v).mpr) (fun v => (up v).mpr)
      by_cases c : Term.compare a b = .eq <;>
        simp [Elixir.Module.Types.Descr.«equal?/2», s₁, s₂, Lynx.Except.orElse, Lynx.Except.andAlso,
          Erlang.erlang.«==/2», c, Term.true, Term.false]

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! The laws on gradual types, at both bounds. -/

    section
    variable {L : Level} {m : Nat}

    theorem gd_opt_de_morgan_union {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 6 ≤ m) :
        ∃ u x nl nr y, Elixir.Module.Types.Descr.«opt_union/2» (D m) a b = .ok u ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) u = .ok x ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) a = .ok nl ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) b = .ok nr ∧
          Elixir.Module.Types.Descr.«opt_intersection/2» (D m) nl nr = .ok y ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) x y = .ok (.atom "true") := by
      obtain ⟨u, hu, ru, su⟩ := gc_opt_union2 ha hb (m := m) (by omega)
      obtain ⟨x, hx, rx, sx⟩ := gc_opt_neg hu hm
      obtain ⟨nl, hnl, rnl, snl⟩ := gc_opt_neg ha hm
      obtain ⟨nr, hnr, rnr, snr⟩ := gc_opt_neg hb hm
      obtain ⟨y, hy, ry, sy⟩ := gc_opt_inter2 hnl hnr (m := m) (by omega)
      exact ⟨u, x, nl, nr, y, ru, rx, rnl, rnr, ry, gc_equal hx hy (by omega)
        (fun v => by rw [sx.1, su.2, sy.1, snl.1, snr.1]; exact not_or)
        (fun v => by rw [sx.2, su.1, sy.2, snl.2, snr.2]; exact not_or)⟩

    theorem gd_opt_de_morgan_inter {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 6 ≤ m) :
        ∃ i x nl nr y, Elixir.Module.Types.Descr.«opt_intersection/2» (D m) a b = .ok i ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) i = .ok x ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) a = .ok nl ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) b = .ok nr ∧
          Elixir.Module.Types.Descr.«opt_union/2» (D m) nl nr = .ok y ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) x y = .ok (.atom "true") := by
      obtain ⟨i, hi, ri, si⟩ := gc_opt_inter2 ha hb (m := m) (by omega)
      obtain ⟨x, hx, rx, sx⟩ := gc_opt_neg hi hm
      obtain ⟨nl, hnl, rnl, snl⟩ := gc_opt_neg ha hm
      obtain ⟨nr, hnr, rnr, snr⟩ := gc_opt_neg hb hm
      obtain ⟨y, hy, ry, sy⟩ := gc_opt_union2 hnl hnr (m := m) (by omega)
      exact ⟨i, x, nl, nr, y, ri, rx, rnl, rnr, ry, gc_equal hx hy (by omega)
        (fun v => by rw [sx.1, si.2, sy.1, snl.1, snr.1]; exact Classical.not_and_iff_not_or_not)
        (fun v => by rw [sx.2, si.1, sy.2, snl.2, snr.2]; exact Classical.not_and_iff_not_or_not)⟩

    theorem gd_opt_inter_sub {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ i, Elixir.Module.Types.Descr.«opt_intersection/2» (D m) a b = .ok i ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) i a = .ok (.atom "true") ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) i b = .ok (.atom "true") := by
      obtain ⟨i, hi, ri, si⟩ := gc_opt_inter2 ha hb hm
      exact ⟨i, ri, gc_sub hi ha (by omega) (fun v h => ((si.1 v).mp h).1) (fun v h => ((si.2 v).mp h).1),
        gc_sub hi hb (by omega) (fun v h => ((si.1 v).mp h).2) (fun v h => ((si.2 v).mp h).2)⟩

    theorem gd_opt_union_sup {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ u, Elixir.Module.Types.Descr.«opt_union/2» (D m) a b = .ok u ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) a u = .ok (.atom "true") ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) b u = .ok (.atom "true") := by
      obtain ⟨u, hu, ru, su⟩ := gc_opt_union2 ha hb hm
      exact ⟨u, ru, gc_sub ha hu (by omega) (fun v h => (su.1 v).mpr (Or.inl h)) (fun v h => (su.2 v).mpr (Or.inl h)),
        gc_sub hb hu (by omega) (fun v h => (su.1 v).mpr (Or.inr h)) (fun v h => (su.2 v).mpr (Or.inr h))⟩

    theorem gd_inter_sub {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ i, Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok i ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) i a = .ok (.atom "true") ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) i b = .ok (.atom "true") := by
      obtain ⟨i, hi, ri, si⟩ := gc_inter ha hb hm
      exact ⟨i, ri, gc_sub hi ha (by omega) (fun v h => ((si.1 v).mp h).1) (fun v h => ((si.2 v).mp h).1),
        gc_sub hi hb (by omega) (fun v h => ((si.1 v).mp h).2) (fun v h => ((si.2 v).mp h).2)⟩

    theorem gd_union_sup {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ u, Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok u ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) a u = .ok (.atom "true") ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) b u = .ok (.atom "true") := by
      obtain ⟨u, hu, ru, su⟩ := gc_union ha hb hm
      exact ⟨u, ru, gc_sub ha hu (by omega) (fun v h => (su.1 v).mpr (Or.inl h)) (fun v h => (su.2 v).mpr (Or.inl h)),
        gc_sub hb hu (by omega) (fun v h => (su.1 v).mpr (Or.inr h)) (fun v h => (su.2 v).mpr (Or.inr h))⟩

    theorem gd_union_equal {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ u w, Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok u ∧
          Elixir.Module.Types.Descr.«opt_union/2» (D m) a b = .ok w ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) u w = .ok (.atom "true") := by
      obtain ⟨u, hu, ru, su⟩ := gc_union ha hb hm
      obtain ⟨w, hw, rw', sw⟩ := gc_opt_union2 ha hb hm
      exact ⟨u, w, ru, rw', gc_equal hu hw (by omega) (fun v => by rw [su.1, sw.1]) (fun v => by rw [su.2, sw.2])⟩

    theorem gd_inter_equal {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ i j, Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a b = .ok i ∧
          Elixir.Module.Types.Descr.«opt_intersection/2» (D m) a b = .ok j ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) i j = .ok (.atom "true") := by
      obtain ⟨i, hi, ri, si⟩ := gc_inter ha hb hm
      obtain ⟨j, hj, rj, sj⟩ := gc_opt_inter2 ha hb hm
      exact ⟨i, j, ri, rj, gc_equal hi hj (by omega) (fun v => by rw [si.1, sj.1]) (fun v => by rw [si.2, sj.2])⟩

    theorem gd_distrib {t a b : Term} (ht : GC L t) (ha : GC L a) (hb : GC L b) (hm : L.K + 5 ≤ m) :
        ∃ u x y z w, Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok u ∧
          Elixir.Module.Types.Descr.«bare_intersection/2» (D m) t u = .ok x ∧
          Elixir.Module.Types.Descr.«bare_intersection/2» (D m) t a = .ok y ∧
          Elixir.Module.Types.Descr.«bare_intersection/2» (D m) t b = .ok z ∧
          Elixir.Module.Types.Descr.«bare_union/2» (D m) y z = .ok w ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) x w = .ok (.atom "true") := by
      obtain ⟨u, hu, ru, su⟩ := gc_union ha hb hm
      obtain ⟨x, hx, rx, sx⟩ := gc_inter ht hu hm
      obtain ⟨y, hy, ry, sy⟩ := gc_inter ht ha hm
      obtain ⟨z, hz, rz, sz⟩ := gc_inter ht hb hm
      obtain ⟨w, hw, rw', sw⟩ := gc_union hy hz hm
      exact ⟨u, x, y, z, w, ru, rx, ry, rz, rw', gc_equal hx hw (by omega)
        (fun v => by rw [sx.1, su.1, sw.1, sy.1, sz.1]; exact and_or_left)
        (fun v => by rw [sx.2, su.2, sw.2, sy.2, sz.2]; exact and_or_left)⟩

    theorem gd_neg_equal {a : Term} (ha : GC L a) (hm : L.K + 6 ≤ m) :
        ∃ x y, Elixir.Module.Types.Descr.«bare_negation/1» (D m) a = .ok x ∧
          Elixir.Module.Types.Descr.«opt_negation/1» (D m) a = .ok y ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) x y = .ok (.atom "true") := by
      obtain ⟨x, hx, rx, sx⟩ := gc_neg ha hm
      obtain ⟨y, hy, ry, sy⟩ := gc_opt_neg ha hm
      exact ⟨x, y, rx, ry, gc_equal hx hy (by omega) (fun v => by rw [sx.1, sy.1]) (fun v => by rw [sx.2, sy.2])⟩

    theorem gd_diff_equal {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 6 ≤ m) :
        ∃ x y, Elixir.Module.Types.Descr.«bare_difference/2» (D m) a b = .ok x ∧
          Elixir.Module.Types.Descr.«opt_difference/2» (D m) a b = .ok y ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) x y = .ok (.atom "true") := by
      obtain ⟨x, hx, rx, sx⟩ := gc_diff ha hb hm
      obtain ⟨y, hy, ry, sy⟩ := gc_opt_diff2 ha hb hm
      exact ⟨x, y, rx, ry, gc_equal hx hy (by omega) (fun v => by rw [sx.1, sy.1]) (fun v => by rw [sx.2, sy.2])⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Types without function fields checked empty hold no points. -/

    section
    variable {L : Level}

    /-- Without function fields, the function fields' class does not matter. -/
    theorem DescrC.nofun {TF LF MF Fn Fn' : Term → Prop} {X : List (Term × Term)} (s : DescrC Fn TF LF MF X)
        (nf : mapLookup X (.atom "fun") = none) : DescrC Fn' TF LF MF X := by
      refine ⟨s.keys, fun name x h => ?_⟩
      rcases s.fields name x h with h' | h' | ⟨e, -⟩ | h' | h' | h'
      · exact Or.inl h'
      · exact Or.inr (Or.inl h')
      · subst e; rw [nf] at h; cases h
      · exact Or.inr (Or.inr (Or.inr (Or.inl h')))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl h'))))
      · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr h'))))

    /-- Emptiness is sound on types without function fields. -/
    theorem tc_empty_sound {C : List (Term × Term)} (sC : DC L C) (nf : mapLookup C (.atom "fun") = none) {m : Nat}
        (hm : L.K + 2 ≤ m) (h : Elixir.Module.Types.Descr.«empty?/1» (D m) (.map C) = .ok (.atom "true")) :
        ∀ v : TP L, ¬denD (.map C) v := by
      have sC' : DescrC FunTop (TField L.E) (LF L.E) (MField L.E) C := sC.nofun nf
      obtain ⟨b, run, ex⟩ := descr_empty (tks L) (funTopC (K := L.K + 2) (by omega)) trivial hm sC' [] trivial
      rw [empty_map_seen, run] at h
      have hb : b = Bool.true := by cases b <;> simp_all [boolAtom]
      have none := (ex (lh (.map C) + 1) (by omega) (safeN_nil _)).2 (fun x hx => by rw [nf] at hx; cases hx) hb
      intro v hv
      have := none v.1.1 v.1.2 v.2.2
      rw [(denD_map v).mp hv] at this
      cases this

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    set_option linter.unusedSimpArgs false
    set_option linter.deprecated false
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! The types of the laws on gradual types. -/

    /-- Gradual types of the laws: a static part and a dynamic part that Descr checks includes it. -/
    theorem opt_gradual_gc {t : Term} {m n : Nat} (hm : (level t n).K + 6 ≤ m) (descr : Term)
        (h : «opt_gradual?/2» (D m) descr (.tuple #[.integer n, t]) = .ok Term.true) : GC (level t n) descr := by
      have static : «opt_negatable?/2» descr (.tuple #[.integer n, t]) = .ok Term.true → GC (level t n) descr := fun h =>
        GC.tc (opt_negatable_tc t n descr h)
      unfold «opt_gradual?/2» at h
      cases descr with
      | map X =>
        cases hD : mapLookup X (.atom "dynamic") with
        | none => simp [getMapKeys_single, hD] at h; exact static h
        | some Dy =>
          simp only [getMapKeys_single, hD, Option.toList, Erlang.maps.«remove/2», Lynx.Except.ok_bind, Term.true,
            Lynx.Except.andAlso_eq_true] at h
          obtain ⟨⟨hS, hDy⟩, hI⟩ := h
          have tS : TC (level t n) (.map (rmDyn X)) := opt_negatable_tc t n _ hS
          have tD := opt_negatable_tc t n _ hDy
          have sS : DC (level t n) (rmDyn X) := by
            rcases tS with e | ⟨S, e, sS⟩
            · cases e
            · simp only [Term.map.injEq] at e; rw [e]; exact sS
          obtain ⟨c, tc, run, sem⟩ := tc_diff tS tD (m := m) hm
          rw [← rmDyn, run] at hI
          simp only [Lynx.Except.ok_bind] at hI
          rcases tc with rfl | ⟨C, rfl, sC⟩
          · simp [«included?/1», Erlang.erlang.«is_map_key/2»] at hI
          · have nf : mapLookup C (.atom "fun") = none := by
              cases hf : mapLookup C (.atom "fun") with
              | none => rfl
              | some _ =>
                simp [«included?/1», Erlang.erlang.«is_map_key/2», any_key, hf] at hI
            have empty : Elixir.Module.Types.Descr.«empty?/1» (D m) (.map C) = .ok (.atom "true") := by
              simpa [«included?/1», Erlang.erlang.«is_map_key/2», any_key, nf] using hI
            have none := tc_empty_sound sC nf (by omega) empty
            refine Or.inr ⟨X, Dy, rfl, hD, tD, sS, fun v hv => ?_⟩
            apply Classical.byContradiction
            intro hn
            exact none v ((sem v).mpr ⟨(denD_rmDyn X v).mpr hv, hn⟩)
      | _ => simp at h; exact static h

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! A gradual type meets its negation only in its dynamic part, which `lower_bound/1` removes, and united with its
    negation it covers every value in its dynamic part, which `upper_bound/1` returns. -/

    theorem lower_bound_run {d : Dispatcher} {a : Term} (h : a = .atom "term" ∨ ∃ X, a = .map X) :
        Elixir.Module.Types.Descr.«lower_bound/1» d a = .ok (lower a) := by
      rcases h with rfl | ⟨X, rfl⟩
      · unfold Elixir.Module.Types.Descr.«lower_bound/1»; rfl
      · unfold Elixir.Module.Types.Descr.«lower_bound/1»
        simp [Erlang.maps.«remove/2», lower, rmDyn]

    /-- Types whose dynamic part, if any, is the top type or a map. -/
    def UB (a : Term) : Prop :=
      a = .atom "term" ∨ ∃ X, a = .map X ∧ ∀ Dy, mapLookup X (.atom "dynamic") = some Dy → Dy = .atom "term" ∨ ∃ Y, Dy = .map Y

    theorem upper_bound_run {d : Dispatcher} {a : Term} (h : UB a) :
        Elixir.Module.Types.Descr.«upper_bound/1» d a = .ok (upper a) := by
      rcases h with rfl | ⟨X, rfl, hd⟩
      · unfold Elixir.Module.Types.Descr.«upper_bound/1»; rfl
      · unfold Elixir.Module.Types.Descr.«upper_bound/1»
        cases e : mapLookup X (.atom "dynamic") with
        | none => simp [getMapKeys_single, e, upper]
        | some Dy =>
          rcases hd Dy e with rfl | ⟨Y, rfl⟩ <;> simp [getMapKeys_single, e, upper]

    @[simp] theorem upper_bound_term (d : Dispatcher) :
        Elixir.Module.Types.Descr.«upper_bound/1» d (.atom "term") = .ok (.atom "term") := by
      unfold Elixir.Module.Types.Descr.«upper_bound/1»; rfl

    theorem upper_bound_static {d : Dispatcher} {X : List (Term × Term)} (h : mapLookup X (.atom "dynamic") = none) :
        Elixir.Module.Types.Descr.«upper_bound/1» d (.map X) = .ok (.map X) := by
      rw [upper_bound_run (Or.inr ⟨X, rfl, fun Dy e => by rw [h] at e; cases e⟩)]
      simp [upper, h]

    section
    variable {L : Level} {m : Nat}

    theorem GC.ub {a : Term} (ha : GC L a) : UB a := by
      rcases ha with (h | ⟨X, rfl, sX⟩) | ⟨X, Dy, rfl, e, tc, -⟩
      · exact Or.inl h
      · exact Or.inr ⟨X, rfl, fun Dy e' => by rw [sX.static] at e'; cases e'⟩
      · refine Or.inr ⟨X, rfl, fun Dy' e' => ?_⟩
        rw [e] at e'; cases e'
        rcases tc with h | ⟨Y, rfl, -⟩
        · exact Or.inl h
        · exact Or.inr ⟨Y, rfl⟩

    theorem gd_inter_neg_lower {a : Term} (ha : GC L a) (hm : L.K + 6 ≤ m) :
        ∃ n i, Elixir.Module.Types.Descr.«bare_negation/1» (D m) a = .ok n ∧
          Elixir.Module.Types.Descr.«bare_intersection/2» (D m) a n = .ok i ∧
          Elixir.Module.Types.Descr.«lower_bound/1» (D m) i = .ok (lower i) ∧
          Elixir.Module.Types.Descr.«empty?/1» (D m) (lower i) = .ok (.atom "true") := by
      obtain ⟨n, hn, rn, sn⟩ := gc_neg ha hm
      obtain ⟨i, hi, ri, si⟩ := gc_inter ha hn (m := m) (by omega)
      exact ⟨n, i, rn, ri, lower_bound_run hi.shape, tc_empty hi.low_tc (by omega) fun v h => by
        obtain ⟨h₁, h₂⟩ := (si.1 v).mp ((denD_lower i v).mp h)
        exact (sn.1 v).mp h₂ (ha.inv v h₁)⟩

    theorem gd_opt_inter_neg_lower {a : Term} (ha : GC L a) (hm : L.K + 6 ≤ m) :
        ∃ n i, Elixir.Module.Types.Descr.«opt_negation/1» (D m) a = .ok n ∧
          Elixir.Module.Types.Descr.«opt_intersection/2» (D m) a n = .ok i ∧
          Elixir.Module.Types.Descr.«lower_bound/1» (D m) i = .ok (lower i) ∧
          Elixir.Module.Types.Descr.«empty?/1» (D m) (lower i) = .ok (.atom "true") := by
      obtain ⟨n, hn, rn, sn⟩ := gc_opt_neg ha hm
      obtain ⟨i, hi, ri, si⟩ := gc_opt_inter2 ha hn (m := m) (by omega)
      exact ⟨n, i, rn, ri, lower_bound_run hi.shape, tc_empty hi.low_tc (by omega) fun v h => by
        obtain ⟨h₁, h₂⟩ := (si.1 v).mp ((denD_lower i v).mp h)
        exact (sn.1 v).mp h₂ (ha.inv v h₁)⟩

    theorem gd_union_neg_upper {a : Term} (ha : GC L a) (hm : L.K + 6 ≤ m) :
        ∃ n u, Elixir.Module.Types.Descr.«bare_negation/1» (D m) a = .ok n ∧
          Elixir.Module.Types.Descr.«bare_union/2» (D m) a n = .ok u ∧
          Elixir.Module.Types.Descr.«upper_bound/1» (D m) u = .ok (upper u) ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) (.atom "term") (upper u) = .ok (.atom "true") := by
      obtain ⟨n, hn, rn, sn⟩ := gc_neg ha hm
      obtain ⟨u, hu, ru, su⟩ := gc_union ha hn (m := m) (by omega)
      refine ⟨n, u, rn, ru, upper_bound_run hu.ub, tc_sub tc_term hu.up_tc (by omega) fun v _ => (su.2 v).mpr ?_⟩
      by_cases h : denD a v
      · exact Or.inl (ha.inv v h)
      · exact Or.inr ((sn.2 v).mpr h)

    theorem gd_opt_union_neg_upper {a : Term} (ha : GC L a) (hm : L.K + 6 ≤ m) :
        ∃ n u, Elixir.Module.Types.Descr.«opt_negation/1» (D m) a = .ok n ∧
          Elixir.Module.Types.Descr.«opt_union/2» (D m) a n = .ok u ∧
          Elixir.Module.Types.Descr.«upper_bound/1» (D m) u = .ok (upper u) ∧
          Elixir.Module.Types.Descr.«subtype?/2» (D m) (.atom "term") (upper u) = .ok (.atom "true") := by
      obtain ⟨n, hn, rn, sn⟩ := gc_opt_neg ha hm
      obtain ⟨u, hu, ru, su⟩ := gc_opt_union2 ha hn (m := m) (by omega)
      refine ⟨n, u, rn, ru, upper_bound_run hu.ub, tc_sub tc_term hu.up_tc (by omega) fun v _ => (su.2 v).mpr ?_⟩
      by_cases h : denD a v
      · exact Or.inl (ha.inv v h)
      · exact Or.inr ((sn.2 v).mpr h)

    theorem gd_de_morgan_union {a b : Term} (ha : GC L a) (hb : GC L b) (hm : L.K + 6 ≤ m) :
        ∃ u x nl nr y, Elixir.Module.Types.Descr.«bare_union/2» (D m) a b = .ok u ∧
          Elixir.Module.Types.Descr.«bare_negation/1» (D m) u = .ok x ∧
          Elixir.Module.Types.Descr.«bare_negation/1» (D m) a = .ok nl ∧
          Elixir.Module.Types.Descr.«bare_negation/1» (D m) b = .ok nr ∧
          Elixir.Module.Types.Descr.«bare_intersection/2» (D m) nl nr = .ok y ∧
          Elixir.Module.Types.Descr.«equal?/2» (D m) x y = .ok (.atom "true") := by
      obtain ⟨u, hu, ru, su⟩ := gc_union ha hb (m := m) (by omega)
      obtain ⟨x, hx, rx, sx⟩ := gc_neg hu hm
      obtain ⟨nl, hnl, rnl, snl⟩ := gc_neg ha hm
      obtain ⟨nr, hnr, rnr, snr⟩ := gc_neg hb hm
      obtain ⟨y, hy, ry, sy⟩ := gc_inter hnl hnr (m := m) (by omega)
      exact ⟨u, x, nl, nr, y, ru, rx, rnl, rnr, ry, gc_equal hx hy (by omega)
        (fun v => by rw [sx.1, su.2, sy.1, snl.1, snr.1]; exact not_or)
        (fun v => by rw [sx.2, su.1, sy.2, snl.2, snr.2]; exact not_or)⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    # Compatibility only checks emptiness, inclusion, and disjointness of the bounds of gradual types, which are
    # exact on the element types of the next level, whose function types are the top one.
    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-! Compatibility of gradual types whose function types are the top one. -/

    section
    variable {L : Level}

    theorem map_nil_of_compare {R : List (Term × Term)} (h : Term.compare (.map R) (.map []) = .eq) : R = [] := by
      cases R with
      | nil => rfl
      | cons e rest =>
        have := lookup_of_map_compare_eq (e :: rest) [] h e.1
        simp at this

    /-- A function field equal to the top function type is the top function type. -/
    theorem fun_top_of_eq {x : Term} (fx : FunF x)
        (h : Erlang.erlang.«==/2» x funTopT = .ok (.atom "true")) : x = funTopT := by
      obtain ⟨p, R, rfl, -⟩ := fx
      have e : Term.compare (.tuple #[.atom (if p then "union" else "negation"), .map R]) funTopT = .eq := by
        simp only [Erlang.erlang.«==/2»] at h
        split at h <;> simp_all
      rw [funTopT, compare_eq_step] at e
      cases p <;> simp [Compare.compareStep, List.compareLex_cons_cons, List.compareLex_nil_nil, Ordering.then] at e
      split at e
      · rename_i c; rw [map_nil_of_compare c]; rfl
      · exact absurd e (by assumption)

    /-- Static types whose function types are the top one are element types of the next level. -/
    theorem de_of_tc {a : Term} (ha : TC L a)
        (top : ∀ X x, a = .map X → mapLookup X (.atom "fun") = some x → x = funTopT) : DE L.E a := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · exact Or.inl rfl
      · refine Or.inr ⟨X, rfl, sX.keys, fun name x h => ?_⟩
        rcases sX.fields name x h with h' | h' | ⟨e, -⟩ | h' | h' | h'
        · exact Or.inl h'
        · exact Or.inr (Or.inl h')
        · subst e; exact Or.inr (Or.inr (Or.inl ⟨rfl, top X x rfl h⟩))
        · exact Or.inr (Or.inr (Or.inr (Or.inl h')))
        · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl h'))))
        · exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr h'))))

    theorem de_tc {a : Term} (ha : DE L.E a) : TC L a := by
      rcases ha with rfl | ⟨X, rfl, sX⟩
      · exact Or.inl rfl
      · exact Or.inr ⟨X, rfl, sX.funF⟩

    /-- Static types that `top_fun?/1` accepts are element types of the next level. -/
    theorem top_fun_de {b : Term} (hb : TC L b) (h : «top_fun?/1» b = .ok (.atom "true")) : DE L.E b := by
      refine de_of_tc hb fun X x e hx => ?_
      subst e
      obtain ⟨Y, e, sY⟩ := hb.resolve_left (by simp)
      simp only [Term.map.injEq] at e; subst e
      rcases sY.fields "fun" x hx with ⟨e, -⟩ | ⟨e, -⟩ | ⟨-, fx⟩ | ⟨e, -⟩ | ⟨e, -⟩ | ⟨e, -⟩
      all_goals try (simp at e)
      unfold «top_fun?/1» at h
      simp [getMapKeys_single, hx] at h
      exact fun_top_of_eq fx (by simpa [funTopT] using h)

    /-- The shapes of gradual types: the top type, static maps, maps whose dynamic part is the top type, and maps whose
    dynamic part is a static map. -/
    theorem GC.cases {a : Term} (ha : GC L a) :
        a = .atom "term" ∨ (∃ X, a = .map X ∧ mapLookup X (.atom "dynamic") = none) ∨
          (∃ X, a = .map X ∧ mapLookup X (.atom "dynamic") = some (.atom "term")) ∨
          ∃ X Y, a = .map X ∧ mapLookup X (.atom "dynamic") = some (.map Y) ∧ mapLookup Y (.atom "dynamic") = none := by
      rcases ha with (rfl | ⟨X, rfl, sX⟩) | ⟨X, Dy, rfl, hD, tD, -, -⟩
      · exact Or.inl rfl
      · exact Or.inr (Or.inl ⟨X, rfl, sX.static⟩)
      · rcases tD with rfl | ⟨Y, rfl, sY⟩
        · exact Or.inr (Or.inr (Or.inl ⟨X, rfl, hD⟩))
        · exact Or.inr (Or.inr (Or.inr ⟨X, Y, rfl, hD, sY.static⟩))

    /-- Emptiness of a gradual type checks its dynamic part. -/
    theorem empty_upper (d : Dispatcher) {a : Term} (ha : GC L a) :
        Elixir.Module.Types.Descr.«empty?/1» d a = Elixir.Module.Types.Descr.«empty?/1» d (upper a) := by
      rcases ha.cases with rfl | ⟨X, rfl, h⟩ | ⟨X, rfl, h⟩ | ⟨X, Y, rfl, h, hY⟩
      · rfl
      · simp [upper, h]
      · simp only [upper, h, Option.getD_some, empty_map_seen]
        rw [Elixir.Module.Types.Descr.«empty_seen?/2».eq_def]
        simp [getMapKeys_single, h, Elixir.Module.Types.Descr.«empty?/1»]
      · simp only [upper, h, Option.getD_some, empty_map_seen]
        conv => lhs; rw [Elixir.Module.Types.Descr.«empty_seen?/2».eq_def]
        conv => rhs; rw [Elixir.Module.Types.Descr.«empty_seen?/2».eq_def]
        simp [getMapKeys_single, h, hY]

    /-- Disjointness of gradual types checks their dynamic parts. -/
    theorem disj_upper (d : Dispatcher) {a b : Term} (ha : GC L a) (hb : GC L b) :
        Elixir.Module.Types.Descr.«disjoint?/2» d a b = Elixir.Module.Types.Descr.«disjoint?/2» d (upper a) (upper b) := by
      have ea := empty_upper d ha
      have eb := empty_upper d hb
      rcases ha.cases with rfl | ⟨X, rfl, h⟩ | ⟨X, rfl, h⟩ | ⟨X, X', rfl, h, h'⟩ <;>
        rcases hb.cases with rfl | ⟨Y, rfl, k⟩ | ⟨Y, rfl, k⟩ | ⟨Y, Y', rfl, k, k'⟩ <;>
        simp only [upper, Option.getD_some, Option.getD_none, *] at ea eb ⊢ <;>
        unfold Elixir.Module.Types.Descr.«disjoint?/2» <;>
        simp [getMapKeys_single, upper_term, *]

    /-- On static types, `subtype_static?/2` answers as `subtype?/2`. -/
    theorem sstatic_sub {a b : Term} (ha : TC L a) (hb : TC L b) {m : Nat} (hm : L.K + 4 ≤ m) :
        Elixir.Module.Types.Descr.«subtype_static?/2» (D m) a b = Elixir.Module.Types.Descr.«subtype?/2» (D m) a b := by
      by_cases incl : ∀ v : TP L, denD a v → denD b v
      · rw [sstatic_complete ha hb hm incl, tc_sub ha hb hm incl]
      obtain ⟨T, term, sT, -, all⟩ := termT L
      have static : ∀ {X : List (Term × Term)}, DC L X → ∀ {Y : List (Term × Term)}, DC L Y →
          Elixir.Module.Types.Descr.«subtype?/2» (D m) (.map X) (.map Y) =
            Elixir.Module.Types.Descr.«subtype_static?/2» (D m) (.map X) (.map Y) := by
        intro X sX Y sY
        unfold Elixir.Module.Types.Descr.«subtype?/2»
        simp [unfold_map, Erlang.erlang.«is_map_key/2», sX.static, sY.static, any_key,
          Lynx.Except.andAlso, Erlang.erlang.«not/1», Lynx.Except.guard, Erlang.erlang.«/=/2»]
      rcases hb with rfl | ⟨B, rfl, sB⟩
      · exact absurd (fun v _ => denD_term v) incl
      rcases ha with rfl | ⟨A, rfl, sA⟩
      · rw [subtype_term_l term, static sT sB]
        have ne : exactCompare (.map B) (.map T) ≠ .eq := fun e => incl fun v _ =>
          (tc_congr (Or.inr ⟨B, rfl, sB⟩) (Or.inr ⟨T, rfl, sT⟩) (compare_eq_of_exactCompare_eq _ _ e) v).mpr (all v)
        unfold Elixir.Module.Types.Descr.«subtype_static?/2»
        simp [Lynx.Except.guard, Erlang.erlang.«=:=/2», ne, Elixir.Module.Types.Descr.«empty_difference_subtype?/2»]
        conv => lhs; rw [Elixir.Module.Types.Descr.«empty_difference_subtype?/3».eq_def]
        conv => rhs; rw [Elixir.Module.Types.Descr.«empty_difference_subtype?/3».eq_def]
        simp [getMapKeys_single, sT.static, sB.static, term]
        split <;> rfl
      · exact (static sA sB).symm

    end

    /-- Gradual types whose parts hold no function types other than the top one: the parts are element types of
    the next level. -/
    theorem top_fun_gradual_ok {t : Term} {m n : Nat} (hm : (level t n).K + 6 ≤ m) {a : Term}
        (h : «top_fun_gradual?/2» (D m) a (.tuple #[.integer n, t]) = .ok (.atom "true")) :
        GC (level t n) a ∧ DE (level t n).E (lower a) ∧ DE (level t n).E (upper a) := by
      unfold «top_fun_gradual?/2» at h
      simp only [Lynx.Except.andAlso_eq_true] at h
      obtain ⟨⟨hg, hl⟩, hu⟩ := h
      have ga := opt_gradual_gc hm a (by simpa [Term.true] using hg)
      rw [lower_bound_run ga.shape, Lynx.Except.ok_bind] at hl
      rw [upper_bound_run ga.ub, Lynx.Except.ok_bind] at hu
      exact ⟨ga, top_fun_de ga.low_tc hl, top_fun_de ga.up_tc hu⟩

    /-- `compatible?/2` checks the dynamic parts when the static part of the left type is empty, and inclusion of the
    static part otherwise. -/
    theorem compat_run (d : Dispatcher) {l r : Term} (hl : l = .atom "term" ∨ ∃ X, l = .map X)
        (hr : UB r) {e s j : Bool}
        (eE : Elixir.Module.Types.Descr.«empty?/1» d (lower l) = .ok (boolAtom e))
        (eS : Elixir.Module.Types.Descr.«subtype_static?/2» d (lower l) (upper r) = .ok (boolAtom s))
        (eJ : Elixir.Module.Types.Descr.«disjoint?/2» d (upper l) (upper r) = .ok (boolAtom j)) :
        Elixir.Module.Types.Descr.«compatible?/2» d l r = .ok (boolAtom (if e then !j else s)) := by
      have finish : ∀ {lo up up' : Term}, Elixir.Module.Types.Descr.«empty?/1» d lo = .ok (boolAtom e) →
          Elixir.Module.Types.Descr.«subtype_static?/2» d lo up' = .ok (boolAtom s) →
          Elixir.Module.Types.Descr.«disjoint?/2» d up up' = .ok (boolAtom j) →
          (do
            let x ← Elixir.Module.Types.Descr.«empty?/1» d lo
            Lynx.Except.guard (.ok (x.isMember [.atom "false", .atom "nil"]))
              (fun _ => Elixir.Module.Types.Descr.«subtype_static?/2» d lo up')
              fun _ => do
                let y ← Elixir.Module.Types.Descr.«disjoint?/2» d up up'
                Erlang.erlang.«not/1» y) = .ok (boolAtom (if e then !j else s)) := by
        intro lo up up' h₁ h₂ h₃
        cases e <;> cases j <;> simp [h₁, h₂, h₃, boolAtom, isMember, Lynx.Except.guard, Erlang.erlang.«not/1»]
      rcases hl with rfl | ⟨X, rfl⟩ <;> rcases hr with rfl | ⟨Y, rfl, hd⟩
      · unfold Elixir.Module.Types.Descr.«compatible?/2»
        simp
        exact finish eE eS eJ
      · unfold Elixir.Module.Types.Descr.«compatible?/2»
        cases hY : mapLookup Y (.atom "dynamic") with
        | none =>
          simp only [upper, hY, Option.getD_none] at eS eJ
          simp [getMapKeys_single, hY]
          exact finish eE eS eJ
        | some Dy =>
          simp only [upper, hY, Option.getD_some] at eS eJ
          rcases hd Dy hY with rfl | ⟨Z, rfl⟩ <;> simp [getMapKeys_single, hY] <;> exact finish eE eS eJ
      · unfold Elixir.Module.Types.Descr.«compatible?/2»
        simp [unfold_map, pop_dyn]
        exact finish eE eS eJ
      · unfold Elixir.Module.Types.Descr.«compatible?/2»
        cases hY : mapLookup Y (.atom "dynamic") with
        | none =>
          simp only [upper, hY, Option.getD_none] at eS eJ
          simp [unfold_map, pop_dyn, getMapKeys_single, hY]
          exact finish eE eS eJ
        | some Dy =>
          simp only [upper, hY, Option.getD_some] at eS eJ
          rcases hd Dy hY with rfl | ⟨Z, rfl⟩ <;> simp [unfold_map, pop_dyn, getMapKeys_single, hY] <;>
            exact finish eE eS eJ

    /-- `compatible?/2` checks that the static part of the left type is included in the dynamic part of the right one and
    that the two meet, as the law states it. -/
    theorem gd_compatible {t : Term} {n : Nat} {l r : Term} (gl : GC (level t n) l) (gr : GC (level t n) r) (ll : DE (level t n).E (lower l))
        (ul : DE (level t n).E (upper l)) (ur : DE (level t n).E (upper r)) {m : Nat} (hm : (level t n).K + 14 ≤ m) :
        ∃ b : Bool, Elixir.Module.Types.Descr.«compatible?/2» (D m) l r = .ok (boolAtom b) ∧
          Lynx.Except.andAlso (Elixir.Module.Types.Descr.«subtype?/2» (D m) (lower l) (upper r))
            (do
              let j ← Elixir.Module.Types.Descr.«disjoint?/2» (D m) l r
              Erlang.erlang.«not/1» j) true = .ok (boolAtom b) := by
      have ef3 : EF (level t n).nd (DE (level t n).E) (TP (level t n)) denD tlD ((level t n).K + 14) := ef_step (level t n).ef (level t n).none
      obtain ⟨bE, rE, semE⟩ := ef3.empty [] ll
      replace semE := semE (lh (lower l) + 1) (by omega) (safeN_nil _)
      obtain ⟨s, rS, semS⟩ := ef3.sub ll ur
      obtain ⟨dj, rJ, semJ⟩ := ef3.disj ul ur
      have tl := de_tc ll
      have tr := de_tc ur
      have eS : Elixir.Module.Types.Descr.«subtype_static?/2» (D m) (lower l) (upper r) = .ok (boolAtom s) := by
        rw [sstatic_sub tl tr (by omega), rS m hm]
      have eE : Elixir.Module.Types.Descr.«empty?/1» (D m) (lower l) = .ok (boolAtom bE) := by
        rcases tl with e | ⟨X, e, -⟩ <;> rw [e] at rE semE ⊢
        · have : bE = Bool.false := by
            cases bE
            · rfl
            · exact absurd (denD_term ptWit) ((semE.mp rfl) ptWit)
          subst this; rfl
        · rw [empty_map_seen]; exact rE m hm
      have eJ : Elixir.Module.Types.Descr.«disjoint?/2» (D m) l r = .ok (boolAtom dj) := by
        rw [disj_upper (D m) gl gr]; exact rJ m hm
      have eJ' : Elixir.Module.Types.Descr.«disjoint?/2» (D m) (upper l) (upper r) = .ok (boolAtom dj) := rJ m hm
      have hc := compat_run (D m) gl.shape gr.ub eE eS eJ'
      rw [hc]
      simp only [eJ, rS m hm, Lynx.Except.ok_bind]
      cases bE
      · -- The static part is not empty: it must be included and then the types meet.
        refine ⟨s, by simp, ?_⟩
        cases s
        · simp [boolAtom, Lynx.Except.andAlso]
        · have meet : dj = Bool.false := by
            cases dj
            · rfl
            · obtain ⟨v, hv⟩ : ∃ v, denD (lower l) v := by
                apply Classical.byContradiction; intro h
                exact absurd (semE.mpr fun v hv => h ⟨v, hv⟩) (by simp)
              exact (semJ rfl v (gl.inv v ((denD_lower l v).mp hv)) (semS rfl v hv)).elim
          subst meet
          simp [boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1»]
      · -- The static part is empty, so it is included.
        have sub : s = Bool.true := by
          have := tc_sub tl tr (m := m) (by omega) fun v hv => absurd hv ((semE.mp rfl) v)
          rw [rS m hm] at this
          cases s <;> simp_all [boolAtom]
        subst sub
        refine ⟨!dj, by simp, ?_⟩
        cases dj <;> simp [boolAtom, Lynx.Except.andAlso, Erlang.erlang.«not/1»]

    end Elixir.STTDescrProofsTest.Nest
    """

    # The top function type of an arity is the arrow from that many arguments of none() to term():
    # removing the arrow leaves a line whose only negative literal is the arrow itself, which phi covers.
    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest
    open Lynx Lynx.Term BddProofs

    /-- The arguments of the top function of arity `n`. -/
    abbrev noneArgs (n : Nat) : Term := Term.list (List.replicate n (.map []))

    theorem fun_arity_run (n : Nat) :
        Elixir.Module.Types.Descr.«fun/1» (.integer n) =
          .ok (.map [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .atom "bdd_top")]])]) := by
      unfold Elixir.Module.Types.Descr.«fun/1»
      simp [Lynx.Except.guard, Erlang.erlang.«is_integer/1», Erlang.erlang.«>=/2», Lynx.Except.andAlso, Int.isGE_compare]

    theorem fun_none_run (n : Nat) : ∃ k : Int, ∀ m, 1 ≤ m →
        Elixir.Module.Types.Descr.«fun/2» (D m) (noneArgs n) (.atom "term") =
          .ok (.map [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .tuple #[.integer k, noneArgs n, .atom "term"])]])]) ∧
        Elixir.Module.Types.Descr.«bdd_leaf_new/2» (noneArgs n) (.atom "term") = .ok (.tuple #[.integer k, noneArgs n, .atom "term"]) := by
      obtain ⟨k, leaf⟩ := leaf_fun (List.replicate n (.map []))
      obtain ⟨r, ⟨s, d, rfl⟩, run⟩ := foldl_uni 1 "Elixir.Module.Types.Descr" "-fun_descr/2-fun-0-" #[]
        (fun a => ∃ s d, a = .tuple #[s, d, .atom "false"]) (List.replicate n (.map [])) (by
          intro x mx a ⟨s, d, ha⟩
          subst ha
          rw [List.eq_of_mem_replicate mx]
          refine ⟨.tuple #[.cons (.map []) s, .cons (.map []) d, .atom "false"], ⟨_, _, rfl⟩, fun m hm => ?_⟩
          obtain ⟨m', rfl, -⟩ := succ_of_le hm
          rw [Erlang.program.«Elixir.Module.Types.Descr:-fun_descr/2-fun-0-/2».pure]
          simp [Elixir.Module.Types.Descr.«-fun_descr/2-fun-0-/2», split_static (Or.inr (Or.inl ⟨[], rfl, rfl⟩)),
            Lynx.Except.orElse]) (.tuple #[.nil, .nil, .atom "false"]) ⟨_, _, rfl⟩
      refine ⟨k, fun m hm => ⟨?_, leaf⟩⟩
      have hl : Erlang.erlang.«is_list/1» (noneArgs n) = .ok (.atom "true") := by
        cases n <;> simp [noneArgs, Erlang.erlang.«is_list/1», Term.list, List.replicate]
      unfold Elixir.Module.Types.Descr.«fun/2» Elixir.Module.Types.Descr.«fun_descr/2»
      simp [Lynx.Except.guard, hl, length_list, run m hm, split_static (Or.inl rfl), Lynx.Except.orElse, isMember,
        Elixir.Module.Types.Descr.«fun_new/3», leaf]

    /-- The top function of arity `n` without its arrow leaves the negated leaf. -/
    theorem fun_top_diff (n : Nat) (L : Term) (leaf : IsLeaf L) (m : Nat) : ∃ h : Int,
        Elixir.Module.Types.Descr.«bare_difference/3» (D (m + 1)) (.atom "fun")
            (.tuple #[.atom "union", .map [(.integer n, .atom "bdd_top")]]) (.tuple #[.atom "union", .map [(.integer n, L)]]) =
          .ok (.tuple #[.atom "union", .map [(.integer n, .tuple #[.integer h, L, .atom "bdd_bot", .atom "bdd_bot", .atom "bdd_top"]),
            (.integer n, .atom "bdd_top")]]) := by
      obtain ⟨h, hN⟩ := node_new (okc := fun _ => True) (oku := fun _ => True) (okd := fun _ => True) L (.atom "bdd_bot")
        (.atom "bdd_bot") (.atom "bdd_top") leaf (by simp [Bdd]) (by simp [Bdd]) (by simp [Bdd])
      obtain ⟨k, x, y, rfl⟩ := leaf
      refine ⟨h, ?_⟩
      simp [Elixir.Module.Types.Descr.«bare_difference/3», Elixir.Module.Types.Descr.«fun_difference/2»,
        Elixir.Module.Types.Descr.«fun_repr_difference/2», Erlang.maps.«fold/3»,
        Erlang.program.«Elixir.Module.Types.Descr:-fun_repr_difference/2-fun-0-/3».pure,
        Elixir.Module.Types.Descr.«-fun_repr_difference/2-fun-0-/3», getMapKeys_single, mapLookup, hN,
        Elixir.Module.Types.Descr.«bdd_difference/2», Elixir.Module.Types.Descr.«bdd_negation/1», Erlang.erlang.«=:=/2»,
        Erlang.erlang.«is_map/1»,
        Erlang.maps.«update/3», Erlang.maps.«remove/2», Erlang.erlang.«map_size/1», Erlang.erlang.«==/2»,
        Lynx.Except.andAlso, List.eraseDupsBy, List.eraseDupsBy.loop]

    /-- An arrow leaf without the top function of its arity is empty. -/
    theorem fun_leaf_diff (n : Nat) (L : Term) (leaf : IsLeaf L) (m : Nat) :
        Elixir.Module.Types.Descr.«bare_difference/3» (D (m + 1)) (.atom "fun")
            (.tuple #[.atom "union", .map [(.integer n, L)]]) (.tuple #[.atom "union", .map [(.integer n, .atom "bdd_top")]]) =
          .ok (.integer 0) := by
      obtain ⟨k, x, y, rfl⟩ := leaf
      simp [Elixir.Module.Types.Descr.«bare_difference/3», Elixir.Module.Types.Descr.«fun_difference/2»,
        Elixir.Module.Types.Descr.«fun_repr_difference/2», Erlang.maps.«fold/3»,
        Erlang.program.«Elixir.Module.Types.Descr:-fun_repr_difference/2-fun-0-/3».pure,
        Elixir.Module.Types.Descr.«-fun_repr_difference/2-fun-0-/3», getMapKeys_single, mapLookup,
        Elixir.Module.Types.Descr.«bdd_difference/2», Erlang.erlang.«=:=/2», Erlang.erlang.«is_map/1»,
        Erlang.maps.«update/3», Erlang.maps.«remove/2», Erlang.erlang.«map_size/1», Erlang.erlang.«==/2»,
        Lynx.Except.andAlso]

    /-- A tuple domain is a subtype of itself. -/
    theorem domain_sub_self (k : Int) (A : Term) (m : Nat) (S : Term) :
        Elixir.Module.Types.Descr.«subtype_seen?/3» (D (m + 2)) (.map [(.atom "tuple", .tuple #[.integer k, .atom "closed", A])])
          (.map [(.atom "tuple", .tuple #[.integer k, .atom "closed", A])]) S =
          .ok (.atom "true") := by
      simp [Elixir.Module.Types.Descr.«subtype_seen?/3»]
      unfold Elixir.Module.Types.Descr.«bare_difference/2»
      simp [Erlang.erlang.«==/2», unfold_map, Erlang.erlang.«is_map_key/2»]
      unfold Elixir.Module.Types.Descr.«dynamic_difference/3»
      simp [Erlang.erlang.«==/2», Erlang.maps.«fold/3»,
        Erlang.program.«Elixir.Module.Types.Descr:-dynamic_difference/3-fun-0-/3».pure,
        Elixir.Module.Types.Descr.«-dynamic_difference/3-fun-0-/4», getMapKeys_single, mapLookup,
        Erlang.program.«Elixir.Module.Types.Descr:bare_difference/3».pure, Elixir.Module.Types.Descr.«bare_difference/3»,
        Elixir.Module.Types.Descr.«tuple_difference/2», bdd_difference_self, Erlang.maps.«remove/2», empty_none_seen]

    theorem diff_none_none (d : Dispatcher) :
        Elixir.Module.Types.Descr.«bare_difference/2» d (.map []) (.map []) = .ok (.map []) := by
      unfold Elixir.Module.Types.Descr.«bare_difference/2»
      simp [Erlang.erlang.«==/2», Lynx.Except.guard]

    /-- Arguments of `none()` stay empty after removing any arrow argument of `none()`. -/
    theorem phi_args_none (n : Nat) (ret pos C S : Term) (m : Nat) : ∀ (r j : Nat), j + r = n →
        Elixir.Module.Types.Descr.«phi_arguments/7» (D m) (Term.list (List.replicate r (.map []))) (.integer j)
            (Term.list (List.replicate n (.tuple #[.atom "false", .map []]))) ret pos C S =
          .ok (.tuple #[.atom "true", C]) := by
      intro r
      induction r with
      | zero => intro j _; rw [Elixir.Module.Types.Descr.«phi_arguments/7».eq_def]; rfl
      | succ r ih =>
        intro j hj
        have nth := nth_list (List.replicate n (.tuple #[.atom "false", .map []])) j (by simp; omega)
        rw [List.getElem?_replicate_of_lt (by omega)] at nth
        have next := ih (j + 1) (by omega)
        rw [Elixir.Module.Types.Descr.«phi_arguments/7».eq_def]
        simp only [List.replicate_succ, Term.list, Erlang.erlang.«+/2_integers»]
        rw [show ((j + 1 : Nat) : Int) = (j : Int) + 1 by omega] at next
        simp [nth, diff_none_none, empty_none_seen, isMember, Lynx.Except.guard, next]

    /-- `phi/5` holds for arguments and a return of `none()` against the top arrow of their arity. -/
    theorem phi_none (n : Nat) (k : Int) (S : Term) (m : Nat) : ∃ C,
        Elixir.Module.Types.Descr.«phi/5» (D m) (Term.list (List.replicate n (.tuple #[.atom "false", .map []])))
            (.tuple #[.atom "false", .map []]) (Term.list [.tuple #[.integer k, noneArgs n, .atom "term"]]) (.map []) S =
          .ok (.tuple #[.atom "true", C]) := by
      have args := phi_args_none n (.tuple #[.atom "false", .map []]) .nil (.map []) S m n 0 (by omega)
      have inter : Elixir.Module.Types.Descr.«bare_intersection/2» (D m) (.map []) (.atom "term") = .ok (.map []) := by
        unfold Elixir.Module.Types.Descr.«bare_intersection/2»; rfl
      refine ⟨.map [(.tuple #[Term.list (List.replicate n (.tuple #[.atom "false", .map []])),
        .tuple #[.atom "false", .map []], Term.list [.tuple #[.integer k, noneArgs n, .atom "term"]]], .atom "true")], ?_⟩
      rw [Elixir.Module.Types.Descr.«phi/5».eq_def]
      rw [show ((0 : Nat) : Int) = 0 from rfl] at args
      simp only [Term.list, noneArgs] at args ⊢
      simp [getMapKeys_single, mapLookup, inter, empty_none_seen, isMember, Lynx.Except.guard, args, Erlang.maps.«put/3»]

    theorem sub_none_term (d : Dispatcher) :
        Elixir.Module.Types.Descr.«subtype?/2» d (.map []) (.atom "term") = .ok (.atom "true") := by
      obtain ⟨T, term, -, -, -, staticT⟩ := unfolded_term_fields
      rw [subtype_term_r term]
      exact subtype_keys d [] T rfl staticT (by simp)

    /-- With no arguments, the top arrow applies to the empty tuple and returns a subtype of `term()`. -/
    theorem phi_starter_zero (k : Int) (S : Term) (m : Nat) (hm : 12 ≤ m) :
        Elixir.Module.Types.Descr.«phi_starter/4» (D m) .nil (.atom "term") (Term.list [.tuple #[.integer k, .nil, .atom "term"]])
          S = .ok (.atom "true") := by
      obtain ⟨ops, dops, fops, hnone, tail⟩ : ElemOk LElem 8 ∧ ElemDiff LElem 8 ∧ ElemFun LElem 8 ∧ LElem (.map []) ∧
          TailOk LElem :=
        ⟨lelemOk.mono (by omega), lelemDiff.mono (by omega), lelemFun, Or.inr ⟨[], rfl, basic_nil⟩, tail_lelem⟩
      have dm := domOk ops dops fops hnone tail
      obtain ⟨dom, hdom, rdom⟩ := dm.dom [] (by simp)
      obtain ⟨i, hi, ri⟩ := dm.inter hdom hdom
      obtain ⟨X, rfl⟩ := dm.isMap hi
      obtain ⟨e, he⟩ := dm.empty hi []
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      have apply : ∃ r, (r = .map [] ∨ r = .atom "term") ∧
          Elixir.Module.Types.Descr.«apply_disjoint/2» (D (m' + 1)) .nil (Term.list [.tuple #[.integer k, .nil, .atom "term"]]) =
            .ok r := by
        simp only [Term.list] at rdom
        unfold Elixir.Module.Types.Descr.«apply_disjoint/2»
        cases e
        · refine ⟨.atom "term", Or.inr rfl, ?_⟩
          simp [rdom, Erlang.lists.«foldl/3», Lynx.Except.guard, Erlang.erlang.«is_function/2»,
            Erlang.lists.«foldl_1/3», Erlang.program.«Elixir.Module.Types.Descr:-apply_disjoint/2-fun-0-/2».pure,
            Elixir.Module.Types.Descr.«-apply_disjoint/2-fun-0-/3», ri m' (by omega), Elixir.Module.Types.Descr.«empty?/1»,
            he m' (by omega), isMember]
          unfold Elixir.Module.Types.Descr.«bare_union/2»
          rfl
        · refine ⟨.map [], Or.inl rfl, ?_⟩
          simp [rdom, Erlang.lists.«foldl/3», Lynx.Except.guard, Erlang.erlang.«is_function/2»,
            Erlang.lists.«foldl_1/3», Erlang.program.«Elixir.Module.Types.Descr:-apply_disjoint/2-fun-0-/2».pure,
            Elixir.Module.Types.Descr.«-apply_disjoint/2-fun-0-/3», ri m' (by omega), Elixir.Module.Types.Descr.«empty?/1»,
            he m' (by omega), isMember]
      obtain ⟨r, hr, run⟩ := apply
      have sub : Elixir.Module.Types.Descr.«subtype?/2» (D (m' + 1)) r (.atom "term") = .ok (.atom "true") := by
        rcases hr with rfl | rfl
        · exact sub_none_term _
        · exact Nest.sub_term_term _
      unfold Elixir.Module.Types.Descr.«phi_starter/4» Elixir.Module.Types.Descr.«disjoint_non_empty_domains?/3»
      simp [Term.list, Erlang.lists.«all/2», Lynx.Except.guard, Erlang.erlang.«is_function/2»,
        Elixir.Module.Types.Descr.«all_non_empty_arguments?/2»,
        Erlang.program.«Elixir.Module.Types.Descr:-all_non_empty_arguments?/2-fun-1-/1».pure,
        Elixir.Module.Types.Descr.«-all_non_empty_arguments?/2-fun-1-/2», Erlang.lists.«all_1/2»,
        Elixir.Module.Types.Descr.«all_disjoint_arguments?/1», Lynx.Except.andAlso, Erlang.erlang.«/=/2», run, sub]

    /-- With arguments of `none()`, `phi/5` decides that the top arrow is covered. -/
    theorem phi_starter_succ (n : Nat) (k : Int) (S : Term) (m : Nat) :
        Elixir.Module.Types.Descr.«phi_starter/4» (D (m + 1)) (noneArgs (n + 1)) (.atom "term")
          (Term.list [.tuple #[.integer k, noneArgs (n + 1), .atom "term"]]) S = .ok (.atom "true") := by
      have all := all_list (D (m + 1)) "Elixir.Module.Types.Descr" "-disjoint_non_empty_domains?/3-fun-0-" #[S]
        (fun _ => Bool.false) (List.replicate (n + 1) (.map [])) (by
          intro x mx
          rw [List.eq_of_mem_replicate mx, Erlang.program.«Elixir.Module.Types.Descr:-disjoint_non_empty_domains?/3-fun-0-/1».pure]
          simp [Elixir.Module.Types.Descr.«-disjoint_non_empty_domains?/3-fun-0-/2», empty_none_seen, Erlang.erlang.«not/1»,
            boolAtom])
      have args := map_list (D (m + 1)) "Elixir.Module.Types.Descr" "-phi_starter/4-fun-0-" #[]
        (fun x => .tuple #[.atom "false", x]) (List.replicate (n + 1) (.map [])) (fun x _ => by
          rw [Erlang.program.«Elixir.Module.Types.Descr:-phi_starter/4-fun-0-/1».pure]; rfl)
      have neg : Elixir.Module.Types.Descr.«bare_negation/1» (D (m + 1)) (.atom "term") = .ok (.map []) := by
        simp [Elixir.Module.Types.Descr.«bare_negation/1»]
      obtain ⟨C, phi⟩ := phi_none (n + 1) k S (m + 1)
      simp only [List.map_replicate] at args
      simp only [List.all_replicate] at all
      unfold Elixir.Module.Types.Descr.«phi_starter/4» Elixir.Module.Types.Descr.«disjoint_non_empty_domains?/3»
      simp [noneArgs, all, boolAtom, Lynx.Except.andAlso, args, neg, phi]

    theorem phi_starter_none (n : Nat) (k : Int) (S : Term) (m : Nat) (hm : 12 ≤ m) :
        Elixir.Module.Types.Descr.«phi_starter/4» (D m) (noneArgs n) (.atom "term")
          (Term.list [.tuple #[.integer k, noneArgs n, .atom "term"]]) S = .ok (.atom "true") := by
      cases n with
      | zero => exact phi_starter_zero k S m hm
      | succ n =>
        obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
        exact phi_starter_succ n k S m'

    /-- The line of the top function of arity `n` without its arrow leaf is empty. -/
    theorem fun_line_top (n : Nat) (k : Int) (S : Term) (m : Nat) (hm : 14 ≤ m)
        (leaf : Elixir.Module.Types.Descr.«bdd_leaf_new/2» (noneArgs n) (.atom "term") =
          .ok (.tuple #[.integer k, noneArgs n, .atom "term"])) :
        Elixir.Module.Types.Descr.«fun_line_empty?/3» (D m) .nil (Term.list [.tuple #[.integer k, noneArgs n, .atom "term"]]) S =
          .ok (.atom "true") := by
      obtain ⟨kd, dom⟩ := args_domain (List.replicate n (.map [])) (fun e me => by
        rw [List.eq_of_mem_replicate me]; exact Or.inr (Or.inl ⟨[], rfl, rfl⟩))
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 3 := ⟨m - 3, by omega⟩
      have margs := map_list (D (m' + 3)) "Elixir.Module.Types.Descr" "-fun_line_empty?/3-fun-0-" #[]
        (fun _ => .map []) (List.replicate n (.map [])) (fun x _ => by
          rw [Erlang.program.«Elixir.Module.Types.Descr:-fun_line_empty?/3-fun-0-/1».pure]; rfl)
      simp only [List.map_const'] at margs
      have fd : Elixir.Module.Types.Descr.«fetch_domain/1» (D (m' + 2)) (Term.list [.tuple #[.integer k, noneArgs n, .atom "term"]]) =
          .ok (.map [(.atom "tuple", .tuple #[.integer kd, .atom "closed", noneArgs n])]) := by
        unfold Elixir.Module.Types.Descr.«fetch_domain/1»
        simp [Erlang.lists.«foldl/3», Lynx.Except.guard, Erlang.erlang.«is_function/2», Erlang.lists.«foldl_1/3»,
          Erlang.program.«Elixir.Module.Types.Descr:-fetch_domain/1-fun-0-/2».pure,
          Elixir.Module.Types.Descr.«-fetch_domain/1-fun-0-/2», dom]
        unfold Elixir.Module.Types.Descr.«bare_union/2»
        simp [Erlang.erlang.«==/2», Lynx.Except.guard]
      rw [Elixir.Module.Types.Descr.«fun_line_empty?/3».eq_def]
      simp [Term.list, margs, leaf]
      simp only [noneArgs] at fd leaf ⊢
      rw [Elixir.Module.Types.Descr.«fun_line_empty?/3».eq_def]
      simp [Erlang.lists.«any/2», Lynx.Except.guard, Erlang.erlang.«is_function/2», Erlang.lists.«any_1/2»,
        Erlang.program.«Elixir.Module.Types.Descr:-fun_line_empty?/3-fun-1-/1».pure,
        Elixir.Module.Types.Descr.«-fun_line_empty?/3-fun-1-/3», dom, fd, domain_sub_self kd _ m',
        phi_starter_none n k S (m' + 2) (by omega)]

    /-- A negated leaf has a single line, whose only literal is negative. -/
    theorem dnf_neg_leaf (h : Int) (L : Term) :
        Elixir.Module.Types.Descr.«bdd_to_dnf/4» .nil .nil .nil
            (.tuple #[.integer h, L, .atom "bdd_bot", .atom "bdd_bot", .atom "bdd_top"]) =
          .ok (Term.list [.tuple #[.nil, Term.list [L]]]) := by
      have bot : ∀ acc p q, Elixir.Module.Types.Descr.«bdd_to_dnf/4» acc p q (.atom "bdd_bot") = .ok acc := by
        intro acc p q; rw [Elixir.Module.Types.Descr.«bdd_to_dnf/4».eq_def]; rfl
      have top : ∀ acc p q, Elixir.Module.Types.Descr.«bdd_to_dnf/4» acc p q (.atom "bdd_top") =
          .ok (.cons (.tuple #[p, q]) acc) := by
        intro acc p q; rw [Elixir.Module.Types.Descr.«bdd_to_dnf/4».eq_def]; rfl
      rw [Elixir.Module.Types.Descr.«bdd_to_dnf/4».eq_def]
      simp [bot, top, Term.list]

    /-- The top function of arity `n` without its arrow leaf is empty. -/
    theorem fun_empty_top (n : Nat) (k h : Int) (m : Nat) (hm : 18 ≤ m)
        (leaf : Elixir.Module.Types.Descr.«bdd_leaf_new/2» (noneArgs n) (.atom "term") =
          .ok (.tuple #[.integer k, noneArgs n, .atom "term"])) :
        Elixir.Module.Types.Descr.«fun_empty?/2» (D m) (.tuple #[.atom "union", .map [(.integer n,
            .tuple #[.integer h, .tuple #[.integer k, noneArgs n, .atom "term"], .atom "bdd_bot", .atom "bdd_bot",
              .atom "bdd_top"]), (.integer n, .atom "bdd_top")]]) (.map []) = .ok (.atom "true") := by
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 2 := ⟨m - 2, by omega⟩
      unfold Elixir.Module.Types.Descr.«fun_empty?/2»
      simp only [Erlang.maps.«to_list/1», Lynx.Except.ok_bind]
      refine all_true _ _ _ _ _ fun x mx => ?_
      obtain ⟨e, me, rfl⟩ := List.mem_map.mp mx
      have hv := mapLookup_of_mem_mapEntries me
      have he : e.2 = .tuple #[.integer h, .tuple #[.integer k, noneArgs n, .atom "term"], .atom "bdd_bot", .atom "bdd_bot",
          .atom "bdd_top"] := by
        by_cases c : exactCompare e.1 (.integer n) = .eq
        · simp [mapLookup, c] at hv; exact hv.symm
        · simp [mapLookup, c] at hv
      rw [he]
      have line := fun_line_top n k (.map [(.cons e.1 (.tuple #[.integer h, .tuple #[.integer k, noneArgs n, .atom "term"],
        .atom "bdd_bot", .atom "bdd_bot", .atom "bdd_top"]), .atom "true")]) m' (by omega) leaf
      rw [Erlang.program.«Elixir.Module.Types.Descr:-fun_empty?/2-fun-1-/1».pure]
      simp [Elixir.Module.Types.Descr.«-fun_empty?/2-fun-1-/2», Elixir.Module.Types.Descr.«empty_bdd_seen_key/2»,
        Erlang.erlang.«is_map_key/2», Erlang.maps.«put/3», Elixir.Module.Types.Descr.«bdd_to_dnf/1», dnf_neg_leaf]
      refine all_true _ _ _ _ _ fun y my => ?_
      rw [List.mem_singleton.mp my, Erlang.program.«Elixir.Module.Types.Descr:-fun_empty?/2-fun-0-/1».pure]
      simpa [Elixir.Module.Types.Descr.«-fun_empty?/2-fun-0-/2»] using line

    /-- The top function of arity `n` is equal to the arrow from `n` arguments of `none()` to `term()`. -/
    theorem fun_arity_equal_run (n : Nat) (m : Nat) (hm : 20 ≤ m) : ∃ right,
        Elixir.Module.Types.Descr.«fun/2» (D m) (noneArgs n) (.atom "term") = .ok right ∧
        Elixir.Module.Types.Descr.«equal?/2» (D m)
          (.map [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .atom "bdd_top")]])]) right = .ok (.atom "true") := by
      obtain ⟨k, run⟩ := fun_none_run n
      obtain ⟨r, leaf⟩ := run m (by omega)
      refine ⟨_, r, ?_⟩
      obtain ⟨m', rfl⟩ : ∃ m', m = m' + 1 := ⟨m - 1, by omega⟩
      obtain ⟨h, diff⟩ := fun_top_diff n (.tuple #[.integer k, noneArgs n, .atom "term"]) ⟨k, _, _, rfl⟩ m'
      have sub₁ := subtype_keys (D (m' + 1)) [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .atom "bdd_top")]])]
        [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .tuple #[.integer k, noneArgs n, .atom "term"])]])]
        (by simp [mapLookup]) (by simp [mapLookup]) (by
          intro e me
          simp only [mapEntries_singleton, List.mem_singleton] at me
          subst me
          refine Or.inl ⟨_, _, by simp [mapLookup], diff, Or.inr (Or.inr ?_)⟩
          simp only [Elixir.Module.Types.Descr.«empty_key?/3»]
          exact fun_empty_top n k h (m' + 1) (by omega) leaf)
      have sub₂ := subtype_keys (D (m' + 1))
        [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .tuple #[.integer k, noneArgs n, .atom "term"])]])]
        [(.atom "fun", .tuple #[.atom "union", .map [(.integer n, .atom "bdd_top")]])]
        (by simp [mapLookup]) (by simp [mapLookup]) (by
          intro e me
          simp only [mapEntries_singleton, List.mem_singleton] at me
          subst me
          exact Or.inl ⟨_, _, by simp [mapLookup], fun_leaf_diff n _ ⟨k, _, _, rfl⟩ m', Or.inl rfl⟩)
      simp [Elixir.Module.Types.Descr.«equal?/2», Erlang.erlang.«==/2», Lynx.Except.orElse, Lynx.Except.andAlso, sub₁, sub₂]
      split <;> simp_all

    end Elixir.STTDescrProofsTest
    """

    law intersection_none_empty(descr),
      requires: descr?(descr),
      expects: Descr.empty?(Descr.bare_intersection(descr, Descr.none())),
      proof: ~LEAN"""
      -- The proofs run from a depth of 100 on.
      refine ⟨100, fun depth deep => ?_⟩
      obtain ⟨δ, rfl⟩ := Nat.exists_eq_add_of_le' deep
      open Lynx Lynx.Term in
      simp only [«intersection_none_empty:requires/1»] at requires
      simp only [Lynx.apply_eq, «intersection_none_empty:ensures/1», Elixir.Module.Types.Descr.«none/0»]
      cases descr with
      | map X =>
        cases dynamic : mapLookup X (.atom "dynamic") with
        | none => simp [intersection_none_static (δ + 99) X dynamic, empty_none]
        | some Dy =>
          have inner : Dy = .atom "term" ∨ ∃ Y, Dy = .map Y := by
            simp [«descr?/1», getMapKeys_single, dynamic, Erlang.erlang.«==/2», Erlang.erlang.«is_map/1»,
              Lynx.Except.orElse_eq_true] at requires
            cases Dy <;> simp_all
          simp [intersection_none_dynamic (δ + 99) X Dy dynamic inner, empty_none]
      | atom name =>
        by_cases top : name = "term"
        · subst top
          unfold Elixir.Module.Types.Descr.«bare_intersection/2»
          simp [empty_none]
        · simp [«descr?/1», top, Lynx.Term.getMapKeys, Erlang.erlang.«is_map/1»] at requires
      | _ => simp [«descr?/1», Lynx.Term.getMapKeys, Erlang.erlang.«is_map/1»] at requires
      """

    law intersection_negation_empty(descr, depth, node),
      requires: (negatable?(descr, {depth, node}) or opt_gradual?(descr, {depth, node})) and depth?(depth),
      expects: Descr.empty?(Descr.lower_bound(Descr.bare_intersection(descr, Descr.bare_negation(descr)))),
      proof: ~LEAN"""
      -- The types nest at most `d` levels, so the proofs run from the bound of level `d` on, and the
      -- precondition from its own bound.
      obtain ⟨bound, requires⟩ := requires
      have checked := requires bound (Nat.le_refl _)
      simp only [Lynx.apply_eq, «intersection_negation_empty:requires/3», Lynx.Term.true, Lynx.Except.andAlso_eq_true] at checked
      obtain ⟨d, rfl⟩ := Nest.depth_nat checked.2
      refine ⟨max bound (100 + 15 * d), fun depth deep => ?_⟩
      obtain ⟨hb, hd⟩ := Nat.max_le.mp deep
      obtain ⟨δ, rfl⟩ : ∃ δ, depth = δ + 100 := ⟨depth - 100, by omega⟩
      have requires := requires (δ + 100) hb
      open Lynx Lynx.Term in
      simp only [Lynx.apply_eq, «intersection_negation_empty:requires/3», Term.true, Lynx.Except.orElse_eq_true, Lynx.Except.andAlso_eq_true] at requires
      replace requires := requires.1
      simp only [Lynx.apply_eq, «intersection_negation_empty:ensures/3»]
      rcases requires with static | ⟨-, gradual⟩
      · rcases Nest.negatable_cases node d descr (by simpa [Term.true] using static) with rfl | ⟨X, rfl, valid⟩
        · simp [negation_term_none, inter_term_left, Nest.lower_bound_run, Nest.lower, Nest.rmDyn, empty_none]
        obtain ⟨ops, -, -, -, -⟩ := closed_ok node d
        replace valid := valid.mono (nest_closed node d)
        by_cases empty : X = []
        · subst empty
          have negation : Elixir.Module.Types.Descr.«bare_negation/1»
              (Dispatcher.ofTable Erlang.program.fun_table (δ + 100)) (.map []) = .ok (.atom "term") := by
            simp only [Elixir.Module.Types.Descr.«bare_negation/1»]
            unfold Elixir.Module.Types.Descr.«bare_difference/2»
            simp [Erlang.erlang.«==/2»]
          have intersection : Elixir.Module.Types.Descr.«bare_intersection/2»
              (Dispatcher.ofTable Erlang.program.fun_table (δ + 100)) (.map []) (.atom "term") = .ok (.map []) := by
            unfold Elixir.Module.Types.Descr.«bare_intersection/2»
            rfl
          simp [negation, intersection, Nest.lower_bound_run, Nest.lower, Nest.rmDyn, empty_none]
        · obtain ⟨N, negation, static, bitmaps, atoms, funs, lists, tuples, maps, -⟩ :=
            negation_fields ops (δ + 98) X valid empty
          obtain ⟨I, run, only⟩ := intersection_disjoint (δ + 99) X N valid static bitmaps atoms
            (fun x y hx hy => funs x y hx hy (δ + 99)) lists tuples maps
          have staticI : mapLookup I (.atom "dynamic") = Option.none := by
            cases h : mapLookup I (.atom "dynamic") with
            | none => rfl
            | some w => rcases only _ _ h with ⟨e, -⟩ | ⟨e, -⟩ | ⟨e, -⟩ <;> simp at e
          simp [negation, run, Nest.lower_bound_run, Nest.lower, Nest.rmDyn_static staticI,
            empty_gone (m := δ + 100) (by omega) I only]
      · have t := Nest.opt_gradual_gc (t := node) (m := δ + 100) (n := d) (by rw [Nest.level_K]; omega) descr gradual
        obtain ⟨n, i, r₁, r₂, r₃, eq⟩ := Nest.gd_inter_neg_lower t (m := δ + 100) (by rw [Nest.level_K]; omega)
        simp [r₁, r₂, r₃, eq]
      """

    law opt_intersection_negation_empty(descr, depth, node),
      requires: opt_gradual?(descr, {depth, node}) and depth?(depth),
      expects: Descr.empty?(Descr.lower_bound(Descr.opt_intersection(descr, Descr.opt_negation(descr)))),
      proof: ~LEAN"""
      -- The types nest at most `d` levels, so the proofs run from the bound of level `d` on, and the
      -- precondition from its own bound.
      obtain ⟨bound, requires⟩ := requires
      have checked := requires bound (Nat.le_refl _)
      simp only [Lynx.apply_eq, «opt_intersection_negation_empty:requires/3», Lynx.Term.true, Lynx.Except.andAlso_eq_true] at checked
      obtain ⟨d, rfl⟩ := Nest.depth_nat checked.2
      refine ⟨max bound (100 + 15 * d), fun depth deep => ?_⟩
      obtain ⟨hb, hd⟩ := Nat.max_le.mp deep
      obtain ⟨δ, rfl⟩ : ∃ δ, depth = δ + 100 := ⟨depth - 100, by omega⟩
      have requires := requires (δ + 100) hb
      open Lynx Lynx.Term in
      simp only [Lynx.apply_eq, «opt_intersection_negation_empty:requires/3», Term.true, Lynx.Except.andAlso_eq_true] at requires
      replace requires := requires.1
      have t := Nest.opt_gradual_gc (t := node) (m := δ + 100) (n := d) (by rw [Nest.level_K]; omega) descr requires
      obtain ⟨n, i, r₁, r₂, r₃, eq⟩ := Nest.gd_opt_inter_neg_lower t (m := δ + 100) (by rw [Nest.level_K]; omega)
      simp only [Lynx.apply_eq, «opt_intersection_negation_empty:ensures/3»]
      simp [r₁, r₂, r₃, eq]
      """

    law union_negation_term(descr, depth, node),
      requires: (negatable?(descr, {depth, node}) or opt_gradual?(descr, {depth, node})) and depth?(depth),
      expects: Descr.subtype?(Descr.term(), Descr.upper_bound(Descr.bare_union(descr, Descr.bare_negation(descr)))),
      proof: ~LEAN"""
      -- The types nest at most `d` levels, so the proofs run from the bound of level `d` on, and the
      -- precondition from its own bound.
      obtain ⟨bound, requires⟩ := requires
      have checked := requires bound (Nat.le_refl _)
      simp only [Lynx.apply_eq, «union_negation_term:requires/3», Lynx.Term.true, Lynx.Except.andAlso_eq_true] at checked
      obtain ⟨d, rfl⟩ := Nest.depth_nat checked.2
      refine ⟨max bound (100 + 15 * d), fun depth deep => ?_⟩
      obtain ⟨hb, hd⟩ := Nat.max_le.mp deep
      obtain ⟨δ, rfl⟩ : ∃ δ, depth = δ + 100 := ⟨depth - 100, by omega⟩
      have requires := requires (δ + 100) hb
      open Lynx Lynx.Term in
      simp only [Lynx.apply_eq, «union_negation_term:requires/3», Term.true, Lynx.Except.orElse_eq_true, Lynx.Except.andAlso_eq_true] at requires
      replace requires := requires.1
      simp only [Lynx.apply_eq, «union_negation_term:ensures/3»]
      rcases requires with static | ⟨-, gradual⟩
      · rcases Nest.negatable_cases node d descr (by simpa [Term.true] using static) with rfl | ⟨X, rfl, valid⟩
        · simp [Elixir.Module.Types.Descr.«term/0», negation_term_none, union_term_l, Nest.upper_bound_term, Nest.upper,
            Nest.sub_term_term]
        obtain ⟨ops, -, -, -, -⟩ := closed_ok node d
        replace valid := valid.mono (nest_closed node d)
        by_cases empty : X = []
        · subst empty
          have negation : Elixir.Module.Types.Descr.«bare_negation/1»
              (Dispatcher.ofTable Erlang.program.fun_table (δ + 100)) (.map []) = .ok (.atom "term") := by
            simp only [Elixir.Module.Types.Descr.«bare_negation/1»]
            unfold Elixir.Module.Types.Descr.«bare_difference/2»
            simp [Erlang.erlang.«==/2»]
          have union : Elixir.Module.Types.Descr.«bare_union/2»
              (Dispatcher.ofTable Erlang.program.fun_table (δ + 100)) (.map []) (.atom "term") = .ok (.atom "term") := by
            unfold Elixir.Module.Types.Descr.«bare_union/2»
            rfl
          simp [Elixir.Module.Types.Descr.«term/0», negation, union, Nest.upper_bound_term, Nest.upper, Nest.sub_term_term]
        · obtain ⟨N, U, negation, union, staticU, sub⟩ := union_negation_covers δ ops (by omega) X valid empty
          simp [Elixir.Module.Types.Descr.«term/0», negation, union, Nest.upper_bound_static staticU, staticU, sub]
      · have t := Nest.opt_gradual_gc (t := node) (m := δ + 100) (n := d) (by rw [Nest.level_K]; omega) descr gradual
        obtain ⟨n, u, r₁, r₂, r₃, sub⟩ := Nest.gd_union_neg_upper t (m := δ + 100) (by rw [Nest.level_K]; omega)
        simp [Elixir.Module.Types.Descr.«term/0», r₁, r₂, r₃, sub]
      """

    law opt_union_negation_term(descr, depth, node),
      requires: opt_gradual?(descr, {depth, node}) and depth?(depth),
      expects: Descr.subtype?(Descr.term(), Descr.upper_bound(Descr.opt_union(descr, Descr.opt_negation(descr)))),
      proof: ~LEAN"""
      -- The types nest at most `d` levels, so the proofs run from the bound of level `d` on, and the
      -- precondition from its own bound.
